// Ideeënbibliotheek van Groteknut (132 ideeën).
// Eén idee per regel. Controleer wijzigingen met: node tools/validate.mjs
export default [
  {"id":"verf-in-een-zakje","title":"Verven zonder knoeien: verf in een zakje","emoji":"👆","category":"verven","summary":"Klodders verf in een dichtgeplakt zakje: je kind duwt, wrijft en tekent met een vinger, zonder één vlek op tafel.","ageMin":1,"ageMax":3,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":15,"supervision":2,"materials":[{"id":"zip-zakjes","note":"een stevig diepvrieszakje, ongeveer 20 x 25 cm"},{"id":"plakkaatverf","note":"2-3 kleuren, een paar flinke klodders"},{"id":"schilderstape","note":"om de rits dicht te plakken en het zakje vast te zetten"}],"optional":[{"id":"wattenstaafjes","note":"om lijnen mee te tekenen"},{"id":"papier","note":"een wit vel onder het zakje, dan zie je de kleuren beter"}],"steps":["Doe 3-4 flinke klodders verf in een diepvrieszakje, het liefst in twee of drie kleuren een stukje uit elkaar.","Druk de lucht er voorzichtig uit, sluit de rits en plak hem extra dicht met een strook schilderstape.","Plak het zakje aan alle kanten vast op tafel, op het blad van de kinderstoel of op het raam, op ooghoogte van je kind.","Laat je kind duwen, wrijven en kloppen: met de hele hand, met één vinger of met een wattenstaafje.","Teken samen lijnen, rondjes of een gezichtje en strijk alles weer glad: het zakje is een tekenbord dat je steeds opnieuw kunt gebruiken.","Controleer na afloop of het zakje nog heel is. Een heel zakje kan plat in de la en gaat zo nog een paar keer mee."],"ageTips":{"young":"Gebruik voor je dreumes twee zakjes in elkaar en plak ze rondom stevig vast, zodat ze niet in de mond kunnen. Benoem wat er gebeurt: duwen, plat, geel!","old":"Een driejarige kan met een wattenstaafje vormen tekenen: een rondje, een streep, de eerste letter van de eigen naam. Of mengen: wat wordt geel en blauw samen?"},"safety":["Een plastic zakje hoort niet in de mond of over het hoofd: blijf erbij en ruim het na afloop meteen op.","Controleer het zakje op lekjes en plak ook scherpe hoekjes af. Lekt het toch, dan vlekt de verf: kies afwasbare kinderverf."],"say":["Duw! Nog een keer!","Waar gaat de verf heen als je hier drukt?","Ik zie geel en blauw elkaar raken… welke kleur komt daar?","Hoe voelt het: zacht, koud, glibberig?","Je blijft maar duwen en wrijven, wat werk je goed door!"],"words":["duwen","glad","zacht","glibberig","mengen","streep","rondje"],"learn":["zintuigen","fijne-motoriek","ontdekken"],"tips":["Hang het zakje op het raam: het licht schijnt door de kleuren en je kind oefent staand met grote armbewegingen.","Geen plakkaatverf? Kook een beetje vingerverf (zie Recepten) en doe die met een paar druppels kleurstof in het zakje."],"variations":["Zoekzakje: leg een foto of plaatje onder het zakje en duw de verf weg om te ontdekken wat eronder zit.","Kleuren mengen: doe rood en geel in één zakje en kijk samen hoe er oranje ontstaat.","Herfst: kies bruin, rood en geel en leg een echt blad onder het zakje."],"themes":[]},
  {"id":"vingerverven","title":"Vingerverven op een groot vel","emoji":"🖐️","category":"verven","summary":"Smeren, kletsen en tekenen met je handen in zachte vingerverf op een groot vel: heerlijk voelen en ontdekken, voor elke leeftijd.","ageMin":1,"ageMax":5,"mess":3,"wet":false,"dirty":true,"prepMinutes":15,"durationMinutes":20,"supervision":2,"materials":[{"id":"vingerverf","note":"zelfgemaakt (zie Recepten) of gekocht, 2-3 kleuren"},{"id":"groot-papier","note":"een flink vel, of een paar A4’tjes aan elkaar"},{"id":"schilderstape","note":"om het papier vast te plakken"},{"id":"oud-shirt","note":"of alleen een luier of onderbroekje aan"},{"id":"kom","note":"met lauw water en een doekje, om handen te wassen"}],"optional":[{"id":"oud-laken","note":"als knoeimat onder het papier"},{"id":"bakjes","note":"een per kleur"},{"id":"kleurstof","note":"om zelfgemaakte verf te kleuren"}],"steps":["Maak de vingerverf (zie Recepten): verwarm 60 g maizena, 500 ml koud water en 2 el suiker al roerend tot het dik is als pudding. Dat doe jij.","Laat de pap helemaal afkoelen, verdeel hem over 3 bakjes en roer er per bakje een paar druppels kleurstof door.","Plak een groot vel papier met schilderstape vast op tafel of vloer, met een knoeimat eronder.","Trek je kind een oud shirt aan en schep met een lepel een paar klodders verf op het papier.","Laat je kind smeren, kletsen, krassen en stempelen met vingers, handen en armen. Doe gerust mee!","Was de handen in de kom met lauw water en laat het vel een paar uur plat drogen."],"ageTips":{"young":"Je dreumes stopt vingers in de mond: kies dan zelfgemaakte verf zonder afwasmiddel en zet je kind in de kinderstoel met een vel op het blad. Begin met één kleur.","old":"Een kleuter kan met één vinger tekenen: een zon, een huis, de eigen naam. Of kras met een vork of ijsstokje lijnen in de verf en maak een patroon."},"safety":["Het koken doe jij, en de pap blijft lang heet: voel zelf of de verf helemaal is afgekoeld voor je kind erin mag.","Laat bij kinderen die alles in hun mond stoppen het druppeltje afwasmiddel uit het recept weg. Gekochte vingerverf is niet om te eten.","Verf en kleurstof vlekken op kleding, tafel en voegen, en klodders op de vloer zijn glad: werk op een knoeimat en veeg gemorste verf meteen op."],"say":["Klets! Nog een keer!","Hoe voelt de verf: koud, glibberig of plakkerig?","Ik zie dat je met je hele hand een grote cirkel maakt.","Wat gebeurt er als rood en geel elkaar tegenkomen?","Wat durf jij goed te voelen, met je hele hand erin!"],"words":["smeren","glibberig","klets","plakkerig","rondje","mengen","vingertop"],"learn":["zintuigen","creativiteit","fijne-motoriek"],"tips":["Verf vlak voor badtijd, in alleen een luier of onderbroekje: dan gaat iedereen daarna meteen in bad.","Zelfgemaakte vingerverf blijft een paar dagen goed in een afgesloten bakje in de koelkast.","Geen groot papier? Verf op een dienblad of tafelzeil en druk er na afloop een vel papier op: zo heb je toch een afdruk."],"variations":["Kleuren mengen: begin met alleen geel en blauw en ontdek samen waar het groen wordt.","Geurverf: roer een snufje kaneel door de bruine verf en wat citroenrasp door de gele. Wat ruik je?","Herfst: verf in bruin, oranje en geel en knip na het drogen bladeren uit het vel."],"themes":[]},
  {"id":"yoghurtverf","title":"Eetbare yoghurtverf voor dreumesen","emoji":"🥣","category":"verven","summary":"Verven met gekleurde yoghurt op het blad van de kinderstoel: je dreumes mag smeren, kletsen én likken, want het is gewoon eten.","ageMin":1,"ageMax":2,"mess":3,"wet":false,"dirty":true,"prepMinutes":5,"durationMinutes":15,"supervision":2,"materials":[{"id":"yoghurt","note":"volle of Griekse yoghurt, ongeveer 3 el per kleur"},{"id":"kleurstof","note":"een druppel per bakje, of natuurlijke kleur van fruit"},{"id":"bakjes","note":"2-3 kleine bakjes"},{"id":"dienblad","note":"of het blad van de kinderstoel"}],"optional":[{"id":"fruit","note":"blauwe bessen of aardbeien om door de yoghurt te prakken"},{"id":"penselen","note":"een dikke, schone kwast"},{"id":"bakpapier","note":"om op het blad te leggen"},{"id":"oud-shirt","note":"of alleen een luier aan"}],"steps":["Verdeel de yoghurt over 2 of 3 bakjes, ongeveer 3 el per bakje.","Kleur elk bakje met één druppel kleurstof, of prak er wat blauwe bessen, aardbeien of een scheutje bietensap door.","Zet je dreumes in de kinderstoel met alleen een luier of een oud shirt aan, of zet een dienblad voor je kind neer.","Schep een paar klodders op het blad en laat je kind smeren, kletsen, tekenen en proeven.","Teken zelf mee met één vinger: een rondje, een streep, een lachend gezichtje.","Veeg het blad schoon met een nat doekje en ga meteen in bad: plan het vlak voor badtijd."],"ageTips":{"young":"Een eenjarige wil vooral voelen en proeven. Geef één kleur tegelijk, een klein beetje is genoeg, en benoem wat je ziet: wit, en nu roze!","old":"Een tweejarige kan met een kwast of vingertop strepen en stippen zetten, kleuren mengen of op een vel bakpapier een eigen schilderij maken."},"safety":["Yoghurt bevat melk: kies bij een melkallergie een plantaardige yoghurt of dikke appelmoes.","Kleurstof, bietensap en bessen vlekken op kleding, kinderstoel en voegen: één druppel per bakje is genoeg.","Gooi restjes na afloop weg: yoghurt die buiten de koelkast stond en waar handjes in zaten, is niet meer goed om te eten."],"say":["Smeer! Nog meer!","Hoe voelt het: koud en glad?","Mmm, proef je de aardbei?","Kijk, jouw hand maakt een roze streep.","Wat zit jij lekker te ontdekken!"],"words":["koud","glad","smeren","roze","proeven","lekker","vinger"],"learn":["zintuigen","taal","ontdekken"],"tips":["Leg een vel bakpapier op het blad van de kinderstoel: na afloop vouw je het dicht en gooi je het weg.","Natuurlijke kleuren: bietensap geeft roze, blauwe bessen paars en een snufje kurkuma geel. Ook die vlekken, dus trek oude kleren aan."],"variations":["Vla- of puddingverf: werkt net zo, maar met een andere kleur en smaak.","Proefpalet: een bakje met bessen, een met geprakte banaan en een met wortelpuree. Welke vindt je kind het lekkerst?","Zomer: zet de bakjes 20 minuten in de vriezer voor koele, dikke verf op een warme dag."],"themes":[]},
  {"id":"groente-stempels","title":"Stempelen met groente en fruit","emoji":"🥔","category":"verven","summary":"Een paprika wordt een bloem, een halve appel een ster: stempel met groente en fruit en ontdek welke vorm erin verstopt zit.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":10,"durationMinutes":20,"supervision":2,"materials":[{"id":"groente","note":"een paprika, een aardappel en een stronk bleekselderij"},{"id":"fruit","note":"een appel, dwars doorgesneden"},{"id":"plakkaatverf","note":"2-3 kleuren"},{"id":"bord","note":"een plat bord per kleur"},{"id":"papier","note":"of groot papier"},{"id":"mes","note":"voor jou"}],"optional":[{"id":"keukenpapier","note":"om de stempels droog te deppen"},{"id":"vork","note":"in een halve aardappel geprikt als handvat"},{"id":"oud-shirt"}],"steps":["Snijd de groente en het fruit door, dat doe jij: een paprika dwars (bloem), een appel dwars (ster) en de onderkant van de bleekselderij (roosje).","Maak een aardappelstempel: snijd een aardappel doormidden en snijd rondom een hartje of driehoek een halve centimeter weg, zodat de vorm uitsteekt.","Dep alle stempels droog met keukenpapier en doe een dun laagje verf op een paar borden, één kleur per bord.","Laat je kind een stempel in de verf drukken, even laten uitlekken en stevig op het papier zetten.","Bekijk samen elke afdruk: welke groente was dit? Zie je de ster van de appel?","Laat het vel plat drogen en gooi de gebruikte stempels weg: met verf erop zijn ze niet meer om te eten."],"ageTips":{"young":"Een tweejarige pakt een halve aardappel of appel het makkelijkst. Prik er een vork in als handvat en geef één kleur tegelijk.","old":"Een kleuter kan een patroon stempelen (ster, bloem, ster, bloem), tellen hoeveel afdrukken er op een rij passen of van de afdrukken een rups of bloemenveld maken."},"safety":["Het snijden doe jij: leg het mes daarna meteen buiten bereik.","Met verf erop is groente geen eten meer: laat je kind niet aan de stempels likken en gooi ze na afloop weg.","Plakkaatverf vlekt op kleding en tafel: kies afwasbare kinderverf en trek een oud shirt aan."],"say":["Druk! Kijk eens!","Wat zie je als je de appel optilt?","Welke groente maakt rondjes, en welke een bloem?","Ik zie dat je heel stevig drukt, daardoor zie je alle lijntjes.","Ruik eens aan de appel. En aan de paprika?"],"words":["stempel","afdruk","ster","bloem","doormidden","stevig","patroon"],"learn":["creativiteit","fijne-motoriek","ontdekken","rekenen"],"tips":["Gebruik restjes en kontjes uit de groentela: een prei, wortel of champignon geeft ook verrassende vormen.","Dep gesneden groente goed droog en doe niet te veel verf op het bord: dan wordt de afdruk scherper."],"variations":["Herfst: stempel appels en peren in rood, geel en bruin en maak er een fruitmand of herfstboom van.","Kaartjes: stempel klein op een dubbelgevouwen kaart, als bedankje of verjaardagskaart.","Raadspel: maak een afdruk en laat de ander raden welke groente of welk fruit het was."],"themes":["herfst"]},
  {"id":"wc-rol-stempels","title":"Stempelen met wc-rolletjes","emoji":"🌸","category":"verven","summary":"Een wc-rolletje is een stempel vol vormen: rond, ingeknepen tot hartje of met franjes als bloem. Stempel samen een bloemenveld.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":5,"durationMinutes":20,"supervision":2,"materials":[{"id":"wc-rollen","note":"3 lege rolletjes"},{"id":"plakkaatverf","note":"2-3 kleuren"},{"id":"bord","note":"een plat bord of deksel per kleur"},{"id":"papier","note":"wit of gekleurd"},{"id":"plakband","note":"om de hartvorm vast te zetten"},{"id":"schaar","note":"voor jou, om franjes te knippen"}],"optional":[{"id":"stiften","note":"voor steeltjes en blaadjes"},{"id":"kinderschaar","note":"voor kleuters die zelf franjes knippen"},{"id":"oud-shirt"}],"steps":["Laat één rolletje zoals het is: dat stempelt rondjes.","Druk een tweede rolletje plat en duw het midden van één kant naar binnen: zo krijg je een hartje. Zet de vorm vast met plakband.","Knip een derde rolletje aan één kant rondom in, 2 cm diep (dat doe jij), en buig de franjes naar buiten: een bloem.","Doe een dun laagje verf op een paar borden en laat je kind de stempels erin dopen en stevig op het papier drukken.","Maak er samen een bloemenveld van: teken steeltjes met stift en stempel een hartje als blaadje.","Laat het vel plat drogen. Droge stempels kunnen nog een keer mee."],"ageTips":{"young":"Een tweejarige begint met het ronde rolletje: dopen, drukken, optillen. Benoem elke afdruk: rondje! Nog een rondje!","old":"Een kleuter kan zelf franjes knippen met een kinderschaar, een patroon stempelen (rond, hart, rond) of tellen hoeveel bloemen er in het veld staan."},"safety":["Het inknippen van de franjes doe jij, of je kleuter met een kinderschaar met ronde punt.","Plakkaatverf vlekt op kleding en tafel: kies afwasbare kinderverf en werk op een knoeimat."],"say":["Druk! Een rondje!","Wat gebeurt er als je het rolletje platknijpt?","Hoeveel bloemen staan er al in jouw veld?","Ik zie dat de franjes allemaal kleine streepjes maken, net blaadjes van een bloem.","Je zoekt steeds een nieuw plekje om te stempelen, goed bedacht!"],"words":["rondje","hartje","bloem","franje","stempelen","plat","rij"],"learn":["creativiteit","fijne-motoriek","rekenen"],"tips":["Spaar een paar weken wc-rolletjes, of knip een keukenrolkoker in drie stukken: dan heb je meteen genoeg stempels.","Een dun laagje verf geeft scherpere vormen dan een dikke klodder. Doe liever vaker een beetje bij."],"variations":["Moederdag: stempel hartjes op een dubbelgevouwen kaart en schrijf er samen een boodschap in.","Lente: maak een bloemenveld met franjebloemen en stip er met een vingertop bijtjes bij.","Aquarium: stempel blauwe en witte rondjes als luchtbelletjes op gekleurd papier en teken er vissen bij."],"themes":["lente","moederdag"]},
  {"id":"noppenfolie-afdruk","title":"Noppenfolie-afdrukken","emoji":"🐝","category":"verven","summary":"Verf de noppen van bubbeltjesplastic en druk er papier op: een honingraat vol stippen. Of wikkel de folie om een deegroller of handje.","ageMin":1,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":5,"durationMinutes":20,"supervision":2,"materials":[{"id":"noppenfolie","note":"een stuk van ongeveer 30 x 30 cm"},{"id":"plakkaatverf","note":"bijvoorbeeld geel en oranje voor een honingraat"},{"id":"penselen","note":"een dikke kwast"},{"id":"papier","note":"of groot papier voor de rolstempel"},{"id":"schilderstape","note":"om de folie vast te zetten"}],"optional":[{"id":"deegroller","note":"om de folie omheen te plakken"},{"id":"sponsjes","note":"om de verf op te deppen"},{"id":"stiften","note":"om bijtjes te tekenen"},{"id":"oud-laken","note":"als knoeimat"}],"steps":["Plak een stuk noppenfolie met de noppen naar boven vast op tafel.","Laat je kind de noppen beschilderen met een dikke kwast of een sponsje, in één of meer kleuren.","Leg een vel papier op de folie, wrijf er samen met platte handen overheen en trek het voorzichtig los.","Bekijk de afdruk: allemaal stippen! Schilder de folie opnieuw voor een tweede of derde afdruk.","Maak een rolstempel: plak noppenfolie om een deegroller, rol door een laagje verf op een bord en daarna over een lang vel.","Laat de afdrukken plat drogen en teken er met stift bijtjes of bloemen bij."],"ageTips":{"young":"Een dreumes vindt de noppen zelf al spannend: laat eerst voelen en knijpen. Wikkel daarna folie om het handje (los, met tape), doop in de verf en druk samen op het papier: klets!","old":"Een kleuter kan van de stippenvellen bijtjes en bloemen knippen, of tellen hoeveel noppen er in één rij staan. Ook leuk: met twee kleuren om en om schilderen."},"safety":["Folie om een handje of voetje maak je los vast met tape, nooit strak of met een elastiekje. Druk een voetafdruk zittend: met verf eronder is lopen spekglad.","Plastic folie hoort niet in de mond of over het gezicht: blijf erbij en ruim losse stukjes meteen op.","Plakkaatverf vlekt op kleding en tafel: kies afwasbare kinderverf."],"say":["Plop! Nog een!","Hoe voelen de bolletjes onder je vingers?","Wat denk je dat we zien als we het papier optillen?","Ik zie allemaal kleine rondjes, net een honingraat van bijen.","Wat wrijf je goed met je hele hand, alle stippen staan erop!"],"words":["bolletje","stip","rij","honingraat","rollen","afdruk","bobbelig"],"learn":["zintuigen","creativiteit","ontdekken"],"tips":["Bewaar de noppenfolie uit pakketjes: een stukje is genoeg, en na afloop spoel je het af om nog eens te gebruiken.","Leg de folie na afloop meteen in de gootsteen: de verf op de noppen blijft lang nat en vlekt."],"variations":["Lente: maak een geel-oranje honingraat, knip er een bijenkorf uit en teken er bijtjes omheen.","Zomer: blauwe en groene stippen worden een zee vol luchtbelletjes, met vissen ernaast.","Voetstapjespad: wikkel folie om een voetje (zittend op een stoel) en druk er stapjes mee op een lange strook papier.","Slangenvel: rol de deegroller in groen en geel over een lange strook en knip er een slang uit."],"themes":["lente","zomer"]},
  {"id":"autosporen","title":"Autosporen verven","emoji":"🚗","category":"verven","summary":"Rijd met speelgoedautootjes door de verf en over een groot vel: elke auto laat een ander bandenspoor achter. Daarna door de wasstraat!","ageMin":2,"ageMax":5,"mess":3,"wet":true,"dirty":true,"prepMinutes":10,"durationMinutes":25,"supervision":2,"materials":[{"id":"speelgoedautos","note":"een paar met verschillende banden, die vies mogen worden"},{"id":"plakkaatverf","note":"2-3 kleuren"},{"id":"bord","note":"een plat bord per kleur"},{"id":"groot-papier","note":"een lange strook, bijvoorbeeld oud behang"},{"id":"schilderstape","note":"om het papier vast te plakken"},{"id":"opbergbak","note":"of afwasteil, voor de wasstraat"},{"id":"water","note":"lauw, voor de wasstraat"},{"id":"afwasmiddel","note":"een scheutje voor het sopje"}],"optional":[{"id":"tandenborstel","note":"om de bandjes te poetsen"},{"id":"sponsjes"},{"id":"handdoek","note":"om de auto’s op te laten drogen"},{"id":"oud-laken","note":"als knoeimat"}],"steps":["Plak een lange strook papier met schilderstape vast op de vloer of tafel, met een knoeimat eronder.","Doe een dun laagje verf op een paar borden, één kleur per bord.","Laat je kind een auto door de verf rijden en dan over het papier: vroem, daar komt het spoor!","Probeer verschillende auto’s en vergelijk de sporen: dikke en dunne banden, rechte lijnen en slingers.","Maak na afloop een wasstraat: een bak lauw water met een scheutje afwasmiddel, een sponsje en een oude tandenborstel. Je kind poetst de auto’s schoon.","Laat de auto’s drogen op een handdoek en het papier plat drogen."],"ageTips":{"young":"Geef een tweejarige één grote auto met brede banden en één kleur. Rijden en vroem roepen is het leukste; het spoor is mooi meegenomen.","old":"Een kleuter kan een route bedenken (bocht, rondje, rechtdoor), raden welke auto welk spoor maakte of de sporen met stift omtoveren tot een stad met huizen en wegen."},"safety":["Laat je kind niet alleen bij de bak sopje, ook niet bij een laagje water, en dweil gemorst water direct op: de vloer wordt glad.","Afwasmiddel prikt in de ogen en is niet om te drinken: een scheutje is genoeg en houd een doekje klaar.","Plakkaatverf vlekt op kleding en vloer: kies afwasbare kinderverf en werk op een knoeimat."],"say":["Vroem! Daar gaat hij!","Welk spoor is van de grote auto, denk je?","Ik zie een kronkelweg en een hele rechte lijn.","Wat gebeurt er als je twee keer door de verf rijdt?","Wat poets je die banden goed, ze zijn weer helemaal schoon!"],"words":["band","spoor","bocht","rechtdoor","snel","langzaam","poetsen"],"learn":["creativiteit","ontdekken","fijne-motoriek","taal"],"tips":["Kies auto’s zonder kleine openingen of losse onderdelen: opgedroogde verf krijg je daar moeilijk uit.","Zet de wasstraat op een handdoek of dienblad: zo blijft het water op één plek."],"variations":["Dierensporen: laat speelgoeddieren door de verf lopen. Wie maakt welke pootafdruk?","Wegenkaart: laat de sporen drogen en speel er de volgende dag op verder met schone auto’s.","Verkeerslicht: rijd alleen met rode, gele en groene verf en speel stoppen en rijden."],"themes":[]},
  {"id":"rolschilderij","title":"Rolschilderij in een doos","emoji":"🌰","category":"verven","summary":"Rol kastanjes of een balletje door klodders verf in een doos, kantel en schud: zo ontstaat een schilderij vol kronkelsporen.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":5,"durationMinutes":15,"supervision":2,"materials":[{"id":"dozen","note":"een schoenendoos met deksel"},{"id":"papier","note":"op maat geknipt voor de bodem"},{"id":"plakkaatverf","note":"2-3 kleuren"},{"id":"kastanjes","note":"3-5 stuks, alleen vanaf 3 jaar"},{"id":"lepel","note":"om de verf te scheppen"}],"optional":[{"id":"bal","note":"voor kinderen onder de 3: een balletje dat niet door een wc-rolletje past"},{"id":"schilderstape","note":"om de deksel dicht te plakken"},{"id":"oud-shirt"}],"steps":["Knip een vel papier op maat en leg het in de bodem van de doos.","Laat je kind met een lepel 3-4 klodders verf op het papier scheppen, verspreid over de bodem.","Leg 3 tot 5 kastanjes in de doos, of één balletje voor kinderen onder de 3, en doe de deksel erop.","Laat je kind de doos kantelen, schudden en draaien: hoor je de kastanjes rollen?","Kijk samen naar de sporen. Nog een kleur erbij? Deksel weer dicht en verder rollen.","Haal het vel er voorzichtig uit om plat te drogen en spoel de kastanjes af onder de kraan."],"ageTips":{"young":"Gebruik voor een tweejarige één grote bal in plaats van kastanjes en plak de deksel dicht met tape. Kantel samen: naar jou, naar mij, rollen maar!","old":"Een kleuter kan voorspellen waar de kleuren terechtkomen, met meer kastanjes en kleuren werken of het gedroogde vel knippen tot herfstbladeren of een kaart."},"safety":["Kastanjes zijn klein en giftig bij opeten: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Tel ze vooraf en na afloop.","Bij flink schudden kan verf langs de deksel spatten: plak de deksel dicht en werk op een knoeimat, want plakkaatverf vlekt."],"say":["Rollen! Hoor je ze?","Waar denk je dat de kastanjes heen gaan als je de doos zo kantelt?","Ik zie een lange rode streep, helemaal van hoek naar hoek.","Wat kantel je voorzichtig, de kastanjes blijven netjes in de doos!","Hoeveel kastanjes zitten erin? Tel je mee?"],"words":["rollen","kantelen","spoor","hoek","schudden","kastanje","kronkel"],"learn":["ontdekken","creativiteit","fijne-motoriek","rekenen"],"tips":["Geen kastanjes? Rol met stevige balletjes aluminiumfolie (vanaf 3 jaar): ook die maken mooie sporen.","Hoe minder verf, hoe scherper de sporen. Begin met kleine klodders en doe er later nog wat bij."],"variations":["Herfst: rol met bruin, oranje en rood en knip van het gedroogde vel bladeren of een egel.","Twee kleuren: doe geel aan de ene kant en blauw aan de andere, en kijk waar het groen wordt.","Grote rolbaan: leg een groot vel in een verhuisdoos en laat samen een bal heen en weer rollen."],"themes":["herfst"]},
  {"id":"toverzout","title":"Toverzout-schilderij","emoji":"🧂","category":"verven","summary":"Strooi zout op lijnen lijm en druppel er kleur op: kijk hoe de kleur als toverij door het zout wegloopt.","ageMin":3,"ageMax":5,"mess":2,"wet":true,"dirty":true,"prepMinutes":10,"durationMinutes":20,"supervision":2,"materials":[{"id":"karton","note":"stevig, bijvoorbeeld van een cornflakesdoos"},{"id":"knutsellijm","note":"witte hobbylijm, het liefst in een knijpflesje"},{"id":"zout","note":"fijn zout, een paar flinke el"},{"id":"waterverf","note":"goed nat gemaakt, of water met een paar druppels kleurstof"},{"id":"pipet","note":"of een kwast"},{"id":"dienblad","note":"om het zout op te vangen"}],"optional":[{"id":"kleurstof","note":"een paar druppels per bakje water, als je geen waterverf hebt"},{"id":"potjes","note":"een per kleur"},{"id":"potlood","note":"om eerst een tekening voor te tekenen"},{"id":"oud-shirt"}],"steps":["Teken met potlood een eenvoudige vorm op het karton, zoals een sneeuwvlok, een slinger of de naam van je kind.","Spuit dikke lijnen lijm over de tekening. Bij een driejarige doe jij dit, of je knijpt samen.","Leg het karton op een dienblad en laat je kind zout over de lijm strooien tot alles wit is.","Kantel het karton en tik het losse zout eraf op het dienblad.","Druppel met een pipet aangelengde waterverf op de zoutlijnen en kijk hoe de kleur wegloopt.","Laat het schilderij een nacht plat drogen: daarna glinstert het zout."],"ageTips":{"young":"Zet voor een driejarige zelf de lijnen lijm, laat je kind strooien met een theelepel en geef één pipet met één kleur. Knijpen en loslaten is al een hele klus.","old":"Een kleuter kan zelf lijm spuiten, de eigen naam of een sneeuwvlok, en plannen welke kleur waar komt. Wat gebeurt er waar twee kleuren elkaar raken?"},"safety":["Zout prikt in de ogen en in wondjes: niet in de ogen wrijven en handen wassen na afloop.","Knutsellijm is niet om te eten: houd de lijmfles bij je en zet hem daarna buiten bereik.","Waterverf en kleurstof vlekken: werk op een dienblad en trek een oud shirt aan."],"say":["Knijp! Daar gaat hij!","Waar denk je dat de blauwe druppel naartoe gaat?","Hoe voelt het zout tussen je vingers: korrelig of glad?","Ik zie dat je heel voorzichtig knijpt, druppel voor druppel.","Wat gebeurt er als rood en geel elkaar raken in het zout?"],"words":["korrelig","druppel","weglopen","zout","knijpen","glinsteren","lijn"],"learn":["ontdekken","fijne-motoriek","concentratie","creativiteit"],"tips":["Doe het zout in een klein bakje met een theelepel of in een strooibus: dan belandt het meeste op het karton.","Giet het losse zout van het dienblad terug in een bakje: je kunt het een volgende keer weer gebruiken, maar niet meer voor eten.","Dun papier krult van het water; stevig karton werkt veel beter."],"variations":["Winter: maak een sneeuwvlok of sterrenhemel op donkerblauw karton met witte en lichtblauwe druppels.","Naam in toverzout: schrijf de naam van je kind met lijm (dat doe jij) en geef elke letter een eigen kleur.","Vuurwerk: spuit sterren en stralen met lijm op zwart karton en druppel er felle kleuren op."],"themes":["winter"]},
  {"id":"tape-geheim","title":"Tape-geheimschilderij","emoji":"🤫","category":"verven","summary":"Plak figuren of een naam met schilderstape, verf eroverheen en trek de tape eraf als alles droog is: er verschijnt een wit geheim patroon.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":10,"durationMinutes":20,"supervision":2,"materials":[{"id":"schilderstape","note":"een rol, liefst niet te smal"},{"id":"karton","note":"of dik papier: dun papier scheurt als je de tape lostrekt"},{"id":"plakkaatverf","note":"of waterverf, een paar kleuren"},{"id":"penselen","note":"dikke kwasten"}],"optional":[{"id":"sponsjes","note":"om grote vlakken te deppen"},{"id":"oud-shirt"}],"steps":["Plak strookjes tape op het karton: een ster, een huisje, strepen of de eerste letter van de naam. Wrijf de randen goed aan.","Laat je kind het hele vel beschilderen, ook over de tape heen, in zoveel kleuren als het wil.","Laat de verf helemaal drogen, een half uur tot een uur. Ga intussen iets anders doen.","Trek samen de tape eraf, langzaam en schuin: daar is het geheim!","Bekijk het witte patroon samen en raad wat het is, of bedenk er een naam voor."],"ageTips":{"young":"Een tweejarige vindt tape plakken en lostrekken al geweldig. Vouw aan elk stuk tape een puntje om, dan pakt je kind het makkelijker, en laat je kind met een sponsje grote vlakken verven.","old":"Een kleuter plakt zelf een figuur, de letters van de eigen naam of een weg met kruispunten, en bedenkt welke kleur in welk vlak komt."},"safety":["Losgetrokken tape plakt aan vingers en belandt zo in de mond: gooi propjes meteen in een bakje.","Plakkaatverf vlekt op kleding en tafel: kies afwasbare kinderverf en werk op een knoeimat."],"say":["Trek! Wat zit eronder?","Waar denk je dat de tape zit, nu alles geverfd is?","Ik zie een witte ster tussen al dat blauw!","Wat trek je de tape voorzichtig los, daardoor scheurt het karton niet.","Welke kleuren wil je over de tape heen schilderen?"],"words":["geheim","tape","plakken","lostrekken","onder","verschijnen","wit"],"learn":["fijne-motoriek","creativiteit","ontdekken"],"tips":["Trek de tape pas los als de verf droog is, anders lopen de kleuren in de witte lijnen. Een föhn op lage stand (dat doe jij) helpt bij een ongeduldig kind.","Plak de tape eerst even op je broek: dan plakt hij minder hard en scheurt het karton niet bij het lostrekken."],"variations":["Naambordje: plak de letters van de naam met tape, verf eroverheen en hang het op de kamerdeur.","Winter: plak sneeuwvlokken van drie gekruiste stroken en verf eroverheen in blauw en paars.","Stad: plak wegen en kruispunten, verf de vlakken als huizenblokken en rijd daarna met autootjes over de witte wegen."],"themes":[]},
  {"id":"geheime-tekening","title":"Geheime tekening met wit krijt","emoji":"🔍","category":"verven","summary":"Jij tekent onzichtbaar met wit waskrijt, je kind schildert er waterverf overheen en zie: de geheime tekening verschijnt.","ageMin":3,"ageMax":5,"mess":2,"wet":true,"dirty":true,"prepMinutes":5,"durationMinutes":15,"supervision":2,"materials":[{"id":"waskrijt","note":"een wit krijtje, of een stompje kaars"},{"id":"papier","note":"stevig wit papier"},{"id":"waterverf","note":"donkere kleuren werken het best"},{"id":"penselen","note":"een dikke kwast"},{"id":"water","note":"een bakje om de kwast in te spoelen"}],"optional":[{"id":"kleurstof","note":"een paar druppels in water, als je geen waterverf hebt"},{"id":"keukenpapier","note":"om natte plassen te deppen"},{"id":"oud-shirt"}],"steps":["Teken met wit waskrijt een geheime tekening op wit papier: een zon, een spookje, een hartje of de naam van je kind. Druk flink.","Maak de waterverf goed nat, of meng een paar druppels kleurstof met water in een bakje.","Geef het ‘lege’ vel aan je kind en vraag: zou er iets op staan?","Laat je kind met brede halen over het hele vel schilderen. Het waskrijt stoot de verf af, dus de tekening verschijnt.","Raad samen wat het is, en draai de rollen om: nu tekent je kind een geheim voor jou.","Laat het vel plat drogen op een handdoek of krant."],"ageTips":{"young":"Teken voor een driejarige grote, dikke vormen en druk flink, zodat de verrassing goed zichtbaar wordt. Gebruik donkere verf, zoals blauw of paars.","old":"Een kleuter tekent zelf een geheim voor een broertje, zusje of voor jou. Of jij schrijft een boodschap van twee woorden: herkent je kind de letters?"},"safety":["Gebruik je een stompje kaars als krijt, steek het dan niet aan en leg aanstekers en lucifers buiten bereik.","Waterverf en kleurstof vlekken op kleding en tafel: leg een knoeimat neer en trek een oud shirt aan."],"say":["Kijk! Daar komt iets!","Wat denk je dat er op dit lege vel staat?","Ik zie een rondje… en nu stralen. Wat zou het zijn?","Je schildert met grote halen over het hele vel, zo vind je het geheim.","Wil jij nu een geheim voor mij tekenen?"],"words":["geheim","onzichtbaar","tevoorschijn","krijt","verf","raden","verrassing"],"learn":["ontdekken","taal","creativiteit","samen"],"tips":["Druk stevig met het krijt en gebruik waterige, donkere verf: dan zie je de tekening het best.","Maak er een paar van tevoren, dan heb je meteen een stapeltje klaar als je kind om meer vraagt."],"variations":["Sinterklaas: Sinterklaas laat een geheime tekening achter bij de schoen. Schildert je kind eroverheen, dan verschijnt er een mijter, een paard of een cadeautje.","Halloween: teken spookjes, een pompoen of een vleermuis en laat je kind er met paarse of zwarte verf overheen schilderen.","Schattenjacht: verstop een paar geheime tekeningen in huis, elk met een getekende aanwijzing naar de volgende."],"themes":["sinterklaas","halloween"]},
  {"id":"ijsverf","title":"Schilderen met ijsverf","emoji":"🧊","category":"verven","summary":"Bevroren verfblokjes op een stokje glijden over het papier en smelten tot heldere kleuren: koel schilderen voor warme dagen.","ageMin":1,"ageMax":5,"mess":3,"wet":true,"dirty":true,"prepMinutes":10,"durationMinutes":20,"supervision":2,"materials":[{"id":"ijsblokjesvorm","note":"of een muffinvorm, voor grotere blokken"},{"id":"kleurstof","note":"een paar druppels per vakje"},{"id":"water","note":"koud, ongeveer 2 el per vakje"},{"id":"ijsstokjes","note":"een per vakje"},{"id":"huishoudfolie","note":"strak over de vorm, zodat de stokjes rechtop blijven"},{"id":"vriezer","note":"minstens 4 uur, liefst een nacht"},{"id":"papier","note":"stevig wit papier of karton"}],"optional":[{"id":"plakkaatverf","note":"een tl per vakje, voor fellere kleuren"},{"id":"fruit","note":"geprakte aardbeien of bessen met wat water, voor proefbare ijsverf"},{"id":"dienblad","note":"om op te schilderen, vangt het smeltwater op"},{"id":"oud-shirt"}],"steps":["Vul elk vakje van de vorm voor driekwart met water en roer er een paar druppels kleurstof of een tl verf door.","Span huishoudfolie strak over de vorm en prik door de folie in elk vakje een ijsstokje: zo blijft het rechtop staan.","Zet de vorm minstens 4 uur in de vriezer, liefst een nacht.","Laat de vorm vijf minuten op het aanrecht staan of houd de onderkant even onder de warme kraan: dan wippen de blokjes er makkelijk uit.","Leg een vel stevig papier op een dienblad en laat je kind schilderen met de ijsblokjes: eerst gebeurt er niets, dan smelt de kleur.","Leg de blokjes na afloop in een bakje en laat het vel plat drogen."],"ageTips":{"young":"Maak voor je dreumes ijsverf van geprakt fruit met wat water: dan mag likken. Kies een muffinvorm voor grote blokken die goed in een knuistje passen.","old":"Een kleuter kan kleuren mengen (wat gebeurt er als geel over blauw gaat?), tellen hoe lang het duurt voor een blokje gesmolten is of een zomers schilderij maken van zon en zee."},"safety":["IJsverf met kleurstof of plakkaatverf is niet om op te zuigen: geef kinderen die alles in hun mond stoppen alleen ijsverf van fruit.","Laat je dreumes niet op het ijs bijten: een los brokje ijs kan in de keel schieten. Blijf erbij.","IJs dat net uit de vriezer komt, kan aan vingers en lippen plakken: laat de blokjes eerst een paar minuten ontdooien.","Gekleurd smeltwater vlekt en maakt de vloer glad: werk op een dienblad, dweil gemorst water direct op en laat een jong kind er niet alleen mee."],"say":["Koud! Brrr!","Kijk, de kleur komt pas als het ijs smelt.","Wat denk je: smelt het ijs sneller in je hand of op het papier?","Hoe voelt het: koud, nat, glad?","Je laat het blokje steeds nieuwe rondjes draaien, wat werk je geduldig!"],"words":["koud","ijs","smelten","glad","nat","druppelen","bevroren"],"learn":["zintuigen","ontdekken","creativiteit"],"tips":["Maak de ijsverf de avond van tevoren: dan is hij precies klaar als je kind ernaar vraagt.","Met een tl plakkaatverf per vakje worden de kleuren feller dan met alleen kleurstof.","Schilder in de lege badkuip of op een dienblad: het smeltwater loopt dan niet van tafel."],"variations":["Zomer: schilder een zon, de zee of een ijsje en kijk hoe snel het ijs in de warmte smelt.","Bloemenijs: vries in elk vakje een bloemblaadje mee en kijk wat er tevoorschijn komt als het smelt.","Grote ijsverf: vries een bakje gekleurd water in en schilder samen op een groot vel."],"themes":["zomer"]},
  {"id":"blaasmonsters","title":"Blaasmonsters met een rietje","emoji":"👾","category":"verven","summary":"Druppel waterige verf op papier en blaas hem met een rietje alle kanten op: zo groeien er wilde monsterpoten en -haren.","ageMin":3,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":5,"durationMinutes":15,"supervision":2,"materials":[{"id":"plakkaatverf","note":"aangelengd met water tot hij zo dun is als melk"},{"id":"water","note":"om de verf dun te maken"},{"id":"bakjes","note":"een per kleur"},{"id":"rietjes","note":"een per kind, een dik rietje blaast het makkelijkst"},{"id":"papier","note":"stevig wit of gekleurd papier"}],"optional":[{"id":"pipet","note":"om druppels te maken (anders een lepel)"},{"id":"stiften","note":"voor ogen, mond en tanden"},{"id":"wiebeloogjes","note":"vanaf 3 jaar, uit de buurt van jongere kinderen"},{"id":"oud-shirt"}],"steps":["Oefen eerst zonder verf: blaas door een rietje op je hand of blaas een propje papier over tafel. Blazen, niet zuigen!","Maak de verf in een bakje dun met water, ongeveer half om half, tot hij zo dun is als melk.","Druppel met een lepel of pipet een flinke druppel verf op het papier.","Laat je kind het rietje vlak boven de druppel houden en hard blazen: de verf schiet alle kanten op.","Draai het vel en blaas opnieuw, of druppel een tweede kleur ernaast.","Laat het monster drogen en teken er met stift ogen, een mond en tanden op."],"ageTips":{"young":"Een driejarige zuigt nog weleens per ongeluk. Knip een klein sneetje vlak onder de bovenkant van het rietje, dan zuigt je kind lucht in plaats van verf. Of blaas om de beurt: eerst jij, dan je kind.","old":"Een kleuter kan bedenken wat voor monster het is: hoe heet hij, wat eet hij, waar woont hij? Schrijf het verhaal erbij of maak een hele monsterfamilie."},"safety":["Blazen, niet zuigen: houd het rietje boven de druppel en niet erin. Plakkaatverf is niet om in te slikken.","Van veel hard blazen kun je duizelig worden: neem af en toe samen een pauze.","Wiebeloogjes zijn klein: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Houd ze uit de buurt van jongere broertjes of zusjes."],"say":["Blazen! Harder!","Waar denk je dat de verf naartoe rent als je van deze kant blaast?","Ik zie een monster met wel tien poten!","Hoe heet jouw monster? Wat eet hij graag?","Wat blaas je lang achter elkaar, knap volgehouden!"],"words":["blazen","rietje","druppel","spetter","monster","harig","griezelig"],"learn":["creativiteit","ontdekken","taal"],"tips":["Hoe dunner de verf, hoe verder hij rent. Is de verf te dik, doe er dan een scheutje water bij.","Leg het vel op een dienblad: dan blijft de verf die van het papier rent op het blad."],"variations":["Halloween: blaas zwarte en paarse verf op oranje papier en maak er spinnen of vleermuizen van.","Herfstboom: blaas bruine verf omhoog tot takken en stip er met een vingertop rode en gele blaadjes aan.","Vuurwerk: blaas felle kleuren vanuit één punt naar buiten op zwart papier."],"themes":["halloween"]},
  {"id":"vouwvlinder","title":"Vlinder-vouwschilderij","emoji":"🦋","category":"verven","summary":"Klodders verf op één helft, dubbelvouwen, stevig aandrukken en open: er verschijnt een vlinder met twee precies dezelfde vleugels.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":5,"durationMinutes":15,"supervision":2,"materials":[{"id":"papier","note":"wit of gekleurd, A4"},{"id":"plakkaatverf","note":"2-4 kleuren, niet te waterig"},{"id":"lepel","note":"of een kwast, om klodders te maken"}],"optional":[{"id":"potlood","note":"om vooraf een halve vlinder te tekenen"},{"id":"schaar","note":"om de vlindervorm uit te knippen (dat doe jij)"},{"id":"kinderschaar","note":"voor kleuters die zelf knippen"},{"id":"stiften","note":"voor een lijfje en voelsprieten"},{"id":"oud-shirt"}],"steps":["Vouw een vel papier dubbel en weer open: de vouw wordt het lijfje van de vlinder.","Laat je kind met een lepel of kwast klodders en stippen verf op één helft zetten, dicht bij de vouw.","Vouw het vel dicht en laat je kind er met platte handen overheen wrijven, van de vouw naar buiten.","Vouw het samen langzaam open: kijk, twee dezelfde vleugels!","Laat het drogen en knip er eventueel een vlindervorm uit. Teken met stift een lijfje en voelsprieten."],"ageTips":{"young":"Een tweejarige laat het vouwen aan jou over, maar wrijven en openvouwen is het spannendste. Geef één of twee kleuren en een lepel in plaats van een kwast.","old":"Een kleuter kan voorspellen waar de kleuren terechtkomen, zelf de vlindervorm knippen met een kinderschaar of een hele rij vlinders maken voor het raam."},"safety":["Plakkaatverf vlekt op kleding en tafel: kies afwasbare kinderverf en werk op een knoeimat.","Het uitknippen doe jij, of je kleuter met een kinderschaar met ronde punt."],"say":["Wrijf, wrijf! En open!","Wat denk je dat er gebeurt als we het papier openvouwen?","Ik zie aan deze kant een rode stip, en aan die kant ook!","Welke kleuren krijgt jouw vlinder?","Je wreef zo stevig, daardoor zijn de vleugels helemaal gevuld."],"words":["vouwen","openvouwen","hetzelfde","spiegelbeeld","vleugel","vlinder","helft"],"learn":["ontdekken","creativiteit","rekenen","fijne-motoriek"],"tips":["Zet de klodders dicht bij de vouw: verf aan de buitenrand loopt er bij het aandrukken snel uit.","Teken vooraf met potlood een halve vlinder tegen de vouw aan: dan weet je kind waar de verf mag."],"variations":["Lente: maak een hele zwerm en plak de vlinders tegen het raam.","Spiegelmonster: hetzelfde trucje, maar teken er daarna ogen, tanden en voelsprieten op.","Lieveheersbeestje: alleen rode verf met zwarte stippen, en knip er een rondje uit."],"themes":["lente"]},
  {"id":"handafdrukken","title":"Hand- en voetafdrukken als cadeautje","emoji":"✋","category":"verven","summary":"Een handje wordt een vogel, een voetje een pinguïn: maak samen afdrukken en tover ze om tot een cadeautje om te bewaren.","ageMin":1,"ageMax":5,"mess":3,"wet":false,"dirty":true,"prepMinutes":10,"durationMinutes":15,"supervision":1,"materials":[{"id":"plakkaatverf","note":"afwasbare kinderverf, 1-3 kleuren"},{"id":"penselen","note":"een dikke kwast"},{"id":"karton","note":"stevig, wit of gekleurd, of een dubbelgevouwen kaart"},{"id":"stiften","note":"een zwarte stift om de afdruk om te toveren"},{"id":"kom","note":"met lauw water, om meteen te wassen"},{"id":"doekje","note":"en een handdoek om af te drogen"}],"optional":[{"id":"oud-laken","note":"als knoeimat"},{"id":"oud-shirt"}],"steps":["Zet alles vooraf klaar: karton, verf, een kwast, en een kom lauw water met een doekje en handdoek ernaast.","Schilder de handpalm of voetzool van je kind met een dun, gelijkmatig laagje verf. Dat kriebelt!","Druk het handje met gespreide vingers stevig op het karton, druk elke vinger even aan en til het recht omhoog.","Was handje of voetje meteen in de kom met water, voordat je kind ergens anders aan zit.","Laat de afdruk drogen en tover hem samen om met stift: een vogel, een boom, een bloem of een rendier.","Schrijf de naam en de datum erbij: over een paar jaar zie je hoe klein dat handje was."],"ageTips":{"young":"Doe het bij je dreumes snel, op een moment dat je kind uitgerust is, en liefst met z’n tweeën: één houdt vast, één verft. Een voetafdruk lukt vaak makkelijker dan een handje dat steeds dichtknijpt.","old":"Een kleuter verft de eigen hand, bedenkt zelf wat de afdruk wordt en tekent de details. Of leg handafdrukken van het hele gezin naast elkaar: wie heeft de grootste?"},"safety":["Gebruik afwasbare kinderverf: verf hoort niet in de mond, en een dreumes stopt een hand er zo in. Was handjes meteen na de afdruk.","Een verfvoetje is spekglad: laat je kind zitten tijdens de voetafdruk en til het daarna naar de kom water.","Verf vlekt op kleding, vloerkleed en voegen: werk op een knoeimat en trek oude kleren aan."],"say":["Kriebel kriebel! Klaar? Druk!","Hoe voelt de verf op je hand: koud en glibberig?","Kijk, daar is jouw handje, met vijf vingers!","Wat zou je handje kunnen worden: een vogel, een vis of een boom?","Wat hield je je hand goed stil, daardoor is de afdruk zo duidelijk."],"words":["hand","voet","vinger","teen","afdruk","kriebelen","stil"],"learn":["zintuigen","taal","creativiteit","rekenen"],"tips":["Lukt het niet in één keer? Vegen, wassen en nog eens: leg alvast twee of drie vellen klaar.","Druk op stevig karton of een gevouwen kaart in plaats van dun papier: dat krult niet en kun je zo inlijsten.","Doe het vlak voor badtijd: dan is schoonmaken meteen geregeld."],"variations":["Moederdag: een bos bloemen van handafdrukken, met getekende steeltjes en een kaartje erbij.","Vaderdag: een zwarte voetafdruk met een witte buik en een getekende snavel wordt een stoere pinguïn.","Kerst: een groene handafdruk ondersteboven wordt een kerstboom, en een bruine voetafdruk met twee handjes als gewei een rendier.","Groeikalender: maak elk jaar op dezelfde dag een afdruk en bewaar ze samen."],"themes":["moederdag","vaderdag","cadeau","kerst"]},
  {"id":"wattenstaafjes-stippen","title":"Stippen met wattenstaafjes","emoji":"🐞","category":"verven","summary":"Dippen, stippen, nog een stip: met wattenstaafjes maak je een boom vol herfstblaadjes, bloesem of sneeuw, of een lieveheersbeestje.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":5,"durationMinutes":20,"supervision":2,"materials":[{"id":"wattenstaafjes","note":"een per kleur"},{"id":"plakkaatverf","note":"2-4 kleuren op een bord"},{"id":"papier","note":"wit of gekleurd"},{"id":"stiften","note":"om vooraf een boomstam of lieveheersbeestje te tekenen"}],"optional":[{"id":"elastiekjes","note":"om 5-6 wattenstaafjes te bundelen, voor kleine handjes"},{"id":"gekleurd-papier","note":"donkerblauw voor een sneeuwboom"},{"id":"oud-shirt"}],"steps":["Teken met stift een boomstam met takken, of een groot rondje met een streep erdoor voor een lieveheersbeestje.","Doe kleine klodders verf op een bord en leg bij elke kleur een eigen wattenstaafje.","Laat je kind het wattenstaafje rechtop in de verf dippen en stippen zetten: tik, tik, tik.","Stip de boom vol blaadjes, bloesem of sneeuw. Voor een lieveheersbeestje: eerst rood stippen, en als dat droog is zwarte stippen erop.","Tel samen de stippen of zoek de grootste en de kleinste stip.","Laat het plat drogen en gooi de gebruikte wattenstaafjes weg."],"ageTips":{"young":"Een tweejarige houdt een bundeltje van 5-6 wattenstaafjes met een elastiekje erom makkelijker vast, en dat maakt grote, vrolijke stippen. Het elastiekje doe jij om.","old":"Een kleuter kan een patroon stippen (rood, geel, rood), de stippen tellen of een letter of cijfer van stippen maken. Ook een uitdaging: alleen binnen de lijnen stippen."},"safety":["Elastiekjes zijn klein en kunnen terugschieten: doe het elastiekje zelf om het bundeltje en houd het in de gaten. Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3.","Wattenstaafjes horen niet in oren of neus: geef ze alleen aan tafel en ruim ze na afloop op.","Plakkaatverf vlekt op kleding en tafel: kies afwasbare kinderverf."],"say":["Tik! Nog een stip!","Hoeveel stippen heeft jouw lieveheersbeestje al?","Ik zie rode, gele en oranje blaadjes aan de boom.","Wat stip je precies, steeds op een nieuw plekje!","Wat gebeurt er als je heel zachtjes tikt? En heel hard?"],"words":["stip","tikken","boom","blaadje","veel","weinig","rij"],"learn":["fijne-motoriek","rekenen","concentratie","creativiteit"],"tips":["Geef elke kleur een eigen wattenstaafje: dan blijven de kleuren apart en hoef je minder bij te vullen.","Geen wattenstaafjes? Een vingertop of de gum achter op een potlood stipt ook prima."],"variations":["Herfst: een boom vol rode, oranje en gele stippen, met een paar gevallen blaadjes eronder.","Lente: roze en witte stippen worden een bloesemboom.","Winter: witte stippen op donkerblauw papier worden een sneeuwboom of een sneeuwbui boven een huisje."],"themes":["herfst","winter","lente"]},
  {"id":"keukenla-kwasten","title":"Verven met spullen uit de keukenla","emoji":"🥄","category":"verven","summary":"Een garde, een vork of een aardappelstamper als kwast: ontdek samen welke sporen al die keukenspullen maken op een groot vel.","ageMin":1,"ageMax":5,"mess":3,"wet":false,"dirty":true,"prepMinutes":5,"durationMinutes":20,"supervision":2,"materials":[{"id":"plakkaatverf","note":"2-3 kleuren, een flinke laag op een bord"},{"id":"groot-papier","note":"met tape vastgeplakt op tafel of vloer"},{"id":"schilderstape","note":"om het papier vast te plakken"},{"id":"garde","note":"een kleine garde"},{"id":"vork","note":"liefst een plastic vork"},{"id":"sponsjes","note":"een droog keukensponsje"},{"id":"bord","note":"een groot bord per kleur"}],"optional":[{"id":"tandenborstel","note":"of een afwasborstel"},{"id":"oud-laken","note":"als knoeimat"},{"id":"oud-shirt"}],"steps":["Plak een groot vel papier met schilderstape vast en leg er een knoeimat onder.","Zoek samen in de keukenla naar ‘kwasten’: een garde, een vork, een aardappelstamper, een sponsje, een borstel.","Doe een laagje verf op een paar grote borden, zo breed dat het keukengerei er goed in past.","Laat je kind elk ding in de verf dopen en ermee stempelen, slepen of draaien.","Vergelijk de sporen: welke maakt strepen, welke stippen, en welke rondjes?","Laat het vel drogen en zet het keukengerei meteen in een bak sopje om te weken. Was het daarna goed af."],"ageTips":{"young":"Geef je dreumes grote, stevige spullen met een dik handvat, zoals een aardappelstamper of afwasborstel. Eén ding tegelijk, en jij doet mee: klop, klop!","old":"Een kleuter kan raden welk ding welk spoor maakte, een patroon stempelen of er een tekening van maken: met de vork gras, met de garde bloemen."},"safety":["Laat messen, de rasp en de kaasschaaf in de la: zoek samen alleen spullen zonder scherpe randen.","Was het keukengerei na afloop goed af voor het weer met eten in aanraking komt, of houd een paar oude spullen apart voor knutselen.","Plakkaatverf vlekt op kleding, tafel en vloer: kies afwasbare kinderverf en werk op een knoeimat."],"say":["Klop! Kijk eens!","Wat denk je dat de garde maakt: strepen of rondjes?","Ik zie dunne lijntjes van de vork, net gras.","Welk ding uit de la gaan we nu proberen?","Je probeert alles uit, echt een onderzoeker!"],"words":["garde","vork","stempelen","streep","stip","slepen","draaien"],"learn":["ontdekken","creativiteit","fijne-motoriek","taal"],"tips":["Laat alles na afloop even weken in een bak sopje: opgedroogde verf krijg je moeilijk uit een garde.","Koop bij de kringloopwinkel een paar goedkope keukenspullen die alleen voor knutselen zijn."],"variations":["Herfst: sleep met een vork bruine takken en stempel er met een sponsje rode en gele blaadjes aan.","Badkamerla: verf met een oude tandenborstel, een haarborstel en een kam.","Speelgoedkist: stempel met duplo, autobandjes en de pootjes van speelgoeddieren."],"themes":[]},
  {"id":"waterschilderen","title":"Schilderen met alleen water","emoji":"💧","category":"verven","summary":"Een dikke kwast en een bakje water: verf de tegels, een schoolbord of bruin karton donker en kijk hoe het als toverij weer verdwijnt.","ageMin":1,"ageMax":4,"mess":1,"wet":true,"dirty":false,"prepMinutes":2,"durationMinutes":15,"supervision":2,"materials":[{"id":"penselen","note":"een dikke kwast, of een kleine verfroller"},{"id":"water","note":"een laagje van een paar centimeter"},{"id":"kom","note":"of een plastic beker, niet te vol"}],"optional":[{"id":"badkuip","note":"verf op de tegels in de lege badkuip of douche"},{"id":"dozen","note":"een opengevouwen bruine doos: wordt donker en droogt weer op"},{"id":"sponsjes","note":"voor brede natte banen"},{"id":"handdoek","note":"onder het bakje en om af te drogen"}],"steps":["Kies een plek: de tegels in de lege douche of badkuip, een schoolbord, of een opengevouwen bruine doos op de vloer.","Doe een laagje water van een paar centimeter in een bakje of beker.","Geef je kind een dikke kwast en laat het de tegels, het bord of het karton ‘verven’.","Kijk samen hoe het donker wordt waar de kwast komt, en hoe het na een tijdje weer opdroogt: weg is de tekening!","Schilder om de beurt een streep, een rondje of een gezichtje en wacht tot het verdwijnt.","Droog de vloer na afloop meteen af met een handdoek."],"ageTips":{"young":"Geef je dreumes een korte, dikke kwast of een sponsje en een bakje met een heel klein laagje water. Zitten in de lege douche of op een handdoek op de vloer werkt het best.","old":"Een vierjarige kan vormen, letters of de eigen naam ‘schrijven’ en kijken welke het eerst opdroogt. Of verf samen een hele tegelwand: lukt het voordat de eerste tegel droog is?"},"safety":["Laat een jong kind nooit alleen bij water, ook niet bij een laagje in een bakje of in de lege badkuip.","Gemorst water maakt tegels en vloer glad: dweil het direct op en laat je kind in de badkuip zitten in plaats van staan."],"say":["Nat! Kijk, donker!","Waar is je streep gebleven?","Ik zie dat het karton donker wordt waar de kwast komt.","Wat denk je: droogt een grote of een kleine vlek het eerst op?","Wat schilder je lekker door, alle tegels zijn al nat!"],"words":["nat","droog","donker","licht","verdwijnen","kwast","druppel"],"learn":["ontdekken","grove-motoriek","zintuigen","taal"],"tips":["Doe het vlak voor badtijd in de lege badkuip: je kind kan daarna zo in bad.","Een kleine verfroller of een oud sponsje maakt brede banen: ideaal voor kleine handjes die nog niet precies schilderen."],"variations":["Zomer: zet de bruine doos bij een zonnig raam en kijk hoe snel het water daar opdroogt.","Raadspel: schilder een simpele vorm en laat je kind raden wat het is voordat hij opdroogt.","Vingerschilderen: doop alleen een vinger in het water en teken op een schoolbord of op de tegels."],"themes":["zomer"]},
  {"id":"vuurwerk-schilderij","title":"Vuurwerkschilderij met wc-rollen","emoji":"🎆","category":"verven","summary":"Knip een wc-rolletje in tot franjes, doop het in felle verf en stempel op donker papier: boem, daar gaat je eigen vuurwerk!","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":5,"durationMinutes":15,"supervision":2,"materials":[{"id":"wc-rollen","note":"2-3 lege rolletjes"},{"id":"schaar","note":"voor jou, om franjes te knippen"},{"id":"plakkaatverf","note":"felle kleuren: geel, rood, roze en wit"},{"id":"gekleurd-papier","note":"zwart of donkerblauw"},{"id":"bord","note":"een plat bord per kleur"}],"optional":[{"id":"kinderschaar","note":"voor kleuters die zelf franjes knippen"},{"id":"wattenstaafjes","note":"voor vonkjes tussen het vuurwerk"},{"id":"oud-shirt"}],"steps":["Knip een rolletje aan één kant rondom in tot halverwege, in stroken van ongeveer een halve centimeter (dat doe jij).","Buig de franjes naar buiten tot een platte bloem of zon.","Doe een laagje felle verf op een paar borden, met per kleur een eigen rolletje.","Laat je kind de franjes in de verf dopen en op het donkere papier drukken: boem, vuurwerk!","Stempel verschillende kleuren over elkaar heen en zet met een wattenstaafje vonkjes eromheen.","Laat het plat drogen en hang het op tegen oud en nieuw."],"ageTips":{"young":"Een tweejarige drukt vooral graag: houd het bij één rolletje en één kleur en roep samen ‘boem!’ bij elke stempel.","old":"Een kleuter knipt zelf de franjes met een kinderschaar, telt af van tien tot nul voor elke stempel of maakt een hele vuurwerkshow boven een getekende stad."},"safety":["Het inknippen doe jij, of je kleuter met een kinderschaar met ronde punt.","Plakkaatverf vlekt op kleding en tafel: kies afwasbare kinderverf en werk op een knoeimat."],"say":["Boem! Nog een!","Welke kleur vuurwerk maken we nu?","Ik zie een gele ster met roze stralen eromheen.","Tellen we af? Drie, twee, één… boem!","Wat druk je stevig, alle franjes staan erop!"],"words":["vuurwerk","knal","franje","stralen","fel","donker","aftellen"],"learn":["creativiteit","fijne-motoriek","rekenen"],"tips":["Felle verf op donker papier geeft het meeste effect. Dekt een kleur niet goed, meng er dan een beetje wit door.","Gebruik de rolletjes een paar keer achter elkaar zonder af te spoelen: kleuren die mengen geven juist vrolijk vuurwerk."],"variations":["Oud en nieuw: maak er een nieuwjaarskaart van voor opa en oma.","Verjaardag: stempel vuurwerk op een groot vel als feestelijke versiering.","Lente: dezelfde franjestempel in roze en geel op wit papier wordt een veld vol bloemen."],"themes":["oudennieuw"]},
  {"id":"inpakpapier-stempelen","title":"Zelf inpakpapier stempelen","emoji":"🎁","category":"verven","summary":"Stempel een groot vel bruin papier vol met sponsjes, kurken en vormpjes: zo pak je cadeautjes in met papier dat je zelf hebt gemaakt.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":10,"durationMinutes":25,"supervision":2,"materials":[{"id":"groot-papier","note":"bruin pakpapier of de achterkant van oud behang"},{"id":"plakkaatverf","note":"2-3 kleuren, op borden"},{"id":"sponsjes","note":"in eenvoudige vormen geknipt"},{"id":"schaar","note":"voor jou, om de sponsjes te knippen"},{"id":"schilderstape","note":"om het vel vast te plakken"}],"optional":[{"id":"kurken","note":"voor stippen"},{"id":"wc-rollen","note":"voor rondjes"},{"id":"uitsteekvormpjes","note":"liefst plastic; doop de rand in de verf"},{"id":"wasknijpers","note":"als handvat voor een sponsje"},{"id":"oud-laken","note":"als knoeimat"}],"steps":["Knip een paar sponsjes in eenvoudige vormen, zoals een ster, hartje of driehoek (dat doe jij).","Plak een groot vel bruin papier met schilderstape vast op tafel of vloer.","Doe een dun laagje verf op een paar borden en leg de stempels ernaast: sponsjes, kurken, wc-rolletjes en uitsteekvormpjes.","Laat je kind het vel vol stempelen, kriskras of in rijen.","Laat het vel een paar uur plat drogen en pak er daarna samen een cadeautje mee in."],"ageTips":{"young":"Geef een tweejarige grote stempels met een handvat, zoals een wc-rolletje of een sponsje in een wasknijper, en één kleur per keer. Kriskras stempelen is prima.","old":"Een kleuter kan een patroon bedenken (ster, ster, hart), in rijen stempelen of het papier ontwerpen voor iemand speciaal: welke kleuren vindt opa mooi?"},"safety":["Kurken en kleine vormpjes passen door een wc-rolletje en zijn dus te klein voor kinderen onder de 3: houd ze bij je en tel ze na afloop.","Metalen uitsteekvormpjes hebben een scherpe rand: kies liever plastic vormpjes.","Plakkaatverf vlekt op kleding en tafel: kies afwasbare kinderverf en leg een knoeimat neer."],"say":["Stempel! Nog een!","Welke vorm wil je nu stempelen?","Ik zie sterren, stippen en rondjes door elkaar.","Voor wie maken we dit papier? Wat zou die persoon leuk vinden?","Wat werk je goed door, het hele vel is al bijna vol!"],"words":["stempel","ster","rondje","stip","rij","inpakken","cadeau"],"learn":["creativiteit","fijne-motoriek","rekenen","samen"],"tips":["Pakpapier, oud behang of een opengeknipte papieren tas is goedkoop en beter voor het milieu dan glanzend cadeaupapier.","Stempel een paar dagen van tevoren: de verf moet helemaal droog zijn voor je gaat inpakken."],"variations":["Sinterklaas: stempel mijters, sterren en pepernoten (vingertopstippen) en pak er de cadeautjes mee in.","Kerst: groene kerstboompjes en gele sterren op bruin papier, of witte sneeuwvlokken op rood papier.","Verjaardag: stempel ballonnen met een wc-rolletje en teken er touwtjes onder.","Cadeaulabel: stempel ook een klein stukje karton en schrijf er de naam op."],"themes":["sinterklaas","kerst","verjaardag","cadeau"]},
  {"id":"kerstkaart-vingerafdruk","title":"Kerstkaarten met vingerafdruk-lampjes","emoji":"🎄","category":"verven","summary":"Een zwarte stiftlijn wordt een snoer, vingertoppen drukken er gekleurde lampjes aan: zo maak je samen een stralende kerstkaart.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":10,"durationMinutes":15,"supervision":2,"materials":[{"id":"karton","note":"stevig wit karton, dubbelgevouwen tot een kaart"},{"id":"stiften","note":"een zwarte stift voor het snoer"},{"id":"plakkaatverf","note":"3-4 felle kleuren, kleine klodders op een bord"},{"id":"doekje","note":"om vingers tussen de kleuren af te vegen"}],"optional":[{"id":"enveloppen","note":"om de kaart te versturen"},{"id":"wattenstaafjes","note":"als je kind liever niet met de vingers verft"},{"id":"oud-shirt"}],"steps":["Vouw een stuk karton dubbel tot een kaart en teken er met zwarte stift een golvende lijn overheen: het snoer.","Doe kleine klodders verf op een bord, elke kleur apart.","Laat je kind een vingertop in de verf dopen en een afdruk zetten langs de lijn: een lampje!","Veeg de vinger af aan een doekje en kies de volgende kleur. Wissel af: rood, geel, groen, blauw.","Teken na het drogen met stift een fitting op elk lampje en kleine streepjes eromheen: zo gaan ze stralen.","Schrijf samen een wens in de kaart en doe hem op de post."],"ageTips":{"young":"Pak bij een tweejarige het handje vast, steek samen één vinger uit en druk samen. Een paar lampjes is genoeg: het drukken is het leukste.","old":"Een kleuter maakt een kleurpatroon langs het snoer, telt de lampjes of tekent zelf het snoer en de fittingen. Probeer ook sneeuwpoppen of rendieren van vingerafdrukken."},"safety":["Plakkaatverf vlekt op kleding en tafel: kies afwasbare kinderverf en veeg vingers tussendoor af aan een doekje.","Laat glitter liever weg bij jonge kinderen (ogen, mond): een gouden of zilveren stift geeft ook glans."],"say":["Druk! Een lampje!","Welke kleur krijgt het volgende lampje?","Ik zie een rood, een geel en een groen lampje naast elkaar.","Voor wie maken we deze kaart?","Wat zet je je vinger precies op de lijn, goed gekeken!"],"words":["lampje","snoer","vingertop","afdruk","rij","kerst","stralen"],"learn":["fijne-motoriek","rekenen","creativiteit","taal"],"tips":["Teken een paar kaarten tegelijk voor: dan maakt je kind er in één keer een stapel van, voor opa, oma en de juf.","Laat de kaarten open en plat drogen voor je ze dichtvouwt, anders plakken ze aan elkaar."],"variations":["Sneeuwpoppen: twee witte vingerafdrukken boven elkaar op blauw karton, met een getekend sjaaltje en neus.","Rendieren: een bruine duimafdruk met een getekend gewei en een rode stip als neus.","Kerstboom: stip met vingertoppen gekleurde ballen in een getekende boom.","Winter: witte vingerafdrukken op donker papier worden een sneeuwbui."],"themes":["kerst","winter"]},
  {"id":"marmerpapier-scheerschuim","title":"Marmerpapier met scheerschuim","emoji":"🌀","category":"verven","summary":"Druppel kleur op een laag schuim, trek er krullen door en druk je papier erop: elk vel wordt een uniek marmerkunstwerk.","ageMin":3,"ageMax":5,"mess":3,"wet":false,"dirty":true,"prepMinutes":10,"durationMinutes":25,"supervision":2,"materials":[{"id":"scheerschuim","note":"of zelfgemaakt zeepschuim"},{"id":"dienblad","note":"met een randje"},{"id":"kleurstof","note":"of plakkaatverf, 2-3 kleuren"},{"id":"karton","note":"of dik papier, iets kleiner dan het dienblad"},{"id":"ijsstokjes","note":"om mee te roeren én af te schrapen"}],"optional":[{"id":"pipet","note":"om druppels te maken"},{"id":"oud-laken","note":"als knoeimat"},{"id":"oud-shirt"}],"steps":["Spuit een laag scheerschuim van een paar centimeter op het dienblad en strijk het glad met een ijsstokje.","Laat je kind druppels kleurstof of verf over het schuim verdelen.","Trek met een ijsstokje slingers en krullen door de kleuren. Niet te veel roeren, anders wordt het één kleur.","Druk een vel karton plat op het schuim en tel samen tot vijf.","Haal het karton eraf en schraap het schuim weg met een schoon ijsstokje: daar is je marmerpatroon!","Laat het vel drogen. Er is meestal schuim genoeg voor nog twee of drie afdrukken."],"ageTips":{"young":"Voor een driejarige is druppelen en roeren het leukste deel. Doe het afdrukken en afschrapen samen en laat het eindresultaat los.","old":"Kies samen passende kleuren (bijv. blauw en groen voor ‘zee’) en knip van het gedroogde marmerpapier vissen of een kaart."},"safety":["Scheerschuim is niet om te eten en prikt in de ogen: houd een doekje klaar en was handen meteen na afloop. Kies bij een gevoelige huid zeepschuim.","Kleurstof vlekt op kleding en tafel: trek een oud shirt aan en leg een knoeimat neer."],"say":["Kijk, de rode druppel blijft bovenop het schuim liggen!","Wat gebeurt er als je met je stokje door blauw en geel gaat?","Ik zie een krul hier en een slinger daar. Welke vind jij het spannendst?","Tel je mee? Eén, twee, drie, vier, vijf… en nu héél voorzichtig optillen."],"words":["schuim","druppel","krul","slinger","afdruk","luchtig"],"learn":["creativiteit","zintuigen","ontdekken"],"tips":["Werk naast de gootsteen of in een lege badkuip: dan spoel je alles direct weg.","Zet het dienblad op een oude handdoek die het schuim opvangt dat over de rand gaat."],"variations":["Herfst: maak bruin-rood-gele vellen en knip er bladeren uit.","Kerst: knip van groen-wit marmerpapier kerstboompjes voor een kaart.","Inpakpapier: marmer een groot vel en pak er een cadeautje mee in."],"themes":[]},
  {"id":"lijf-natekenen","title":"Je eigen lijf natekenen","emoji":"🧍","category":"tekenen","summary":"Je kind gaat op een groot vel liggen, jij trekt de omtrek na en samen maak je er een levensgrote ik-tekening van.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":20,"supervision":1,"materials":[{"id":"groot-papier","note":"iets langer dan je kind, bijv. een stuk oud behang of pakpapier"},{"id":"stiften","note":"een dikke stift voor de omtrek (dat doe jij)"},{"id":"waskrijt","note":"om het lijf in te kleuren"},{"id":"schilderstape","note":"om het papier op de vloer vast te plakken"}],"optional":[{"id":"gekleurd-papier","note":"om kleren uit te knippen en op te plakken"},{"id":"lijmstift"},{"id":"touw","note":"stukjes wol als haar"}],"steps":["Rol het papier uit op de vloer, iets langer dan je kind, en plak de hoeken vast met schilderstape.","Laat je kind op het papier gaan liggen in een houding naar keuze: armen wijd, benen gespreid of als een ster.","Trek met een dikke stift langzaam de omtrek na en vertel wat je doet: nu kom ik bij je oor, nu bij je knie!","Laat je kind voorzichtig opstaan en bekijk samen de omtrek: ben jij dat? Waar zitten je handen en voeten?","Maak het lijf samen af met een gezicht, haar, kleren en schoenen. Je kind kiest de kleuren.","Teken ook wat er binnenin zit: waar klopt je hart, en waar gaat je eten naartoe?","Hang de tekening op een deur en zet de datum erbij: over een paar maanden zie je hoeveel je kind gegroeid is."],"ageTips":{"young":"Een tweejarige ligt niet lang stil: zing een liedje terwijl je tekent, of trek eerst alleen handen en voeten na. Tik daarna de lichaamsdelen aan en benoem ze: hoofd, buik, voet!","old":"Laat je kleuter jouw omtrek natekenen, of tel samen hoeveel handen lang de tekening is. Zoek in een boek op waar je hart, longen en maag zitten en teken ze erin."},"safety":["Plak het papier rondom goed vast: los papier op een gladde vloer schuift weg als je kind opstaat of eroverheen loopt.","Teken niet vlak langs het gezicht: trek het hoofd na als een ruim rondje, dan blijft de stift uit de buurt van ogen en neus."],"say":["Ik teken langs je arm… kriebelt dat?","Kijk eens, dat ben jij! Waar zijn je voeten?","Welke kleur krijgt jouw broek? En je haar?","Waar denk jij dat je hart zit? Voel maar: boem-boem.","Hoofd! Buik! Voet!"],"words":["hoofd","buik","knie","elleboog","hart","lang","binnenin"],"learn":["taal","creativiteit","fijne-motoriek"],"tips":["Geen groot papier? Plak vier tot zes A4’tjes met plakband aan elkaar of vouw een grote doos open.","Leg er een laag kranten onder als je op parket of vloerbedekking tekent: een stift die doordrukt, geeft af.","Rol de tekening op en bewaar hem: elk jaar opnieuw natekenen laat mooi zien hoe je kind groeit."],"variations":["Omgekeerd: je kind trekt jouw hand, voet of hele lijf na, en nu moet jij stilliggen!","Verkleden op papier: maak van het lijf een astronaut, ridder, prinses of tijger.","Familieportret: teken iedereen in huis na en hang de lijven naast elkaar op, van groot naar klein."],"themes":[]},
  {"id":"tekenen-onder-tafel","title":"Tekenen onder de tafel","emoji":"🙃","category":"tekenen","summary":"Plak papier onder het tafelblad, kruip eronder en teken op je rug: net een kunstenaar die een plafond beschildert.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":15,"supervision":2,"materials":[{"id":"groot-papier","note":"of een paar A4’tjes, samen zo groot als het tafelblad"},{"id":"schilderstape","note":"flinke stroken, om het papier onder het tafelblad te plakken"},{"id":"waskrijt","note":"dikke krijtjes; die blijven ook werken als je ze omhoog houdt"},{"id":"dekens","note":"kussens of een opgevouwen deken om op te liggen"}],"optional":[{"id":"kleurpotloden"},{"id":"zaklamp","note":"als het onder de tafel wat donker is"},{"id":"stickers","note":"om een plafond vol sterren te plakken"}],"steps":["Haal alles van de tafel af, ook het tafelkleed, en schuif de stoelen weg.","Plak een vel papier met flinke stroken schilderstape onder het tafelblad en druk alle randen goed aan.","Leg kussens of een opgevouwen deken onder de tafel, zodat je kind lekker op de rug kan liggen.","Kruip er samen onder en geef je kind een paar dikke krijtjes: kun je bij het papier?","Teken liggend: lijnen, rondjes, krassen. Vertel dat sommige kunstenaars hele plafonds beschilderen.","Neem pauzes, want je armen omhoog houden is zwaar. Schud ze los en ga daarna weer verder.","Haal het papier er voorzichtig af en bewonder samen het plafondschilderij."],"ageTips":{"young":"Plak voor een tweejarige het papier onder een lage salontafel, zodat het dichtbij is. Een dik krijtje dat in de vuist past werkt het best; lig er zelf naast en doe het voor.","old":"Geef je kleuter een opdracht: een sterrenhemel, vogels die over je heen vliegen of het plafond van een kasteel. Vergelijk daarna met tekenen aan tafel: wat was moeilijker, en waarom?"},"safety":["Afgebroken stukjes krijt kunnen op het gezicht vallen: kies dikke krijtjes en laat je kind niet met iets in de mond op de rug liggen.","Leer je kind eerst opzij te rollen en dan onder de tafel uit te kruipen, zodat het niet met het hoofd tegen het tafelblad stoot."],"say":["Kras, kras! Nog een rondje!","Kijk omhoog! Waar is je papier?","Voel je je armen? Het is zwaar werk om zo te tekenen.","Wat zie je boven je? Zullen we de lucht vol vogels tekenen?","Wat is er anders dan tekenen aan tafel, denk jij?"],"words":["onder","boven","omhoog","plafond","liggen","zwaar","kunstenaar"],"learn":["grove-motoriek","fijne-motoriek","creativiteit"],"tips":["Stiften werken op hun kop slecht, omdat de inkt van de punt wegloopt. Waskrijt en kleurpotloden blijven het wel doen.","Maak er een hut van: hang een deken over de tafel en geef je kind een zaklamp. Dan wordt tekenen een geheime missie."],"variations":["Grottekening: hang een deken over de tafel en teken bij zaklamplicht dieren op het plafond, net als de eerste mensen in hun grot.","Muurschildering: plak het papier tegen de muur of een deur en teken staand, met je arm zo hoog mogelijk.","Sterrenhemel: plak donker papier onder de tafel en maak er een nachtlucht van met stickers of geel krijt."],"themes":[]},
  {"id":"tekenen-op-muziek","title":"Tekenen op muziek","emoji":"🎶","category":"tekenen","summary":"Zet muziek op en laat het krijtje meedansen: snel en wild bij vrolijke muziek, langzaam en zacht bij een slaapliedje.","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":3,"durationMinutes":15,"supervision":1,"materials":[{"id":"groot-papier","note":"of een paar A4’tjes aan elkaar geplakt"},{"id":"schilderstape","note":"om het papier vast te plakken, zodat het niet wegschuift"},{"id":"waskrijt","note":"dikke krijtjes; voor dreumesen blokkrijt"},{"id":"muziek","note":"een mix van snelle en langzame liedjes"}],"optional":[{"id":"stiften","note":"voor kleuters die ook dunne lijntjes willen"}],"steps":["Plak een groot vel papier met schilderstape op tafel of op de vloer, zodat het niet wegschuift.","Zet een rustig liedje op en teken samen langzaam mee: lange, zachte lijnen, als golfjes in het water.","Wissel na een minuutje naar snelle, vrolijke muziek: stippen, krassen en zigzaggen maar!","Zet de muziek af en toe stil: dan stopt het krijtje ook. Wie kan het best bevriezen?","Probeer het ook met twee handen tegelijk: in elke hand een krijtje, en dans maar over het papier.","Bekijk samen het vel: waar was de muziek snel en waar langzaam? Hang het op of gebruik het als inpakpapier."],"ageTips":{"young":"Een dreumes krast vooral, en dat is prima. Geef een dik blokkrijtje of één krijtje per vuist en wieg en stamp zelf mee op de muziek.","old":"Laat je kleuter vooraf kiezen welke kleur bij boze, blije of slaperige muziek past. Of teken met de ogen dicht en raad daarna welk stukje bij welk liedje hoort."},"safety":["Dreumesen stoppen krijtjes graag in de mond: kies dikke krijtjes die niet snel afbreken en ruim afgebroken stukjes meteen op.","Zet de muziek niet te hard: als je elkaar niet meer gewoon kunt verstaan, is het te luid voor jonge oren."],"say":["Hoor je dat? Snel, snel, snel!","Deze muziek is zacht. Kan jouw krijtje ook zacht dansen?","Ik zie allemaal kleine stipjes. Was de muziek toen snel of langzaam?","Welke kleur past bij dit liedje, denk jij?","Stop! Bevriezen… en weer verder!"],"words":["snel","langzaam","hard","zacht","golf","zigzag","stip","stop"],"learn":["creativiteit","zintuigen","grove-motoriek"],"tips":["Maak vooraf een afspeellijst met afwisselend snelle en langzame nummers, dan hoef je tijdens het tekenen niet te zoeken.","Plak het papier ook eens op de muur of een deur: staand tekenen met grote armbewegingen voelt nog meer als dansen."],"variations":["Kleurenmuziek: pak bij elk nieuw liedje een andere kleur en tel achteraf hoeveel liedjes je hebt gehoord.","Verfversie: doe hetzelfde met vingerverf of een dikke kwast. Leg dan wel een knoeimat neer.","Winter: teken bij rustige muziek dwarrelende sneeuwvlokken en bij snelle muziek een sneeuwstorm."],"themes":[]},
  {"id":"bladeren-wrijven","title":"Bladeren wrijven: zie de nerven verschijnen","emoji":"🍂","category":"tekenen","summary":"Leg een blad onder dun papier en wrijf er met de zijkant van een krijtje over: als bij toverslag verschijnen de nerven.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":15,"supervision":2,"materials":[{"id":"bladeren","note":"eerder verzameld; platte, niet te droge bladeren in verschillende vormen"},{"id":"papier","note":"dun wit papier, bijv. printpapier"},{"id":"waskrijt","note":"papiertje eraf gehaald, of afgebroken stukjes"},{"id":"schilderstape","note":"om het papier vast te zetten"}],"optional":[{"id":"kinderschaar","note":"om de afdrukken uit te knippen"},{"id":"kranten","note":"om de bladeren een nacht plat te drukken"}],"steps":["Haal het papiertje van een paar waskrijtjes af. Een afgebroken stuk werkt ook prima.","Leg een blad met de bobbelige onderkant naar boven op tafel: daar zitten de nerven het dikst.","Leg een vel dun papier eroverheen en plak de randen vast met schilderstape, zodat er niets verschuift.","Wrijf met de lange zijkant van het krijtje over het papier, van het midden naar buiten. Kijk: daar komt het blad!","Schuif een volgend blad onder een leeg stuk van het vel en wrijf met een andere kleur.","Vergelijk samen de afdrukken: welk blad heeft de meeste nerven? Hang het vel op of knip de bladeren uit."],"ageTips":{"young":"Plak voor een tweejarige zowel het blad als het papier vast, zodat er niets schuift. Kies grote, stevige bladeren zoals eiken- of kastanjeblad en wrijf samen, hand over hand.","old":"Laat je kleuter raden welk blad bij welke afdruk hoort, of zoek samen de namen op: eik, esdoorn, beuk. Ook leuk: wrijf één blad met twee kleuren over elkaar."},"safety":["Leg alleen bladeren klaar, geen bessen, eikels of kastanjes: die zijn niet eetbaar en klein. Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3.","Ruim kleine brokjes waskrijt meteen op: peuters stoppen ze graag in de mond."],"say":["Wrijf, wrijf… kijk, daar komt hij!","Ik zie lijntjes in het blad. Weet je hoe die heten? Nerven!","Welk blad is het grootst? En welk blad voelt het ruwst?","Wat denk je dat er gebeurt als je heel zacht wrijft? En heel hard?","Je hebt heel geduldig het hele blad laten verschijnen."],"words":["blad","nerf","steel","ruw","glad","wrijven","verschijnen"],"learn":["fijne-motoriek","ontdekken","zintuigen"],"tips":["Leg vers geraapte bladeren een nacht plat tussen kranten onder een stapel boeken: dan zijn ze droog en plat, maar nog niet knisperig.","Geen bladeren in huis? Wrijf over een deurmat, de zool van een gymschoen, een vergiet of een kam: overal zitten verborgen patronen."],"variations":["Herfstboom: teken een stam met takken en wrijf er rondom bladeren in rood, oranje en geel bij.","Wrijfjacht door het huis: zoek dingen met reliëf, wrijf ze over en raad later samen wat wat was.","Lente: wrijf over jonge blaadjes en platte bloemen en maak er een kaart van."],"themes":["herfst"]},
  {"id":"krabbelspel","title":"Het krabbelspel: maak er iets van!","emoji":"✏️","category":"tekenen","summary":"Om de beurt zet je een kras op papier en de ander tovert er iets van: wordt het een slang, een hoed of een monster?","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":1,"durationMinutes":15,"supervision":1,"materials":[{"id":"papier","note":"een stapeltje, ook de achterkant van oud printpapier"},{"id":"stiften","note":"twee kleuren: één voor de krabbel, één om af te maken"}],"optional":[{"id":"kleurpotloden","note":"om de tekening daarna in te kleuren"},{"id":"nietmachine","note":"om de vellen tot een krabbelboekje te nieten (dat doe jij)"}],"steps":["Leg een stapel papier klaar en pak allebei een stift in een andere kleur.","Zet jij een kras op het eerste vel: een krul, een zigzag of een lus. Niet nadenken, gewoon krabbelen.","Laat je kind het vel draaien en goed kijken: wat zou dit kunnen worden? Een slurf? Een golf?","Laat je kind de krabbel afmaken met de andere kleur. Vraag wat het is geworden en schrijf dat erbij.","Wissel om: nu krabbelt je kind en maak jij er iets van. Denk hardop na over wat je ziet.","Leg alle vellen naast elkaar, of maak er met de nietmachine een krabbelboekje van om later samen te lezen."],"ageTips":{"young":"Een driejarige ziet nog niet altijd iets in een kras. Draai het vel samen rond en raad hardop: is dit een staart? Van wie? Ogen en pootjes erbij tekenen is al genoeg.","old":"Laat je kleuter jouw krabbel afmaken terwijl jij tot twintig telt, of verzin samen een verhaal waarin alle krabbelfiguren meedoen."},"safety":["Stiftdopjes zijn klein en worden graag op gekauwd: leg ze op een vaste plek en houd ze weg bij jongere broertjes of zusjes. Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3."],"say":["Kras! Jouw beurt!","Wat zie jij in deze kras?","Als ik het vel omdraai… wordt het dan iets anders?","Van mijn krul heb jij een slakkenhuis gemaakt! Hoe kwam je op dat idee?","Hmm, wat zou ik hiervan maken? Help jij me?"],"words":["krul","lus","zigzag","omdraaien","beurt","raden","afmaken"],"learn":["creativiteit","samen","taal","fijne-motoriek"],"tips":["Houd een paar makkelijke krabbels achter de hand voor als je kind vastloopt: een cirkel met een staartje, een golflijn of een driehoek.","Er bestaan hier geen foute antwoorden: of de kras nu een draak wordt of ‘gewoon een kras’ blijft, het gaat om het fantaseren."],"variations":["Krabbelpost: stuur een krabbel in een envelop naar opa of oma en vraag of zij hem afmaken en terugsturen.","Vouwmonster: vouw een vel in drieën en teken om de beurt een hoofd, een lijf en benen zonder te kijken. Vouw het daarna open!","Wachtkamerspel: dit spel kan overal, met één pen en een notitieboekje in je tas."],"themes":[]},
  {"id":"stad-tekenen","title":"Een stad tekenen voor je autootjes","emoji":"🚗","category":"tekenen","summary":"Teken samen wegen, een rotonde, huizen en parkeerplaatsen op een groot vel en speel daarna in je eigen stad met de autootjes.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":30,"supervision":1,"materials":[{"id":"groot-papier","note":"zo groot mogelijk: oud behang, pakpapier of een opengevouwen doos"},{"id":"stiften","note":"een dikke zwarte stift voor de wegen"},{"id":"waskrijt","note":"voor gras, water en huizen"},{"id":"schilderstape","note":"om het papier op de vloer vast te plakken"},{"id":"speelgoedautos"}],"optional":[{"id":"dozen","note":"kleine doosjes als huizen of garage"},{"id":"duplo","note":"om gebouwen en bruggen langs de weg te bouwen"},{"id":"stickers","note":"als verkeersborden of stoplichten"}],"steps":["Plak een groot vel papier met schilderstape op de vloer of de salontafel.","Teken samen met een dikke stift een paar brede wegen: recht, met bochten, en een rotonde in het midden.","Bedenk wat er nog meer in jullie stad moet: je eigen huis, de winkel, een garage, een park of een vijver.","Laat je kind gras, water en huizen inkleuren. Jij tekent parkeervakken en een zebrapad.","Pak de autootjes en speel: rijd naar de bakker, parkeer bij huis en stop voor het zebrapad.","Laat de stad een paar dagen liggen of rol hem op. Je kunt er later altijd nog wegen bij tekenen."],"ageTips":{"young":"Teken voor een tweejarige zelf een paar brede wegen en laat je kind krassen in het gras en het water. Rijden en toet-toet roepen is voor een peuter het leukste deel.","old":"Laat je kleuter een plattegrond van jullie eigen buurt maken: waar staat ons huis, waar is school? Zet nummers bij de parkeervakken en parkeer er net zoveel auto’s in."},"safety":["Plak het papier rondom vast: op een gladde vloer schuift los papier weg als je kind erop rent of knielt.","Kijk de autootjes na op losse wieltjes of kapotte onderdelen als er ook kleintjes meespelen: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3."],"say":["Vroem! Waar rijdt jouw auto naartoe?","Ik zie een lange, bochtige weg. Waar komt die uit?","Hoeveel auto’s passen er op de parkeerplaats? Zullen we tellen?","Wat moet de auto doen bij het zebrapad?","Jij hebt een hele stad bedacht, met een park én een garage!"],"words":["weg","bocht","rotonde","parkeren","links","rechts","voor","achter"],"learn":["creativiteit","taal","rekenen","fijne-motoriek"],"tips":["Gebruik schilderstape als snelweg: een strook tape op het papier of direct op de vloer is meteen een weg.","Rol de stad na het spelen op en doe er een elastiekje om: op een regenachtige dag heb je hem zo weer tevoorschijn."],"variations":["Boerderij: teken weilanden, een sloot en een stal en speel met tractors en speelgoeddieren.","Treinbaan: teken rails met dwarsliggers en een station en laat de knuffels instappen.","Dozenstad: zet lege doosjes als huizen langs de weg en teken er ramen en deuren op."],"themes":[]},
  {"id":"schaduw-natekenen","title":"Schaduwen natekenen","emoji":"🔦","category":"tekenen","summary":"Zet een speelgoeddier voor een zaklamp, teken zijn schaduw na op papier en kleur hem in: wordt het een dino of een olifant?","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":20,"supervision":2,"materials":[{"id":"zaklamp","note":"of de lamp van je telefoon"},{"id":"klein-speelgoed","note":"speelgoeddieren met een duidelijke vorm, zoals een giraffe of dino"},{"id":"papier"},{"id":"stiften","note":"of een potlood om de schaduw na te trekken"},{"id":"schilderstape","note":"om het papier tegen de muur of een doos te plakken"}],"optional":[{"id":"waskrijt","note":"om de schaduwen in te kleuren"},{"id":"dozen","note":"een grote doos om het papier tegenaan te plakken"}],"steps":["Maak de kamer een beetje donker: gordijnen dicht en de grote lamp uit.","Plak een vel papier tegen de muur, op de hoogte waar je kind zittend kan tekenen, of tegen een grote doos die rechtop staat.","Zet een speelgoeddier vlak voor het papier en leg de zaklamp er een stukje voor op een stapel boeken, zodat hij op het dier schijnt.","Schuif samen met de lamp: dichterbij maakt de schaduw groot, verder weg klein. Kies de schaduw die jullie het mooist vinden.","Laat je kind naast het papier zitten en de rand van de schaduw natrekken. Wie voor de lamp zit, tekent de eigen schaduw!","Haal het dier weg en kleur de schaduw in. Raad daarna bij elkaars tekeningen: welk dier was dit?"],"ageTips":{"young":"Voor een driejarige is de zaklamp aan- en uitdoen al spannend genoeg. Kies grote dieren met een duidelijke vorm, zoals een olifant of dino, en trek de schaduw samen na, hand over hand.","old":"Laat je kleuter hetzelfde dier groot én klein natekenen door de lamp te verschuiven en vergelijk: wat is er veranderd? Of trek samen de schaduw van jouw hoofd na als profiel."},"safety":["Kijk niet recht in de zaklamp en schijn niet in elkaars ogen: een felle lamp doet van dichtbij pijn aan de ogen.","Speelgoeddiertjes zijn soms klein: houd ze weg bij jongere broertjes of zusjes, want alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3."],"say":["Licht aan! Kijk, een schaduw!","Wat denk je dat er gebeurt als ik de lamp dichterbij schuif?","Ik zie een lange nek en kleine oortjes. Welk dier zou dit zijn?","Je trekt heel nauwkeurig langs de rand, steeds een stukje verder.","Waar is jouw eigen schaduw gebleven?"],"words":["schaduw","licht","donker","groot","klein","dichtbij","ver weg","rand"],"learn":["ontdekken","fijne-motoriek","concentratie"],"tips":["Een zaklamp met een smalle, felle bundel geeft de scherpste schaduw. Het lampje van je telefoon werkt ook, op een stapel boeken.","Vindt je kind het donker spannend? Laat een klein lampje aan en laat je kind zelf de zaklamp aan- en uitknippen."],"variations":["Schaduwportret: laat je kind van opzij voor de lamp zitten en trek het profiel na op papier tegen de muur.","Halloween: teken de schaduwen van spinnen en vleermuizen na op oranje papier en hang ze voor het raam.","Schaduwmemory: teken een paar schaduwen na en laat je kind daarna bij elke schaduw het juiste dier zetten."],"themes":[]},
  {"id":"kraskunst","title":"Kraskunst: regenboog onder zwart","emoji":"🎆","category":"tekenen","summary":"Kleur een vel vol felle kleuren, verstop alles onder zwart waskrijt en kras er tekeningen in: vuurwerk en sterren verschijnen!","ageMin":4,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":30,"supervision":2,"materials":[{"id":"karton","note":"wit karton of stevig papier; een klein vel (A5) is sneller vol"},{"id":"waskrijt","note":"felle, lichte kleuren en zwart"},{"id":"ijsstokjes","note":"om mee te krassen; een lege balpen kan ook"},{"id":"schilderstape","note":"om het vel vast te plakken, zodat het niet wegschuift"}],"optional":[{"id":"kranten","note":"als onderlegger voor de krijtkruimels"},{"id":"plakkaatverf","note":"zwart, als snellere bovenlaag (dan wordt het wel vies)"}],"steps":["Plak het karton met schilderstape vast op tafel, zodat het niet wegschuift als je hard drukt.","Laat je kind het hele vel dik inkleuren met felle kleuren, in vlakken of strepen. Er mag geen wit meer te zien zijn.","Kleur daarna alles over met zwart waskrijt en druk stevig. Wissel gerust af: het is veel werk voor kleine armen.","Kras met een ijsstokje tekeningen in het zwart: vuurwerkpijlen, sterren, krullen. De regenboog komt tevoorschijn!","Veeg de zwarte kruimels bij elkaar en hang het kunstwerk op."],"ageTips":{"young":"Voor een vierjarige is twee keer inkleuren veel. Neem een klein vel zo groot als een ansichtkaart en kleur de zwarte laag samen: jij de ene helft, je kind de andere.","old":"Laat je kleuter vooraf plannen: waar komt het vuurwerk, waar de maan? Kras ook patronen zoals stippen, zigzag en spiralen, of schrijf je naam en het nieuwe jaartal."},"safety":["Kras met een ijsstokje en niet met een satéprikker of schaarpunt: een scherpe punt schiet makkelijk uit en dan zit je zo in je hand.","Verf je de zwarte laag met plakkaatverf, kies dan afwasbare kinderverf en trek een oud shirt aan: zwart vlekt op kleding en tafel."],"say":["Ik zie geen wit meer. Wat heb je dat goed volgehouden!","Alles is zwart… wat zou eronder verstopt zitten?","Kras! Kijk, rood!","Welke kleur denk je dat er tevoorschijn komt als je hier krast?","Hoor je het krassen? Hoe voelt het in je hand?"],"words":["krassen","verstoppen","tevoorschijn","vuurwerk","fel","zwart","regenboog"],"learn":["fijne-motoriek","concentratie","creativiteit"],"tips":["Kleur de onderlaag met lichte, felle kleuren zoals geel, oranje, roze en lichtblauw: donkere kleuren zie je straks nauwelijks.","Werk op een krant: de zwarte krijtkruimels geven af op tafel, kleding en vloerbedekking, en zo vouw je ze in één keer weg.","Sneller klaar: verf de zwarte laag met plakkaatverf met een druppel afwasmiddel erdoor, dan blijft de verf beter op het krijt zitten. Laat hem helemaal drogen voordat je krast."],"variations":["Oud en nieuw: kras vuurwerkpijlen en knallen in een zwarte nachtlucht en hang ze voor het raam.","Sterrenhemel: maak de onderlaag geel en oranje en kras een maan, sterren en een raket.","Onderwater: kras vissen, kwallen en zeewier in een regenboogzee.","Nieuwjaarskaart: maak een klein krasvel op een dubbelgevouwen kaart voor opa en oma."],"themes":["oudennieuw"]},
  {"id":"tekening-voor-de-schoen","title":"Een tekening voor in je schoen","emoji":"👞","category":"tekenen","summary":"Maak een tekening voor Sinterklaas, leg er een wortel voor het paard bij en zing samen een liedje bij de schoen.","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":2,"durationMinutes":20,"supervision":1,"materials":[{"id":"papier","note":"of gekleurd papier, opgerold of gevouwen past het in de schoen"},{"id":"waskrijt","note":"dikke krijtjes voor de kleinsten"},{"id":"groente","note":"een wortel voor het paard"}],"optional":[{"id":"stiften","note":"voor oudere kinderen"},{"id":"stickers","note":"om de tekening te versieren"},{"id":"potlood","note":"om naam, datum en wat je kind vertelt erbij te schrijven"}],"steps":["Vertel dat Sinterklaas in het land is en dat kinderen hun schoen mogen zetten. Wat zou hij leuk vinden?","Leg papier en krijtjes klaar en laat je kind tekenen: het paard, de stoomboot, een pakje of gewoon fijne krassen.","Vraag wat er op de tekening staat en schrijf het er klein bij, samen met de naam en de datum.","Rol de tekening op of vouw hem dubbel en laat je kind hem in de schoen stoppen, met de wortel voor het paard.","Zet de schoen bij de schoorsteen, de verwarming of de voordeur en zing samen een sinterklaasliedje.","Haal ’s avonds stiekem de tekening en de wortel eruit (bewaar de tekening!) en kijk ’s ochtends samen in de schoen."],"ageTips":{"young":"Een dreumes krast vooral, en dat is precies goed. Geef één dik krijtje, zeg wat je ziet (wat een rode strepen voor Sinterklaas!) en laat je kind zelf de tekening in de schoen stoppen.","old":"Laat je kleuter een tekenbrief maken: wat wil je kind Sinterklaas vertellen? Schrijf letterlijk op wat het zegt, of laat het zelf de eerste letter van de eigen naam schrijven."},"safety":["Zet de schoen niet tegen een kachel, open haard of brandende kaarsjes: papier vat snel vlam.","Laat een dreumes niet op de rauwe wortel kauwen: een harde hap kan in de keel schieten. De wortel is voor het paard!","Dreumesen stoppen krijtjes graag in de mond: geef dikke krijtjes en ruim afgebroken stukjes meteen op."],"say":["Kras! Voor Sinterklaas!","Wat wil jij voor Sinterklaas tekenen?","Ik zie een groot rondje en lange strepen. Vertel eens, wat is dit?","Wat denk je dat het paard van de wortel vindt?","Je hebt er zo je best op gedaan. Wat zal Sinterklaas blij zijn!"],"words":["Sinterklaas","paard","schoen","wortel","pakje","zingen","dak"],"learn":["creativiteit","taal","fijne-motoriek"],"tips":["Bewaar elk jaar één schoentekening in een map met de datum erop: zo zie je mooi hoe het tekenen groeit.","Houd de verrassing in de schoen klein, zoals een mandarijn of een kleurplaat: het gaat om het spannende ritueel."],"variations":["Stoomboot: teken samen de boot op blauw papier en plak er watten bij als stoom uit de schoorsteen.","Zelf een kleurplaat maken: jij tekent de omtrek van een paard of een mijter, je kind kleurt hem in.","Pietenpad: leg papieren voetstapjes van de deur naar de schoen, alsof er ’s nachts iemand is geweest."],"themes":["sinterklaas"]},
  {"id":"nat-krijt","title":"Nat krijt op zwart papier","emoji":"🖍️","category":"tekenen","summary":"Doop stoepkrijt in water en teken op zwart papier: de kleuren knallen ervan af en er stuift geen krijtstof meer.","ageMin":2,"ageMax":5,"mess":2,"wet":true,"dirty":true,"prepMinutes":5,"durationMinutes":20,"supervision":2,"materials":[{"id":"stoepkrijt","note":"dikke stukken in felle kleuren"},{"id":"gekleurd-papier","note":"zwart of donkerblauw"},{"id":"water","note":"een laagje van een paar centimeter"},{"id":"kom","note":"een stevig bakje dat niet snel omvalt"},{"id":"doekje","note":"voor tussendoor de handen"}],"optional":[{"id":"oud-laken","note":"als knoeimat"},{"id":"oud-shirt"},{"id":"penselen","note":"om het papier nat te kwasten"},{"id":"suiker","note":"voor suikerwater: nog fellere kleuren"}],"steps":["Leg een knoeimat neer en zet een stevig bakje met een laagje water op tafel.","Leg een vel zwart papier klaar en geef je kind een paar stukken stoepkrijt.","Laat je kind het krijt in het water dopen en dan tekenen: kijk eens hoe fel de kleur wordt!","Maak ook eens een stukje papier nat met een natte kwast of hand en teken er met droog krijt op. Zie je het verschil?","Laat de tekening plat drogen. Droog wordt het krijt wat lichter en het kan nog een beetje afgeven.","Spoel handen en krijtjes af en laat de krijtjes een nacht drogen voordat je ze opbergt."],"ageTips":{"young":"Geef een tweejarige één dik stuk krijt en een klein bakje met maar een bodempje water. Het dopen is minstens zo leuk als het tekenen: laat dat gewoon gebeuren.","old":"Laat je kleuter vuurwerk, een sterrenhemel of een onderwaterwereld tekenen. Of onderzoek samen: wat geeft de felste kleur, krijt in water of krijt in suikerwater?"},"safety":["Laat je peuter niet alleen met het waterbakje en dweil gemorst water meteen op: een natte vloer is glad.","Krijt is niet om op te eten en krijtstof niet om in te ademen: daarom juist nat. Ruim afgebroken stukjes op, want alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3.","Nat krijt kan kleuren op kleding en tafel: trek een oud shirt aan. Meestal gaat het eruit in de was, felle kleuren niet altijd."],"say":["Doop! Teken! Kijk, fel!","Wat gebeurt er met het krijt als het nat wordt?","Ik zie een knalroze lijn op het zwarte papier. Hij lijkt wel te gloeien!","Voel eens aan het krijt: is het nu zacht of hard?","Je hebt goed uitgeprobeerd wat het felst wordt: nat of droog."],"words":["nat","droog","fel","dopen","zacht","donker","gloeien"],"learn":["ontdekken","zintuigen","creativiteit","fijne-motoriek"],"tips":["Nog feller en minder vegen: leg het krijt 10 minuten in suikerwater (2 el suiker op 100 ml water) voordat je begint.","Nat krijt wordt zacht en breekt makkelijker: laat het na afloop een nacht drogen op een stuk keukenpapier.","Geen zwart papier? Neem een bruine papieren zak of een stuk karton: ook daarop knallen de kleuren."],"variations":["Vuurwerk: teken spetters en strepen in alle kleuren op zwart papier, mooi rond oud en nieuw.","Onderwaterwereld: teken vissen en kwallen op donkerblauw papier.","Badtijd: teken met nat krijt op de tegels van de lege douche of badkuip en spoel het daarna meteen weg. Probeer eerst een hoekje, want felle kleuren kunnen in de voegen blijven zitten."],"themes":[]},
  {"id":"folie-muur","title":"Tekenen op een foliemuur","emoji":"🖼️","category":"tekenen","summary":"Span huishoudfolie tussen twee stoelen en teken erop met stift: je ziet elkaar door je kunstwerk heen, kiekeboe!","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":20,"supervision":2,"materials":[{"id":"huishoudfolie","note":"een brede rol"},{"id":"stoelen","note":"twee stevige stoelen, of gebruik een deuropening"},{"id":"stiften","note":"afwasbare, liefst dikke stiften"},{"id":"schilderstape","note":"om de folie aan de stoelen of de deurpost vast te zetten"}],"optional":[{"id":"knuffels","note":"om achter de folie te zetten en na te tekenen"},{"id":"zaklamp","note":"om door de tekening heen te schijnen"}],"steps":["Zet twee stevige stoelen naast elkaar, ongeveer een meter uit elkaar.","Wikkel de folie strak om beide stoelen heen, van de poten tot de rugleuning, tot er een doorzichtige muur staat. Zet de uiteinden vast met tape.","Ga aan weerskanten zitten: jij aan de ene kant, je kind aan de andere. Kiekeboe, kun je elkaar zien?","Teken met stift op de folie: krassen, rondjes, of een hoed en een snor precies op de plek van elkaars gezicht.","Zet een knuffel achter de folie en laat je kind hem natekenen door de folie heen.","Haal de folie er na afloop af, prop hem op en gooi hem meteen weg. Stift op handen gaat eraf met water en zeep."],"ageTips":{"young":"Voor een tweejarige is kiekeboe door de folie al het grootste feest. Teken samen grote krassen en rondjes en geef een dikke stift die makkelijk in de vuist past.","old":"Laat je kleuter jouw gezicht natekenen door de folie heen terwijl je stilzit, of teken samen een aquarium en laat knuffels erachter langs zwemmen."},"safety":["Huishoudfolie is plastic: houd het weg van het gezicht, laat je kind er niet in wikkelen of er alleen mee spelen en gooi losse stukken direct weg.","Kies zware stoelen die niet omvallen als je kind tegen de folie leunt of duwt, of gebruik een deuropening.","Stiftdopjes zijn klein en worden graag op gekauwd: leg ze op een vaste plek. Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3."],"say":["Kiekeboe! Ik zie jou!","Zal ik een hoed op jouw hoofd tekenen? Blijf even stil zitten…","Hoe voelt de folie: glad, koud, of een beetje plakkerig?","Wat zie je als je door jouw tekening heen kijkt?","Jij tekende precies langs de rand van de knuffel. Wat goed gekeken!"],"words":["doorzichtig","glad","voorkant","achterkant","kiekeboe","strak","door"],"learn":["creativiteit","samen","zintuigen"],"tips":["Hoe strakker de folie, hoe beter het tekent. Werkt een stift slecht op het plastic, probeer dan een andere: dikke stiften geven vaak de mooiste lijn.","Wil je de tekening bewaren? Maak een foto met je kind erachter: dan staan jullie er allebei op."],"variations":["Verfmuur: schilder met plakkaatverf en een dikke kwast op de folie. Dat wordt wel viezer, dus leg een knoeimat neer.","Raamversie: plak een stuk folie op het raam en trek na wat je buiten ziet: een boom, een auto, de kat van de buren.","Aquarium: teken vissen en waterplanten op de folie en laat knuffels erachter langs ‘zwemmen’."],"themes":[]},
  {"id":"plakmuur","title":"Plakmuur van kaftfolie","emoji":"🖐️","category":"plakken","summary":"Hang kaftfolie met de plakkant naar voren op het raam en laat je kind er snippers, veertjes en blaadjes op plakken, helemaal zonder lijm.","ageMin":1,"ageMax":4,"mess":1,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":15,"supervision":2,"materials":[{"id":"kaftfolie","note":"een vel van ongeveer 40 x 60 cm"},{"id":"schilderstape","note":"om de randen aan het raam of de muur vast te plakken"},{"id":"vloeipapier","note":"in snippers geknipt of gescheurd, in een paar kleuren"},{"id":"gekleurd-papier","note":"vierkantjes en rondjes van een paar centimeter"}],"optional":[{"id":"veren","note":"zachte veertjes"},{"id":"bladeren","note":"platte, eerder verzamelde bladeren"},{"id":"bakjes","note":"om de snippers per kleur in te doen"}],"steps":["Knip of scheur alvast een stapeltje snippers vloeipapier en gekleurd papier.","Trek de beschermlaag van de kaftfolie en plak het vel met de plakkant naar voren op het raam, op de hoogte van je kind.","Zet alle vier de randen vast met stroken schilderstape, zodat de folie niet loslaat.","Leg de snippers in een bakje naast het raam, zodat je kind er zelf bij kan.","Laat je kind snippers pakken en op de folie drukken. Voel samen eens hoe plakkerig het is!","Laat de plakmuur een paar dagen hangen en vul hem steeds aan. Lostrekken en opnieuw plakken mag ook."],"ageTips":{"young":"Geef een dreumes grote stukken die makkelijk te pakken zijn, zoals brede stroken vloeipapier of een grote veer. Doe het voor en zeg het erbij: plak! Nog een!","old":"Laat je kleuter een plaatje maken: een regenboog in de goede volgorde, een bloem of een gezicht. Of zoek eerst alle snippers in één kleur bij elkaar en plak alleen die."},"safety":["Geef een dreumes grote snippers: kleine stukjes papier en veertjes belanden makkelijk in de mond. Blijf dichtbij en haal wat in de mond verdwijnt er rustig uit.","Hang de plakmuur zo laag dat je kind er staand of zittend bij kan: zet er geen stoel of krukje bij om op te klimmen, zeker niet bij een raam dat open kan."],"say":["Plak! Nog een!","Voel eens: het plakt aan je vingers!","Ik zie de zon door het rode papiertje schijnen.","Wat gebeurt er als je de veer er weer aftrekt?","Jij hebt alle blauwe snippers bij elkaar geplakt. Wat goed gezocht!"],"words":["plakken","plakkerig","zacht","veer","licht","erop","eraf"],"learn":["fijne-motoriek","zintuigen","creativiteit"],"tips":["Knip de snippers als je kind slaapt en bewaar ze in een zakje: dan kun je meteen beginnen.","Geen kaftfolie? Plak brede plakband met de plakkant naar voren in banen naast elkaar.","Is de folie vol? Plak er een tweede vel overheen, plakkant op plakkant, knip het rond en hang het als zonnevanger voor het raam."],"variations":["Herfst: plak bladeren, takjes en snippers in herfstkleuren en maak er samen een boom van.","Kleurenmuur: plak alleen rode snippers en zoek daarna in huis nog meer dingen in die kleur.","Gezicht: plak een groot rond vel papier op de folie en laat je kind er ogen, een neus en een mond op plakken.","Lente: plak bloemblaadjes en groene snippers tot een bloementuin op het raam."],"themes":[]},
  {"id":"scheurcollage","title":"Scheuren en plakken","emoji":"📰","category":"plakken","summary":"Scheur tijdschriften en gekleurd papier in snippers en plak ze op karton: zo groeit er een collage, bijvoorbeeld een herfstboom vol blaadjes.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":20,"supervision":2,"materials":[{"id":"tijdschriften","note":"of reclamefolders, die scheuren makkelijk"},{"id":"gekleurd-papier","note":"voor een herfstboom: rood, oranje, geel en bruin"},{"id":"lijmstift"},{"id":"karton","note":"als stevige ondergrond"}],"optional":[{"id":"stiften","note":"een bruine stift voor de stam"},{"id":"bakjes","note":"om de snippers per kleur te verzamelen"},{"id":"dienblad","note":"om op te werken, dan blijven de snippers bij elkaar"}],"steps":["Leg tijdschriften en gekleurd papier klaar. Scheur zelf een strook in, zodat je kind ziet hoe het gaat.","Laat je kind stroken en snippers scheuren: groot of klein, recht of rafelig, alles is goed.","Scheur samen een stam en takken uit bruin papier en plak ze op het karton, of teken ze met stift.","Smeer met de lijmstift een plekje op het karton in en druk er een snipper op. Lijm op het karton gaat makkelijker dan op de snipper.","Vul de boom met blaadjes in herfstkleuren en plak er ook een paar onder, alsof ze naar beneden dwarrelen.","Laat de collage plat drogen onder een boek en ruim de snippers op in een bak of met stoffer en blik."],"ageTips":{"young":"Een tweejarige scheurt het makkelijkst in een strook die jij al een stukje hebt ingescheurd. Smeer zelf de lijm op het karton en laat je kind alleen de snippers erop drukken.","old":"Laat je kleuter de snippers eerst sorteren op kleur, of bewust vormen scheuren: een rondje voor de zon, een driehoek voor een dak. Ook leuk: een gezicht van tijdschriftsnippers."},"safety":["Peuters stoppen papiersnippers soms in de mond: blijf erbij en haal ze er rustig uit. Inkt van tijdschriften is niet om op te eten.","De dop van de lijmstift is klein en wordt graag op gekauwd: leg hem weg tijdens het plakken. Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3."],"say":["Krrrr! Hoor je het scheuren?","Ik zie een rafelig randje. Voel eens, is het glad of kriebelig?","Waar moet dit oranje blaadje komen?","Wat heb jij veel snippers gescheurd, helemaal zelf!","Hoeveel blaadjes vallen er al naar beneden?"],"words":["scheuren","snipper","rafelig","plakken","stam","tak","dwarrelen"],"learn":["fijne-motoriek","creativiteit","zintuigen"],"tips":["Dun papier scheurt het makkelijkst: tijdschriften en folders gaan beter dan stevig karton.","Werk op een dienblad of bakplaat: de snippers blijven bij elkaar en je ruimt alles in één keer op.","Bewaar overgebleven snippers in een zakje voor de volgende keer of voor een plakmuur."],"variations":["Winter: scheur wit papier en maak een besneeuwde boom of een sneeuwpop van snippers.","Kleurenmonster: scheur alles in één kleur en plak er een groot monster van, met getekende ogen.","Lente: plak een bloesemboom van roze en witte snippers."],"themes":["herfst"]},
  {"id":"knipsoep","title":"Knipsoep koken: de eerste keer knippen","emoji":"✂️","category":"plakken","summary":"Knip stroken papier in hapjes en kook er knipsoep van: één knip is één hap, zo oefent je kind spelenderwijs met de schaar.","ageMin":3,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":15,"supervision":1,"materials":[{"id":"kinderschaar","note":"met ronde punt; er zijn ook scharen voor linkshandigen"},{"id":"gekleurd-papier","note":"in stroken van 2-3 cm breed (die knip jij voor)"},{"id":"pan","note":"een speelgoedpan of gewone pan als soeppan"},{"id":"lepel","note":"een grote lepel om te roeren"}],"optional":[{"id":"karton","note":"dun karton van een cornflakesdoos, in stroken: lekker stevig om te knippen"},{"id":"kom","note":"soepkommen om op te scheppen"},{"id":"speeldeeg","note":"rolletjes deeg knippen is een makkelijke eerste oefening"}],"steps":["Knip een paar vellen papier in stroken van 2 tot 3 cm breed. Dan is één knip genoeg voor een hapje.","Laat zien hoe je de schaar vasthoudt: duim in het kleine gat, vingers in het grote, duim boven. Open, dicht, open, dicht.","Houd jij de strook strak vast en laat je kind er een stukje afknippen: knip! Daar valt een hapje in de pan.","Laat je kind de strook daarna zelf vasthouden en knippen. Knip, knip, knip: de pan loopt vol.","Roer de soep om, strooi er ‘zout en peper’ in (nog meer snippers) en schep op in kommen. Eet smakelijk!","Ruim samen op: de soep gaat terug in de pan en daarna in het oud papier."],"ageTips":{"young":"Voor een driejarige is vasthouden én knippen tegelijk lastig: houd jij de strook vast en laat je kind alleen ‘happen’ met de schaar. Lukt knippen nog niet, scheur dan de soep.","old":"Teken lijnen op de stroken (recht, golvend of zigzag) en laat je kleuter erlangs knippen. Of knip soepgroenten: rondjes wortel, blokjes prei en lange slierten vermicelli."},"safety":["Gebruik een kinderschaar met ronde punt en spreek af: de schaar blijft aan tafel, we lopen er niet mee rond en na afloop gaat hij in de la.","Leg uit dat de schaar alleen papier knipt, geen haar, kleren of gordijnen, en houd scharen buiten bereik als jij er niet bij bent.","Let op de vingers van de hand die vasthoudt: die blijven naast de schaar, nooit ertussen."],"say":["Knip! Daar is een hapje!","Open, dicht, open, dicht: hoor je de schaar?","Ik zie dat je je duim bovenop houdt. Zo gaat het precies goed.","Wat voor soep koken we vandaag? Tomatensoep of regenboogsoep?","Hoeveel hapjes heb je al geknipt? Zullen we tellen?"],"words":["knippen","open","dicht","strook","hapje","soep","roeren"],"learn":["fijne-motoriek","concentratie","creativiteit"],"tips":["Met een goede kinderschaar en een strook die jij vasthoudt, kunnen veel kinderen vanaf ongeveer 2,5 jaar al knippen. Lukt het nog niet, oefen dan eerst met scheuren.","Stevig papier of dun karton knipt makkelijker dan slap papier, dat dubbelvouwt in de schaar.","Linkshandig? Kies een linkshandige kinderschaar: met een gewone schaar ziet je kind niet waar het knipt en klemt het papier."],"variations":["Spaghetti koken: knip lange, dunne slierten en dien ze op met rode snippers als tomatensaus.","Knipkapper: teken een gezicht op een vel en knip de bovenkant in tot lange haren. Nu mag je kind de kapper zijn!","Heksensoep: knip snippers in herfstkleuren en roer er met een grote lepel een toversoep van. Mooi rond Halloween."],"themes":[]},
  {"id":"glas-in-lood","title":"Glas-in-lood voor het raam","emoji":"🌈","category":"plakken","summary":"Plak snippers vloeipapier op kaftfolie in een lijstje van karton en hang het voor het raam: als de zon schijnt, gaat het stralen.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":20,"supervision":2,"materials":[{"id":"kaftfolie","note":"twee stukken, iets groter dan het lijstje"},{"id":"vloeipapier","note":"in snippers of vierkantjes van een paar centimeter"},{"id":"karton","note":"of zwart papier voor het lijstje"},{"id":"schilderstape","note":"om de folie op tafel en het kunstwerk tegen het raam te plakken"}],"optional":[{"id":"kinderschaar","note":"voor kleuters die zelf snippers knippen"},{"id":"gekleurd-papier","note":"zwart, voor een lijstje als echt glas-in-lood"}],"steps":["Knip een lijstje uit karton: een hart, ster of rondje met een groot gat in het midden. Dat doe jij.","Trek de beschermlaag van een stuk kaftfolie en leg het met de plakkant naar boven op tafel. Zet de hoeken vast met tape.","Druk het lijstje op de plakkant, zodat het goed vastzit.","Laat je kind snippers vloeipapier in het lijstje plakken. Overlappen mag: daar ontstaan nieuwe kleuren!","Plak het tweede stuk kaftfolie er bovenop als alles vol is en knip de randen netjes bij langs het lijstje.","Hang het kunstwerk met schilderstape tegen het raam en kijk samen hoe het licht erdoorheen schijnt."],"ageTips":{"young":"Laat een tweejarige vrij plakken in een groot, rechthoekig lijstje en kies grote snippers in een paar felle kleuren. Het afplakken en ophangen doe jij.","old":"Laat je kleuter de vorm zelf tekenen en de snippers knippen, of maak een patroon: om en om rood en geel. Wat gebeurt er als blauw en geel over elkaar liggen?"},"safety":["Het gat in het lijstje steek je het makkelijkst voor met een mespunt of schaarpunt. Dat doe jij, op een snijplank en buiten bereik van je kind.","Hang het kunstwerk met tape tegen het raam, niet aan een lang touwtje bij bed of box: koordjes zijn een wurggevaar."],"say":["Plak! Rood! Nog een!","Kijk, de zon schijnt door jouw raam heen!","Wat gebeurt er als het gele papiertje over het blauwe ligt?","Ik zie dat je het hele lijstje hebt volgeplakt, tot in de hoekjes.","Welke kleur straalt het mooist als het licht erdoor schijnt, denk jij?"],"words":["doorzichtig","licht","plakkerig","overlappen","raam","stralen","kleur"],"learn":["fijne-motoriek","creativiteit","ontdekken"],"tips":["Knip vooraf een stapeltje snippers en bewaar ze per kleur in bakjes of zakjes: dan kun je zo beginnen.","Geen kaftfolie? Gebruik brede plakband met de plakkant naar boven, in banen naast elkaar."],"variations":["Kerst: knip een ster of kerstbal als lijstje en plak er rood, groen en geel in.","Halloween: maak een pompoen van oranje snippers met zwarte ogen, of een vleermuis tegen een gele maan.","Lente: maak een vlinder of bloem en hang er een hele rij van voor het raam."],"themes":["kerst","halloween","lente"]},
  {"id":"bordjes-dieren","title":"Dieren van papieren bordjes","emoji":"🦁","category":"plakken","summary":"Met verf, papier en een beetje lijm wordt een papieren bordje een leeuw, vis, lieveheersbeestje of schildpad: welk dier kies jij?","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":10,"durationMinutes":25,"supervision":2,"materials":[{"id":"papieren-bordjes"},{"id":"plakkaatverf","note":"afwasbare kinderverf in de kleur van het dier"},{"id":"penselen","note":"dikke kwasten"},{"id":"gekleurd-papier","note":"voor manen, vinnen, pootjes en stippen"},{"id":"knutsellijm","note":"houdt beter op een bordje dan een lijmstift"},{"id":"stiften","note":"een zwarte stift voor ogen en mond"}],"optional":[{"id":"kinderschaar","note":"voor kleuters die zelf stroken knippen"},{"id":"wiebeloogjes","note":"alleen vanaf 3 jaar"},{"id":"ijsstokjes","note":"om er een handpop van te maken"},{"id":"oud-laken","note":"als knoeimat"},{"id":"oud-shirt"}],"steps":["Kies samen een dier: een leeuw, vis, lieveheersbeestje of schildpad. Leg een knoeimat neer en trek een oud shirt aan.","Laat je kind het bordje verven in de kleur van het dier: geel voor de leeuw, rood voor het lieveheersbeestje, groen voor de schildpad.","Knip ondertussen de onderdelen uit gekleurd papier: stroken voor manen, vinnen en een staart, zwarte stippen of pootjes. Dat doe jij.","Laat de verf een kwartiertje drogen. Lees intussen een dierenboekje of doe samen het geluid van het dier na.","Zet stipjes lijm op het bordje en laat je kind de onderdelen erop drukken. Teken ogen en een mond met stift.","Laat het dier plat drogen en hang het op. Voor een poppenkast: plak er een ijsstokje achter als handvat."],"ageTips":{"young":"Voor een tweejarige is verven het hele feest: laat de rest gerust zitten of plak samen alleen een paar stroken. Ogen tekenen doe jij; wiebeloogjes nog niet.","old":"Laat je kleuter zelf de stroken voor de manen knippen en de stippen van het lieveheersbeestje tellen. Of verzin een eigen fantasiedier met vinnen én manen."},"safety":["Wiebeloogjes zijn klein: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Teken voor jonge kinderen de ogen met stift.","Plakkaatverf kan vlekken op kleding en tafel: kies afwasbare kinderverf, trek een oud shirt aan en leg een knoeimat neer."],"say":["Geel! Nog meer geel!","Welk dier wordt jouw bordje? Wat heeft dat dier nodig?","Ik zie dat je helemaal tot de rand hebt geverfd.","Hoe klinkt jouw leeuw? Kan hij ook zachtjes brullen?","Hoeveel stippen heeft jouw lieveheersbeestje? Zullen we tellen?"],"words":["leeuw","manen","vin","stip","schild","rond","brullen"],"learn":["creativiteit","fijne-motoriek","taal"],"tips":["Minder vies: kleur het bordje met dikke stiften of waskrijt in plaats van verf.","Knip de onderdelen alvast als je kind een dutje doet en leg ze per dier in een bakje: dan kan je peuter meteen plakken."],"variations":["Leeuw: plak stroken geel en oranje papier rondom als manen en krul ze om een potlood.","Vis: knip een punt uit het bordje als bek en plak die punt aan de achterkant vast als staart. Schubben van vloeipapier erop!","Schildpad: verf het bordje groen, plak er vierkantjes op als schild en maak een kop en pootjes van papier.","Lieveheersbeestje: verf het bordje rood en plak er zwarte stippen en een zwarte kop op. Mooi in de lente."],"themes":[]},
  {"id":"wc-rol-diertjes","title":"Wc-rol-diertjes: uil, pinguïn en paashaas","emoji":"🦉","category":"plakken","summary":"Een leeg wc-rolletje wordt met verf, papier en een beetje lijm een uil, pinguïn, paashaas of spookje: knutselen met wat je anders weggooit.","ageMin":3,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":10,"durationMinutes":25,"supervision":2,"materials":[{"id":"wc-rollen","note":"één per diertje; een halve keukenrolkoker kan ook"},{"id":"plakkaatverf","note":"afwasbare kinderverf"},{"id":"penselen"},{"id":"gekleurd-papier","note":"voor oren, vleugels, snavels en buikjes"},{"id":"knutsellijm","note":"of een lijmstift"},{"id":"stiften","note":"voor ogen en snavel"}],"optional":[{"id":"wiebeloogjes"},{"id":"watten","note":"een plukje als staartje voor de paashaas"},{"id":"kinderschaar","note":"voor kleuters die zelf vleugels knippen"},{"id":"oud-shirt"}],"steps":["Kies samen een dier: een uil, pinguïn, paashaas of spookje. Leg een knoeimat neer.","Laat je kind het rolletje verven: bruin voor de uil, zwart voor de pinguïn, wit of grijs voor de haas. Laat het een kwartiertje drogen.","Vouw voor de uil de bovenrand aan de voor- en achterkant naar binnen: dan steken er twee puntoortjes uit.","Knip ondertussen vleugels, buikjes, snavels of lange oren uit gekleurd papier. Dat doe jij, of je kleuter zelf.","Laat je kind de onderdelen opplakken en ogen tekenen met een stift. Een plukje watten wordt een staartje.","Zet de diertjes op een rij in de vensterbank of maak er een hele familie van."],"ageTips":{"young":"Voor een driejarige is verven het leukste deel. Knip de onderdelen vooraf en plak ze samen op; teken grote ogen met stift als wiebeloogjes nog te priegelig zijn.","old":"Laat je kleuter zelf vleugels en oren tekenen en knippen, of een hele dierentuin plannen: welk dier heeft wat nodig? Speel daarna poppenkast met de diertjes."},"safety":["Wiebeloogjes en plukjes watten zijn klein: houd ze weg bij jongere broertjes of zusjes. Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3.","Plakkaatverf kan vlekken: kies afwasbare kinderverf en verf met een oud shirt aan."],"say":["Oehoe! Daar is de uil!","Verf maar rond, helemaal om het rolletje heen!","Welk dier wordt dit, denk je? Wat heeft het nodig: oren, vleugels of een snavel?","Ik zie twee puntjes bovenop. Zijn dat oren?","Je hebt aan allebei de kanten precies een vleugel geplakt."],"words":["uil","pinguïn","haas","vleugel","snavel","oren","rond"],"learn":["creativiteit","fijne-motoriek","taal"],"tips":["Spaar een paar weken wc-rolletjes en keukenrolkokers in een doos. Een keukenrolkoker in tweeën geknipt geeft twee diertjes.","Minder vies: wikkel een strook gekleurd papier om het rolletje en plak die vast, in plaats van te verven."],"variations":["Herfst: maak een uil met veren van bruine bladeren of gescheurd papier.","Winter: een pinguïn met een wit buikje en een sjaaltje van een reepje vilt.","Pasen: een paashaas met lange papieren oren en een staartje van watten.","Halloween: een spookje van een wit rolletje of een vleermuis met zwarte vleugels."],"themes":["herfst","winter","pasen","halloween"]},
  {"id":"gekke-gezichten","title":"Gekke gezichten uit tijdschriften","emoji":"🤪","category":"plakken","summary":"Knip ogen, neuzen en monden uit tijdschriften en mix ze tot gekke gezichten: blij, boos, verbaasd of alles tegelijk!","ageMin":3,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":20,"supervision":2,"materials":[{"id":"tijdschriften","note":"met grote foto’s van gezichten, ook reclamefolders"},{"id":"kinderschaar"},{"id":"lijmstift"},{"id":"papier","note":"met een groot hoofd erop getekend, of een papieren bordje"}],"optional":[{"id":"stiften","note":"voor haar, oren en wenkbrauwen"},{"id":"touw","note":"stukjes wol als haar"},{"id":"bakjes","note":"om ogen, neuzen en monden apart te bewaren"}],"steps":["Blader samen door tijdschriften en zoek grote gezichten. Wie lacht er? Wie kijkt boos?","Knip ogen, neuzen en monden uit en leg ze op drie stapeltjes. Grote stukken knip jij, de rest je kleuter.","Teken een groot hoofd op een vel papier, of neem een papieren bordje.","Laat je kind kiezen: welke ogen, welke neus en welke mond? Leg alles eerst los neer en schuif tot het grappig is.","Plak alles vast met de lijmstift en teken er haar, oren of een hoed bij.","Bekijk samen het gezicht: hoe voelt dit gezicht zich? Doe het maar eens na!"],"ageTips":{"young":"Knip voor een driejarige alvast een stapeltje ogen, neuzen en monden uit. Kiezen, schuiven en plakken is genoeg werk; benoem steeds wat je ziet: ogen, een neus, een lachende mond.","old":"Laat je kleuter zelf knippen en een gezicht maken bij een gevoel: maak eens een verdrietig of een verbaasd gezicht. Of maak een monster met drie ogen en twee monden."},"safety":["Blader de tijdschriften even door voordat je kind gaat zoeken: haal pagina’s met enge of ongepaste foto’s eruit.","Gebruik een kinderschaar met ronde punt en knip zelf de moeilijke stukjes, zoals een mond met smalle lippen."],"say":["Ogen! Waar zijn de ogen?","Kijk, deze mond lacht heel breed. Hoe voelt deze persoon zich?","Wat gebeurt er als we boze ogen bij een lachende mond plakken?","Kun jij dit gezicht nadoen? En ik?","Je hebt heel goed gezocht naar precies de goede neus."],"words":["ogen","neus","mond","blij","boos","verdrietig","verbaasd","gek"],"learn":["taal","creativiteit","fijne-motoriek"],"tips":["Reclamefolders van kledingwinkels en supermarkten staan vol grote gezichten en zijn gratis.","Plak de gezichten in een schrift: zo maak je een gevoelensboekje om later samen te bekijken en na te doen."],"variations":["Gevoelensmeter: maak een blij, boos, bang en verdrietig gezicht en vraag elke dag welk gezicht bij je kind past.","Dierengezichten: knip ogen en neuzen van dieren en maak bijvoorbeeld een poes met een olifantenslurf.","Carnaval: plak het gezicht op karton, knip het uit en maak er een masker op een stokje van."],"themes":[]},
  {"id":"bladerendieren","title":"Bladerendieren: egel, vos en uil","emoji":"🦔","category":"plakken","summary":"Plak herfstbladeren op karton als stekels, vacht of veren en teken ogen en pootjes erbij: daar is je egel, vos of uil!","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":5,"durationMinutes":20,"supervision":2,"materials":[{"id":"bladeren","note":"eerder verzameld; platte, droge bladeren in verschillende kleuren en vormen"},{"id":"knutsellijm","note":"houdt bladeren beter vast dan een lijmstift"},{"id":"karton","note":"of stevig papier als ondergrond"},{"id":"stiften","note":"zwart, voor ogen, snuit en pootjes"}],"optional":[{"id":"penselen","note":"om de lijm uit te smeren"},{"id":"wiebeloogjes","note":"alleen vanaf 3 jaar"},{"id":"kinderschaar","note":"om bladeren in vorm te knippen"},{"id":"oud-shirt"}],"steps":["Leg de bladeren op tafel en bekijk ze samen: welke zijn puntig, welke rond, welke rood of bruin?","Teken op het karton de kop van een dier: een puntige snuit voor de egel, een vossenkop met oren, of twee grote uilenogen.","Smeer lijm op het karton waar de stekels, vacht of veren moeten komen. Met een kwast gaat het makkelijk.","Laat je kind de bladeren op de lijm drukken, een beetje over elkaar heen. Voor egelstekels wijzen de punten naar buiten.","Teken ogen, een neus en pootjes erbij en laat het dier een paar uur plat drogen onder een boek."],"ageTips":{"young":"Een tweejarige drukt graag, maar smeert nog niet precies: smeer zelf de lijm en laat je kind de bladeren erop leggen en aandrukken. Grote bladeren werken het makkelijkst.","old":"Laat je kleuter zelf kiezen welk blad bij welk dier past en tel samen de stekels. Of knip bladeren in vorm: puntige oren voor de vos, een ronde buik voor de uil."},"safety":["Gebruik alleen bladeren, geen bessen, eikels of kastanjes: die zijn niet eetbaar en klein. Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3.","Wiebeloogjes pas vanaf 3 jaar: teken voor een tweejarige de ogen met stift."],"say":["Plak! Nog een blad!","Voel eens: is dit blad glad of ruw? Knispert het?","Ik zie heel veel puntige bladeren. Zijn dat de stekels van de egel?","Welk dier heeft er een rode vacht? Wat denk jij?","Je hebt de bladeren zo dicht naast elkaar gelegd dat er geen gaatje meer is."],"words":["egel","stekel","vos","uil","puntig","knisperen","herfst"],"learn":["creativiteit","fijne-motoriek","zintuigen","taal"],"tips":["Leg vers geraapte bladeren een nacht plat tussen kranten onder een stapel boeken: dan krullen ze niet op en plakken ze beter.","Giet een klein plasje lijm op een dekseltje of bordje en laat je kind met een kwast stippen. Zo gaat er minder lijm verloren.","Natte lijmvlekken spoel je met koud water uit kleding; opgedroogde lijm laat je eerst weken."],"variations":["Bladerenvis: plak bladeren als schubben op een getekende vis en maak er een herfstzee van.","Bladerenboom: plak bladeren onder een getekende boom, alsof ze net gevallen zijn.","Leeuw: plak oranje en gele bladeren rondom een getekende kop als manen."],"themes":["herfst"]},
  {"id":"watten-sneeuwpop","title":"Sneeuwpop van wattenbolletjes","emoji":"⛄","category":"plakken","summary":"Plak wattenbolletjes op donker papier tot een zachte sneeuwpop met een sjaal van vilt: sneeuwpret zonder koude handen!","ageMin":2,"ageMax":4,"mess":2,"wet":false,"dirty":true,"prepMinutes":5,"durationMinutes":20,"supervision":2,"materials":[{"id":"watten","note":"een handvol wattenbolletjes"},{"id":"gekleurd-papier","note":"donkerblauw of zwart, plus een stukje oranje voor de neus"},{"id":"knutsellijm","note":"uitsmeren met een kwastje of wattenstaafje"},{"id":"vilt","note":"een reepje als sjaal; gekleurd papier kan ook"}],"optional":[{"id":"penselen","note":"om de lijm uit te smeren"},{"id":"stiften","note":"voor ogen, mond en knopen"},{"id":"stickers","note":"als knopen of sneeuwvlokken"},{"id":"oud-shirt"}],"steps":["Smeer lijm in de vorm van een sneeuwpop op het donkere papier: een grote cirkel onderaan, een middelste en een kleine als hoofd. Dat doe jij.","Laat je kind wattenbolletjes op de lijm drukken, tot de sneeuwpop helemaal wit en zacht is.","Trek samen een paar bolletjes uit elkaar tot plukjes en plak ze rondom als dwarrelende sneeuw.","Knip een reepje vilt als sjaal en een oranje driehoekje als wortelneus en laat je kind ze opplakken.","Teken ogen, een mond en knopen, of plak er stickers op. Laat de sneeuwpop een uur plat drogen."],"ageTips":{"young":"Een tweejarige vindt de watten voelen en aandrukken al genoeg. Smeer de lijm vooraf in grote vlakken en benoem wat je doet: zacht, wit, druk maar!","old":"Laat je vierjarige zelf de cirkels tekenen, van groot naar klein, en tellen hoeveel bolletjes er in elke cirkel passen. Of maak een hele sneeuwpoppenfamilie."},"safety":["Peuters stoppen wattenbolletjes graag in hun mond of neus: geef er een paar tegelijk en blijf erbij. Een plukje watten kan bij inslikken in de keel blijven hangen.","Knutsellijm is niet om te eten: giet een klein beetje in een dekseltje en zet de fles buiten bereik."],"say":["Zacht! Nog een!","Voel eens: is het watje zacht of hard? En is het koud, net als echte sneeuw?","Ik zie een dikke buik en een klein hoofdje.","Wat heeft onze sneeuwpop nog nodig om het warm te hebben?","Jij hebt de hele buik volgeplakt, bolletje voor bolletje."],"words":["sneeuw","zacht","wit","rond","groot","klein","sjaal","koud"],"learn":["zintuigen","fijne-motoriek","taal"],"tips":["Smeer de lijm in kleine stukjes tegelijk: dan droogt hij niet op voordat de watten erop zitten en plakt hij niet aan alles.","Maak er een kerstkaart van: vouw stevig donker papier dubbel en plak de sneeuwpop op de voorkant."],"variations":["Kerst: maak een kerstman met een witte baard van watten op een rood gezicht.","Schaapje: plak watten op een getekend lijf en geef het zwarte pootjes en een kopje.","Sneeuwlandschap: plak een heuvel van watten en laat er sneeuw uit een getekende wolk dwarrelen."],"themes":["winter","kerst"]},
  {"id":"confetti-maken","title":"Confetti maken met de perforator","emoji":"🎊","category":"plakken","summary":"Pons gaatjes in gekleurd papier en kijk wat er uit de perforator komt: zelfgemaakte confetti om op te plakken of te strooien!","ageMin":3,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":2,"durationMinutes":15,"supervision":2,"materials":[{"id":"perforator","note":"een enkele perforator gaat lichter dan een dubbele"},{"id":"gekleurd-papier","note":"in stroken van een paar centimeter breed"},{"id":"bakjes","note":"om de confetti in te verzamelen"}],"optional":[{"id":"lijmstift","note":"om confetti op een kaart of tekening te plakken"},{"id":"papier","note":"als kaart of ondergrond"},{"id":"tijdschriften","note":"glanzende folders geven bonte confetti"},{"id":"dienblad","note":"om boven te werken, dan veeg je alles zo weer op"}],"steps":["Knip het gekleurde papier in stroken van een paar centimeter breed: die passen makkelijk in de perforator.","Laat zien hoe het werkt: strook erin schuiven, met je hele hand stevig drukken en klak!","Laat je kind gaatjes ponsen, zoveel als het wil. Open daarna samen het klepje: kijk, confetti!","Verzamel de confetti in bakjes, per kleur of lekker door elkaar.","Smeer lijmstift op een kaart of tekening en strooi er confetti op. Schud de rest eraf boven een bakje.","Bewaar de overgebleven confetti in een potje voor het volgende feest."],"ageTips":{"young":"Voor een driejarige is drukken zwaar werk: laat je kind met twee handen bovenop drukken, of zet de perforator op de grond en laat je kind er met een platte hand op leunen.","old":"Laat je kleuter tellen hoeveel gaatjes er in één strook passen, of de confetti sorteren op kleur. Pons ook eens een rij gaatjes langs de rand van een vel: een kanten kaart!"},"safety":["Confetti is klein en blijft aan vingers en lippen plakken: houd het weg bij kinderen onder de 3, want alles wat door een wc-rolletje past, is te klein voor hen.","Alleen papier in de gleuf, geen vingertoppen: laat je kind drukken met de hand plat bovenop.","Strooi confetti niet in elkaars gezicht: een snippertje in het oog prikt en is lastig weg te krijgen."],"say":["Klak! Nog een keer!","Wat denk je dat er in het klepje zit?","Ik zie gaatjes in je papier, en hier liggen de rondjes die eruit kwamen!","Wat druk je hard. Je handen worden er sterk van!","Hoeveel rode rondjes heb jij al?"],"words":["gaatje","rondje","drukken","hard","confetti","strooien","klein"],"learn":["fijne-motoriek","rekenen","concentratie"],"tips":["Gebruik dun papier: een te dikke of dubbelgevouwen strook loopt vast en kost veel kracht.","Werk boven een dienblad of in een grote doos: de confetti blijft bij elkaar en je giet hem zo in een potje.","Ligt er toch confetti op de vloer? Stofzuig het op of druk er een stuk plakband op."],"variations":["Verjaardag: strooi confetti op een zelfgemaakte uitnodiging of plak hem op een feestmuts.","Oud en nieuw: plak confetti als vuurwerk op zwart papier.","Carnaval: plak confetti op een masker of een papieren hoed.","Herfst: pons gaatjes in verse bladeren en maak bladerconfetti in groen, geel en rood."],"themes":["verjaardag","oudennieuw","carnaval"]},
  {"id":"papieren-slinger","title":"Papieren kettingslinger","emoji":"🎉","category":"plakken","summary":"Plak stroken papier tot ringen die in elkaar haken en maak samen een lange slinger: hoe lang wordt hij, en welk patroon kies je?","ageMin":3,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":25,"supervision":2,"materials":[{"id":"gekleurd-papier","note":"in stroken van ongeveer 3 x 20 cm"},{"id":"plakband","note":"kleine stukjes alvast aan de tafelrand plakken"},{"id":"schilderstape","note":"om de slinger op te hangen"}],"optional":[{"id":"lijmstift","note":"in plaats van plakband"},{"id":"nietmachine","note":"snel en stevig; dat doe jij"},{"id":"kinderschaar","note":"voor kleuters die zelf stroken knippen"},{"id":"tijdschriften","note":"stroken uit folders voor een bonte slinger"}],"steps":["Knip gekleurd papier in stroken van ongeveer 3 cm breed en 20 cm lang. Een kleuter kan langs een getekende lijn meeknippen.","Plak alvast een rij stukjes plakband aan de rand van de tafel, zodat je kind ze makkelijk kan pakken.","Buig de eerste strook tot een ring en plak de uiteinden op elkaar.","Steek de volgende strook door de ring, buig hem rond en plak hem dicht. Zo groeit de ketting ring voor ring.","Kies samen een patroon, bijvoorbeeld rood, geel, rood, geel… Welke kleur komt er nu?","Hang de slinger op met schilderstape, hoog en buiten bereik van baby’s, en niet bij een bed."],"ageTips":{"young":"Voor een driejarige is de ring dichtplakken lastig: houd jij de uiteinden vast en laat je kind het plakbandje erop drukken. Een korte slinger van vijf ringen is al een feest.","old":"Laat je kleuter een patroon bedenken en volhouden, zoals rood-geel-geel, en tellen: hoeveel ringen heb je nodig van de deur tot de kast?"},"safety":["Een lange slinger is net een koord: hang hem hoog op, nooit bij bed, box of kinderstoel, en laat je kind hem niet om de nek leggen.","Nietjes zijn klein en scherp: de nietmachine is voor jou, en raap losse nietjes meteen op."],"say":["Rondje! Nog een rondje!","Rood, geel, rood, geel… welke kleur komt er nu?","Kijk eens hoe lang hij al is! Hoeveel ringen zijn het?","Ik zie dat je de strook netjes door de ring hebt gestoken. Lastig, en het is je toch gelukt!","Waar zullen we de slinger ophangen?"],"words":["ring","strook","ketting","patroon","lang","langer","door"],"learn":["rekenen","fijne-motoriek","concentratie","samen"],"tips":["Snelste manier: jij zet de ringen vast met de nietmachine, je kind kiest de kleur en steekt de strook door de ring.","Begin een paar dagen voor het feest en maak een aftelketting: elke dag mag er één ring af."],"variations":["Verjaardag: maak een aftelketting met evenveel ringen als nachtjes slapen tot het feest.","Kerst: maak een rood-groene slinger voor de kerstboom of rond de deur.","Koningsdag: rood, wit, blauw en oranje, voor in de vensterbank of boven de tafel."],"themes":["verjaardag","kerst","koningsdag"]},
  {"id":"lampion","title":"Een lampion voor Sint-Maarten","emoji":"🏮","category":"plakken","summary":"Plak snippers vloeipapier op een fles, melkpak of pot, maak er een hengsel aan en loop zingend rond met je eigen gloeiende lampion.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":15,"durationMinutes":30,"supervision":2,"materials":[{"id":"plastic-flesjes","note":"een lege fles van 1 tot 1,5 liter; de bovenkant knip jij eraf"},{"id":"vloeipapier","note":"in snippers van een paar centimeter, in een paar kleuren"},{"id":"knutsellijm","note":"aangelengd met water: 2 delen lijm op 1 deel water"},{"id":"water"},{"id":"kom","note":"om de lijm in aan te lengen"},{"id":"penselen","note":"een brede kwast"},{"id":"plakband","note":"om de scherpe snijrand af te plakken"},{"id":"touw","note":"voor een kort hengsel"},{"id":"led-lampje","note":"een waxinelichtje op batterij of een lampionstokje met lampje"},{"id":"schaar","note":"voor jou, om de fles op maat te knippen"}],"optional":[{"id":"melkpak","note":"met uitgeknipte raampjes, in plaats van de fles"},{"id":"glazen-pot","note":"voor kleuters van 4-5 jaar: extra mooi, maar breekbaar"},{"id":"takjes","note":"een stevig stokje om de lampion aan te dragen"},{"id":"oud-laken","note":"als knoeimat"}],"steps":["Knip de fles af op ongeveer 15 cm hoogte en plak een strook plakband over de scherpe rand. Dat doe jij.","Roer in een bakje 2 delen knutsellijm met 1 deel water tot een dunne lijm.","Laat je kind met een brede kwast een stukje van de fles insmeren en er snippers vloeipapier op leggen. Strijk er nog wat lijm overheen.","Werk zo rondom de hele fles. Overlappen mag: daar ontstaan nieuwe kleuren!","Laat de lampion een nacht drogen. Prik daarna bovenaan twee gaatjes tegenover elkaar en knoop er een kort hengsel aan. Dat doe jij.","Zet het ledlampje erin, doe de grote lamp uit en oefen samen de liedjes: Sint-Maarten, Sint-Maarten, de koeien hebben staarten…"],"ageTips":{"young":"Voor een tweejarige werkt een plastic fles het best: licht en niet breekbaar. Laat je kind vooral snippers op de lijm leggen en strijk jij er een laagje lijm overheen.","old":"Een kleuter van 4 of 5 kan een glazen jampot beplakken en zelf snippers knippen. Plak er zwarte figuurtjes op, zoals een maan, sterren of een kat: die steken mooi af tegen de kleuren."},"safety":["Gebruik nooit een echte kaars of een waxinelichtje met vlam: vloeipapier vat in een paar seconden vlam. Alleen een ledlampje.","Ledlampjes werken vaak op een knoopcelbatterij, die levensgevaarlijk is bij inslikken. Plak het batterijklepje dicht met tape en bewaar reservebatterijen buiten bereik.","Een glazen pot alleen voor kleuters vanaf 4 jaar, en laat er niet mee rennen: glas breekt op een stoep. Plak bij een fles de snijrand goed af.","Houd het hengsel kort en hang de lampion na afloop niet bij bed of box: touw is een wurggevaar."],"say":["Plak! Rood, en nog een!","Kijk eens wat er gebeurt als het lampje aangaat!","Waar schijnt het licht door het papier? En waar is het donkerder?","Wat heb je geduldig geplakt, helemaal rond de fles!","Zullen we samen het lampionliedje oefenen?"],"words":["lampion","licht","donker","doorschijnend","kleverig","hengsel","zingen"],"learn":["fijne-motoriek","creativiteit","taal"],"tips":["Maak de lampion minstens een dag van tevoren: de lijm moet goed droog zijn, anders plakt het vloeipapier aan handen en jas.","Lampion van een melkpak: knip er raampjes in (dat doe jij), plak de binnenkant dicht met vloeipapier en versier de buitenkant met stift.","Plak het waxinelichtje met een rolletje plakband op de bodem vast, dan schuift het niet heen en weer tijdens het lopen."],"variations":["Pompoenlampion: gebruik alleen oranje vloeipapier en plak er een gezichtje van zwart papier op.","Sterrenlampion: donkerblauw vloeipapier met gele sterren van papier.","Optocht in huis: doe alle lampen uit, loop met de lampions door de gang en zing bij elke deur een liedje (met een mandarijn als beloning)."],"themes":["sintmaarten"]},
  {"id":"speeldeeg-maken","title":"Speeldeeg maken zonder koken","emoji":"🥣","category":"deeg","summary":"Weeg, roer en kneed samen je eigen zachte speeldeeg in jullie lievelingskleur: zelf maken is de helft van de pret.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":5,"durationMinutes":30,"supervision":1,"materials":[{"id":"bloem","note":"250 g"},{"id":"zout","note":"125 g fijn zout"},{"id":"olie","note":"2 el"},{"id":"water","note":"ca. 200 ml, kokend"},{"id":"kookplaat","note":"of waterkoker, voor het kokende water"},{"id":"kom","note":"een grote"},{"id":"lepel","note":"een stevige (houten) lepel om te roeren"},{"id":"kleurstof","note":"een paar druppels per kleur"}],"optional":[{"id":"zip-zakjes","note":"om de kleur zonder vlekken door te kneden, en om te bewaren"},{"id":"potjes","note":"afgesloten bakjes om het deeg in te bewaren"},{"id":"oud-shirt"}],"steps":["Weeg samen 250 g bloem en 125 g zout af in een grote kom. Je kind mag strooien en roeren.","Doe er 2 el olie bij, en eventueel 1 el citroensap: dan blijft het deeg langer goed.","Giet er ca. 200 ml kokend water bij en roer met een lepel tot alles samenkomt (dat doe jij; je kind kijkt op afstand).","Laat het deeg een paar minuten afkoelen. Voel eerst zelf of het niet meer heet is.","Kneed het deeg samen glad op tafel. Plakt het? Strooi er dan een beetje bloem bij.","Verdeel het in bollen, maak er een kuiltje in en druppel er kleurstof in. Kneed de kleur erdoor, het liefst in een ritszakje.","Bewaar het deeg in een afgesloten bakje of zakje in de koelkast: zo blijft het 1-2 weken goed."],"ageTips":{"young":"Een tweejarige kan vooral strooien, roeren in de droge bloem en kneden zodra het deeg lauw is. Geef je peuter een eigen klein bolletje om alvast mee te knijpen.","old":"Laat je kleuter zelf afwegen (wanneer staat de weegschaal op 250?), de lepels olie tellen en een mengkleur bedenken: wat krijg je als je geel en blauw deeg door elkaar kneedt?"},"safety":["Kokend water: dat doe jij. Zet de kom ver van de tafelrand en laat je kind pas meekneden als het deeg lauw is.","Speeldeeg bevat veel zout: niet opeten, en giftig voor honden. Houd het buiten bereik van huisdieren.","Rauwe bloem kan bacteriën bevatten: proeven is niet de bedoeling. Proeft je kind veel, verhit de bloem dan eerst 5 minuten op 175 °C in de oven en laat hem afkoelen."],"say":["Kneden, kneden, kneden!","Hoe voelt het deeg nu: warm, zacht of plakkerig?","Wat denk je dat er gebeurt als we blauw en geel door elkaar kneden?","Ik zie dat het deeg rood wordt, en je handen ook een beetje!","Wat heb jij stevig gekneed, je armen zijn vast moe!"],"words":["afwegen","roeren","kneden","plakkerig","zacht","warm","mengen","bolletje"],"learn":["fijne-motoriek","rekenen","zintuigen","ontdekken"],"tips":["Kneed de kleurstof door het deeg in een ritszakje: geen vlekken op handen en tafel.","Te plakkerig? Een beetje bloem erbij. Te droog of brokkelig? Kneed er een paar druppels olie of water door.","Haal het deeg een kwartiertje voor het spelen uit de koelkast, dan is het weer lekker soepel."],"variations":["Sinterklaas: kneed er 1 tl speculaaskruiden door voor geurig, bruin deeg.","Kerst: maak rood en groen deeg en steek er sterren en boompjes uit.","Regenboog: verdeel het deeg in zes bolletjes en geef elk een eigen kleur."],"themes":[]},
  {"id":"zoutdeeg","title":"Zoutdeeg-hangers en afdrukjes","emoji":"🧂","category":"deeg","summary":"Kneed zoutdeeg, steek hangers uit of maak een handafdruk, droog ze in de oven en beschilder ze: een cadeautje dat jaren meegaat.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":5,"durationMinutes":30,"supervision":1,"materials":[{"id":"bloem","note":"200 g"},{"id":"zout","note":"100 g fijn zout"},{"id":"water","note":"±125 ml lauw water"},{"id":"kom"},{"id":"deegroller"},{"id":"uitsteekvormpjes","note":"of een glas om rondjes uit te steken"},{"id":"rietjes","note":"om een ophanggaatje te prikken"},{"id":"bakpapier"},{"id":"oven"},{"id":"plakkaatverf","note":"om te beschilderen als alles droog is"},{"id":"penselen"}],"optional":[{"id":"touw","note":"lint of touw om de hanger op te hangen"},{"id":"mes","note":"om een rondje om de handafdruk te snijden (dat doe jij)"},{"id":"knutsellijm","note":"verdund met wat water als glanslaagje"},{"id":"oud-shirt"}],"steps":["Meng samen 200 g bloem en 100 g zout in een kom. Giet er beetje bij beetje ±125 ml lauw water bij en kneed tot een stevig, glad deeg.","Rol het deeg op bakpapier uit tot ongeveer een halve centimeter dik. Voor een handafdruk maak je een plak van ruim 1 cm.","Steek vormpjes uit. Voor een handafdruk druk je de hand van je kind stevig in het deeg en snijd je er een rondje omheen (dat doe jij).","Prik met een rietje een gaatje bovenin, zodat je de hanger later kunt ophangen.","Droog alles op de bakplaat 1-3 uur in de oven op 100-120 °C (dat doe jij), of 2-3 dagen aan de lucht. Dikke stukken hebben langer nodig.","Laat alles helemaal afkoelen en beschilder het dan met plakkaatverf. Rijg er een lintje door als de verf droog is."],"ageTips":{"young":"Een tweejarige vindt kneden, prikken en vormpjes drukken het leukst. Rol jij het deeg uit; je peuter drukt de vormpjes met twee handen. Bij een handafdruk druk jij zachtjes mee terwijl jullie tot drie tellen.","old":"Laat je kleuter zelf het water afmeten en kneden, met een potlood een naam of jaartal in de achterkant krassen en bedenken welke hanger voor wie is."},"safety":["Zoutdeeg bevat veel zout: niet opeten, en giftig voor honden. Hang de hangers hoog in de kerstboom als je een hond hebt.","De oven en de bakplaat zijn heet: dat doe jij. Laat alles op de plaat afkoelen voordat je kind het pakt.","Plakkaatverf kan vlekken op kleding en tafel: kies afwasbare kinderverf en trek een oud shirt aan."],"say":["Druk! Hard drukken!","Hoe voelt het deeg: korrelig of glad?","Ik zie al je vingers in het deeg staan, zelfs je duim!","Wie krijgt deze hanger, denk je?","Wat schilder je zorgvuldig, je neemt echt de tijd."],"words":["kneden","uitrollen","uitsteken","afdruk","gaatje","korrelig","hard","drogen"],"learn":["fijne-motoriek","creativiteit","zintuigen"],"tips":["Bobbelt het deeg in de oven? Zet de oven lager (100 °C) en droog wat langer.","Een laagje verdunde knutsellijm na het verven maakt de hanger glanzend en steviger.","Overgebleven deeg blijft in een afgesloten zakje in de koelkast nog een paar dagen goed."],"variations":["Kerst: steek sterren, boompjes en hartjes uit voor in de kerstboom.","Moederdag: maak een hartje met de vingerafdrukken van je kind en rijg er een lint door.","Herfst: rol een blad over het deeg en bekijk de nerven in de afdruk.","Naambordje: steek een groot rondje uit en kras er samen de naam van je kind in, voor op de kamerdeur."],"themes":["kerst","cadeau","moederdag"]},
  {"id":"wolkendeeg","title":"Wolkendeeg: zacht maanzand","emoji":"☁️","category":"deeg","summary":"Met alleen bloem en olie maak je wolkendeeg: zo zacht als een wolk, kruimelig als zand en toch te vormen tot taartjes en bergen.","ageMin":2,"ageMax":5,"mess":3,"wet":false,"dirty":true,"prepMinutes":5,"durationMinutes":30,"supervision":2,"materials":[{"id":"bloem","note":"500 g"},{"id":"olie","note":"125 ml zonnebloemolie (of babyolie, dan niet om te proeven)"},{"id":"opbergbak","note":"een grote bak om in te mengen en te spelen"}],"optional":[{"id":"uitsteekvormpjes","note":"of zandvormpjes"},{"id":"plastic-bekers","note":"om taartjes mee te maken"},{"id":"lepel","note":"om te scheppen"},{"id":"klein-speelgoed","note":"diertjes of autootjes om te verstoppen"},{"id":"oud-laken","note":"als knoeimat"}],"steps":["Leg een knoeimat neer en zet een grote bak op de vloer of tafel: wolkendeeg komt overal.","Doe 500 g bloem in de bak en giet er 125 ml olie over.","Wrijf en kneed het samen met je handen door elkaar tot het kruimelig is, maar een bal blijft als je erin knijpt. Te droog? Nog een scheutje olie.","Geef bekertjes, vormpjes en lepels: bak zandtaartjes, bouw bergen en graaf tunnels.","Verstop diertjes of autootjes in het deeg en laat je kind ze weer opgraven.","Bewaar het wolkendeeg in een afgesloten bak: het blijft een paar weken goed. Veeg of zuig kruimels eerst droog op; een natte doek maakt er pap van."],"ageTips":{"young":"Een tweejarige schept en graaft het liefst. Geef één grote lepel, een beker en een paar grote diertjes, en speel in een bak met een hoge rand.","old":"Laat je kleuter zelf afmeten en mengen, een maanlandschap bouwen met kraters en een raket van een wc-rolletje, of zandtaartjes tellen en verkopen."},"safety":["Rauwe bloem kan bacteriën bevatten: niet opeten. Proeft je kind veel, verhit de bloem dan eerst 5 minuten op 175 °C in de oven, laat hem afkoelen en gebruik zonnebloemolie in plaats van babyolie.","Kruimels met olie maken de vloer glad: veeg ze direct op.","Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3: verstop voor je peuter alleen grote speeltjes."],"say":["Knijp… en het blijft een bal!","Hoe voelt het: zacht, koel of een beetje vettig?","Wat gebeurt er als je de bal weer loslaat en erop drukt?","Ik zie dat je een hele hoge berg bouwt.","Graven! Wie zit daar verstopt?"],"words":["kruimelig","zacht","knijpen","graven","scheppen","vormpje","berg","verstoppen"],"learn":["zintuigen","fijne-motoriek","creativiteit","ontdekken"],"tips":["Speel op een oud laken of in de lege badkuip: schud het laken daarna uit boven de vuilnisbak of veeg de badkuip leeg met een stoffer.","Olie kan vetvlekjes geven op kleding en vloerkleed: trek oude kleren aan en speel liever op een gladde vloer.","Wolkendeeg is goedkoop: huismerkbloem en gewone zonnebloemolie werken prima."],"variations":["Zomer: zet er schelpen en emmertjes bij en bouw een zandkasteel.","Bouwplaats: laat graafmachines en vrachtautootjes het deeg verplaatsen.","Geurdeeg: meng er 1 el kaneel of speculaaskruiden door voor een bruine, geurige versie.","Maanlandschap: druk kraters met een bal en laat een raket van een wc-rolletje landen."],"themes":[]},
  {"id":"sneeuwdeeg","title":"Sneeuwdeeg van maizena","emoji":"⛄","category":"deeg","summary":"Kneed maizena en conditioner tot koel, zijdezacht sneeuwdeeg en bouw binnen sneeuwpoppen, iglo’s en een winterlandschap voor je speelgoeddieren.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":3,"durationMinutes":25,"supervision":2,"materials":[{"id":"maizena","note":"200 g"},{"id":"conditioner","note":"100 ml; liefst mild en zonder sterke geur"},{"id":"kom","note":"of een bak om in te mengen"}],"optional":[{"id":"dienblad","note":"met randje, om op te spelen"},{"id":"klein-speelgoed","note":"pinguïns, ijsberen of andere diertjes"},{"id":"takjes","note":"als bomen of als armen voor de sneeuwpop"},{"id":"koelkast","note":"voor extra koude sneeuw"}],"steps":["Doe 200 g maizena in een kom en laat je kind er eerst in voelen: hoor je het knerpen als je knijpt?","Giet er 100 ml conditioner bij en kneed met je handen tot een zacht deeg dat aan elkaar plakt als je knijpt. Te plakkerig? Nog wat maizena erbij.","Leg het deeg 15 minuten in de koelkast als je het extra koud wilt: dan voelt het nog meer als sneeuw.","Rol balletjes en bouw samen sneeuwpoppen: een grote bal onderop, een kleine erbovenop, takjes als armen.","Zet speelgoeddieren in de sneeuw: laat ze sporen maken, een iglo bouwen of verstoppertje spelen.","Bewaar het deeg een paar dagen in een afgesloten bakje. Gooi restjes in de vuilnisbak, niet door de gootsteen."],"ageTips":{"young":"Een tweejarige vindt knijpen en verkruimelen het leukst. Speel op een dienblad met rand, geef een lepel en een bekertje en houd een doekje klaar voor de handjes.","old":"Laat je kleuter zelf afwegen (200 g maizena, 100 ml conditioner) en een heel winterdorp bouwen. Hoeveel sneeuwballen heb je nodig voor drie sneeuwpoppen?"},"safety":["Conditioner is niet om te eten en prikt in de ogen: houd een doekje klaar en was handen na afloop. Stopt je kind nog alles in de mond, kies dan eetbaar havermoutdeeg.","Gemorste maizena maakt de vloer spiegelglad: veeg het meteen op."],"say":["Brrr, koud! Voel je dat?","Hoor je het knerpen als je knijpt?","Wat gebeurt er als je een bal rolt en hem dan platdrukt?","Ik zie pootafdrukken in de sneeuw. Van wie zouden die zijn?","Wat heb je lang en geduldig gerold!"],"words":["sneeuw","koud","zijdezacht","knerpen","rollen","sneeuwpop","spoor","bovenop"],"learn":["zintuigen","fijne-motoriek","creativiteit","taal"],"tips":["Speel op een dienblad of bakplaat met rand: de kruimels blijven dan bij elkaar.","Neem de goedkoopste conditioner; zonder sterke geur is het fijner voor de huid en de neus."],"variations":["Poolgebied: zet pinguïns en ijsberen in de sneeuw en bouw een iglo van bolletjes.","Kerst: prik groene takjes als kerstboompjes in de sneeuw en geef de sneeuwpop een sjaaltje van vilt.","Sporen raden: laat autootjes of dierenpootjes sporen maken en raad samen van wie ze zijn."],"themes":["winter","kerst"]},
  {"id":"eetbaar-deeg","title":"Eetbaar speeldeeg voor de kleinsten","emoji":"🌾","category":"deeg","summary":"Maak zacht deeg van havermout, olie en water dat je dreumes gerust mag proeven: knijpen, prikken en platslaan zonder zorgen.","ageMin":1,"ageMax":2,"mess":2,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":15,"supervision":2,"materials":[{"id":"havermout","note":"100 g"},{"id":"blender","note":"of staafmixer, om de havermout fijn te malen"},{"id":"olie","note":"1 el zonnebloemolie"},{"id":"water","note":"±5-6 el"},{"id":"kom"}],"optional":[{"id":"dienblad","note":"of het blad van de kinderstoel"},{"id":"uitsteekvormpjes","note":"grote, zonder scherpe randjes"},{"id":"plastic-bekers","note":"om rondjes mee uit te steken"}],"steps":["Maal 100 g havermout in de blender tot fijn meel (dat doe jij).","Doe het meel in een kom met 1 el olie en voeg lepel voor lepel water toe (±5-6 el), tot je een soepel deeg hebt.","Kneed het deeg kort door en geef je dreumes een flinke bol op een dienblad of het blad van de kinderstoel.","Doe voor wat je allemaal kunt: een balletje rollen, een plat koekje slaan, gaatjes prikken met je vinger.","Geef er een bekertje of groot vormpje bij om in te drukken of rondjes mee uit te steken.","Bewaar restjes afgedekt in de koelkast en gebruik ze binnen 1-2 dagen."],"ageTips":{"young":"Een dreumes van 1 ontdekt vooral met handen en mond. Geef één bol zonder spulletjes erbij en benoem wat er gebeurt: plat, rond, een gaatje!","old":"Een tweejarige kan meehelpen met water erbij lepelen en kneden, slangetjes rollen en met een beker koekjes uitsteken. Tel ze samen: één, twee, drie!"},"safety":["Ook eetbaar deeg is plakkerig en kan in de keel blijven steken: laat je dreumes rechtop zitten en blijf erbij als er gehapt wordt.","Havermout bevat vaak sporen van gluten: kies glutenvrije havermout bij coeliakie of een glutenallergie.","Het mes van de blender is vlijmscherp: dat doe jij, en haal de stekker eruit voordat je het meel eruit schept.","Het deeg bederft snel: bewaar het in de koelkast en gooi het na 1-2 dagen weg, of eerder als het zuur ruikt."],"say":["Knijp! Zacht hè?","Plat! Nog eens!","Ik zie dat je er met je vinger een gaatje in prikt.","Hoe ruikt het? Een beetje naar pap?","Wat rol jij goed, met allebei je handen!"],"words":["zacht","plakkerig","knijpen","plat","rond","rollen","prikken","gaatje"],"learn":["zintuigen","fijne-motoriek","taal","ontdekken"],"tips":["Doe het vlak voor het badje: havermout plakt een beetje, maar veegt makkelijk af met een vochtig washandje.","Te plakkerig? Strooi er wat havermoutmeel bij. Te droog? Nog een lepel water."],"variations":["Kleurtje: kneed er een theelepel bietensap of een paar geprakte blauwe bessen door (dat vlekt wel een beetje).","Geurtje: kneed er een snufje kaneel door en ruik er samen aan.","Feestje: steek met een bekertje taartjes uit en zing samen ‘Lang zal ze leven’."],"themes":[]},
  {"id":"deegbakkerij","title":"Bakkertje spelen met speeldeeg","emoji":"🎂","category":"deeg","summary":"Rol, steek uit en versier: je kind is de bakker en bakt koekjes, broodjes en een verjaardagstaart met kaarsjes, en jij komt alles kopen.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":25,"supervision":2,"materials":[{"id":"speeldeeg","note":"zelfgemaakt of gekocht, in een paar kleuren"},{"id":"deegroller","note":"of een glazen fles"},{"id":"uitsteekvormpjes","note":"of een beker en een flessendop"},{"id":"rietjes","note":"in stukjes geknipt, als kaarsjes"}],"optional":[{"id":"papieren-bordjes","note":"als taartbordjes"},{"id":"muffinvorm","note":"voor taartjes"},{"id":"ijsstokjes","note":"als taartmes, of als kaarsjes voor peuters"},{"id":"papier","note":"voor prijskaartjes"}],"steps":["Richt samen een bakkerij in: een theedoek als toonbank, bordjes, een deegroller en vormpjes.","Rol het deeg uit en steek koekjes uit, of rol balletjes tot bolletjes en broodjes.","Bak een verjaardagstaart: druk een dikke bol deeg plat op een bord en prik er stukjes rietje in als kaarsjes.","Zing samen ‘Lang zal ze leven’ en blaas de kaarsjes uit. Trek ze er dan één voor één weer uit.","Speel winkeltje: jij komt kopen. Mag ik drie koekjes? Tel ze samen uit: één, twee, drie!","Ruim op door het deeg per kleur terug te stoppen in een afgesloten bakje."],"ageTips":{"young":"Een tweejarige rolt, prikt en drukt het liefst. Geef zacht, soepel deeg en grote vormpjes, en gebruik hele rietjes of ijsstokjes als kaarsjes.","old":"Laat je kleuter prijskaartjes tekenen, bestellingen opnemen (twee rode koekjes en één taart) en het wisselgeld tellen. Hoeveel kaarsjes horen er op een taart voor een vijfjarige?"},"safety":["Speeldeeg bevat veel zout: niet opeten, en giftig voor honden; houd het buiten bereik van huisdieren. Proeft je peuter veel, kies dan eetbaar havermoutdeeg.","Stukjes rietje passen door een wc-rolletje: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Gebruik voor je peuter hele rietjes of ijsstokjes."],"say":["Rollen, rollen… plat!","Mag ik drie koekjes, alstublieft?","Hoe oud is de jarige? Hoeveel kaarsjes moeten erop?","Ik zie dat je de koekjes netjes naast elkaar legt.","Wat bak jij een bijzondere taart, hoe heb je dat bedacht?"],"words":["bakker","rollen","uitsteken","taart","kaarsjes","kopen","alstublieft","dank je wel"],"learn":["fijne-motoriek","rekenen","taal","samen"],"tips":["Speel op een dienblad of onderlegger: kruimels deeg blijven dan bij elkaar en plakken niet in het kleed.","Geen vormpjes? Een beker, een flessendop en een vork werken net zo goed."],"variations":["Verjaardag: oefen het feestje met een knuffel als jarige, een taart, kaarsjes en een liedje.","Pizzeria: rol rondjes uit en beleg ze met deegballetjes en -slierten.","Sinterklaas: rol kleine bolletjes als kruidnoten en verkoop ze per zakje.","IJssalon: bolletjes deeg in een bekertje, met een rietje als lepeltje."],"themes":["verjaardag"]},
  {"id":"deegafdrukken","title":"Afdrukken en fossielen in deeg","emoji":"🦕","category":"deeg","summary":"Druk schelpen, blaadjes, vorken en dinopootjes in plat speeldeeg en ontdek welke patronen ze achterlaten: kun jij raden wat het was?","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":20,"supervision":2,"materials":[{"id":"speeldeeg","note":"zelfgemaakt of gekocht"},{"id":"vork","note":"voor strepen en ruitjes"},{"id":"klein-speelgoed","note":"bijv. speelgoeddino’s of andere dieren met pootjes"}],"optional":[{"id":"duplo","note":"voor stippenpatronen"},{"id":"schelpen","note":"gladde, hele schelpen"},{"id":"bladeren","note":"met dikke nerven"},{"id":"dennenappels","note":"voor een schubbenpatroon"},{"id":"deegroller","note":"om het deeg plat te rollen"}],"steps":["Rol of druk een paar flinke plakken speeldeeg plat, ongeveer 1 cm dik.","Zoek samen spullen met een mooi patroon: een schelp, een blad met dikke nerven, een vork, een duploblokje, de pootjes van een speelgoeddino.","Druk ze één voor één stevig in het deeg en haal ze er voorzichtig weer uit: kijk, een afdruk!","Speel ‘raad wat het was’: je kind doet de ogen dicht, jij maakt een afdruk en je kind raadt welk voorwerp het was.","Laat de dino’s een spoor door het deeg lopen: wie liep hier, een grote of een kleine?","Kneed het deeg weer tot een bal en begin opnieuw."],"ageTips":{"young":"Een tweejarige drukt het liefst zelf. Geef grote voorwerpen die makkelijk vast te houden zijn, zoals een duploblok of een vork, en druk samen met jouw hand eroverheen.","old":"Laat je kleuter een fossielenmuseum maken: afdrukken op een rij met een naamkaartje erbij. Of leg de voorwerpen ernaast en laat je kleuter ze bij de juiste afdruk zoeken."},"safety":["Kies gladde, hele schelpen: gebroken schelpen hebben scherpe randjes. Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3.","Speeldeeg bevat veel zout: niet opeten, en giftig voor honden. Houd het buiten bereik van huisdieren."],"say":["Druk! En nu… optillen!","Wat zie je in de afdruk: lijntjes, rondjes of stippen?","Welk voorwerp heeft dit gemaakt, denk je?","Ik zie dat je heel voorzichtig optilt, zo blijft de afdruk mooi.","Hoe voelt de schelp: glad of ribbelig?"],"words":["afdruk","drukken","spoor","ribbels","nerven","fossiel","glad","hobbelig"],"learn":["zintuigen","ontdekken","fijne-motoriek","taal"],"tips":["Wil je een afdruk bewaren? Maak hem in zoutdeeg en laat hem drogen in de oven of aan de lucht.","Bewaar een doosje met ‘afdrukspullen’: schelpen en blaadjes van een wandeling, een oude vork en een paar blokjes."],"variations":["Zomer: druk schelpen in het deeg voor een strand vol fossielen en zet er een speelgoedkrab bij.","Herfst: druk blaadjes, dennenappels en takjes in het deeg en bekijk de nerven en schubben.","Dinojacht: verstop speelgoeddino’s, laat sporen achter en zoek de dino bij het spoor.","Rolpatroon: rol een autootje of een vork over het deeg: wat voor spoor geeft dat?"],"themes":["zomer","herfst"]},
  {"id":"deeg-egeltjes","title":"Deeg-egeltjes met spaghettistekels","emoji":"🦔","category":"deeg","summary":"Rol een egel van speeldeeg en prik er stukjes droge spaghetti in als stekels: hoeveel stekels krijgt jouw egel?","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":20,"supervision":2,"materials":[{"id":"speeldeeg","note":"een bal zo groot als een mandarijn per egel"},{"id":"pasta","note":"droge spaghetti, in stukjes van ±4 cm gebroken"}],"optional":[{"id":"rietjes","note":"in stukjes geknipt: dikker en makkelijker voor peuters"},{"id":"bladeren","note":"voor een herfstbos rond de egels"},{"id":"wiebeloogjes","note":"pas vanaf 3 jaar"}],"steps":["Breek droge spaghetti in stukjes van ongeveer 4 cm (dat doe jij) en leg ze in een bakje.","Rol samen een bal speeldeeg en knijp er aan één kant een puntje aan: de snuit van de egel.","Prik de stekels één voor één in de rug van de egel. Hoeveel passen erop?","Rol twee kleine deegbolletjes als oogjes en een iets grotere als neus, of druk de ogen in met een potlood.","Leg bladeren neer als herfstbos en zet de egels erin.","Trek de stekels er na het spelen uit, gooi gebroken stukjes weg en bewaar het deeg in een afgesloten bakje."],"ageTips":{"young":"Een tweejarige prikt makkelijker met dikkere stekels, zoals stukjes rietje. Geef ze één voor één aan en help de egel stevig vast te houden.","old":"Laat je kleuter een egelfamilie maken: een grote, een middelste en een kleine. Wie heeft de meeste stekels? Tel en vergelijk, of maak een patroon met lange en korte stekels."},"safety":["Droge spaghetti breekt in kleine, scherpe stukjes: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Blijf bij je peuter en ruim gebroken stukjes meteen op.","Speeldeeg bevat veel zout: niet opeten, en giftig voor honden. Houd het buiten bereik van huisdieren.","Gebruik geen wiebeloogjes of kralen als oogjes bij kinderen onder de 3: maak de oogjes van deeg."],"say":["Prik! Nog een stekel!","Au, puntig! Hoe voelen de stekels?","Hoeveel stekels heeft jouw egel al?","Ik zie dat je de stekels heel voorzichtig rechtop zet.","Wat zou een egel eten, denk je?"],"words":["egel","stekels","prikken","puntig","rond","snuit","winterslaap"],"learn":["fijne-motoriek","rekenen","concentratie","creativiteit"],"tips":["Breek de spaghetti in een theedoek: dan vliegen er geen stukjes door de keuken.","Bewaar het deeg en de stekels samen in een afgesloten bakje: een kant-en-klaar herfstspelletje."],"variations":["Herfst: bouw een bladerhoopje als winterslaapnest en stop de egels erin.","Verjaardag: maak een taart van deeg en prik er spaghetti in als kaarsjes.","Monsters: prik er pijpenragers met omgevouwen puntjes en rietjes in als haar en voelsprieten.","Cactus: groen deeg met spaghettistekels in een bekertje als bloempot."],"themes":["herfst"]},
  {"id":"papier-mache","title":"Papier-maché-kommetje","emoji":"📰","category":"deeg","summary":"Plak laagjes krant met zelfgemaakt plaksel over een kom en beschilder het kommetje als het hard is: heerlijk kliederen met iets om te bewaren.","ageMin":4,"ageMax":5,"mess":3,"wet":true,"dirty":true,"prepMinutes":10,"durationMinutes":30,"supervision":2,"materials":[{"id":"kranten","note":"in repen en snippers gescheurd"},{"id":"bloem","note":"100 g, voor het plaksel"},{"id":"water","note":"200 ml, voor het plaksel"},{"id":"zout","note":"een snufje"},{"id":"kom","note":"één als mal en één voor het plaksel"},{"id":"huishoudfolie","note":"of aluminiumfolie, om de mal in te pakken"},{"id":"plakkaatverf","note":"om te beschilderen als het droog is"},{"id":"penselen"}],"optional":[{"id":"keukenpapier","note":"als witte laag, dan zie je welke laag nieuw is"},{"id":"knutsellijm","note":"verdund met wat water als glanslaagje"},{"id":"oud-laken","note":"als knoeimat"},{"id":"oud-shirt"}],"steps":["Scheur samen kranten in repen en snippers van ongeveer 2 bij 5 cm. Scheuren is al een prima klus voor je kleuter.","Maak het plaksel: roer 100 g bloem met 200 ml water glad in een kom en doe er een snufje zout door.","Zet een andere kom ondersteboven op tafel en pak hem strak in met huishoudfolie.","Haal een snipper door het plaksel, strijk het overtollige plaksel eraf tussen twee vingers en plak hem op de kom. Leg de snippers dakpansgewijs over elkaar.","Plak zo 3-4 lagen over de hele kom. Wissel krant af met keukenpapier, dan zie je waar de nieuwe laag zit.","Laat het kommetje 1-2 dagen drogen op een warme plek. Haal het dan voorzichtig van de mal, trek de folie eruit en knip de rand recht (dat doe jij).","Beschilder het kommetje met plakkaatverf en laat het weer drogen."],"ageTips":{"young":"Voor een vierjarige zijn kleine snippers lastig: gebruik grotere repen en maak twee of drie lagen. Of beplak een papieren bordje als plat schaaltje, dat is sneller af.","old":"Een vijfjarige kan zelf de lagen tellen (krant, wit, krant…), een ontwerp bedenken voor het schilderen, zoals stippen, strepen of een dierengezicht, en vertellen wat er in het kommetje komt."},"safety":["Plaksel is gemaakt van rauwe bloem: niet proeven, en was handen na afloop.","Het kommetje is niet geschikt voor eten of drinken: gebruik het voor sieraden, sleutels of andere spulletjes.","Plakkaatverf kan vlekken op kleding en tafel: kies afwasbare kinderverf en trek een oud shirt aan."],"say":["Plak, strijk, nog een!","Hoe voelt het plaksel? Glibberig en koud!","Ik zie dat je de snippers netjes over elkaar legt, als dakpannen.","Hoeveel lagen hebben we nu: één, twee of drie?","Wat werk je geduldig, laagje na laagje! Wat wil jij in je kommetje bewaren?"],"words":["plaksel","glibberig","snipper","laag","scheuren","gladstrijken","drogen","hard"],"learn":["fijne-motoriek","creativiteit","concentratie","ontdekken"],"tips":["Werk op een oud laken of een opengeknipte vuilniszak: plaksel droogt op tot harde korstjes.","Gooi restjes plaksel in de vuilnisbak, niet door de gootsteen: het wordt hard in de afvoer.","Haast? Laat het kommetje drogen op de verwarming of in de zon voor het raam."],"variations":["Cadeau: een sieradenbakje voor mama of oma, met een glanslaagje van verdunde knutsellijm.","Vaderdag: een bakje voor sleutels of muntjes, beschilderd in papa’s lievelingskleur.","Zonder verf: plak als laatste laag vloeipapier of servetjes, dan is het kommetje meteen gekleurd."],"themes":["cadeau"]},
  {"id":"rijstbak","title":"Ontdekbak met gekleurde rijst","emoji":"🍚","category":"zintuigen","summary":"Scheppen, gieten en graven in een bak vol gekleurde rijst: het ritselt heerlijk, voelt fijn en er zitten diertjes in verstopt.","ageMin":2,"ageMax":5,"mess":3,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":25,"supervision":2,"materials":[{"id":"rijst","note":"±1 kg; gewoon wit of gekleurd (3 × 200 g, zie Recepten)"},{"id":"opbergbak","note":"met een rand van minstens 10 cm"},{"id":"plastic-bekers","note":"een paar in verschillende maten"},{"id":"lepel","note":"grote lepels of een soeplepel"},{"id":"trechter"},{"id":"klein-speelgoed","note":"diertjes of poppetjes om te verstoppen, groter dan een wc-rolletje"}],"optional":[{"id":"kleurstof","note":"om de rijst te kleuren, een paar druppels per 200 g"},{"id":"azijn","note":"1 tl per 200 g rijst, bij het kleuren"},{"id":"zip-zakjes","note":"om de rijst in te kleuren"},{"id":"bakpapier","note":"om de gekleurde rijst op te drogen"},{"id":"oud-laken","note":"onder de bak als knoeimat"},{"id":"muffinvorm","note":"om te sorteren op kleur"}],"steps":["Kleur de rijst eventueel een dag van tevoren: 200 g rijst, 1 tl azijn en wat kleurstof in een ritszakje schudden en 1-2 uur laten drogen op bakpapier.","Leg een oud laken op de vloer en zet de bak erop. Doe de rijst erin en verstop er een paar diertjes in.","Zet bekers, lepels en de trechter erbij en laat je kind eerst gewoon voelen: handen erin, ritselen, laten vallen.","Schep en giet samen: van beker naar beker, door de trechter, of een beker zo vol dat hij overloopt.","Ga samen op diertjesjacht: graaf, voel en vertel wat je vindt.","Spreek af dat de rijst in de bak blijft. Giet na afloop wat op het laken ligt terug en bewaar de rijst in een bak met deksel."],"ageTips":{"young":"Voor een tweejarige: gebruik grote bekers en grote diertjes en blijf ernaast zitten. Stopt je peuter nog veel in de mond? Neem dan havermout in plaats van rijst.","old":"Een kleuter kan sorteren op kleur in een muffinvorm, tellen hoeveel lepels er in een beker passen, of met de ogen dicht een verstopt diertje zoeken en raden wat het is."},"safety":["Droge rijst kan in de luchtpijp, neus of oren terechtkomen: blijf bij een kind onder de 3 dichtbij en stop als het rijst in de mond, neus of oren stopt.","Verstop alleen speelgoed dat niet door een wc-rolletje past: alles wat erdoor past, is te klein voor kinderen onder de 3.","Rijst op een gladde vloer rolt als knikkers onder je voeten: veeg tussendoor op en speel liefst op een laken of kleed."],"say":["Hoor je dat? Ritsel, ritsel!","Ik zie een staartje uit de rijst steken. Van wie zou dat zijn?","Hoeveel lepels heb je nodig om de beker vol te maken?","Wat giet je voorzichtig, er valt bijna niks naast!","Vol! En nu… leeg!"],"words":["scheppen","gieten","vol","leeg","ritselen","verstoppen","vinden"],"learn":["zintuigen","fijne-motoriek","ontdekken","concentratie"],"tips":["Leg een oud laken onder de bak: na afloop vouw je de hoeken naar elkaar toe en giet je de gemorste rijst zo terug.","In een afgesloten bak blijft (gekleurde) rijst maanden goed. Kook en eet hem na het spelen niet meer.","Laat gekleurde rijst helemaal droog worden voordat je ermee speelt, dan geeft hij niet af op handen en kleren."],"variations":["Bouwplaats: rijd met graafmachientjes en vrachtwagens door de rijst en laad hem over.","Kerst: rode en groene rijst met onbreekbare kerstballen om op te graven.","Herfst: bruine en oranje rijst met dennenappels en kastanjes (kastanjes pas vanaf 3 jaar).","Zee: blauwe rijst met schelpen en plastic visjes die je eruit schept met een zeef."],"themes":[]},
  {"id":"havermoutbak","title":"Havermout-ontdekbak voor dreumesen","emoji":"🥣","category":"zintuigen","summary":"Een ontdekbak voor de allerkleinsten: scheppen, strooien en graven in zachte havermout, en een hapje proeven mag.","ageMin":1,"ageMax":2,"mess":3,"wet":false,"dirty":false,"prepMinutes":3,"durationMinutes":15,"supervision":1,"materials":[{"id":"havermout","note":"±500 g, gewone vlokken"},{"id":"opbergbak","note":"of het blad van de kinderstoel voor een klein bergje"},{"id":"plastic-bekers","note":"2-3 stevige bekers"},{"id":"lepel","note":"een paar grote lepels"},{"id":"klein-speelgoed","note":"grote diertjes of duploblokken, groter dan een wc-rolletje"}],"optional":[{"id":"oud-laken","note":"onder de bak als knoeimat"},{"id":"muffinvorm","note":"om vakjes te vullen"},{"id":"zeef","note":"om ‘sneeuw’ te strooien"},{"id":"ontbijtgranen","note":"een handje erdoor voor een ander geluid"}],"steps":["Leg een oud laken op de vloer en zet de bak erop, of zet je dreumes in de kinderstoel met een paar handen havermout op het blad.","Doe de havermout in de bak en verstop er 3-4 grote diertjes of blokken in.","Ga erbij zitten en laat je kind eerst gewoon voelen: handen erin, knijpen, strooien.","Doe het scheppen voor: een lepel in de beker en dan… omkieperen! Laat je kind het nadoen.","Zoek samen de diertjes: graaf, vind en benoem ze. Waar is de koe?","Vouw het laken na afloop naar het midden toe. Gooi havermout die in een mond of op de vloer is geweest weg en bewaar de rest droog."],"ageTips":{"young":"Een dreumes van 1 jaar heeft genoeg aan één beker, één lepel en een klein bergje havermout. Benoem wat je kind doet: scheppen, strooien, weg!","old":"Een tweejarige kan bekers vullen tot ze vol zijn, de gevonden diertjes tellen of havermout door een zeef laten sneeuwen over een diertje."},"safety":["Proeven mag, maar een volle mond droge vlokken kan tot verslikken leiden: laat je kind rechtop zitten, blijf ernaast en geef zo nodig een slokje water.","Gebruik alleen grote diertjes en blokken: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3.","Gewone havermout bevat vaak sporen van gluten: kies bij coeliakie of een glutenallergie glutenvrije havermout."],"say":["Strooi, strooi… weg!","Hoe voelt dat aan je handjes? Zacht, hè?","Ik zie een staart! Wie zit daar verstopt?","Wat ben je lang aan het scheppen. Je beker is bijna vol!"],"words":["zacht","scheppen","strooien","vol","leeg","weg","gevonden"],"learn":["zintuigen","fijne-motoriek","ontdekken","taal"],"tips":["Speel vlak voor badtijd: havermout plakt een beetje aan handjes en haar, en zo is het daarna meteen weg.","Schone, droge havermout kun je in een afgesloten bak een paar keer opnieuw gebruiken.","Een kruimeldief of stofzuiger is na afloop je beste vriend."],"variations":["Boerderij: koe, paard en schaap in de ‘haver’, met een beker als voerbak.","Knisperbak: meng er een handje ontbijtringetjes of cornflakes door voor een ander geluid en gevoel.","Winter: zeef havermout als sneeuw over een ijsbeer of pinguïn en blaas het er weer af."],"themes":[]},
  {"id":"zeepschuim","title":"Regenboog-zeepschuim","emoji":"🌈","category":"zintuigen","summary":"Klop samen bergen luchtig schuim in pastelkleuren en ga erin graven, smeren en diertjes redden: zacht, koel en verrassend.","ageMin":2,"ageMax":5,"mess":3,"wet":true,"dirty":false,"prepMinutes":10,"durationMinutes":20,"supervision":2,"materials":[{"id":"badschuim","note":"of afwasmiddel: 2-3 el per portie"},{"id":"water","note":"100 ml per portie"},{"id":"garde","note":"een (hand)mixer gaat het snelst"},{"id":"kom","note":"een kom per kleur"},{"id":"opbergbak","note":"of het lege bad"}],"optional":[{"id":"kleurstof","note":"2-3 druppels per kleur, voor pastelkleuren"},{"id":"klein-speelgoed","note":"plastic diertjes om te verstoppen"},{"id":"plastic-bekers","note":"om mee te scheppen"},{"id":"slagroom","note":"in plaats van zeepschuim als je kind nog veel in de mond stopt"}],"steps":["Doe per kleur 100 ml water en 2-3 el badschuim of afwasmiddel in een kom, en eventueel 2-3 druppels kleurstof.","Mix 1-2 minuten tot stevig schuim dat blijft staan als je de garde optilt. Mixen doe jij; je kind kijkt hoe het schuim groeit.","Schep de kleuren naast elkaar in de bak: een regenboog van schuim!","Verstop er een paar diertjes in en laat je kind ze opzoeken en ‘redden’.","Laat je kind vrij spelen: scheppen, smeren, kleuren door elkaar roeren en schuim tussen de vingers knijpen.","Spoel alles na afloop weg in de gootsteen of het bad, en spoel handen en diertjes na met schoon water."],"ageTips":{"young":"Voor een tweejarige: begin met één kleur en zet de bak in het lege bad. Stopt je peuter nog veel in de mond, gebruik dan slagroom met een drupje kleurstof.","old":"Een kleuter kan zelf het water afmeten, kleuren kiezen en voorspellen wat er gebeurt als je geel en blauw schuim mengt. Of je kind ‘wast’ alle diertjes en zet ze op een rij te drogen."},"safety":["Zeepschuim prikt in de ogen en is niet om te eten: houd een nat washandje klaar en spoel ogen met lauw water als er schuim in komt.","Schuim op de vloer maakt hem spekglad: zet de bak op een handdoek, dweil gemorst schuim en water direct op en laat je kind niet alleen bij de bak."],"say":["Kijk, het schuim groeit en groeit!","Hoe voelt het schuim tussen je vingers?","Wat denk je dat er gebeurt als je roze en blauw door elkaar roert?","Je hebt alle diertjes gevonden, wat heb je goed gezocht!","Plop! Weg!"],"words":["schuim","luchtig","zacht","bubbel","regenboog","mengen","verstoppen"],"learn":["zintuigen","ontdekken","taal","fijne-motoriek"],"tips":["Speel in de lege badkuip, vlak voor badtijd: daarna gaan schuim en kind samen onder de douche.","Met maar 2-3 druppels kleurstof per kom krijg je pastelkleuren die makkelijk wegspoelen; meer kleurstof kan handen en voegen even kleuren.","Schuim zakt na 20-30 minuten in: mix een nieuwe portie of klop het even op."],"variations":["Schuimzee: blauw schuim met plastic visjes, schelpen en een bootje.","Winter: wit sneeuwschuim met een ijsbeer en pinguïns.","Afwasfeest: was plastic bordjes en bekers van de poppenkeuken in het schuim."],"themes":[]},
  {"id":"gelei-redding","title":"Diertjes redden uit de gelei","emoji":"🦖","category":"zintuigen","summary":"De diertjes zitten vast in wiebelige gelei: graaf, knijp en schep ze los. Koud, glibberig en heerlijk vies.","ageMin":1,"ageMax":4,"mess":3,"wet":true,"dirty":true,"prepMinutes":15,"durationMinutes":20,"supervision":1,"materials":[{"id":"gelatine","note":"geleipudding of gelatine voor ±1 liter (meestal 2 pakjes)"},{"id":"water","note":"volgens de verpakking, deels heet"},{"id":"kookplaat","note":"voor het hete water (dat doe jij)"},{"id":"kom","note":"een ondiepe schaal of bak"},{"id":"klein-speelgoed","note":"5-8 plastic diertjes, groter dan een wc-rolletje"},{"id":"koelkast"},{"id":"lepel"}],"optional":[{"id":"kleurstof","note":"bij gewone gelatine, een paar druppels"},{"id":"dienblad","note":"onder de schaal, vangt klodders op"},{"id":"oud-laken","note":"als knoeimat"},{"id":"oud-shirt"}],"steps":["Maak de gelei volgens de verpakking. Het hete water doe jij; je kind kijkt op afstand.","Laat de gelei een kwartier afkoelen. Laat je kind intussen de diertjes in de schaal zetten.","Giet de lauwe gelei over de diertjes en zet de schaal minstens 4 uur (of een nacht) in de koelkast.","Zet de schaal op een dienblad, met een kom lauw water ernaast om geredde diertjes in te wassen.","Laat je kind de diertjes bevrijden: met de vingers graven, knijpen of met een lepel scheppen.","Gooi de gelei na afloop in de vuilnisbak en was diertjes en handjes in een warm sopje."],"ageTips":{"young":"Voor een dreumes: gebruik 3-4 grote diertjes en zet de schaal op het blad van de kinderstoel. Proeven mag. Benoem wat je kind voelt: koud, wiebel, glibberig!","old":"Een vierjarige kan tellen hoeveel diertjes er nog vastzitten, ze daarna sorteren (zee, boerderij, wild) of een reddingsverhaal bedenken: wie was het eerst vrij?"},"safety":["Het hete water en de warme gelei doe jij; laat de gelei helemaal opstijven en afkoelen voordat je kind erin mag.","Gebruik alleen grote diertjes: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3.","Gevallen gelei is glibberig: ruim klodders direct op en laat je kind niet alleen met de schaal en de kom water.","Rode en paarse gelei vlekt op kleding, tafel en voegen: kies liever geel of groen en trek een oud shirt aan."],"say":["Wiebel, wiebel! Voel je hoe koud het is?","Ik zie een staartje uitsteken. Van wie zou dat zijn?","Hoe ga je de leeuw bevrijden: met je vingers of met de lepel?","Je bleef doorgraven tot hij los was. Wat een doorzetter!","Gered! Nog een!"],"words":["glibberig","wiebelen","koud","plakkerig","vast","los","redden"],"learn":["zintuigen","fijne-motoriek","ontdekken","taal"],"tips":["Drijven de diertjes naar boven? Giet eerst een laagje gelei, laat dat een uur opstijven, zet de diertjes erop en giet de rest erover.","Speel vlak voor badtijd of zet de schaal in de lege badkuip: dan spoel je alles zo weg.","Vegetarisch? Agar-agar werkt ook: kook het volgens de verpakking (dat doe jij)."],"variations":["Zee-redding: blauwe gelei met plastic visjes, een krab en een duiker.","Dino-opgraving: dinosaurussen in groene gelei, opgraven met lepels en een kwast.","Halloween: groene ‘slijmgelei’ met plastic spinnen, voor stoere kleuters."],"themes":[]},
  {"id":"voelzak","title":"Raad wat er in de voelzak zit","emoji":"👜","category":"zintuigen","summary":"Steek je hand in de zak, voel zonder te kijken en raad wat het is: een spannend raadspel met gewone spullen uit huis.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":3,"durationMinutes":10,"supervision":1,"materials":[{"id":"stoffen-tas","note":"of een kussensloop, niet doorzichtig"},{"id":"lepel"},{"id":"sokken","note":"een opgerolde sok"},{"id":"bal"},{"id":"duplo","note":"een groot blok"},{"id":"knuffels","note":"een kleine knuffel"}],"optional":[{"id":"sponsjes","note":"zacht én ruw"},{"id":"dennenappels","note":"voor een herfstzak"},{"id":"fruit","note":"bijv. een banaan of mandarijn"}],"steps":["Zoek 5-8 bekende voorwerpen bij elkaar, bijvoorbeeld een lepel, een sok, een bal, een blok en een knuffel.","Stop ze in de tas of kussensloop zonder dat je kind kijkt.","Laat je kind één hand in de zak steken en één ding vastpakken, zonder te kijken.","Vraag wat hij voelt: is het zacht of hard, rond of plat, koud of warm? Laat hem raden wat het is.","Haal het eruit: goed geraden? Ruil daarna van rol: nu stopt je kind iets in de zak voor jou.","Ruim op als spel: wat je geraden hebt, breng je terug naar zijn plek."],"ageTips":{"young":"Voor een tweejarige: laat de spullen eerst zien en benoem ze, en stop er dan maar 3 in. Vraag: Waar is de bal? Gluren mag, het gaat om het voelen en benoemen.","old":"Laat een kleuter eerst beschrijven en dan pas raden (‘Het is rond en hard…’) of zoek op opdracht: pak iets wat zacht is. Moeilijker: spullen die op elkaar lijken, zoals een lepel en een vork."},"safety":["Doet er een kind onder de 3 mee? Stop dan alleen spullen in de zak die niet door een wc-rolletje passen, en niets scherps of met knoopcelbatterijen.","Gebruik nooit een plastic tas als voelzak en laat je kind de kussensloop niet over het hoofd trekken (verstikking)."],"say":["Wat voel je? Is het zacht of hard?","Ik voel iets ronds… wat zou dat zijn?","Je voelde heel goed voordat je raadde. Knap!","Bal! Goed zo!","Wat denk je dat het is, als het koud en glad is?"],"words":["zacht","hard","glad","ruw","rond","koud","voelen"],"learn":["zintuigen","taal","concentratie","samen"],"tips":["Een grote sok werkt ook: daar past precies één hand in.","Neem de voelzak mee naar de wachtkamer of op visite: een spelletje dat je overal kunt doen.","Wissel de inhoud af met het seizoen, dan blijft het spannend."],"variations":["Sinterklaas: wat zit er in de zak van Sinterklaas? Stop er een mandarijn, een schoen en een klein cadeautje in en zing er een liedje bij.","Herfst: een dennenappel, een blad, een takje en (vanaf 3 jaar) een kastanje.","Zoek het paar: leg één voorwerp op tafel en laat je kind het tweelingbroertje in de zak zoeken."],"themes":["sinterklaas"]},
  {"id":"kalmeerfles","title":"Kalmeerfles: zeefles of glitterfles","emoji":"🌊","category":"zintuigen","summary":"Maak samen een fles vol golven of dwarrelende glitters: schudden, kijken en tot rust komen tot alles weer stil is.","ageMin":1,"ageMax":5,"mess":2,"wet":true,"dirty":false,"prepMinutes":10,"durationMinutes":10,"supervision":2,"materials":[{"id":"plastic-flesjes","note":"stevig en doorzichtig, ±500 ml, etiket eraf"},{"id":"water"},{"id":"kleurstof","note":"blauw voor de zeefles, een paar druppels"},{"id":"olie","note":"voor de zeefles: ±1/3 van de fles"},{"id":"trechter"},{"id":"knutsellijm","note":"of lijm uit een lijmpistool, voor de dop (dat doe jij)"},{"id":"ducttape","note":"om de dop extra dicht te plakken"}],"optional":[{"id":"glitter","note":"voor een glitterfles, liefst bio-glitter; 50-100 ml glycerine (drogist) laat hem langzamer dwarrelen"},{"id":"dienblad","note":"om op te vullen, vangt gemorst water op"}],"steps":["Zet de fles met een trechter erin op een dienblad of in de gootsteen.","Vul voor een zeefles de fles voor twee derde met water en laat je kind er 2-3 druppels blauwe kleurstof bij doen.","Giet de fles verder vol met olie tot ±3 cm onder de rand. Kijk samen: de olie blijft bovenop drijven!","Vul voor een glitterfles de fles in plaats daarvan met lauw water, 1-2 el glitter en eventueel wat glycerine, zodat het langzamer dwarrelt.","Doe lijm op de schroefdraad, draai de dop er stevig op en plak er ducttape omheen. Dat doe jij; laat de lijm een paar uur drogen.","Schud, kantel en rol de fles en kijk samen hoe de golven of glitters bewegen en langzaam weer tot rust komen."],"ageTips":{"young":"Een dreumes speelt alleen met de dichte, afgeplakte fles. Rol hem over de vloer zodat je dreumes erachteraan kruipt, of schud samen: golven! En nu… stil.","old":"Een kleuter kan zelf afmeten en gieten met de trechter. Gebruik de fles als zandloper: kun je stil blijven zitten tot alle glitters beneden liggen?"},"safety":["Lijm de dop vast én plak hem af: een gewone dop krijgt een peuter zo open. Kijk de fles regelmatig na op lekken en scheurtjes en gebruik nooit glas.","Glitter hoort niet in ogen of mond: vul de fles zelf en laat je kind alleen met de dichte fles spelen.","Gemorst water en olie maken de vloer spekglad: vul de fles boven een dienblad of de gootsteen en veeg direct op."],"say":["Kijk, de olie blijft bovenop drijven!","Wat gebeurt er als je de fles heel langzaam kantelt?","Schud, schud… golven!","Zullen we samen diep ademhalen tot alle glitters beneden liggen?","Je goot heel voorzichtig, er ging bijna niets naast."],"words":["golf","drijven","zakken","dwarrelen","schudden","langzaam","stil"],"learn":["zintuigen","concentratie","ontdekken"],"tips":["Gebruik de fles als rustmoment: bij boosheid of voor het slapengaan samen kijken tot alles stil is.","Kies een fles van stevig plastic (bijvoorbeeld van sap of bronwater); dun plastic deukt en scheurt sneller.","Geen glitter in huis? Snippers aluminiumfolie of confetti dwarrelen ook mooi."],"variations":["Zomer: een zeefles met een paar kleine schelpen of een plastic visje erin (stevig dichtplakken!).","Winter: een sneeuwfles met witte glitter en een klein plastic dennenboompje.","Druppelfles: vul water en olie zonder kleurstof, doe er pas daarna één druppel kleurstof in en kijk hoe die door de olie zakt."],"themes":["zomer","winter"]},
  {"id":"voelpad","title":"Voelpad op blote voeten","emoji":"👣","category":"zintuigen","summary":"Loop op blote voeten over knisperende folie, ploppende noppen en zachte kussens: een ontdekpad voor je voeten.","ageMin":1,"ageMax":4,"mess":1,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":15,"supervision":1,"materials":[{"id":"noppenfolie","note":"een stuk van ±50 cm"},{"id":"aluminiumfolie","note":"een paar lagen dik"},{"id":"handdoek","note":"of een badmat of deurmat"},{"id":"dekens","note":"een kussen of opgevouwen deken"},{"id":"schilderstape","note":"om alles vast te plakken"}],"optional":[{"id":"karton","note":"ribbelkarton van een doos"},{"id":"kranten","note":"een paar lagen, ritselt lekker"},{"id":"sponsjes","note":"naast elkaar vastgeplakt"}],"steps":["Leg 5-6 voeltegels achter elkaar op de vloer: noppenfolie, aluminiumfolie, een handdoek, een kussen en een stuk karton.","Plak de randen vast met schilderstape, zodat niets kan schuiven.","Trek samen schoenen en sokken uit en loop het pad heel langzaam af, hand in hand.","Sta bij elke tegel even stil: hoe voelt dat? Knispert het, plopt het, is het zacht of koud?","Loop het pad nog een keer: op je tenen, achteruit of zo zwaar als een olifant.","Haal het pad weg en bewaar de noppenfolie en de folie voor een volgende keer."],"ageTips":{"young":"Een dreumes kruipt of loopt het pad aan jouw hand. Begin met drie tegels en benoem één woord per tegel: zacht, knisper, plop!","old":"Een vierjarige loopt met de ogen dicht (jij houdt een hand vast) en raadt waar de voetjes op staan. Of je kind ontwerpt zelf een nieuw pad en bepaalt de volgorde."},"safety":["Losse folie en kussens schuiven weg: plak alle randen vast, leg het pad liefst op een kleed en houd een dreumes een hand vast.","Haal kapotte stukjes folie en noppenfolie meteen weg: losse snippers horen niet in de mond (verstikking)."],"say":["Plop, plop! Hoor je dat?","Hoe voelt de folie onder je voeten: koud of warm?","Welke tegel vind jij het fijnst? En welke het gekst?","Je liep helemaal tot het eind, ook over het wiebelige kussen. Goed gedaan!","Wat denk je dat dit is, met je ogen dicht?"],"words":["zacht","ruw","glad","knisperen","wiebelig","koud","blote voeten","plop"],"learn":["zintuigen","grove-motoriek","taal"],"tips":["Speel het vlak na het badderen of aankleden, als de voetjes toch al bloot zijn.","Noppenfolie en karton uit pakketjes zijn gratis: bewaar ze in een tas voor dit spel.","Leg het pad in de gang: dan wordt het vanzelf een lange route."],"variations":["Handenpad: maak voor kruipers kleine voeltegels op de vloer om met de handen te voelen.","Herfst: leg droge bladeren in een dichtgeplakt diepvrieszakje: knisperen zonder rommel.","Voelmemory: plak van elke tegel een stukje op karton en zoek met je voeten de tegel die erbij hoort."],"themes":[]},
  {"id":"zoutbak-tekenen","title":"Tekenen in een zoutbak","emoji":"🧂","category":"zintuigen","summary":"Trek met je vinger een lijn door het zout en zie de kleur tevoorschijn komen. Even schudden en je kunt opnieuw beginnen.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":15,"supervision":2,"materials":[{"id":"dienblad","note":"met een randje"},{"id":"zout","note":"±250 g fijn zout, voor een laagje van ½ cm"},{"id":"gekleurd-papier","note":"een vel in een felle kleur, voor op de bodem"}],"optional":[{"id":"penselen","note":"een dikke kwast om mee te tekenen"},{"id":"ijsstokjes","note":"om lijnen te trekken"},{"id":"karton","note":"voorbeeldkaartjes met vormen of letters"},{"id":"trechter","note":"om het zout terug in de pot te gieten"},{"id":"suiker","note":"in plaats van zout voor een peuter die alles proeft"}],"steps":["Leg een vel gekleurd papier op de bodem van het dienblad.","Strooi er een laagje zout van ±½ cm over en schud het blad zachtjes tot het zout overal even dik ligt.","Trek met je vinger een lijn: kijk, de kleur komt tevoorschijn! Laat je kind het nadoen.","Teken samen lijnen, rondjes, zigzaggen en golven, met een vinger, een kwast of een ijsstokje.","Schud het blad zachtjes heen en weer om alles uit te gummen, en begin opnieuw.","Giet het zout na afloop via een trechter terug in een pot met deksel, zodat je het vaker kunt gebruiken."],"ageTips":{"young":"Voor een tweejarige: laat je kind vooral krassen, voelen en uitgummen. Stopt je peuter alles in de mond, gebruik dan suiker in plaats van zout.","old":"Een kleuter kan vormen natekenen van een voorbeeldkaartje, de eerste letter van de eigen naam schrijven of een doolhof tekenen voor een autootje. Of jij tekent een vorm en je kind raadt."},"safety":["Zout is niet om te eten: een paar theelepels kan voor een peuter al gevaarlijk zijn. Blijf erbij en stop als je kind ervan gaat snoepen.","Zout prikt in de ogen en in wondjes: niet in de ogen wrijven en handen wassen na afloop.","Zout is ook gevaarlijk voor honden en katten: zet de pot na het spelen buiten hun bereik."],"say":["Kijk, waar je vinger gaat, komt de kleur!","Kun jij een rondje tekenen? En nu een grote golf?","Schud, schud… weg!","Je tekent heel langzaam en precies. Ik zie een lange slingerlijn.","Hoe voelt het zout aan je vinger: korrelig of glad?"],"words":["lijn","rondje","zigzag","golf","korrelig","uitgummen","opnieuw"],"learn":["fijne-motoriek","zintuigen","creativiteit","concentratie"],"tips":["Een bakplaat met randje of het deksel van een schoenendoos werkt ook.","Zet het dienblad op een handdoek: wat ernaast valt, schud je zo terug.","Plak stroken in verschillende kleuren naast elkaar onder het zout: elke lijn wordt dan een verrassing."],"variations":["Winter: wit zout op donkerblauw papier is tekenen in de sneeuw. Teken een sneeuwpop of sporen van een vogel.","Letters oefenen: leg kaartjes met letters of cijfers naast het blad om na te tekenen.","Zandtekenen: met een laagje droog speelzand voelt en klinkt het heel anders."],"themes":[]},
  {"id":"maizenapap","title":"Maizenapap: vloeibaar of vast?","emoji":"🌽","category":"zintuigen","summary":"Knijp erin en het wordt hard, doe je hand open en het druipt weg: maizenapap is magisch spul om mee te kliederen.","ageMin":1,"ageMax":5,"mess":3,"wet":true,"dirty":false,"prepMinutes":5,"durationMinutes":20,"supervision":2,"materials":[{"id":"maizena","note":"200 g per portie"},{"id":"water","note":"100-125 ml per portie, beetje bij beetje"},{"id":"opbergbak","note":"een ondiepe bak, of een dienblad met rand"},{"id":"lepel","note":"om te roeren en te scheppen"}],"optional":[{"id":"oud-laken","note":"als knoeimat"},{"id":"oud-shirt"},{"id":"klein-speelgoed","note":"diertjes die langzaam wegzakken"}],"steps":["Doe 200 g maizena in de bak en laat je kind eerst het droge poeder voelen: zacht en piepend.","Giet er beetje bij beetje 100-125 ml water bij en roer met een lepel of je handen tot het overal even dik is.","Voeg een lepel maizena toe als het te dun is, of een scheutje water als het kruimelt.","Laat je kind een handje pakken en knijpen: het wordt hard! Doe je hand open en het druipt weg.","Probeer samen: tik er snel op met je vingers, duw je hand er langzaam in, rol een balletje en kijk hoe het smelt.","Laat de restjes opdrogen en gooi ze in de vuilnisbak, nooit door de gootsteen of de wc: het verstopt de afvoer."],"ageTips":{"young":"Een dreumes speelt op het blad van de kinderstoel met een paar lepels pap. Knijpen, druppen en kletsen is genoeg. Proeven kan geen kwaad: maizena is eetbaar.","old":"Een kleuter kan zelf afmeten en het water toevoegen. Laat je kind voorspellen: is het vast of vloeibaar? Lukt het om een balletje te rollen en het vast te houden voordat het wegsmelt?"},"safety":["Proeven kan geen kwaad, maar laat je dreumes er niet van eten en laat een jong kind nooit alleen met een bak pap of water.","Gemorste pap maakt de vloer spekglad: dweil het direct op, of laat het opdrogen en stofzuig het weg."],"say":["Knijp maar… hé, hij is hard!","Kijk, het druipt tussen je vingers door!","Wat denk je dat er gebeurt als je er snel op tikt? En als je langzaam duwt?","Je blijft het maar uitproberen, net een echte onderzoeker!","Plets!"],"words":["vloeibaar","vast","druipen","knijpen","hard","zacht","langzaam","snel"],"learn":["zintuigen","ontdekken","fijne-motoriek","taal"],"tips":["Speel op het blad van de kinderstoel of in de lege badkuip, vlak voor badtijd.","Opgedroogde maizena vlekt niet: borstel het zo van kleding en tafel.","Bewaar de pap afgedekt hooguit een dag. Opgedroogd? Roer er een scheutje water door."],"variations":["Dinomoeras: zet dinosaurusjes op de pap en kijk hoe ze langzaam wegzakken.","Glijbaan: houd het dienblad schuin en kijk hoe langzaam de pap naar beneden loopt. Wie is het eerst beneden?","Kleurenpap: roer door twee kleine porties elk een druppel kleurstof en meng ze (dat kan wel vlekken)."],"themes":[]},
  {"id":"geurpotjes","title":"Geurpotjes: raad de geur","emoji":"👃","category":"zintuigen","summary":"Snuffel aan potjes met kaneel, citroen en koffie en raad wat erin zit: een spel voor je neus, met gewone keukenspullen.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":10,"supervision":1,"materials":[{"id":"potjes","note":"4-6 kleine potjes, liefst niet doorzichtig"},{"id":"watten","note":"één watje per potje"},{"id":"kruiden","note":"kaneel, speculaaskruiden; ook koffie of thee"},{"id":"fruit","note":"een citroen of sinaasappel, voor de schil"},{"id":"aluminiumfolie","note":"om de potjes af te dekken"},{"id":"vork","note":"om gaatjes te prikken (dat doe jij)"}],"optional":[{"id":"papier","note":"om doorzichtige potjes in te pakken"},{"id":"plakband"}],"steps":["Kies 4-6 geuren, bijvoorbeeld kaneel, speculaaskruiden, citroenschil, sinaasappelschil en koffie.","Leg in elk potje een watje en strooi er ½ tl kruiden op, of leg er een stukje schil bij.","Dek elk potje af met aluminiumfolie en prik er met een vork 3-4 gaatjes in. Dat doe jij.","Ruik samen aan één potje tegelijk: is het lekker of vies, zoet of fris? Wat zou het zijn?","Haal de folie eraf: had je het goed? Ruik nog eens, nu je weet wat het is.","Bewaar de potjes dicht. Kruiden blijven een paar weken ruiken, schillen een paar dagen."],"ageTips":{"young":"Een tweejarige raadt nog niet, maar ruikt graag. Gebruik 2-3 geuren die je kind kent en laat het echte ding ernaast zien. Benoem: mmm, sinaasappel!","old":"Maak van elke geur twee potjes en laat je kleuter de paren zoeken: memory voor je neus. Of vraag: waar ruikt dit naar, aan welk eten of welke plek denk je?"},"safety":["Gebruik geen etherische oliën: die zijn schadelijk voor jonge kinderen, ook op de huid. Houd het bij gewone keukenkruiden.","Ruiken, niet snuiven of blazen: poeder zoals kaneel prikt in neus en ogen. Gebruik geen peper of chilipoeder.","Zet de potjes na het spelen weg: watjes en kruiden horen niet in de mond van een peuter."],"say":["Ruik maar… mmm! Wat ruik je?","Ruikt dit zoet of fris?","Waar heb je dit eerder geroken? Bij het ontbijt of in de keuken?","Je rook heel goed en dacht lang na. Knap gedaan!","Mmm, kaneel!"],"words":["ruiken","neus","zoet","zuur","fris","sterk","lekker","vies"],"learn":["zintuigen","taal","concentratie"],"tips":["Gebruik niet-doorzichtige potjes of plak ze in met papier, anders raadt je kind met de ogen.","Na 4-5 geuren ruikt je neus minder goed: ruik tussendoor even aan je eigen mouw, dan doet je neus het weer.","Een eierdoos met folie erover werkt ook: één geur per vakje."],"variations":["Sinterklaas: speculaaskruiden, sinaasappel, cacao en anijs. Welke geur hoort bij Sinterklaas?","Kerst: kaneel, gemalen kruidnagel, mandarijnschil en een dennentakje.","Ontbijtgeuren: koffie, thee, banaan en jam. Wie raadt wat papa of mama ’s ochtends drinkt?"],"themes":["sinterklaas","kerst"]},
  {"id":"herfst-ontdekbak","title":"Herfst-ontdekbak","emoji":"🌰","category":"zintuigen","summary":"Haal het bos naar binnen: graaf, sorteer en ritsel in een bak vol kastanjes, dennenappels, bladeren en takjes.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":20,"supervision":2,"materials":[{"id":"opbergbak","note":"een grote platte bak of doos"},{"id":"kastanjes","note":"een paar handen vol, alleen vanaf 3 jaar"},{"id":"dennenappels","note":"verschillende maten"},{"id":"bladeren","note":"droog, in verschillende kleuren"},{"id":"takjes"},{"id":"plastic-bekers"},{"id":"lepel"}],"optional":[{"id":"muffinvorm","note":"om te sorteren"},{"id":"klein-speelgoed","note":"een plastic egel, eekhoorn of uil"},{"id":"oud-laken","note":"onder de bak tegen kruimels"},{"id":"kranten","note":"om de verzamelde spullen op te drogen"}],"steps":["Spreid de verzamelde spullen een dag van tevoren uit op een krant om te drogen en kijk ze na op beestjes, schimmel en scherpe stekels.","Doe alles in een grote platte bak en zet bekers, lepels en eventueel een muffinvorm ernaast.","Laat je kind eerst graven, voelen en ruiken: hoe voelt een dennenappel, en hoe een gladde kastanje?","Schep en giet samen: kastanjes in een beker, door de bak laten rollen, ritselende bladeren omhoog gooien.","Sorteer samen in de muffinvorm: alle kastanjes bij elkaar, alle dennenappels bij elkaar. Tel ze.","Ruim op door alles terug in de bak te doen. Met een deksel erop kun je de bak een paar weken bewaren."],"ageTips":{"young":"Voor een tweejarige: laat kastanjes en eikels weg en kies grote dennenappels, grote bladeren en dikke takjes. Ritsel en benoem samen: blad, ritsel ritsel!","old":"Een kleuter kan sorteren op grootte of kleur, een rij maken van klein naar groot, of van de spullen een gezicht of egel leggen. Hoeveel kastanjes passen er in één beker?"},"safety":["Kastanjes en eikels passen door een wc-rolletje en zijn dus te klein voor kinderen onder de 3: laat ze weg bij een tweejarige.","Kastanjes en eikels zijn niet eetbaar (giftig bij opeten): spreek af dat alles uit de bak buiten de mond blijft.","Gooi bolsters met stekels, beschimmelde spullen en scherpe takjes weg, en was na het spelen handen."],"say":["Ritsel, ritsel! Hoor je de blaadjes?","Deze kastanje is glad en glimmend. Hoe voelt de dennenappel?","Waar denk je dat deze takjes vandaan komen?","Je hebt alles zo goed gesorteerd, wat heb je goed gezocht!","Ruik eens aan het blad. Waar ruikt het naar?"],"words":["ritselen","glad","ruw","prikkelig","bruin","kastanje","dennenappel","herfst"],"learn":["zintuigen","ontdekken","rekenen","taal"],"tips":["Verzamel de spullen samen op een herfstwandeling, dan begint het ontdekken al buiten.","Leg de dennenappels een nacht in de vriezer: zo ben je eventuele beestjes kwijt.","Leg de bak op een oud laken: verkruimelde blaadjes vouw je er zo in en schud je buiten uit."],"variations":["Eekhoorntje spelen: verstop kastanjes onder de bladeren en laat de ‘eekhoorn’ zijn wintervoorraad zoeken.","Kleurenbak: alleen gele, rode en bruine blaadjes. Van welke kleur heb je er het meest?","Kerst: vervang de bladeren door dennentakjes en leg er onbreekbare kerstballen bij."],"themes":["herfst"]},
  {"id":"kleurenjacht","title":"Kleurenjacht door het huis","emoji":"🔴","category":"zintuigen","summary":"Kies een kleur en ga samen op jacht: alles wat rood is, mag mee naar het rode vel papier.","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":2,"durationMinutes":15,"supervision":2,"materials":[{"id":"gekleurd-papier","note":"een vel per kleur, bijv. rood, geel en blauw"}],"optional":[{"id":"wasmand","note":"om de buit in te verzamelen"}],"steps":["Leg een paar vellen gekleurd papier op de vloer, bijvoorbeeld rood, geel en blauw.","Kies samen één kleur en wijs iets in de kamer aan dat die kleur heeft.","Ga op jacht: je kind zoekt spullen in die kleur en legt ze op het juiste vel.","Bekijk samen de buit: wat is het, is het groot of klein, zacht of hard?","Ruim op door alles terug te brengen: waar woont de rode beker?"],"ageTips":{"young":"Begin met één kleur en leg zelf alvast drie rode dingen klaar om te vinden. Benoem alleen kleur en voorwerp: rood, een rode bal!","old":"Zoek binnen één minuut vijf dingen, of sorteer van licht- naar donkerblauw. Ook leuk: zoek iets dat rond én geel is."},"safety":["Let op kleine voorwerpen die je kind onderweg vindt, zoals munten, kraaltjes of knoopcelbatterijen: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3."],"say":["Ik zie iets roods… zie jij het ook?","Is deze sok rood of oranje? Wat denk jij?","Je hebt al vier rode dingen gevonden. Zullen we ze tellen?","Rood! Nog een!"],"words":["rood","geel","blauw","licht","donker","hetzelfde","anders"],"learn":["taal","rekenen","grove-motoriek"],"tips":["Speel het als opruimspel: laat je kind alle blauwe spullen terugbrengen naar hun plek.","Maak een foto van elke kleurenstapel: zo heb je meteen een eigen kleurenboekje."],"variations":["Vormenjacht: zoek alles wat rond is, of alles wat vierkant is.","Herfst: zoek bruin, oranje en geel en leg er kastanjes en bladeren bij.","Koningsdag: zoek alles wat oranje is en maak er een oranje tentoonstelling van."],"themes":[]},
  {"id":"water-overgieten","title":"Overgieten op een dienblad","emoji":"💧","category":"water","summary":"Bekers, een trechter en een sponsje op een dienblad: gieten, vullen en knijpen tot je kind een echte watermeester is.","ageMin":1,"ageMax":5,"mess":2,"wet":true,"dirty":false,"prepMinutes":3,"durationMinutes":15,"supervision":2,"materials":[{"id":"dienblad","note":"met een randje"},{"id":"water","note":"een laagje lauw water"},{"id":"plastic-bekers","note":"2-3 in verschillende maten, ook een met tuit"},{"id":"trechter"},{"id":"sponsjes","note":"een sponsje om op te deppen"},{"id":"handdoek","note":"onder het dienblad"}],"optional":[{"id":"kleurstof","note":"één druppel, dan zie je beter hoe vol een beker is"},{"id":"pipet"},{"id":"kom"}],"steps":["Leg een handdoek op tafel of op de vloer en zet het dienblad erop.","Zet 2-3 bekers, een trechter en een sponsje op het blad en vul één beker halfvol met lauw water.","Doe voor hoe je langzaam van de ene in de andere beker giet en laat je kind het proberen.","Ontdek samen: water door de trechter gieten, de spons vol laten zuigen en uitknijpen boven een lege beker.","Laat je kind gemorst water opdeppen met het sponsje en uitknijpen boven een beker: morsen hoort erbij.","Giet het water na afloop in de gootsteen en hang de handdoek te drogen."],"ageTips":{"young":"Een dreumes begint met één beker en een kom: scheppen en omkieperen is genoeg. Gebruik weinig water, zo blijft het overzichtelijk.","old":"Een kleuter kan tot een streepje vullen (zet een stip met stift), tellen hoeveel kleine bekers er in een grote passen of met een pipet een beker druppel voor druppel vullen."},"safety":["Laat een jong kind nooit alleen bij water, ook niet bij een laagje op een dienblad.","Dweil gemorst water direct op: een natte vloer is glad, zeker voor wiebelige beentjes."],"say":["Plons! Nog een keer?","Kijk, het water loopt door het gaatje van de trechter.","Welke beker is voller: deze of die?","Je giet heel langzaam en voorzichtig. Er ging bijna niks naast!","Hoe voelt de natte spons in je hand?"],"words":["gieten","vol","leeg","half","druppel","nat","knijpen","langzaam"],"learn":["fijne-motoriek","ontdekken","rekenen","concentratie"],"tips":["Geef weinig water tegelijk: liever vaak bijvullen dan een grote plas.","Trek je dreumes een oud shirt aan of speel in alleen een luier, vlak voor badtijd.","Een theedoek op het dienblad dempt het gespetter en zuigt gemorst water op."],"variations":["Kleuren mengen: een beker geel en een beker blauw water. Wat krijg je als je ze samen giet?","Theekransje: schenk thee (water) in kopjes voor de knuffels.","IJsblokjes: doe een paar ijsblokjes in de bekers en kijk hoe lang het duurt voordat ze gesmolten zijn."],"themes":[]},
  {"id":"speelgoed-wassen","title":"Speelgoed wassen in een sopje","emoji":"🧽","category":"water","summary":"Een bak sop, een sponsje en een oude tandenborstel: je kind schrobt de diertjes en de pop schoon, net als een grote.","ageMin":1,"ageMax":5,"mess":2,"wet":true,"dirty":false,"prepMinutes":5,"durationMinutes":20,"supervision":2,"materials":[{"id":"opbergbak","note":"een afwasteil met een laagje lauw water"},{"id":"water"},{"id":"afwasmiddel","note":"een klein scheutje, of badschuim"},{"id":"sponsjes"},{"id":"tandenborstel"},{"id":"klein-speelgoed","note":"plastic diertjes, duplo of autootjes"},{"id":"handdoek","note":"om op af te drogen"}],"optional":[{"id":"poppen","note":"een plastic pop die nat mag worden"},{"id":"oud-laken","note":"een tafelzeil of douchegordijn onder de bak"},{"id":"kom","note":"met schoon water om na te spoelen"}],"steps":["Leg een handdoek of tafelzeil op de vloer en zet daar een afwasteil op met een laagje lauw water.","Doe er een klein scheutje afwasmiddel bij en klop het samen met je handen tot een sopje.","Verzamel samen ‘vies’ speelgoed: plastic diertjes, duplo, autootjes of een pop.","Laat je kind alles wassen met het sponsje en de tandenborstel: achter de oren, tussen de tenen!","Spoel het speelgoed na in een kom schoon water en leg het op een handdoek om te drogen.","Droog alles samen af, giet het water weg en hang de handdoeken te drogen."],"ageTips":{"young":"Een dreumes zit op de vloer bij een laag bakje water met één diertje en een spons. Doe het voor: wrijf, wrijf, buikje wassen! Laat de zeep weg als je kind alles in de mond stopt.","old":"Maak er een autowasstraat of dierenkliniek van: een kleuter bedenkt de stappen (inzepen, schrobben, spoelen, drogen) en houdt bij hoeveel klanten er geweest zijn."},"safety":["Laat een jong kind nooit alleen bij een bak water: een dreumes kan al in een paar centimeter water verdrinken.","Gebruik maar een scheutje afwasmiddel en houd het uit de ogen en de mond; spoel handjes na met schoon water.","Dweil gemorst water direct op: de vloer wordt glad."],"say":["Wrijf, wrijf! Schoon!","Waar zit het vuil nog? Achter zijn oren?","Hoe voelt het sopje aan je handen: glad of glibberig?","Je wast heel zorgvuldig, zelfs tussen de pootjes.","Wat moeten we eerst doen: wassen of afdrogen?"],"words":["wassen","schoon","vies","sop","schrobben","afdrogen","nat","droog"],"learn":["fijne-motoriek","zintuigen","taal","samen"],"tips":["Doe het vlak voor badtijd, of gewoon in het bad zelf.","Handig: zo worden badspeeltjes en duplo ook echt schoon.","Laat speelgoed met batterijen of geluid erbuiten."],"variations":["Poppenwasdag: was de pop en haar kleertjes en hang ze met wasknijpers op aan een kort touw tussen twee stoelen.","Autowasstraat: rij speelgoedautootjes door het sop en daarna door een droogstraat van handdoeken.","Afwassen: was plastic bordjes en bekers van de poppenkeuken en zet ze op een rek te drogen."],"themes":[]},
  {"id":"bevroren-diertjes","title":"Bevroren diertjes bevrijden","emoji":"🧊","category":"water","summary":"De diertjes zitten vast in het ijs! Met lauw water, zout en een pipet smelt je kind ze los, en ontdekt het hoe ijs werkt.","ageMin":2,"ageMax":5,"mess":2,"wet":true,"dirty":false,"prepMinutes":5,"durationMinutes":20,"supervision":2,"materials":[{"id":"klein-speelgoed","note":"plastic diertjes, groter dan een wc-rolletje"},{"id":"bakjes","note":"yoghurtbekers of boterkuipjes om in te vriezen"},{"id":"water"},{"id":"vriezer"},{"id":"opbergbak","note":"een grote platte bak om in te spelen"},{"id":"plastic-bekers","note":"met lauw water"},{"id":"zout","note":"een schaaltje met een paar eetlepels"},{"id":"lepel"}],"optional":[{"id":"pipet","note":"voor gericht druppelen"},{"id":"plantenspuit","note":"met lauw water"},{"id":"handdoek","note":"onder de bak"}],"steps":["Zet de avond ervoor in elk bakje een diertje, vul het met water en zet de bakjes een nacht in de vriezer.","Laat het ijs 5 minuten liggen, haal de blokken uit de bakjes (even onder de warme kraan als het vastzit) en leg ze in de grote bak.","Zet bekertjes lauw water, een pipet, een lepel en een schaaltje zout ernaast.","Laat je kind het ijs bevrijden: lauw water erover gieten, druppelen met de pipet en zout strooien. Waar smelt het het snelst?","Juich bij elk bevrijd dier en leg het in een warm handdoeknestje om op te warmen.","Giet het smeltwater weg en droog de diertjes af."],"ageTips":{"young":"Voor een tweejarige: vries één groot dier in een groot bakje in en geef een beker lauw water en een lepel. Gieten en kijken is al spannend genoeg. Brr, koud!","old":"Een kleuter kan voorspellen wat het snelst werkt: warm water, koud water of zout? Laat je kind tellen hoeveel bekers er nodig zijn, of vries een groot blok met drie dieren op verschillende hoogtes."},"safety":["IJs dat net uit de vriezer komt, kan aan natte vingers en lippen vastvriezen: laat het eerst 5 minuten liggen en laat je kind er niet aan likken.","Zout prikt in wondjes en ogen en is niet om te eten: strooi met een lepel en was handen na afloop.","Gebruik alleen diertjes die niet door een wc-rolletje passen: kleinere zijn te klein voor kinderen onder de 3.","Laat je kind niet alleen bij het water en dweil smeltplassen direct op."],"say":["Brr, koud! Voel maar.","Kijk, het zout maakt gaatjes en geultjes in het ijs!","Wat denk je: smelt het sneller met warm of met koud water?","Je bleef maar doorgaan tot de pinguïn vrij was. Wat een doorzetter!","Vrij! Nog een!"],"words":["ijs","koud","smelten","bevriezen","druppelen","vrij","glad","nat"],"learn":["ontdekken","zintuigen","fijne-motoriek","concentratie"],"tips":["Diertjes drijven naar boven: vries eerst een laagje water, zet er na een uur het diertje op en vul daarna aan. Dan zit het mooi in het midden.","Kleine blokken (muffinvorm of ijsblokjesvorm) smelten sneller: fijn voor ongeduldige peuters.","Speel in de lege badkuip of zet de bak op een handdoek: smeltwater blijft dan waar het hoort."],"variations":["Winter: vries in een grote bak een ijsschots in met pinguïns en ijsberen en ga op poolexpeditie.","Zomer: smelt het ijs met een plantenspuit lauw water, lekker verfrissend.","Schatten bevrijden: vries duploblokken en lege schelpen in als ‘schatten’ voor een ijspiraat."],"themes":["winter"]},
  {"id":"waterbaan","title":"Waterbaan op de badkamermuur","emoji":"🚿","category":"water","summary":"Plak doorgesneden flessen en trechters op de tegels en giet er water doorheen: waar komt het uit? Bouwen en spetteren tegelijk.","ageMin":2,"ageMax":5,"mess":2,"wet":true,"dirty":false,"prepMinutes":15,"durationMinutes":20,"supervision":2,"materials":[{"id":"plastic-flesjes","note":"3-4 lege flessen, door jou doorgesneden"},{"id":"trechter"},{"id":"ducttape","note":"plakt het best op droge tegels"},{"id":"schaar","note":"om de flessen door te knippen (voor jou)"},{"id":"badkuip","note":"het lege bad of de douchebak"},{"id":"water"},{"id":"plastic-bekers","note":"of een kannetje om mee te gieten"}],"optional":[{"id":"badspeelgoed","note":"eendjes die mee mogen glijden"},{"id":"pingpongballen","note":"om mee te laten varen (vanaf 3 jaar)"}],"steps":["Snijd 3-4 flessen in de lengte doormidden (goten) of knip de bodem eraf (trechters). Dat doe jij; plak scherpe randen af met tape.","Droog de tegels boven het lege bad of de douchebak goed af.","Plak de goten en trechters schuin onder elkaar op de tegels met stukken ducttape, zodat het water van de ene in de andere loopt.","Zet je kind in het lege bad of de douchebak, met een beker water.","Giet het water bovenin en kijk waar het naartoe stroomt. Loopt het ernaast? Verschuif samen een goot.","Haal na afloop de tape eraf en bewaar de goten en trechters voor een volgende keer."],"ageTips":{"young":"Voor een tweejarige: plak de baan laag, op ooghoogte in het bad, en gebruik grote bekers. Gieten en kijken is al genoeg: daar gaat het! Plons!","old":"Een kleuter kan meebouwen en zelf bedenken waar de volgende goot moet. Laat een pingpongballetje meevaren of tel hoe lang het water over de baan doet."},"safety":["Laat je kind nooit alleen in of bij het bad, ook niet als er alleen een laagje water in staat.","Een nat bad is glad: leg een antislipmat neer, laat je peuter liefst zitten en dweil water naast het bad direct op.","Doorgesneden plastic heeft scherpe randen: knip zelf en plak de randen af met tape.","Pingpongballetjes passen door een wc-rolletje en zijn dus te klein voor kinderen onder de 3: laat een tweejarige liever grote badspeeltjes door de baan sturen."],"say":["Daar gaat het water! Plons!","Waar denk je dat het water heen gaat als je hier giet?","Het loopt ernaast… hoe kunnen we dat oplossen?","Wat goed bedacht om die trechter eronder te zetten!","Hoor je het klateren?"],"words":["stromen","gieten","bovenaan","onderaan","goot","trechter","schuin","plons"],"learn":["ontdekken","fijne-motoriek","samen"],"tips":["Doe het vlak voor badtijd: na de waterbaan meteen in bad.","Bewaar de goten en trechters in een tas bij het bad: de volgende keer hangt de baan er in een paar minuten.","Lijmresten van de tape haal je van de tegels met een beetje olie op een doekje."],"variations":["Zomer: speel in je zwembroek met lauw water, een binnen-zwembaddag.","Bootjesrace: laat badeendjes of plastic doppen (vanaf 3 jaar) door de goten glijden. Welke is het eerst beneden?","Regenbui: prik gaatjes in de bodem van een bekertje en hang het bovenaan de baan."],"themes":["zomer"]},
  {"id":"bellenblaas","title":"Zelf bellenblaas maken","emoji":"🧼","category":"water","summary":"Maak samen bellenblaas en buig blaasringen van pijpenragers: blazen, zwaaien en bellen vangen, gewoon binnen.","ageMin":2,"ageMax":5,"mess":2,"wet":true,"dirty":false,"prepMinutes":5,"durationMinutes":15,"supervision":2,"materials":[{"id":"afwasmiddel","note":"100 ml"},{"id":"water","note":"600 ml"},{"id":"suiker","note":"1 el, maakt de bellen sterker"},{"id":"kom","note":"een brede kom om de ringen in te dopen"},{"id":"lepel","note":"om zacht te roeren"},{"id":"pijpenragers","note":"2-3 per kind, om blaasringen van te buigen"}],"optional":[{"id":"glazen-pot","note":"om het restje in te bewaren"},{"id":"rietjes","note":"om blazen te oefenen"},{"id":"bakjes","note":"een eigen bakje sop per kind"}],"steps":["Roer in een kom 600 ml water, 100 ml afwasmiddel en 1 el suiker zachtjes door elkaar. Niet kloppen, anders krijg je schuim.","Laat het sop als het kan een paar uur staan, bijvoorbeeld ’s ochtends maken en ’s middags blazen. Dan worden de bellen sterker.","Buig samen pijpenragers tot ringen met een steeltje: een rondje, een hartje, een grote ring. Draai de uiteinden goed om.","Oefen eerst blazen zonder sop: blaas zachtjes tegen je hand of blaas een propje papier over tafel.","Ga in de badkamer of bij de keukentegels staan, doop de ring in het sop en blaas zachtjes. Zwaaien met de ring geeft ook bellen.","Bewaar het overgebleven sop in een pot met deksel: het blijft een paar weken goed."],"ageTips":{"young":"Een tweejarige kan nog moeilijk blazen. Laat je kind de ring rondzwaaien, of jij blaast en je kind vangt, prikt en stampt de bellen kapot. Plop!","old":"Een kleuter kan zelf vormen buigen en ontdekken: wordt een vierkante ring ook een vierkante bel? Tel hoeveel bellen je in één keer blaast, of wie de grootste bel maakt."},"safety":["Bellenblaas is niet om te drinken en prikt in de ogen: oefen eerst blazen zonder sop, zodat je kind niet per ongeluk zuigt, en houd een nat washandje klaar.","Geknapte bellen maken de vloer spekglad: blaas boven het bad, de douchebak of tegels, dweil direct op en laat je kind niet alleen bij het sop.","Buig de uiteinden van de pijpenragers goed om, zodat er geen scherpe draadjes uitsteken."],"say":["Plop! Weg is de bel!","Kijk, ik zie regenboogkleuren in de bel.","Wat denk je: wordt een hartjesring ook een hartjesbel?","Je blies heel zachtjes, daardoor werd hij zo groot!","Hoeveel bellen kun jij vangen?"],"words":["bel","blazen","zachtjes","plop","rond","zweven","groot","klein"],"learn":["ontdekken","fijne-motoriek","grove-motoriek"],"tips":["Vang een bel met een natte hand: dan knapt hij niet meteen. Probeer het maar!","Blaas bellen in de badkamer vlak voor badtijd: dan is een natte vloer geen probleem.","Spoel handjes na het spelen af met water: afwasmiddel kan prikken in kleine wondjes."],"variations":["Zomer: blaas bellen boven je kind terwijl het in een ondiep bad zit, en jij blijft er natuurlijk bij.","Bellenslang: knip de bodem van een plastic flesje, trek er een oude sok over, doop hem in het sop en blaas: een lange slang van schuim (alleen blazen, niet zuigen).","Verjaardag: geef elk kind op het feestje een eigen pijpenragerring en een bakje sop."],"themes":["zomer"]},
  {"id":"sponsbommen","title":"Sponsbommen voor in bad","emoji":"💦","category":"water","summary":"Bind repen spons samen tot een kleurige bom: vol laten zuigen, uitknijpen en pets, raak tegen de tegels!","ageMin":2,"ageMax":5,"mess":2,"wet":true,"dirty":false,"prepMinutes":10,"durationMinutes":15,"supervision":2,"materials":[{"id":"sponsjes","note":"3 per bom, liefst in verschillende kleuren en zonder schuurkant"},{"id":"schaar","note":"om de sponzen in repen te knippen (voor jou)"},{"id":"elastiekjes","note":"2 stevige per bom, of een strak geknoopt touwtje"},{"id":"badkuip"},{"id":"water","note":"een laagje in het bad"}],"optional":[{"id":"plastic-bekers","note":"als doel op de badrand"},{"id":"badspeelgoed","note":"eendjes om te raken"}],"steps":["Knip elk sponsje in de lengte in 3 repen. Dat doe jij.","Leg 9 repen in 3 laagjes van 3 op elkaar, met de kleuren door elkaar.","Bind ze in het midden strak samen met 2 elastiekjes en trek de repen uit elkaar tot een bol.","Laat de sponsbom in bad vol water zuigen en knijp hem uit: wat een straal!","Gooi samen naar een doel: een tegel, een beker op de rand of een eendje in het water. Pets!","Knijp de bommen na afloop goed uit en laat ze drogen op de rand van het bad."],"ageTips":{"young":"Een tweejarige vindt vol laten zuigen en uitknijpen het leukst. Geef je kind een bom en een beker: knijpen, gieten, nog een keer. Gooien mag naar de tegels, niet naar gezichten.","old":"Een kleuter gooit van steeds verder weg naar een doel, telt de punten of gooit om de beurt. Laat je kind zelf de repen tellen en de kleuren kiezen voordat jij ze vastbindt."},"safety":["Elastiekjes zijn klein (verstikkingsgevaar onder de 3) en kunnen terugschieten: bind ze zelf vast, kijk de bom na elk gebruik na en gooi een los elastiekje meteen weg.","Laat je kind nooit alleen in bad, ook niet bij een laagje water, en dweil gespetter naast het bad direct op.","Een volle sponsbom is zwaar: spreek af dat je naar de tegels gooit, niet naar hoofden."],"say":["Knijp! Kijk eens wat een straal!","Hoe zwaar is de bom nu hij vol water zit? En na het knijpen?","Pets! Raak!","Je bleef het proberen tot je de beker raakte. Wat een doorzetter!","Welke kleur gooi jij als volgende?"],"words":["knijpen","gooien","zwaar","licht","nat","raak","mis","druppelen"],"learn":["grove-motoriek","fijne-motoriek","zintuigen"],"tips":["Laat de bommen na het spelen goed drogen, ook vanbinnen, anders gaan ze muf ruiken. Af en toe kunnen ze mee in de wasmachine op 60 °C.","Goedkope sponsjes uit een grootverpakking zijn prima; knip een eventuele harde schuurkant eraf.","Geen elastiekjes? Een stevig touwtje dat je strak dubbel knoopt werkt ook."],"variations":["Zomer: speel met een laagje koel water in je zwempak, een verkoelend binnenbad.","Omgooispel: zet drie plastic bekers op de badrand en probeer ze eraf te gooien.","Hoeveel water? Knijp de bom uit boven een maatbeker en vergelijk wie er het meest water in had."],"themes":["zomer"]},
  {"id":"eendjes-vissen","title":"Eendjes vissen met een zeef","emoji":"🦆","category":"water","summary":"Laat eendjes en badspeeltjes drijven en vis ze eruit met een zeef: het water loopt eruit, het eendje blijft. Tel samen je vangst!","ageMin":1,"ageMax":4,"mess":2,"wet":true,"dirty":false,"prepMinutes":3,"durationMinutes":15,"supervision":1,"materials":[{"id":"badspeelgoed","note":"5-10 eendjes, bekertjes of ballen, groter dan een wc-rolletje"},{"id":"zeef","note":"of een soeplepel"},{"id":"opbergbak","note":"een afwasteil, of het bad met een laagje water"},{"id":"water","note":"lauw, een paar centimeter"},{"id":"kom","note":"voor de gevangen eendjes"},{"id":"handdoek"}],"optional":[{"id":"vergiet","note":"laat het water extra snel weglopen"},{"id":"oud-laken","note":"een tafelzeil of douchegordijn onder de bak"}],"steps":["Vul een afwasteil of het bad met een laagje lauw water van een paar centimeter.","Laat 5-10 badspeeltjes in het water drijven en zet een lege kom naast de bak.","Geef je kind een zeef of soeplepel en doe voor hoe je een eendje vangt en het water eruit laat lopen.","Leg elk gevangen eendje in de kom en tel samen: één, twee, drie!","Maak het spannender: maak golven met je hand of vraag om een bepaalde kleur.","Gooi alles terug en vis opnieuw. Knijp de eendjes na afloop leeg en laat alles drogen."],"ageTips":{"young":"Een dreumes (1 jaar) vist eerst met de handen of een grote soeplepel. Gebruik 3-4 grote speeltjes en benoem: eend! Nat! Gevangen!","old":"Een vierjarige vist op opdracht (alle gele, of alleen de kleine), telt de vangst of speelt om de beurt: wie heeft er na één liedje de meeste?"},"safety":["Laat een dreumes nooit alleen bij een bak water of in bad: een klein kind kan al in een paar centimeter water verdrinken.","Gebruik alleen speeltjes die niet door een wc-rolletje passen: kleinere zijn te klein voor kinderen onder de 3.","Knijpeendjes met een gaatje kunnen vanbinnen gaan schimmelen: knijp ze na het spelen leeg en laat ze drogen, of plak het gaatje dicht."],"say":["Hap! Gevangen!","Zie je het water door de gaatjes lopen?","Welke kleur ga je nu vangen?","Je hield de zeef heel stil tot het eendje erin zat. Goed gedaan!","Hoeveel eendjes hebben we al? Zullen we tellen?"],"words":["eend","vangen","drijven","gaatjes","nat","meer","minder"],"learn":["fijne-motoriek","rekenen","taal","zintuigen"],"tips":["Speel het vlak voor of tijdens het badderen: dan hoef je niets extra op te ruimen.","Geen badeendjes? Plastic bekertjes en grote deksels drijven ook.","Een gewone eetlepel is lastiger dan een zeef: een leuke uitdaging voor oudere kinderen."],"variations":["Kermis: zet met watervaste stift een stip onder een paar eendjes. Wie een stip vangt, mag een liedje kiezen.","IJsvissen: laat ook ijsblokjes drijven. Wat smelt er terwijl je vist?","Zee: vis plastic visjes van het wateroppervlak en schelpen van de bodem."],"themes":[]},
  {"id":"toverdrankjes","title":"Toverdrankjes brouwen","emoji":"🧪","category":"water","summary":"Gekleurd water, bloemblaadjes en een snufje kaneel: roer, druppel en bruis een echte toverdrank in je eigen ketel.","ageMin":2,"ageMax":5,"mess":3,"wet":true,"dirty":true,"prepMinutes":10,"durationMinutes":25,"supervision":2,"materials":[{"id":"water"},{"id":"kleurstof","note":"2-3 kleuren, een paar druppels per beker"},{"id":"kom","note":"een grote kom als ketel en kleine bakjes voor ingrediënten"},{"id":"plastic-bekers","note":"3-4 stuks"},{"id":"lepel","note":"een grote lepel om te roeren"},{"id":"pipet"},{"id":"bloemen","note":"bloemblaadjes van uitgebloeide bloemen"},{"id":"kruiden","note":"een snufje kaneel, gedroogde kruiden of thee"},{"id":"opbergbak","note":"een grote platte bak om in te werken"}],"optional":[{"id":"baking-soda","note":"1-2 el, voor het bruisen"},{"id":"azijn","note":"een scheutje, voor het bruisen"},{"id":"bladeren","note":"voor een herfstdrankje"},{"id":"zeef","note":"om blaadjes op te vangen bij het weggieten"},{"id":"oud-shirt"},{"id":"oud-laken","note":"als knoeimat"}],"steps":["Zet een grote platte bak op tafel met daarin een kom als ketel en 3-4 bekers water, elk met een paar druppels kleurstof.","Zet de ingrediënten in bakjes klaar: bloemblaadjes, blaadjes en een snufje kaneel of andere kruiden.","Laat je kind brouwen: water overgieten, druppelen met de pipet, roeren en ingrediënten erin strooien.","Bedenk samen wat het drankje doet: is het een slaapdrankje voor de knuffel of een drankje om groot van te worden?","Doe voor bruis 1-2 el baking soda in de ketel en laat je kind er een scheutje azijn bij gieten. Het bruist!","Giet het drankje na afloop weg via een zeef, gooi de blaadjes in de groenbak en spoel bak en bekers om."],"ageTips":{"young":"Een tweejarige giet en roert vooral graag. Geef 2 kleuren en een grote lepel en doe het bruisen zelf. Benoem: geel erbij… nu wordt het groen!","old":"Een kleuter kan een recept tekenen (3 druppels rood, 1 lepel blaadjes) en dat precies nabrouwen, of een naam en een toverspreuk voor het drankje bedenken."},"safety":["Een toverdrank is niet om te drinken: spreek dat vooraf af en gebruik alleen spullen die geen kwaad kunnen als er toch geproefd wordt, dus geen zeep of schoonmaakmiddel.","Gebruik alleen bloemen en blaadjes die je kent; laat giftige planten als lelietje-van-dalen, vingerhoedskruid en narcis weg.","Azijn prikt in de ogen en kleurstof vlekt op kleding, tafel en voegen: werk in de bak, met een oud shirt aan.","Laat je peuter niet alleen bij de bekers water en dweil gemorst water direct op."],"say":["Roer, roer! Wat brouw jij?","Kijk, geel en blauw samen… wat wordt het?","Wat doet jouw toverdrank als je knuffel hem krijgt?","Je hebt heel precies gedruppeld met de pipet. Knap!","Ruik eens aan de kaneel: mmm of bah?"],"words":["brouwen","roeren","druppelen","bruisen","mengen","toverdrank","ketel"],"learn":["creativiteit","ontdekken","fijne-motoriek","taal"],"tips":["Werk in een grote platte bak of in de lege badkuip: wat overloopt, blijft binnen de rand.","Bewaar uitgebloeide bloemen en blaadjes van een wandeling in een bakje: dat zijn je toveringrediënten.","Gebruik kleine beetjes baking soda en azijn, dan kun je vaker bruisen."],"variations":["Halloween: groene heksensoep met plastic spinnen, geroerd met een pollepel.","Herfst: een bosdrankje met blaadjes, dennennaalden en een snufje kaneel.","Lente: bloemensoep met bloemblaadjes en verse munt.","IJsdrankje: laat gekleurde ijsblokjes in de ketel smelten en kijk hoe de kleur zich verspreidt."],"themes":["halloween","herfst"]},
  {"id":"schuimverf-in-bad","title":"Schilderen met schuim in bad","emoji":"🛁","category":"water","summary":"Smeer schuim op de badtegels, de badrand en je eigen buik, en spoel daarna alles weg: kliederen zonder opruimgedoe.","ageMin":2,"ageMax":5,"mess":3,"wet":true,"dirty":false,"prepMinutes":5,"durationMinutes":20,"supervision":2,"materials":[{"id":"scheerschuim","note":"of zelfgemaakt zeepschuim (zie Recepten)"},{"id":"muffinvorm","note":"elk vakje een kleur"},{"id":"badkuip","note":"het lege bad"},{"id":"penselen","note":"dikke kwasten"},{"id":"water","note":"om af te spoelen"}],"optional":[{"id":"kleurstof","note":"een drupje per vakje"},{"id":"sponsjes","note":"om mee te schilderen"},{"id":"plantenspuit","note":"met lauw water, om de tegels schoon te spuiten"}],"steps":["Zet je kind zonder kleren of in een oude zwembroek in het lege bad, op een antislipmat.","Spuit in elk vakje van de muffinvorm een toef schuim en roer er eventueel een drupje kleurstof door.","Geef je kind een kwast of sponsje, of gewoon de handen, en laat je kind de tegels en de badrand beschilderen.","Schilder ook op buik en knieën! Benoem wat je ziet: een gele streep, een blauwe stip, een groene buik.","Spoel alles af met de douche of een beker water en ga daarna meteen in bad.","Veeg de tegels na met een doekje en spoel de muffinvorm om."],"ageTips":{"young":"Voor een tweejarige: begin met wit schuim zonder kleur en laat je kind vooral voelen en smeren. Stopt je kind alles in de mond, neem dan slagroom. Benoem: zacht! Koud! Weg!","old":"Een kleuter kan kleuren mengen (geel en blauw), vormen of de eigen naam op de tegels schrijven, of een schuimgezicht op de buik maken en dat in de spiegel bekijken."},"safety":["Scheerschuim prikt in de ogen en is niet om te eten: houd een nat washandje klaar. Voor een peuter die alles proeft: neem slagroom en spoel die goed weg.","Een bad met schuim is extra glad: laat je kind liefst zitten, op een antislipmat, en laat een jong kind nooit alleen in bad.","Bij een gevoelige huid kan scheerschuim irriteren: kies dan zelfgemaakt zeepschuim van kindershampoo."],"say":["Smeer, smeer! Hoe voelt het?","Ik zie een gele streep naast de blauwe stip.","Wat gebeurt er als je rood en geel door elkaar roert?","Je hebt de hele muur beschilderd. Wat heb je goed doorgezet!","Spoelen… weg is het! Waar is het naartoe?"],"words":["schuim","smeren","zacht","luchtig","mengen","spoelen","glad","weg"],"learn":["zintuigen","creativiteit","ontdekken","taal"],"tips":["Doe het in plaats van het gewone badmoment: na het spelen is je kind meteen schoon.","Met een plantenspuit lauw water wordt het schoonspuiten van de tegels ook een spel.","Gebruik maar een drupje kleurstof en spoel direct na: veel kleurstof kan voegen en een kunststof bad even kleuren."],"variations":["Winter: wit schuim als sneeuw. Teken sneeuwpoppen en sneeuwvlokken op de tegels.","Vormen raden: jij tekent een vorm in het schuim op de tegel, je kind raadt hem en veegt hem weg.","Verjaardag: maak een schuimtaart op de badrand met badspeeltjes als kaarsjes."],"themes":[]},
  {"id":"hut-bouwen","title":"Een hut bouwen in de woonkamer","emoji":"⛺","category":"bouwen","summary":"Dekens over de stoelen, kussens op de vloer en een zaklamp mee naar binnen: in je eigen hut is voorlezen extra gezellig.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":30,"supervision":2,"materials":[{"id":"dekens","note":"een paar dekens of lakens, plus kussens voor op de vloer"},{"id":"stoelen","note":"2-4 stoelen, of de bank en twee stoelen"},{"id":"wasknijpers","note":"om de dekens vast te zetten"},{"id":"zaklamp","note":"of het lampje van je telefoon"}],"optional":[{"id":"knuffels","note":"als gasten"},{"id":"handdoek","note":"een theedoek als gordijn voor de deur"},{"id":"papier","note":"voor een naambordje"},{"id":"stiften"}],"steps":["Zet 2-4 stoelen in een vierkant met de rugleuningen naar buiten, of zet twee stoelen tegenover de bank.","Gooi samen een groot laken of een deken over de leuningen en zet hem vast met wasknijpers.","Laat één kant open als deur, of hang er een theedoek voor als gordijn.","Leg kussens en een dekentje op de vloer: zo wordt het een zacht nest.","Neem een zaklamp, boekjes en knuffels mee naar binnen en lees samen een verhaal bij zaklamplicht.","Laat de hut als het kan een dag staan. Opruimen? Roep ‘de storm komt!’, trek samen de dekens eraf en vouw ze op."],"ageTips":{"young":"Een tweejarige vindt een kleine, lage hut het fijnst: een deken over één stoel of over de tafel is genoeg. Speel kiekeboe met de deur.","old":"Laat je kleuter de hut zelf ontwerpen: waar komt de deur, waar het raam? Maak een naambordje en verzin samen een wachtwoord om binnen te mogen."},"safety":["Zet de stoelen stevig neer en laat je kind er niet op klimmen of aan hangen: een omvallende stoel is zwaar.","Gebruik in de hut alleen een zaklamp, nooit echte kaarsjes of een lamp die heet wordt.","Leg geen zware boeken op het dak om de deken op zijn plek te houden: die vallen zo op kleine hoofdjes."],"say":["Klop klop! Wie woont er in deze hut?","Hoe zorgen we dat de deken niet van het dak glijdt?","Binnen! Gezellig!","Wat heb je goed meegedacht over waar de deur moet.","Hoe klinkt het hier binnen? Is het stiller dan buiten de hut?"],"words":["hut","binnen","buiten","onder","donker","licht","deur","gezellig"],"learn":["grove-motoriek","creativiteit","samen","taal"],"tips":["Een hoeslaken over de tafel is in één minuut een hut die niet afglijdt.","Maak de hut vlak voor het slapengaan voor een voorleesavond, of eet er een picknick in: dat maakt het extra bijzonder."],"variations":["Winter: bouw een iglo van witte lakens en lees een boekje over sneeuw en ijsberen.","Kampeerhut: leg rood papier over een zaklamp als kampvuur en zing kampliedjes.","Dierenhol: de hut is een vossenhol of berengrot, en je kind is het dier dat er woont.","Sterrenhut: prik gaatjes in een stuk karton en schijn er met de zaklamp doorheen: sterren op het dak!"],"themes":["winter"]},
  {"id":"dozenauto","title":"Rijden in een dozenauto","emoji":"🚗","category":"bouwen","summary":"Maak van een grote doos een auto met bordjeswielen, een stuur en koplampen, en ga samen op reis door de kamer.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":15,"durationMinutes":30,"supervision":2,"materials":[{"id":"dozen","note":"een doos waar je kind in kan zitten, bijv. een verhuisdoos"},{"id":"papieren-bordjes","note":"vier als wielen, één als stuur"},{"id":"plakkaatverf","note":"of dikke stiften als het minder vies mag"},{"id":"penselen","note":"liefst dikke"},{"id":"ducttape","note":"of stevig plakband"},{"id":"mes","note":"of een hobbymes, om de kleppen weg te snijden (dat doe jij)"}],"optional":[{"id":"bakjes","note":"twee yoghurtbekers als koplampen"},{"id":"aluminiumfolie","note":"voor glimmende koplampen of een nummerbord"},{"id":"oud-shirt"},{"id":"oud-laken","note":"als knoeimat"}],"steps":["Snijd de kleppen aan de bovenkant weg (dat doe jij) en plak ruwe randen af met ducttape.","Leg een oud laken neer en laat je kind de auto verven in de eigen lievelingskleur.","Laat de verf ±1 uur drogen. Kleur intussen de bordjes als wielen: zwart met een grijs midden.","Plak vier bordjes als wielen op de zijkanten en één als stuur aan de binnenkant van de voorkant.","Maak koplampen van yoghurtbekers of folie en teken een nummerbord met de naam van je kind.","Stap in en ga op reis: waar rijden we heen? Jij duwt de auto langzaam over de vloer."],"ageTips":{"young":"Voor een tweejarige: teken met dikke stiften in plaats van verf, dan kan je peuter meteen instappen. Zeg samen tuut-tuut en vroem.","old":"Laat je kleuter een route bedenken met wegen van schilderstape, een tankstation en een garage, en verkeersborden tekenen: stop, rechtsaf, parkeren."},"safety":["Snijd de doos als je kind niet naast je staat, snijd van je af en berg het mes meteen op.","Duw de auto alleen langzaam over een vlakke vloer en ver van de trap: een doos kantelt makkelijk.","Plakkaatverf kan vlekken op kleding en vloer: kies afwasbare kinderverf, trek een oud shirt aan en leg een knoeimat neer."],"say":["Tuut-tuut! Waar rijden we heen?","Je hebt de hele zijkant al geverfd. Je gaat maar door!","Welke kleur krijgt jouw auto?","Rood licht… stoppen! Groen licht… rijden!","Hoe klinkt jouw motor: zacht of heel hard?"],"words":["auto","wiel","stuur","rijden","stoppen","toeteren","snel","langzaam"],"learn":["creativiteit","grove-motoriek","taal","fijne-motoriek"],"tips":["Vraag in een witgoedwinkel of fietsenwinkel naar een grote lege doos: vaak krijg je er gratis een mee.","Verf een dag van tevoren: dan is de auto droog als je kind wil gaan rijden."],"variations":["Brandweerauto: verf hem rood, met een ladder van ijsstokjes en een slang van een oude panty of touw.","Bus of trein: zet een paar dozen achter elkaar en laat knuffels instappen met een kaartje.","Loopauto: knip de bodem eruit en maak brede schouderbanden van stof; je kind loopt met de auto om zich heen (over de schouders, nooit om de nek).","Drive-in: rijd met de dozenauto naar het loket bij de bank en bestel een boterham of een boekje."],"themes":[]},
  {"id":"ballenbaan","title":"Ballenbaan van kokers op de muur","emoji":"🏓","category":"bouwen","summary":"Plak kokers schuin onder elkaar op een deur of muur en kijk hoe pingpongballetjes van boven naar beneden zigzaggen.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":20,"supervision":1,"materials":[{"id":"wc-rollen","note":"6-10 wc-rolletjes en keukenrolkokers"},{"id":"schilderstape","note":"laat weinig sporen achter op muur of deur"},{"id":"pingpongballen","note":"2-5 stuks"}],"optional":[{"id":"wasmand","note":"of een bak, om de balletjes onderaan op te vangen"},{"id":"stiften","note":"om de kokers te versieren"},{"id":"kinderschaar","note":"om kokers in de lengte open te knippen tot gootjes"}],"steps":["Verzamel 6-10 kokers en knip er een paar in de lengte doormidden: zo heb je ook open gootjes.","Plak de eerste koker schuin op de deur of muur, met het hoogste punt net binnen bereik van je kind.","Plak de volgende koker eronder, schuin de andere kant op, zodat het balletje uit de eerste erin valt.","Bouw zo verder tot vlak boven de vloer en zet daar een mand of bak om de balletjes op te vangen.","Test samen met één balletje. Valt het ernaast? Schuif de koker een stukje bij.","Laat je kind de balletjes er bovenin stoppen en tel hoeveel er in de mand belanden.","Trek de tape bij het opruimen langzaam en schuin los, dan blijft de verf op de muur."],"ageTips":{"young":"Bij een tweejarige plak jij de baan en speel je samen: geef één balletje tegelijk en tel na afloop of ze er allemaal weer zijn. Een korte baan van drie kokers is genoeg.","old":"Laat je kleuter de baan zelf ontwerpen en verbouwen: hoe wordt hij langer, sneller of krijgt hij een bocht? Doe een race met twee balletjes tegelijk."},"safety":["Pingpongballetjes passen door een wc-rolletje en zijn dus te klein voor kinderen onder de 3: speel met je peuter samen, tel ze na afloop en berg ze op.","Laat je kind niet op een stoel klimmen om bij de bovenste koker te komen: plak de baan op kindhoogte, of geef jij de balletjes aan."],"say":["Daar gaat hij… waar komt hij eruit?","Rol, rol, plof!","Wat gebeurt er als we deze koker steiler zetten?","Je hebt de koker net zo lang verschoven tot het lukte. Knap uitgezocht!","Hoeveel balletjes liggen er al in de mand?"],"words":["boven","onder","schuin","rollen","snel","langzaam","erin","eruit"],"learn":["ontdekken","concentratie","fijne-motoriek","rekenen"],"tips":["Schilderstape laat minder sporen achter dan plakband, maar test het eerst op een onopvallend plekje van je muur.","Geen pingpongballetjes? Stevige propjes aluminiumfolie rollen ook, maar zijn net zo klein: alleen samen spelen of vanaf 3 jaar."],"variations":["Wedstrijd: bouw twee banen naast elkaar en laat twee balletjes tegelijk racen. Welke is eerst beneden?","Kleurenbaan: geef elke koker een kleur en noem de kleuren hardop terwijl het balletje erdoorheen rolt.","Autobaan voor kleuters: knip de kokers open tot gootjes en laat er kleine autootjes overheen rijden."],"themes":[]},
  {"id":"flessen-bowlen","title":"Flessen bowlen","emoji":"🎳","category":"bouwen","summary":"Verzwaar lege flesjes, zet ze in een driehoek en rol ze om met een zachte bal: wie gooit ze allemaal om?","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":15,"supervision":1,"materials":[{"id":"plastic-flesjes","note":"6-10 lege flesjes van 0,5 liter met dop"},{"id":"rijst","note":"of water, een laagje van ±3 cm per flesje"},{"id":"ducttape","note":"om de doppen rondom dicht te plakken"},{"id":"bal","note":"een zachte bal"}],"optional":[{"id":"trechter","note":"om de rijst erin te gieten"},{"id":"stickers","note":"om de flesjes te versieren"},{"id":"schilderstape","note":"voor een gooilijn op de vloer en strepen op de flesjes"}],"steps":["Doe in elk flesje een laagje rijst of water van ±3 cm (dat doe jij): dan vallen ze niet vanzelf om, maar wel als je raak rolt.","Draai de doppen stevig dicht en plak ze rondom af met ducttape.","Laat je kind de flesjes versieren met stickers of strepen schilderstape.","Zet de flesjes in een driehoek op een gladde vloer, bijvoorbeeld in de gang, en plak een gooilijn van tape.","Rol de bal om de beurt naar de flesjes. Hoeveel zijn er omgevallen? Tel ze samen.","Laat je kind de flesjes weer rechtop zetten en probeer het opnieuw, of ga een stap verder naar achteren staan."],"ageTips":{"young":"Je dreumes rolt de bal vanaf een halve meter, of duwt de flesjes gewoon met de hand om; dat is net zo leuk. Begin met drie flesjes en roep samen: boem, om!","old":"Zet nummers op de flesjes en tel de punten op, of laat je kleuter de flesjes zelf in een driehoek van 1, 2, 3 zetten. Wie gooit ze allemaal in één keer om?"},"safety":["Doppen en rijst zijn te klein voor kinderen onder de 3 (alles wat door een wc-rolletje past): draai de doppen stevig dicht, plak ze rondom af en controleer ze na het spelen.","Gebruik alleen plastic flesjes, nooit glas, en een zachte bal: een harde bal stuitert zo tegen een kast of een broertje."],"say":["Boem! Om!","Hoeveel flesjes zijn er omgevallen?","Wat gebeurt er als je de bal heel zacht rolt?","Je bleef het proberen tot ze allemaal om lagen.","Zet jij ze weer rechtop?"],"words":["rollen","om","rechtop","raak","mis","hard","zacht","tellen"],"learn":["grove-motoriek","rekenen","concentratie","samen"],"tips":["Met water erin zie je het klotsen, met rijst rammelt het als ze omvallen: maak er een paar van elk.","Bewaar de flesjes in een tas: dan heb je een kant-en-klaar spel voor een regenachtige dag."],"variations":["Kleurenbowlen: geef elk flesje een kleur en noem welke kleuren er omvallen.","Dierenbowlen: plak dierengezichtjes op de flesjes en maak het geluid van elk dier dat omvalt.","Winter: teken sneeuwpopgezichtjes op de flesjes en gooi met een ‘sneeuwbal’ van een opgerolde witte sok."],"themes":[]},
  {"id":"torens-bouwen","title":"Torens bouwen en omgooien","emoji":"🧱","category":"bouwen","summary":"Stapel bekers, doosjes en kokers zo hoog als je kunt en gooi alles met een flinke boem weer om: voor dreumesen het allerleukste deel.","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":2,"durationMinutes":15,"supervision":2,"materials":[{"id":"plastic-bekers","note":"of lege yoghurtbekers, zo veel mogelijk"},{"id":"verpakkingen","note":"lege doosjes van bijv. cornflakes, thee of rijst"},{"id":"wc-rollen"}],"optional":[{"id":"dozen","note":"grote dozen voor een toren die hoger is dan je kind"},{"id":"bal","note":"een zachte bal om de toren om te rollen"},{"id":"duplo","note":"of andere blokken om mee te combineren"},{"id":"wasmand","note":"om alles in op te ruimen"}],"steps":["Verzamel een berg bekers, lege doosjes en kokers en leg ze midden in de kamer, op een plek zonder breekbare dingen in de buurt.","Bouw samen een eerste toren: grote doosjes onderop, kleine bovenop.","Laat je kind de toren omgooien: met de hand, met een zachte bal of door ertegenaan te kruipen. Boem!","Bouw opnieuw en tel elke laag hardop: één, twee, drie…","Probeer iets nieuws: een toren van alleen bekers, een muur, of een brug van een koker op twee doosjes.","Ruim op door alles in een wasmand of doos te gooien: ook dat is een spel."],"ageTips":{"young":"Je dreumes bouwt nog niet hoog, maar gooit graag om. Bouw jij een toren van drie of vier bekers en laat je kind slopen; daarna stapelt het er misschien zelf twee op elkaar.","old":"Daag je kleuter uit: hoe hoog wordt de toren voordat hij valt? Bouw een toren zo hoog als je kind zelf, of een kasteel met een poort waar een auto door kan."},"safety":["Gebruik alleen lichte spullen die zacht vallen: geen glas, blikken of zware boeken in de toren.","Laat je kind niet op een stoel of de bank klimmen om hoger te bouwen; wil het hoger, dan zet jij de bovenste beker erop."],"say":["Boem! Alles om!","Nog eentje erop?","Wat moet er onderop: een grote of een kleine doos?","Wat bouw je voorzichtig, hij wiebelt bijna niet.","Hoe hoog wordt jouw toren, denk je?"],"words":["hoog","laag","bovenop","onderop","wiebelen","vallen","om","groot"],"learn":["fijne-motoriek","ontdekken","rekenen","concentratie"],"tips":["Spaar een week lang doosjes en bekers in een grote doos of wasmand: dat is meteen je bouwdoos én je opruimbak.","Plak doosjes die steeds openvallen even dicht met plakband, dan stapelen ze beter."],"variations":["Kleurentoren: plak gekleurd papier om de bekers en bouw een regenboogtoren.","Bekerpiramide: zet bekers ondersteboven in een driehoek van 3, 2, 1 en rol hem om met een bal.","Stad: bouw een paar torens naast elkaar als flats en laat er autootjes tussendoor rijden.","Kerst: stapel groene bekers tot een kerstboom en zet er een ster van papier bovenop."],"themes":[]},
  {"id":"parkeergarage","title":"Parkeergarage van wc-rolletjes","emoji":"🅿️","category":"bouwen","summary":"Plak wc-rolletjes in een schoenendoos, zet er nummers of kleuren bij en laat je kind elk autootje in het juiste vak parkeren.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":15,"durationMinutes":20,"supervision":2,"materials":[{"id":"wc-rollen","note":"6-12 wc-rolletjes"},{"id":"dozen","note":"een schoenendoos zonder deksel"},{"id":"plakband","note":"of ducttape"},{"id":"stiften"},{"id":"speelgoedautos","note":"die in een wc-rolletje passen"}],"optional":[{"id":"schilderstape","note":"voor nummers op de autodaken en een weg op de vloer"},{"id":"knutsellijm","note":"maakt de garage steviger (±1 uur laten drogen)"},{"id":"gekleurd-papier","note":"om de rolletjes in kleuren te beplakken"}],"steps":["Zet de schoenendoos op zijn lange kant, met de open kant naar je kind toe.","Leg een rij wc-rolletjes liggend onderin de doos en plak ze aan elkaar en aan de doos vast (dat doe jij).","Leg er een tweede en een derde rij bovenop, tot de doos vol is. Elk rolletje is een parkeerplek.","Zet met stift een nummer of kleurstip bij elk rolletje, en hetzelfde op een stukje tape op het dak van elk autootje.","Laat je kind de autootjes parkeren: welke auto hoort in welk vak?","Rijd ze er weer uit, tel de lege plekken en begin opnieuw."],"ageTips":{"young":"Werk voor een tweejarige met kleuren in plaats van cijfers: de rode auto in het rode vak. Begin met drie vakken en zeg wat je peuter doet: auto erin, auto eruit.","old":"Laat je kleuter de cijfers zelf schrijven, de auto’s op volgorde parkeren of sommetjes doen: er staan vijf auto’s in de garage en er rijden er twee weg. Hoeveel blijven er over?"},"safety":["Kleine autootjes passen door een wc-rolletje en zijn dus te klein voor kinderen onder de 3: speel met je tweejarige samen en berg de autootjes daarna op.","Zet de rolletjes vast met plakband en niet met nietjes: kleine vingers gaan graag op onderzoek in de gaten."],"say":["Waar moet de rode auto parkeren?","Auto erin! Auto eruit!","Welk nummer staat er op deze auto? Kun je hetzelfde nummer vinden?","Je zoekt heel goed tot je het juiste vak hebt gevonden.","Hoeveel plekken zijn er nog vrij?"],"words":["parkeren","erin","eruit","vol","leeg","hetzelfde","nummer","vrij"],"learn":["rekenen","fijne-motoriek","concentratie","taal"],"tips":["Plakband is handig als je meteen wilt spelen; met knutsellijm wordt de garage steviger als je hem wilt bewaren.","Spaar een paar weken wc-rolletjes in een tas, dan heb je er genoeg voor een grote garage."],"variations":["Parkeertoren: plak de rolletjes rechtop in de doos en laat de autootjes er van bovenaf in zakken.","Kleurengarage: beplak de rolletjes met gekleurd papier en parkeer op kleur.","Stal of kazerne: maak vakken voor speelgoeddieren of brandweerauto’s in plaats van gewone auto’s.","Stad: plak met schilderstape een weg van de garage door de kamer naar de bank."],"themes":[]},
  {"id":"monster-voeren","title":"Voer het hongerige monster","emoji":"👾","category":"bouwen","summary":"Maak van een doos een monster met een grote mond en laat je kind het voeren met sokken, ballen en deksels: hap, nog een!","ageMin":1,"ageMax":3,"mess":1,"wet":false,"dirty":false,"prepMinutes":15,"durationMinutes":15,"supervision":1,"materials":[{"id":"dozen","note":"een stevige doos met deksel, bijv. een schoenendoos of groter"},{"id":"mes","note":"of een schaar, om de mond uit te snijden (dat doe jij)"},{"id":"stiften","note":"dikke, voor het monstergezicht"},{"id":"sokken","note":"opgerold tot balletjes, als monstervoer"},{"id":"bal","note":"een paar zachte ballen"}],"optional":[{"id":"gekleurd-papier","note":"voor ogen, tanden en haar"},{"id":"lijmstift"},{"id":"schilderstape","note":"om de randen van de mond af te plakken"},{"id":"doppen","note":"alleen grote deksels van potten, die niet door een wc-rolletje passen"},{"id":"knuffels","note":"kleine knuffels als monstervoer"}],"steps":["Teken een grote mond op de voorkant van de doos, minstens 15 cm breed.","Snijd de mond uit (dat doe jij, terwijl je kind niet naast je staat) en plak de randen af met schilderstape.","Geef het monster ogen, tanden en haar: met dikke stift of plakken met gekleurd papier. Je kind mag meehelpen.","Leg het monstervoer klaar: opgerolde sokken, zachte ballen, grote deksels en kleine knuffels.","Laat je kind het monster voeren: hap! Maak smakgeluiden en laat het monster om meer vragen.","Doe het deksel open en haal alles er samen weer uit. Dan kan het monster opnieuw eten."],"ageTips":{"young":"Je dreumes stopt dingen erin en haalt ze er net zo graag weer uit. Maak de mond extra groot, laat het deksel open en zeg bij elke hap: hap! Weg! Waar is de sok?","old":"Laat je driejarige het monster voeren op bestelling: het monster wil twee ballen, of alleen gele dingen. Of gooi van een afstand en zet bij elke goede worp een stap naar achteren."},"safety":["Voer het monster alleen dingen die niet door een wc-rolletje passen: wat kleiner is, is te klein voor kinderen onder de 3. Dus grote deksels en geen flessendopjes.","Snijd de mond als je kind niet in de buurt is, snijd van je af en plak de snijranden af: dan zijn ze minder scherp."],"say":["Hap! Nog een!","Het monster heeft honger. Wat wil het eten?","Waar is de sok gebleven? Zit hij in zijn buik?","Je mikt hem er zo precies in, recht in de mond!","Mmm, lekker. Wat zou het monster nu willen?"],"words":["hap","erin","eruit","mond","honger","vol","leeg","nog een"],"learn":["grove-motoriek","fijne-motoriek","taal","ontdekken"],"tips":["Gebruik het monster als opruimspel: het monster eet alleen speelgoed dat van de vloer moet.","Laat het monster na afloop staan: dreumesen spelen dit spel graag dagen achter elkaar."],"variations":["Kleurenmonster: plak een kleur rond de mond; het monster eet alleen dingen in die kleur.","Dierenmonster: maak er een kikker, een haai of een nijlpaard met een grote bek van.","Brievenbusmonster: een smalle mond waar je kind kaartjes of grote platte deksels in stopt.","Halloween: verf de doos oranje en maak er een hongerige pompoen van."],"themes":[]},
  {"id":"robot-van-dozen","title":"Een robot van dozen","emoji":"🤖","category":"bouwen","summary":"Stapel dozen op elkaar, pak ze in met glimmende folie en geef je robot knoppen van doppen en antennes van pijpenragers.","ageMin":3,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":30,"supervision":2,"materials":[{"id":"dozen","note":"een grote en een kleinere doos, bijv. een schoenendoos als hoofd"},{"id":"aluminiumfolie"},{"id":"ducttape","note":"of stevig plakband"},{"id":"doppen","note":"een handvol, als knoppen"},{"id":"pijpenragers","note":"2-4 stuks, als antennes"},{"id":"stiften"}],"optional":[{"id":"wc-rollen","note":"als armen en benen"},{"id":"bakjes","note":"als ogen of oren"},{"id":"plakband","note":"rolletjes plakband om de doppen vast te zetten"},{"id":"gekleurd-papier"}],"steps":["Plak de kleppen van de dozen dicht, zet de kleine doos als hoofd op de grote en plak ze aan elkaar met ducttape.","Laat je kind de robot inpakken met aluminiumfolie: scheuren, wikkelen en vastplakken met tape.","Teken samen een gezicht, en op de buik een schermpje met knoppen en metertjes.","Plak doppen op de buik als knoppen, met een rolletje plakband aan de achterkant.","Prik twee gaatjes in het hoofd (dat doe jij), steek er pijpenragers in als antennes en vouw de puntjes om.","Plak kokers als armen aan de zijkant en laat de robot praten: druk op een knop, wat zegt hij dan?"],"ageTips":{"young":"Een driejarige vindt folie scheuren en wikkelen het leukst. Houd het bij één doos en laat je peuter de knoppen plakken waar het wil: elk knopje doet iets anders.","old":"Laat je kleuter eerst een robot tekenen als bouwtekening en die dan nabouwen. Wat kan jouw robot? Bedenk samen knoppen voor opruimen, dansen en tandenpoetsen."},"safety":["Pijpenragers hebben scherpe draadpuntjes: vouw de uiteinden een stukje om.","Doppen zijn klein: houd ze uit de buurt van jongere broertjes of zusjes, want alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3.","Gaatjes prikken doe jij, bijvoorbeeld met een potlood: houd je andere hand niet achter het karton."],"say":["Biep biep! Ik ben een robot!","Wat gebeurt er als je op deze knop drukt?","Je hebt de hele doos ingepakt, er is bijna geen bruin meer te zien.","Hoe loopt een robot? Laat eens zien!","Hoe voelt de folie: glad, koud of kreukelig?"],"words":["robot","knop","antenne","glimmen","kreukelig","biep","aan","uit"],"learn":["creativiteit","fijne-motoriek","taal"],"tips":["Kreukels en scheurtjes in de folie maken een robot juist stoerder: perfect hoeft niet.","Geen doppen? Teken knoppen met stift of plak rondjes gekleurd papier: dat is ook veiliger als er kleine kinderen rondlopen."],"variations":["Robotpak: knip in een grote doos gaten voor hoofd en armen (dat doe jij), zodat je kind zelf de robot is.","Ruimteschip: een lange doos met kokers als raketmotoren en een bedieningspaneel van doppen.","Robotdans: zet muziek aan en dans met stijve armen en kleine stapjes; stop zodra de muziek stopt."],"themes":[]},
  {"id":"eierdoos-beestjes","title":"Eierdoos-rupsen en kuikentjes","emoji":"🐛","category":"bouwen","summary":"Knip een eierdoos in stroken en kuiltjes, verf ze vrolijk en maak er rupsen met voelsprieten en kuikentjes met een snaveltje van.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":10,"durationMinutes":25,"supervision":2,"materials":[{"id":"eierdoos","note":"van karton, schoon en zonder eiresten"},{"id":"plakkaatverf","note":"groen, geel en een paar vrolijke kleuren"},{"id":"penselen","note":"liefst dikke"},{"id":"pijpenragers","note":"voor voelsprieten"},{"id":"stiften","note":"voor ogen en een mondje"},{"id":"schaar","note":"om de eierdoos te knippen (dat doe jij)"}],"optional":[{"id":"gekleurd-papier","note":"oranje, voor snaveltjes en pootjes"},{"id":"veren","note":"als vleugeltjes voor de kuikens"},{"id":"wiebeloogjes","note":"alleen vanaf 3 jaar"},{"id":"knutsellijm"},{"id":"oud-shirt"},{"id":"oud-laken","note":"als knoeimat"}],"steps":["Knip het deksel van de eierdoos en knip de bodem in de lengte doormidden: zo heb je twee rupsen. Een paar losse kuiltjes worden kuikens.","Leg een knoeimat neer en laat je kind de rupsen groen of in alle kleuren verven, en de kuikens geel.","Laat de verf ±30 minuten drogen en was intussen samen de kwasten uit.","Prik twee gaatjes in het eerste kuiltje (dat doe jij), steek er een stukje pijpenrager door als voelsprieten en vouw de puntjes om.","Teken ogen en een mondje met stift, of plak wiebeloogjes (vanaf 3 jaar).","Geef de kuikens een snaveltje en pootjes van oranje papier, en eventueel een veertje als vleugel."],"ageTips":{"young":"Voor een tweejarige knip jij alles vooraf en houd je het bij verven; de ogen teken jij daarna. Benoem de kleuren en tel samen de bultjes van de rups.","old":"Laat je kleuter de rups in een patroon verven (groen, geel, groen…), zelf snaveltjes knippen en een verhaal bedenken: wat eet deze rups voordat hij een vlinder wordt?"},"safety":["Wiebeloogjes zijn klein: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Teken bij een tweejarige de ogen met stift.","Pijpenragers hebben scherpe draadpuntjes: knip ze op lengte en vouw de uiteinden om (dat doe jij).","Plakkaatverf kan vlekken op kleding en tafel: kies afwasbare kinderverf en trek een oud shirt aan."],"say":["Hoeveel bultjes heeft de rups? Tel je mee?","Geel! Nog een kuiken!","Wat eet een rups, denk je?","Je hebt elk bultje een andere kleur gegeven, heel precies.","Hoe voelt de eierdoos: ruw of glad?"],"words":["rups","kuiken","voelspriet","snavel","bultje","geel","groen","kruipen"],"learn":["fijne-motoriek","creativiteit","rekenen"],"tips":["Verf op een dienblad: eierdozen zijn klein, dus de rommel blijft op één plek.","Spaar in het voorjaar een paar eierdozen: met Pasen heb je dan meteen een nestje voor de kuikens."],"variations":["Pasen: zet de kuikentjes in een nestje van een halve eierdoos met slierten geknipt geel papier.","Lieveheersbeestjes: verf losse kuiltjes rood en stip er zwarte stippen op met een wattenstaafje.","Rupsverhaal: lees een prentenboek over een rups die steeds meer eet en laat je eierdoosrups meedoen.","Lente: maak een bloemenveld van eierdooskuiltjes in roze, geel en paars op een stuk karton."],"themes":["lente","pasen"]},
  {"id":"bruisvulkaan","title":"Bruisende vulkaan","emoji":"🌋","category":"proefjes","summary":"Giet azijn bij baking soda en kijk hoe er gekleurde schuimlava uit je vulkaan borrelt: elke keer een spannende uitbarsting.","ageMin":2,"ageMax":5,"mess":3,"wet":true,"dirty":true,"prepMinutes":5,"durationMinutes":20,"supervision":1,"materials":[{"id":"baking-soda","note":"±2 el, genoeg voor een paar uitbarstingen"},{"id":"azijn","note":"natuurazijn, ±50 ml per uitbarsting"},{"id":"afwasmiddel","note":"een scheutje, voor dik schuim"},{"id":"kleurstof","note":"rood of oranje, voor echte ‘lava’"},{"id":"plastic-bekers","note":"een smalle beker of klein leeg flesje als krater, plus een beker voor de azijn"},{"id":"opbergbak","note":"een afwasteil of bak met hoge rand die de lava opvangt"}],"optional":[{"id":"pipet","note":"om de azijn druppel voor druppel toe te voegen"},{"id":"speeldeeg","note":"om een berg rond de beker te boetseren"},{"id":"oud-shirt"}],"steps":["Zet de bak op tafel of op de vloer en zet een plastic beker in het midden: dat is de krater.","Schep samen 2 el baking soda in de beker en doe er een scheutje afwasmiddel en een paar druppels kleurstof bij.","Schenk ±50 ml azijn in een tweede beker en geef die aan je kind.","Tel samen af: drie, twee, één… en giet de azijn in één keer in de krater!","Kijk: het schuim bruist omhoog en stroomt over de rand. Nog een keer? Giet er nieuwe azijn bij, of leeg de beker en begin opnieuw.","Spoel na afloop alles door de gootsteen en neem de bak af met een doekje."],"ageTips":{"young":"Geef je peuter een klein bekertje met een bodempje azijn: zelf gieten is het allerleukste. Doe de baking soda en kleurstof er zelf in en houd het bij één woord: bruisen!","old":"Laat je kleuter voorspellen en testen: wat gebeurt er zonder afwasmiddel? En met een klein scheutje of met een hele beker azijn? Of boetseer samen een berg van speeldeeg om de beker en bedenk er een verhaal bij."},"safety":["Azijn prikt in de ogen en in wondjes: spoel bij een spatje meteen met lauw water en laat je kind niet in de ogen wrijven.","Baking soda, azijn en afwasmiddel zijn niet om te eten of te drinken: houd de flessen zelf vast en zet ze na het afmeten buiten bereik.","Kleurstof vlekt op kleding, tafel en voegen, en gemorst schuim maakt de vloer glad: werk in de bak, trek een oud shirt aan en veeg morsen meteen op."],"say":["Wat denk je dat er gebeurt als we de azijn erbij gieten?","Hoor je dat? Het sist en knispert!","Ik zie bubbels over de rand kruipen, net echte lava.","Je goot heel voorzichtig: bijna alles kwam in de krater.","Bruisen! Nog een keer?"],"words":["bruisen","schuim","bubbels","vulkaan","uitbarsting","sissen","overstromen"],"learn":["ontdekken","zintuigen","taal"],"tips":["Een liter natuurazijn en een pak baking soda zijn goedkoop en genoeg voor een hele middag uitbarstingen.","Doe het in de lege badkuip of vlak voor badtijd: de lava spoel je daar zo weg, en je kind kan meteen in bad."],"variations":["Regenboogvulkaan: zet vijf bekertjes met elk een andere kleur naast elkaar in de bak en laat ze om de beurt uitbarsten.","Dinovulkaan: zet plastic dinootjes rond de krater en laat ze op tijd wegvluchten voor de lava.","Halloween: kleur het schuim groen en laat een ‘heksenketel’ overkoken in een grote kom."],"themes":[]},
  {"id":"bruisende-kleuren","title":"Bruisende kleuren met een pipet","emoji":"🧪","category":"proefjes","summary":"Druppel gekleurde azijn op een laagje baking soda en zie het overal bruisen en knisperen in rood, geel en blauw.","ageMin":2,"ageMax":5,"mess":2,"wet":true,"dirty":true,"prepMinutes":5,"durationMinutes":20,"supervision":2,"materials":[{"id":"baking-soda","note":"±150 g voor een dun laagje op het dienblad"},{"id":"azijn","note":"±200 ml, verdeeld over 3 potjes"},{"id":"kleurstof","note":"rood, geel en blauw"},{"id":"potjes","note":"3 kleine bakjes of glaasjes"},{"id":"pipet","note":"liefst één per kleur"},{"id":"dienblad","note":"met randje; een ovenschaal kan ook"}],"optional":[{"id":"muffinvorm","note":"om de potjes stevig in te zetten"},{"id":"oud-laken","note":"als knoeimat onder het dienblad"},{"id":"klein-speelgoed","note":"grote plastic diertjes om te begraven en vrij te bruisen"},{"id":"oud-shirt"}],"steps":["Strooi een dun laagje baking soda over het dienblad en strijk het een beetje glad met de bolle kant van een lepel.","Verdeel de azijn over drie potjes en doe in elk potje een paar druppels kleurstof: rood, geel en blauw.","Doe voor hoe de pipet werkt: knijp het bolletje in, steek de punt in de azijn, laat los en knijp hem boven het blad weer leeg.","Laat je kind druppels op de baking soda maken: overal waar een druppel valt, bruist het in kleur.","Druppel samen geel bij blauw of rood bij geel. Welke nieuwe kleur ontstaat er?","Strooi er een nieuw laagje baking soda over als het nergens meer bruist. Klaar? Spoel het dienblad af boven de gootsteen."],"ageTips":{"young":"Een pipet is voor een tweejarige nog lastig. Geef een theelepel om de azijn mee te scheppen en te gieten, en zet maar één kleur tegelijk neer.","old":"Laat je kleuter eerst voorspellen welke kleur er ontstaat als je twee kleuren mengt, en pas daarna druppelen. Of teken met druppels een letter, een lachend gezichtje of een regenboog."},"safety":["Azijn prikt in de ogen: knijp de pipet nooit richting gezichten en spoel bij een spatje meteen met lauw water.","Kleurstof vlekt op kleding, hout en voegen: leg een knoeimat neer en trek een oud shirt aan.","Baking soda en azijn zijn niet om te eten of te drinken: zet de fles azijn na het inschenken buiten bereik."],"say":["Knijpen, loslaten… zie je de azijn in de pipet kruipen?","Hoor je het knisperen als de druppel valt?","Wat denk je dat er gebeurt als geel en blauw elkaar raken?","Ik zie een groene vlek! Hoe komt die daar?","Druppel! Bruis!"],"words":["druppel","knijpen","loslaten","bruisen","mengen","oranje","groen","paars"],"learn":["fijne-motoriek","ontdekken","concentratie"],"tips":["Geen pipet? Een medicijnspuitje, een theelepel of een rietje met je vinger op het gaatje werkt ook.","Zet de potjes in een muffinvorm: dan staan ze stevig en vallen ze minder snel om."],"variations":["Verstopte schatten: begraaf een paar grote plastic diertjes in een dikker laagje baking soda en bruis ze met de pipet weer vrij.","Bruisende ijsblokjes: meng baking soda met een beetje gekleurd water tot een dikke pap, vries die in een ijsblokjesvorm in en druppel er azijn op.","Winter: strooi een sneeuwpop van baking soda op een donker bord en laat hem met druppels azijn bruisend smelten."],"themes":[]},
  {"id":"drijven-zinken","title":"Drijft het of zinkt het?","emoji":"⛵","category":"proefjes","summary":"Raad eerst en test dan: welke spullen uit huis blijven drijven in een bak water en welke zakken plons naar de bodem?","ageMin":2,"ageMax":5,"mess":2,"wet":true,"dirty":false,"prepMinutes":5,"durationMinutes":20,"supervision":1,"materials":[{"id":"opbergbak","note":"of een afwasteil, half vol water"},{"id":"water","note":"lauw"},{"id":"kurken","note":"drijven altijd"},{"id":"lepel","note":"een metalen lepel, die zinkt"},{"id":"fruit","note":"bijv. een appel en een sinaasappel"},{"id":"duplo","note":"een paar grote bouwblokken"},{"id":"aluminiumfolie","note":"een vel van ±30 cm voor een bootje"},{"id":"handdoek","note":"onder de bak en om af te drogen"}],"optional":[{"id":"steentjes","note":"een flinke kiezel die niet door een wc-rolletje past"},{"id":"badspeelgoed"},{"id":"papier","note":"voor een lijstje: drijft of zinkt"}],"steps":["Zet de bak op een handdoek op de vloer of tafel en vul hem half met lauw water.","Verzamel samen een stuk of acht voorwerpen, zoals een kurk, een metalen lepel, een appel, een bouwblok en een grote kiezel.","Pak één voorwerp en vraag eerst: wat denk je, blijft het drijven of zakt het naar de bodem?","Laat je kind het voorwerp in het water leggen en kijk samen of de gok klopte. Leg het daarna op de drijf- of de zinkstapel.","Vouw van aluminiumfolie een bootje en laat het drijven. Hoeveel blokjes kan het dragen voordat het zinkt?","Droog alles af op de handdoek en giet het water weg, of geef de planten er water mee."],"ageTips":{"young":"Voor een tweejarige is plonzen en weer opvissen al een feest. Kies grote, onbreekbare voorwerpen en zeg na elke plons alleen: drijft! of zinkt! Het raden komt later vanzelf.","old":"Laat je kleuter vooraf een lijstje maken met twee rijtjes, drijven en zinken, en een vinkje zetten bij elke goede gok. Ook spannend: drijft een sinaasappel met schil, en zonder schil?"},"safety":["Laat je kind nooit alleen bij de bak water, ook niet bij een laagje: blijf er de hele tijd bij.","Kies voor kinderen onder de 3 alleen grote voorwerpen: alles wat door een wc-rolletje past, is te klein (verstikkingsgevaar).","Dweil gemorst water meteen op: een natte vloer is glad."],"say":["Wat denk je: drijft de appel of zinkt hij?","Plons! Helemaal naar de bodem.","Ik zie dat de kurk steeds weer bovenkomt, ook als je hem onderduwt.","Wat goed dat je eerst nadacht voordat je ging testen.","Drijft! Nog een?"],"words":["drijven","zinken","zwaar","licht","bodem","bovenop","plons","nat"],"learn":["ontdekken","taal","rekenen"],"tips":["Laat je kind zelf voorwerpen zoeken die nat mogen worden: dat is de helft van het plezier.","Doe het proefje in de lege badkuip met een laagje water, vlak voor badtijd: dan mag het lekker spetteren."],"variations":["Fruitschaal-test: probeer een banaan, een citroen, een mandarijn en een stuk komkommer. Wat had je niet verwacht?","Bootjesrace: blaas met een rietje je folieboot naar de overkant van de bak.","Toveren met klei: een bolletje klei zinkt, maar maak je er een bakje van, dan blijft het drijven. Hoe kan dat?"],"themes":[]},
  {"id":"dansende-melk","title":"Dansende kleuren in melk","emoji":"🥛","category":"proefjes","summary":"Druppel kleurstof in een laagje melk, raak het aan met een wattenstaafje met afwasmiddel en kijk hoe de kleuren wegschieten en dansen.","ageMin":2,"ageMax":5,"mess":2,"wet":true,"dirty":true,"prepMinutes":5,"durationMinutes":15,"supervision":2,"materials":[{"id":"melk","note":"volle melk, een laagje van ±1 cm"},{"id":"bord","note":"een diep bord of schaaltje"},{"id":"kleurstof","note":"3-4 kleuren"},{"id":"afwasmiddel","note":"een bodempje op een schoteltje"},{"id":"wattenstaafjes","note":"een paar"}],"optional":[{"id":"dienblad","note":"onder het bord, voor gemorste melk"},{"id":"pipet","note":"om de kleurstof te druppelen"},{"id":"koffiefilters","note":"om een afdruk van de kleuren te maken"}],"steps":["Giet een laagje volle melk van ongeveer een centimeter in een diep bord en laat het even stil worden.","Druppel drie of vier druppels kleurstof in verschillende kleuren dicht bij elkaar in het midden. Niet roeren!","Doe een bodempje afwasmiddel op een schoteltje en laat je kind het puntje van een wattenstaafje erin dopen.","Houd het wattenstaafje rustig midden in de melk, tussen de kleuren, en tel tot tien. Kijk hoe de kleuren wegschieten en draaien!","Probeer een andere plek of dop het wattenstaafje opnieuw. Stopt het dansen? Druppel er nieuwe kleuren bij of begin met verse melk.","Giet de melk na afloop weg en was het bord en de handen goed af."],"ageTips":{"young":"Laat je peuter vooral het wattenstaafje erin houden; het druppelen van de kleurstof doe jij. Twee kleuren is genoeg, en zeg wat je ziet: weg! Ze rennen weg!","old":"Laat je kleuter een patroon bedenken, bijvoorbeeld druppels in een cirkel of op een rij, en voorspellen waar de kleuren heen gaan. Vertel daarna: het afwasmiddel duwt het vet in de melk opzij."},"safety":["Deze melk is niet meer om te drinken: giet hem na afloop meteen weg en houd het schoteltje afwasmiddel bij jezelf. Komt er zeep in een oog, spoel dan met lauw water.","Kleurstof vlekt op kleding en tafel: zet het bord op een dienblad en schuif de mouwen omhoog."],"say":["Kijk eens! De kleuren rennen weg van je stokje.","Wat denk je dat er gebeurt als je het wattenstaafje in het midden houdt?","Ik zie rood en blauw door elkaar draaien. Welke kleur wordt het?","Wat houd je je hand goed stil: daardoor blijven de kleuren dansen.","Dans, kleurtjes, dans!"],"words":["druppel","dansen","draaien","wegschieten","melk","zeep","mengen","stil"],"learn":["ontdekken","zintuigen","concentratie"],"tips":["Volle melk werkt het best: hoe meer vet, hoe wilder de kleuren dansen. Melk die net over de datum is, is prima.","Maak een foto van elk bord: elke keer ontstaat er een ander patroon.","Zet het bord op een dienblad met een theedoek eronder: gemorste melk in een vloerkleed ruik je nog dagen."],"variations":["Vergelijk drie borden: volle melk, halfvolle melk en water. Waar dansen de kleuren het wildst?","Oud en nieuw: tel samen af van tien naar nul en steek dan met het wattenstaafje je kleurenvuurwerk af.","Afdrukje: leg na het dansen voorzichtig een koffiefilter op de melk, til hem op en laat hem drogen: een kleurig kunstwerkje."],"themes":[]},
  {"id":"lopend-water","title":"Regenboog van lopend water","emoji":"🌈","category":"proefjes","summary":"Zet bekers met gekleurd water op een rij, hang er bruggetjes van keukenpapier tussen en zie het water klimmen en nieuwe kleuren mengen.","ageMin":3,"ageMax":5,"mess":2,"wet":true,"dirty":true,"prepMinutes":10,"durationMinutes":20,"supervision":2,"materials":[{"id":"plastic-bekers","note":"7 doorzichtige bekers of glazen"},{"id":"water"},{"id":"kleurstof","note":"rood, geel en blauw"},{"id":"keukenpapier","note":"6 vellen"}],"optional":[{"id":"dienblad","note":"om de bekers op te zetten, eventueel in een kring"},{"id":"papier","note":"om je voorspelling op te tekenen"},{"id":"kleurpotloden","note":"in dezelfde kleuren als het water"}],"steps":["Zet zeven bekers op een rij. Vul de eerste, derde, vijfde en zevende beker voor driekwart met water; de bekers ertussen blijven leeg.","Laat je kind kleurstof druppelen: rood in de eerste, geel in de derde, blauw in de vijfde en weer rood in de zevende beker.","Vouw zes vellen keukenpapier in de lengte een paar keer dubbel tot stevige repen.","Hang de repen als bruggetjes tussen de bekers: één uiteinde in een volle beker, het andere in de lege beker ernaast.","Kijk na tien minuten: het gekleurde water kruipt omhoog door het papier! Kom daarna elk uur even kijken.","Bekijk na een paar uur of de volgende ochtend de lege bekers: welke nieuwe kleuren zijn er ontstaan?","Gooi het natte papier weg, giet het water in de gootsteen en spoel de bekers om."],"ageTips":{"young":"Voor een driejarige is het lang wachten. Begin met drie bekers (geel, leeg, blauw) en kijk samen elke tien minuten: wordt het al groen?","old":"Laat je kleuter vooraf voorspellen welke kleur er in elke lege beker komt en dat tekenen met kleurpotloden. Leg de tekening na afloop naast de bekers: klopte het?"},"safety":["Kleurstof vlekt op kleding, tafel en vloerkleed: zet de bekers op een dienblad op een plek waar ze uren mogen blijven staan.","Zet de opstelling buiten bereik van jongere broertjes, zusjes en huisdieren, en dweil gemorst water meteen op: een natte vloer is glad."],"say":["Kijk, het rode water klimt omhoog in het papier!","Welke kleur denk je dat er komt als rood en geel elkaar ontmoeten?","Ik zie een groen randje in de lege beker. Waar komt dat vandaan?","Wat ben je geduldig: het water werkt nog hard voor ons.","Kijk! Groen!"],"words":["opzuigen","klimmen","mengen","nat","droog","oranje","paars","wachten"],"learn":["ontdekken","rekenen","taal"],"tips":["Wees niet zuinig met kleurstof (zo’n 10 druppels per beker): hoe feller de kleur, hoe mooier de regenboog.","Start het proefje ’s ochtends of vlak voor bedtijd: dan is er na het spelen of bij het ontbijt een regenboog te zien.","Stevig keukenpapier werkt het best: dun servetpapier zakt in elkaar als het nat wordt."],"variations":["Regenboogkring: zet zes bekers in een kring (rood, leeg, geel, leeg, blauw, leeg) en maak een complete kleurencirkel.","Bloemen kleuren: zet een witte bloem of een selderijstengel in water met veel kleurstof en bekijk na een dag de blaadjes.","Lente: laat de gekleurde repen keukenpapier drogen en knip er bloemen of vlinders van voor het raam."],"themes":[]},
  {"id":"pepertruc","title":"Pepertruc: de peper rent weg","emoji":"🧂","category":"proefjes","summary":"Strooi peper op water, doop je vinger in afwasmiddel en kijk hoe alle peperpuntjes in een flits naar de rand vluchten.","ageMin":3,"ageMax":5,"mess":1,"wet":true,"dirty":false,"prepMinutes":2,"durationMinutes":10,"supervision":2,"materials":[{"id":"bord","note":"een diep bord, liefst wit"},{"id":"water"},{"id":"kruiden","note":"gemalen zwarte peper"},{"id":"afwasmiddel","note":"een druppel op een schoteltje"}],"optional":[{"id":"wattenstaafjes","note":"om het afwasmiddel op te doen in plaats van een vinger"}],"steps":["Vul een diep bord met een laagje water van een paar centimeter en laat het stil worden.","Laat je kind flink wat gemalen peper over het water strooien, tot het vol zwarte puntjes ligt.","Laat je kind eerst een schone, droge vinger in het midden steken. Wat doet de peper?","Doe een druppel afwasmiddel op een schoteltje. Laat je kind de vingertop erin dopen en die weer midden in het water steken.","Kijk hoe de peper in een flits naar de rand vlucht! Raad samen: waarom rent de peper weg?","Spoel het bord om en begin opnieuw met vers water: met zeep erin werkt de truc niet meer."],"ageTips":{"young":"Een driejarige wil de truc steeds opnieuw zien. Zet een paar borden met water en peper klaar, zodat je snel weer kunt toveren, en laat je kind zelf strooien.","old":"Laat je kleuter testen wat nog meer werkt: een vinger met boter, met zout of met shampoo. Wat laat de peper rennen, en wat niet? Vertel daarna: het zeepje breekt het dunne vliesje op het water."},"safety":["Peper prikt in ogen en neus: strooi laag boven het bord en laat je kind niet met peperhanden in de ogen wrijven.","Afwasmiddel hoort niet in de mond: spoel de vinger na elke keer even af onder de kraan."],"say":["Kijk eens, de peper drijft als allemaal kleine bootjes!","Wat denk je dat er gebeurt als je je vinger erin steekt?","Weg! Ze rennen allemaal naar de kant.","Wat zit er nu op je vinger dat er net nog niet op zat?","Wat goed dat je het ook met een schone vinger probeerde. Zo ontdek je het verschil."],"words":["strooien","drijven","wegrennen","rand","midden","zeep","toveren"],"learn":["ontdekken","taal","concentratie"],"tips":["Speel het als goocheltruc met ‘hocus pocus’, en laat je kind de truc daarna zelf aan opa, oma of een vriendje voordoen.","Een wit bord laat de zwarte peper het best zien. Geen peper? Gedroogde oregano of peterselie werkt ook."],"variations":["Visjes en de haai: de peperpuntjes zijn visjes en de zeepvinger is de haai. Waar zwemmen de visjes naartoe?","Tegentruc: leg na het wegrennen een suikerklontje midden in het water. Komt de peper dan juist naar het midden toe?","Zeepbootje: knip een klein bootje van karton met een inkeping achteraan, zet het op het water en druppel afwasmiddel in de inkeping: het vaart vanzelf weg."],"themes":[]},
  {"id":"lavalamp","title":"Lavalamp in een fles","emoji":"🧴","category":"proefjes","summary":"Water met kleurstof, olie en een stukje bruistablet in een fles: kijk hoe de gekleurde bellen op en neer borrelen, net een echte lavalamp.","ageMin":3,"ageMax":5,"mess":2,"wet":true,"dirty":true,"prepMinutes":5,"durationMinutes":15,"supervision":1,"materials":[{"id":"plastic-flesjes","note":"doorzichtig, ±500 ml, etiket eraf"},{"id":"water","note":"±125 ml"},{"id":"kleurstof","note":"een paar druppels"},{"id":"olie","note":"±350 ml zonnebloemolie"},{"id":"bruistablet","note":"een half tablet per keer, in stukjes gebroken"},{"id":"dienblad","note":"om op te werken: olie op tafel is glibberig"}],"optional":[{"id":"trechter","note":"om de olie in de fles te gieten"},{"id":"zaklamp","note":"eronder of erachter, voor een echt lampeffect"},{"id":"zout","note":"als je geen bruistablet hebt"}],"steps":["Zet de fles op het dienblad. Giet er ±125 ml water in (tot een kwart) en laat je kind een paar druppels kleurstof toevoegen.","Vul de fles samen verder met olie tot een paar centimeter onder de rand; met een trechter gaat het makkelijker.","Wacht even en kijk: de olie blijft bovenop drijven en het gekleurde water zakt naar de bodem.","Breek een half bruistablet in een paar stukjes en laat je kind er één in de fles gooien.","Kijk: de gekleurde bellen borrelen naar boven en zakken weer naar beneden. Gestopt? Doe er een nieuw stukje in.","Draai de dop er pas op als het bruisen helemaal gestopt is, en bewaar de fles voor een volgende keer."],"ageTips":{"young":"Een driejarige mag het stukje tablet erin gooien; de olie giet jij en de tabletten houd je bij je. Doe telkens een klein stukje, dan is er vaak iets nieuws te zien.","old":"Laat je kleuter voorspellen en testen: bruist een groot stuk tablet langer dan een klein stukje? Tel samen hoe lang de bellen doorgaan en vergelijk."},"safety":["Bruistabletten zijn medicijnen of vitaminen: houd de verpakking zelf vast en berg hem daarna hoog en buiten bereik op.","Olie en kleurstof vlekken, en olie op de vloer is spiegelglad: werk op een dienblad en veeg morsen meteen op met keukenpapier en een sopje.","Draai de dop niet dicht zolang het nog bruist: er bouwt dan druk op in de fles."],"say":["Kijk, de olie en het water willen niet mengen!","Wat denk je dat er gebeurt als het tabletje erin valt?","Ik zie een rode bel naar boven gaan… en weer naar beneden zakken.","Blub, blub, blub! Nog een stukje?","Wat kijk je goed: jij zag als eerste dat het stopte."],"words":["bubbels","olie","omhoog","omlaag","drijven","zakken","bruisen"],"learn":["ontdekken","zintuigen","taal"],"tips":["Gebruik goedkope zonnebloemolie: de fles kun je dagenlang bewaren en steeds opnieuw laten borrelen met een nieuw stukje tablet.","Geen bruistablet? Strooi 1 tl zout in de fles: er zakken oliebolletjes naar beneden die daarna weer naar boven drijven.","Giet de olie na afloop niet door de gootsteen, maar doe hem in een afgesloten fles bij het restafval of lever hem in bij de inzamelplek voor frituurvet."],"variations":["Lichtshow: doe het grote licht uit en schijn met een zaklamp onder of achter de fles.","Regenbooglampen: maak drie kleine flesjes in verschillende kleuren en zet ze naast elkaar voor het raam.","Kleurenmix: druppel later een tweede kleur in de fles. Zakt de druppel door de olie heen, en welke kleur krijgt het water?"],"themes":[]},
  {"id":"dansende-rozijnen","title":"Dansende rozijnen","emoji":"🍇","category":"proefjes","summary":"Gooi rozijnen in een glas bruiswater en kijk hoe ze naar de bodem zakken, weer naar boven zweven en op en neer blijven dansen.","ageMin":3,"ageMax":5,"mess":1,"wet":true,"dirty":false,"prepMinutes":2,"durationMinutes":10,"supervision":2,"materials":[{"id":"bruiswater","note":"een vers geopende fles"},{"id":"rozijnen","note":"6-8 stuks"},{"id":"beker","note":"een hoog, doorzichtig glas of plastic beker"}],"optional":[{"id":"water","note":"kraanwater in een tweede glas, om te vergelijken"},{"id":"pasta","note":"stukjes droge spaghetti om ook te laten dansen"}],"steps":["Schenk een hoog glas vol met vers bruiswater en kijk samen naar de belletjes.","Laat je kind vijf tot acht rozijnen één voor één in het glas gooien.","Kijk goed: de rozijnen zakken eerst naar de bodem. Wacht even… daar komen ze weer omhoog!","Bekijk een rozijn van dichtbij: zie je de belletjes die eraan vastplakken? Die tillen hem op als een zwembandje.","Zet een glas kraanwater ernaast en doe daar ook een paar rozijnen in. Wat is het verschil?","Vis de rozijnen er na afloop uit met een lepel. Opeten mag, ze zijn alleen wat zachter geworden."],"ageTips":{"young":"Voor een driejarige is het dansen al spannend genoeg. Houd het bij één glas en zing erbij: op en neer, op en neer!","old":"Laat je kleuter tellen hoeveel rozijnen er tegelijk bovenaan drijven, of kies samen één rozijn en tel hoe vaak hij bovenkomt. Vertel dan: bovenaan knappen de belletjes en zakt hij weer."},"safety":["Gebruik een stevig glas of een doorzichtige plastic beker en zet hem midden op tafel: een omgestoten glas kan breken.","Dweil gemorst bruiswater meteen op: een natte vloer is glad."],"say":["Kijk, de rozijn zakt naar de bodem… en nu komt hij weer omhoog!","Wat zie je allemaal aan de rozijn plakken?","Wat denk je: gaan ze ook dansen in gewoon water?","Op en neer! Op en neer!","Wat kijk je geduldig. Jij zag als eerste dat die kleine rozijn bovenkwam."],"words":["bubbels","omhoog","omlaag","bodem","bovenop","dansen","prik"],"learn":["ontdekken","taal","rekenen"],"tips":["Gebruik een vers geopende fles: hoe meer prik, hoe langer de rozijnen dansen. Na een kwartier is de prik er meestal uit.","Een hoog, smal glas werkt het best: dan hebben de rozijnen een lange dansvloer en zie je alles goed."],"variations":["Dansende spaghetti: breek droge spaghetti in stukjes van 2 cm en kijk of die ook gaan dansen.","Zonder prik: doe 1 tl baking soda in een glas water, giet er een scheutje azijn bij en gooi er rozijnen in.","Rozijnendisco: zet muziek op en dans mee. Gaat de rozijn omhoog, dan sta jij op; zakt hij, dan ga je zitten."],"themes":[]},
  {"id":"tuinkers-eierkoppen","title":"Eierkoppen met tuinkershaar","emoji":"🥚","category":"proefjes","summary":"Teken een gezichtje op een lege eierschaal, zaai er tuinkers in en kijk hoe je eierkop in een week een groene bos haar krijgt.","ageMin":2,"ageMax":5,"mess":2,"wet":true,"dirty":false,"prepMinutes":10,"durationMinutes":15,"supervision":2,"materials":[{"id":"eieren","note":"lege schalen van gekookte eitjes, alleen het kapje eraf"},{"id":"watten","note":"een paar wattenbolletjes per ei"},{"id":"tuinkers","note":"een zakje zaadjes"},{"id":"stiften","note":"om een gezichtje te tekenen"},{"id":"eierdoos","note":"als standaard voor de eierkoppen"},{"id":"water"}],"optional":[{"id":"plantenspuit","note":"om de watten vochtig te houden"},{"id":"kinderschaar","note":"kleuters knippen het haar zelf"},{"id":"potgrond","note":"in plaats van watten"}],"steps":["Bewaar een paar lege schalen van gekookte eitjes: tik alleen het kapje eraf, eet het ei op en spoel de schaal om met warm water.","Zet de schalen in de eierdoos en laat je kind er met stiften een gezichtje op tekenen.","Vul elke schaal met wattenbolletjes en maak ze goed nat met 2-3 el water.","Strooi een flinke snuf tuinkerszaadjes op de natte watten en druk ze zachtjes aan.","Zet de eierkoppen op een lichte vensterbank en houd de watten elke dag vochtig.","Kijk elke dag even: na 1-2 dagen zie je kiempjes, na ongeveer een week heeft je eierkop een flinke bos haar.","Knip het haar af en eet het op een boterham met ei of kaas."],"ageTips":{"young":"Een eierschaal is voor een tweejarige erg breekbaar: gebruik dan een vakje van de eierdoos als kopje. Zaadjes strooien en water geven met een theelepel kan je peuter prima zelf.","old":"Laat je kleuter elke dag een tekening van de eierkop maken in een groeiboekje. Hoeveel dagen duurt het tot de eerste blaadjes? En welk kapsel knip je straks?"},"safety":["Ei-allergie in huis? Gebruik dan vakjes van de eierdoos of lege bakjes in plaats van eierschalen.","Werk je met schalen van rauwe eieren, spoel ze dan goed om met heet water en was daarna ieders handen: op rauw ei kunnen bacteriën (salmonella) zitten.","Een kapotte eierschaal heeft scherpe randjes: gooi gebroken schalen meteen weg."],"say":["Kijk, piepkleine zaadjes! Wat zou eruit groeien?","Nat maken. Druppel, druppel!","Ik zie witte worteltjes! Gisteren waren die er nog niet.","Wat zorg je goed voor je eierkop: je geeft hem elke dag water.","Hoe zal jouw eierkop eruitzien met lang haar?"],"words":["zaadje","kiemen","groeien","wortel","blaadje","knippen","haar"],"learn":["ontdekken","fijne-motoriek","creativiteit","taal"],"tips":["Spaar een paar dagen lang de schalen van gekookte eitjes en spoel ze meteen om, dan gaan ze niet ruiken.","Geen watten? Een prop nat keukenpapier of een schepje potgrond werkt net zo goed.","Draai de eierkoppen elke dag een kwartslag: tuinkers groeit naar het licht toe en anders krijgt je eierkop een scheve kuif."],"variations":["Pasen: zet de eierkoppen als groene versiering op de paastafel, met een zelfgemaakt kuikentje erbij.","Kapsalon: strooi de zaadjes alleen in een smalle strook voor een hanenkam, of aan één kant voor een scheiding.","Lente: zaai tuinkers op nat keukenpapier in de vorm van de eerste letter van de naam van je kind."],"themes":["lente","pasen"]},
  {"id":"vogelvoer-dennenappels","title":"Vogelvoer-dennenappels voor bij het raam","emoji":"🐦","category":"proefjes","summary":"Smeer een dennenappel in met pindakaas, rol hem door vogelzaad en hang hem bij het raam: daarna kijk je vanuit binnen wie er komt snoepen.","ageMin":2,"ageMax":5,"mess":3,"wet":false,"dirty":true,"prepMinutes":10,"durationMinutes":20,"supervision":2,"materials":[{"id":"dennenappels","note":"grote, open exemplaren, eerder verzameld"},{"id":"pindakaas","note":"liefst zonder zout; bij een pinda-allergie reuzel of vet"},{"id":"vogelzaad","note":"of havermout met ongezouten zaden"},{"id":"touw","note":"±30 cm per dennenappel"},{"id":"ijsstokjes","note":"om mee te smeren"},{"id":"bord","note":"om het vogelzaad op uit te strooien"}],"optional":[{"id":"zip-zakjes","note":"om de dennenappel in het zaad te schudden (minder rommel)"},{"id":"oud-laken","note":"als knoeimat"},{"id":"oud-shirt"},{"id":"wc-rollen","note":"in plaats van een dennenappel"}],"steps":["Knoop een touw van ongeveer 30 cm stevig om de bovenste schubben van de dennenappel. Dat doe jij.","Doe 3-4 el pindakaas in een kommetje en strooi het vogelzaad uit op een bord.","Laat je kind de dennenappel met een ijsstokje insmeren: tussen de schubben mag de pindakaas er lekker dik in.","Rol de dennenappel door het vogelzaad en druk het zaad met je handen goed aan.","Hang hem buiten bij het raam, aan een tak, de balkonrand of een haakje, buiten bereik van katten. Dat doe jij.","Ga samen binnen op de uitkijk zitten: welke vogels komen er eten? Tel ze en geef ze een naam."],"ageTips":{"young":"Een tweejarige smeert het liefst met de handen: prima, dat voelt lekker. Doe het zaad in een diepvrieszakje en laat je peuter de dennenappel erin schudden.","old":"Laat je kleuter een turflijst maken: teken een mees, een merel en een mus en zet een streepje bij elke vogel die je ziet. Wie komt er het vaakst?"},"safety":["Pinda-allergie in huis? Gebruik dan reuzel of vet in plaats van pindakaas en was na afloop handen, tafel en spullen goed.","Vogelzaad is niet om te eten: zaden en hele pinda’s kunnen in de luchtpijp schieten. Hele noten en pinda’s zijn niet geschikt voor kinderen onder de 4."],"say":["Smeer, smeer! Helemaal plakkerig!","Hoe voelt de dennenappel: glad of stekelig?","Ik zie dat je pindakaas tussen alle schubben hebt gestopt. Daar smullen de vogels van.","Welke vogel denk je dat als eerste komt eten?","Sst… kijk, daar is een mees! Wat doet hij?"],"words":["dennenappel","plakkerig","smeren","zaadjes","vogel","mees","pikken"],"learn":["fijne-motoriek","zintuigen","ontdekken","taal"],"tips":["Leg een knoeimat of krant neer en trek een oud shirt aan: vet geeft vlekken en vogelzaad rolt overal heen. Met een kruimeldief is het zo opgeruimd.","Geen dennenappels? Smeer een wc-rolletje in, rol het door het zaad en schuif het over een tak of rijg er een touwtje door.","Hang het voer op een plek waar katten niet bij kunnen en vervang het als het gaat schimmelen. Vogels hebben het vooral nodig bij vorst en sneeuw."],"variations":["Vetkoekjes: meng gesmolten vet met vogelzaad, giet het in uitsteekvormpjes op bakpapier, leg er een lusje touw in en laat het opstijven in de koelkast. Het smelten doe jij.","Kerst: hang een paar dennenappels met een strikje als versiering in een boom bij het raam.","Vogelboekje: maak een foto van elke vogel die komt eten en zoek samen de naam op."],"themes":["winter"]},
  {"id":"pasta-rijgen","title":"Pastaketting rijgen","emoji":"📿","category":"motoriek","summary":"Rijg penne of rigatoni aan een touw tot een ketting of armband: goed voor handige vingers én een cadeautje om trots op te zijn.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":20,"supervision":1,"materials":[{"id":"pasta","note":"penne of rigatoni: hoe groter het gat, hoe makkelijker"},{"id":"touw","note":"of wol: ±70 cm voor een ketting, ±25 cm voor een armband"},{"id":"plakband","note":"om het puntje van het touw stijf te maken"}],"optional":[{"id":"schoenveter","note":"heeft al een hard puntje: makkelijk voor beginners"},{"id":"pijpenragers","note":"stijf en makkelijk om op te oefenen; puntjes omvouwen"},{"id":"kleurstof","note":"om de pasta vooraf te kleuren (zie tips)"},{"id":"zip-zakjes","note":"om de pasta in te kleuren"}],"steps":["Knip een touw van ±70 cm voor een ketting of ±25 cm voor een armband. Draai plakband strak om één uiteinde: dat is je ‘naald’.","Knoop aan het andere uiteinde een stuk pasta vast, dan glijdt de rest er niet af.","Doe de pasta in een bakje en laat je kind rijgen: puntje in het gat, doorschuiven en de volgende!","Bedenk samen een patroon, bijvoorbeeld penne-rigatoni-penne, of rood-geel-rood als je gekleurde pasta hebt.","Knoop de uiteinden stevig aan elkaar als het touw bijna vol is (dat doe jij) en knip het plakbandpuntje eraf.","Geef de ketting cadeau of hang hem op. Draagt je kind hem zelf, doe hem dan af voor het slapen."],"ageTips":{"young":"Een tweejarige rijgt het makkelijkst met rigatoni op een schoenveter of pijpenrager. Houd jij het touw rechtop vast; je peuter doet de pasta op het puntje en laat hem naar beneden zakken.","old":"Laat je kleuter een patroon bedenken en volhouden, de stukjes tellen of de pasta zelf kleuren. Hang er een hartje of letter van karton aan voor wie de ketting krijgt."},"safety":["Droge pasta past door een wc-rolletje: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Blijf bij je peuter en ruim gevallen stukjes direct op.","Een ketting kan verstrikt raken (wurggevaar): laat je kind hem nooit zonder toezicht om de nek dragen en doe hem af voor het slapen en bij het klimmen."],"say":["Erin… en doorschuiven! Nog een!","Ik zie dat je het touw goed strak houdt. Zo glijdt de pasta er makkelijk op.","Hoeveel stukjes zitten er al aan je ketting? Zullen we tellen?","Wat komt er nu in jouw patroon: een dunne of een dikke?","Wat heb jij lang volgehouden, wat een geduld!"],"words":["rijgen","gat","door","touw","ketting","patroon","lang","kort"],"learn":["fijne-motoriek","concentratie","rekenen","creativiteit"],"tips":["Gekleurde pasta: schud 200 g pasta met 1 tl azijn en een paar druppels kleurstof in een ritszakje, spreid uit op bakpapier en laat 1-2 uur drogen.","Bewaar een half afgemaakte ketting met de pasta in een ritszakje: morgen gewoon verder rijgen."],"variations":["Moederdag: rijg een ketting voor mama of oma en hang er een hartje van karton aan.","Armband: vijf of zes stukjes op een kort touwtje, snel af en net zo trots om te geven.","Rups: rijg pasta op een pijpenrager, buig hem in een bocht en teken met stift een gezichtje op het eerste stukje.","Kerst: rijg rood en groen gekleurde pasta tot een slinger voor in de kerstboom."],"themes":["moederdag","cadeau"]},
  {"id":"spaghetti-prikken","title":"Spaghetti prikken in een vergiet","emoji":"🍝","category":"motoriek","summary":"Prik droge spaghetti of pijpenragers door de gaatjes van een omgekeerd vergiet en schuif er ontbijtringetjes overheen: een rustig prikspel voor kleine vingers.","ageMin":1,"ageMax":3,"mess":1,"wet":false,"dirty":false,"prepMinutes":2,"durationMinutes":15,"supervision":2,"materials":[{"id":"vergiet","note":"omgekeerd op tafel; liefst met gaatjes waar een sliert net door past"},{"id":"pasta","note":"droge spaghetti, in halve slierten gebroken"},{"id":"ontbijtgranen","note":"ontbijtringetjes om over de slierten te schuiven"}],"optional":[{"id":"pijpenragers","note":"zachter en steviger voor dreumesen; puntjes omvouwen"},{"id":"dienblad","note":"onder het vergiet, dan rollen de ringetjes niet weg"}],"steps":["Zet een vergiet ondersteboven op een dienblad of op tafel.","Breek een paar slierten droge spaghetti doormidden en leg ze in een bakje naast het vergiet.","Laat zien hoe je een sliert door een gaatje prikt. Nu jij: hoeveel slierten passen erin?","Geef ontbijtringetjes als het vergiet vol staat, en laat je kind ze één voor één over een sliert schuiven.","Trek alles er weer uit en begin opnieuw: eruit halen is net zo leuk als erin stoppen."],"ageTips":{"young":"Geef een dreumes van 1 liever pijpenragers met omgevouwen puntjes: die breken niet en zijn makkelijker vast te pakken. Prikken en eruit trekken is uitdaging genoeg; de ringetjes komen later.","old":"Een driejarige kan tellen hoeveel ringetjes er op één sliert passen, gekleurde pijpenragers op kleur sorteren of penne over de slierten rijgen. Wie bouwt de hoogste toren van ringetjes?"},"safety":["Droge spaghetti breekt in harde, scherpe stukjes. Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3: ruim gebroken stukjes meteen op en blijf erbij.","In pijpenragers zit ijzerdraad met een scherp puntje: vouw beide uiteinden een stukje om.","Ontbijtringetjes mogen opgegeten worden, maar laat je kind dan rechtop zitten en blijf erbij."],"say":["Prik! Nog een!","Ik zie dat je heel goed mikt op dat kleine gaatje.","Waar gaat deze sliert naartoe: bovenop of aan de zijkant?","Wat heb je geduldig geprikt, het vergiet lijkt wel een egel!","Hoe voelt de pijpenrager: zacht of kriebelig?"],"words":["prikken","gaatje","erin","eruit","lang","vol","ringetje","bovenop"],"learn":["fijne-motoriek","concentratie","ontdekken"],"tips":["Zet het vergiet op een dienblad: gevallen ringetjes blijven dan binnen handbereik en rollen niet onder de bank.","Geen vergiet? Prik met een pen gaatjes in een omgekeerde schoenendoos (dat doe jij)."],"variations":["Taart: prik de slierten als kaarsjes in een bal speeldeeg of eetbaar havermoutdeeg en zing ‘Lang zal ze leven’.","Doos: prik grotere gaten in een schoenendoos en laat je kind er rietjes of pijpenragers in steken.","Kleuren: gebruik pijpenragers in verschillende kleuren en zet ze per kleur bij elkaar."],"themes":[]},
  {"id":"wasknijpers","title":"Wasknijper-figuren: leeuw, egel en zon","emoji":"🦁","category":"motoriek","summary":"Knijp wasknijpers op de rand van een papieren bordje tot een leeuw met manen, een egel of een zon: knijpen maakt kleine vingers sterk.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":15,"supervision":2,"materials":[{"id":"wasknijpers","note":"10-20 stuks; liefst met een niet te stugge veer"},{"id":"papieren-bordjes","note":"of een rondje karton"},{"id":"stiften","note":"om een gezicht te tekenen"}],"optional":[{"id":"waskrijt","note":"om het bordje geel of oranje te kleuren"},{"id":"karton","note":"voor een egel: knip een druppelvorm uit"},{"id":"bladeren","note":"om tussen de stekels van de egel te knijpen"}],"steps":["Kies samen wat je maakt: een leeuw, een zon of een egel. Teken met stift een gezicht in het midden van het bordje.","Kleur het bordje eventueel geel of oranje met waskrijt. Voor een egel knip je een druppelvorm uit karton (dat doe jij).","Laat zien hoe een knijper werkt: knijpen, openhouden, over de rand schuiven en loslaten.","Knijp samen de knijpers rondom de rand: manen voor de leeuw, stralen voor de zon, stekels op de rug van de egel.","Haal ze er weer af en begin opnieuw, of tel hoeveel knijpers er rondom passen."],"ageTips":{"young":"Voor een tweejarige is een knijper openknijpen echt zwaar werk. Zoek de slapste knijpers uit, houd jij het bordje vast en begin met drie knijpers. Knijpers eraf halen is ook al knap.","old":"Laat je kleuter een kleurpatroon maken (geel, oranje, geel…), tellen hoeveel knijpers er passen of een eigen dier bedenken: een spin met acht poten of een krab met scharen."},"safety":["Knijpers knijpen ook in vingertjes, neusjes en oorlelletjes: laat ze niet aan het gezicht hangen.","Gooi kapotte knijpers meteen weg: het losse veertje is klein en scherp, en alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3."],"say":["Knijp… open… en los!","Ik zie dat je duim en je wijsvinger samen hard werken.","Hoeveel stralen heeft jouw zon al?","Wat heb je goed doorgezet: die knijper was stug!","Wat voor dier zou jij nog kunnen maken met knijpers?"],"words":["knijpen","open","dicht","rand","rondom","manen","stekels","stralen"],"learn":["fijne-motoriek","rekenen","creativiteit"],"tips":["Test de knijpers eerst zelf: sommige zijn veel stugger dan andere. Leg de makkelijkste apart voor je kind.","Bewaar bordjes en knijpers samen in een zak: een kant-en-klaar spelletje voor onderweg of bij opa en oma."],"variations":["Herfst: knip een egel uit bruin karton, knijp er stekels op en steek een blaadje achter een van de knijpers.","Zomer: maak een gele zon met knijpers als stralen en hang hem voor het raam.","Kleurenspel: kleur de rand van het bordje in vakjes en zoek een knijper in dezelfde kleur.","Bloem of vis: knijpers als bloemblaadjes rond een hartje, of als vinnen en staart aan een kartonnen vis."],"themes":["herfst","zomer"]},
  {"id":"kleuren-sorteren","title":"Sorteren op kleur in een muffinvorm","emoji":"🌈","category":"motoriek","summary":"Leg in elk vakje van een muffinvorm een gekleurd papiertje en zoek samen uit wat waar hoort: met je handen, een lepel of een knijper.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":15,"supervision":2,"materials":[{"id":"muffinvorm","note":"of een eierdoos of losse bakjes"},{"id":"gekleurd-papier","note":"een rondje per vakje, in de kleuren van je spullen"},{"id":"duplo","note":"of andere grote spulletjes in verschillende kleuren"}],"optional":[{"id":"pompons","note":"pas vanaf 3 jaar"},{"id":"doppen","note":"kleine doppen pas vanaf 3 jaar"},{"id":"wasknijpers","note":"als tangetje voor kleuters"},{"id":"lepel","note":"om mee te scheppen"}],"steps":["Knip rondjes gekleurd papier en leg er één onderin elk vakje van de muffinvorm, bijvoorbeeld rood, geel, blauw en groen.","Doe alle spulletjes door elkaar in een kom: duplo, of vanaf 3 jaar ook pompons en doppen.","Pak er samen één uit: welke kleur is dit? Waar woont rood?","Laat je kind alles sorteren met de handen. Gaat dat makkelijk? Probeer dan een lepel of een wasknijper als tangetje.","Kijk samen naar de vakjes: waar zitten de meeste? Gooi alles terug in de kom en begin opnieuw."],"ageTips":{"young":"Begin bij een tweejarige met twee kleuren en grote spullen, en leg in elk vakje alvast één voorbeeld. Benoem steeds de kleur: rood! Nog een rode!","old":"Laat je kleuter sorteren met een wasknijper als tang, of op twee dingen tegelijk: rood én groot. Tel daarna per vakje: van welke kleur heb je er het meest?"},"safety":["Pompons, kleine doppen en kralen passen door een wc-rolletje: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Geef je peuter duplo of andere grote spullen.","Tel na afloop of alle kleine spulletjes terug zijn in het bakje, zeker als er een jonger broertje of zusje rondkruipt."],"say":["Rood! Waar woont rood?","Ik zie dat je alle gele blokjes al bij elkaar hebt gezet.","Hoe weet jij dat deze bij blauw hoort?","Van welke kleur hebben we de meeste, denk je?","Met een wasknijper pakken is lastig, en jij blijft het proberen!"],"words":["rood","geel","blauw","groen","hetzelfde","sorteren","meer","minder"],"learn":["rekenen","fijne-motoriek","taal","concentratie"],"tips":["Passen je spullen niet in de vakjes? Sorteer dan in kommen of schoenendozen met een gekleurd vel erin.","Bewaar de muffinvorm met de papiertjes en spulletjes in een zak: een snel spelletje voor een regenachtige ochtend."],"variations":["Op maat: sorteer groot en klein, of zwaar en licht, in twee bakken.","Herfst: sorteer verzamelde blaadjes op kleur in bakjes: groen, geel, oranje en bruin.","Opruimspel: laat je kind speelgoed per kleur terugbrengen naar de bakken."],"themes":[]},
  {"id":"plakbandweb","title":"Redden uit het plakbandweb","emoji":"🕸️","category":"motoriek","summary":"Plak schilderstape kriskras over een wasmand vol speelgoed en laat je kind de gevangen diertjes één voor één bevrijden.","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":15,"supervision":2,"materials":[{"id":"schilderstape","note":"of plakband, één rol"},{"id":"wasmand","note":"of een doos zonder deksel"},{"id":"klein-speelgoed","note":"of knuffels; voor kinderen onder de 3 groter dan een wc-rolletje"}],"optional":[{"id":"wasknijpers","note":"als vistang voor kleuters"},{"id":"pijpenragers","note":"om een spin van te buigen"}],"steps":["Leg speelgoed of knuffels onderin een wasmand of doos.","Plak lange stroken schilderstape kriskras over de opening, van rand naar rand. Laat genoeg ruimte voor een kinderhand.","Vertel erbij: oh nee, de diertjes zitten gevangen in het web! Wie helpt ze eruit?","Laat je kind de diertjes tussen de stroken door eruit halen, of de tape lostrekken: allebei goed.","Zet de geredde diertjes op een rij en tel samen: hoeveel zijn er al vrij?","Prop de tape samen tot een grote bal en gooi hem in de prullenbak."],"ageTips":{"young":"Plak voor een dreumes maar een paar stroken, ver uit elkaar, en gebruik knuffels of grote blokken die makkelijk te pakken zijn. Lostrekken is voor je dreumes net zo leuk als redden.","old":"Maak het web dichter en laat je kleuter vissen met een wasknijper als tang, zonder de tape te raken. Of speel tegen de klok: hoeveel diertjes red je in één minuut?"},"safety":["Propjes tape belanden bij een dreumes snel in de mond (verstikkingsgevaar): gooi losgetrokken stroken direct weg.","Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3: verstop voor je dreumes of peuter alleen grote speeltjes en knuffels."],"say":["Trek! Daar is de eend!","Wie zit er nog gevangen in het web?","Ik zie dat je je hand heel voorzichtig tussen de stroken door steekt.","Hoe voelt de tape: plakkerig of glad?","Wat ben jij een goede redder: je blijft het gewoon proberen!"],"words":["plakkerig","trekken","onder","tussen","door","vast","los","bevrijden"],"learn":["fijne-motoriek","concentratie","taal","ontdekken"],"tips":["Schilderstape is fijner dan plakband: het plakt minder hard aan kleine vingers en trekt makkelijk los van de wasmand.","Geen wasmand? Plak het web tussen de poten van een stoel of over een la."],"variations":["Halloween: buig een spin van een pijpenrager, zet hem op het web en red de diertjes voor hij terugkomt!","Muffinvorm-web (vanaf 3 jaar): plak tape over de vakjes van een muffinvorm met in elk vakje een kleine verrassing.","Garage: zet speelgoedautootjes in een doos en laat ze door het web naar buiten rijden."],"themes":["halloween"]},
  {"id":"plakband-lostrekken","title":"Plakbandjes lostrekken","emoji":"✋","category":"motoriek","summary":"Plak stroken schilderstape op tafel, raam of vloer en laat je kind ze lostrekken: simpel, stil en heerlijk voor kleine vingertjes.","ageMin":1,"ageMax":3,"mess":1,"wet":false,"dirty":false,"prepMinutes":3,"durationMinutes":10,"supervision":2,"materials":[{"id":"schilderstape","note":"liefst in een paar kleuren"}],"optional":[{"id":"papier","note":"om de losgetrokken stroken op te plakken"},{"id":"stiften","note":"om de tape in te kleuren of figuurtjes op te tekenen"},{"id":"speelgoedautos","note":"om over een tapeweg te laten rijden"}],"steps":["Plak 10-15 stroken schilderstape op het tafelblad, het raam of de vloer: rechte lijnen, kruisjes of een zonnetje.","Vouw aan elke strook een puntje om, plakkant op plakkant: zo kan je kind het makkelijk vastpakken.","Laat zien hoe je aan het puntje trekt. Nu jij!","Benoem wat je ziet: een lange gele strook, een korte blauwe, een kruisje.","Plak de losgetrokken stroken samen op een vel papier: een kunstwerk van tape."],"ageTips":{"young":"Plak voor een dreumes van 1 een paar korte, brede stroken laag op de vloer of het raam, met een groot omgevouwen puntje. Trek de eerste samen los.","old":"Een driejarige kan in een vaste volgorde lostrekken (eerst alle rode), zelf stukjes tape afscheuren en opplakken, of eerst met een autootje over de tapeweg rijden."},"safety":["Een propje tape is voor een dreumes zo in de mond (verstikkingsgevaar): verzamel losgetrokken stroken meteen op een vel papier of in de prullenbak.","Plak geen tape in de buurt van stopcontacten en snoeren: daar wil je je kind niet laten peuteren en trekken."],"say":["Trek! Los!","Ik zie een lange gele streep. Kun jij hem vinden?","Hoor je dat? Krrrt, zegt de tape.","Hoe voelt de plakkant aan je vinger?","Wat zet jij goed door, die laatste zat echt vast!"],"words":["trekken","los","plakkerig","lang","kort","streep","kruis","puntje"],"learn":["fijne-motoriek","taal","zintuigen","concentratie"],"tips":["Haal de tape dezelfde dag weg van ramen, deuren en lak: hoe langer hij zit, hoe vaster hij gaat plakken.","Geen gekleurde tape? Kleur gewone schilderstape met stift, dan kun je toch kleuren benoemen."],"variations":["Tapeweg: plak een weg op de vloer, rijd er met autootjes over en trek hem daarna samen los.","Knuffelredding: plak een knuffel ‘vast’ op tafel onder een paar stroken en laat je kind hem bevrijden.","Raamkunst: plak een huis of zon op het raam en trek de stroken er een voor een weer af."],"themes":[]},
  {"id":"rijgkaarten","title":"Rijgkaarten maken","emoji":"🧵","category":"motoriek","summary":"Knip een vorm uit karton, pons er gaatjes in en rijg er een veter doorheen: een rustig rijgspel dat je steeds opnieuw kunt doen.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":20,"supervision":2,"materials":[{"id":"karton","note":"bijv. van een cornflakesdoos: dun karton is makkelijk te ponsen"},{"id":"perforator","note":"voor de gaatjes"},{"id":"schoenveter","note":"of touw van ±60 cm met plakband om het puntje"},{"id":"stiften","note":"om de vorm te tekenen en te versieren"}],"optional":[{"id":"touw","note":"of wol, als je geen veter hebt"},{"id":"plakband","note":"om het puntje van het touw stijf te maken"},{"id":"stickers","note":"om de kaart te versieren"},{"id":"kinderschaar","note":"voor kleuters die zelf willen knippen"}],"steps":["Teken een grote, eenvoudige vorm op het karton, zoals een appel, vis, hart of auto, en knip hem uit (dat doe jij).","Pons rondom gaatjes in de rand, ongeveer 2-3 cm uit elkaar. Laat je kind ook eens ponsen: met twee handen flink drukken!","Laat je kind de vorm versieren met stift of stickers.","Knoop de veter vast aan het eerste gaatje. Gebruik je touw? Draai dan plakband strak om het losse puntje.","Rijg samen: door een gaatje naar achteren, door het volgende weer naar voren. Zeg erbij: erin… en eruit!","Trek de veter eruit als je helemaal rond bent en begin opnieuw, of knoop hem vast en hang de kaart op."],"ageTips":{"young":"Maak voor een driejarige maar 6-8 gaten en gebruik een veter met een hard puntje. Het maakt niet uit hoe je kind rijgt: kriskras is ook rijgen.","old":"Laat je kleuter zelf de vorm tekenen, uitknippen met een kinderschaar (jij knipt de lastige stukjes) en ponsen. Of nummer de gaatjes en rijg ze in de goede volgorde, net als verbind-de-stippen."},"safety":["Veters en touw kunnen om de nek verstrikt raken (wurggevaar): houd ze kort, hooguit ±60 cm, en berg ze op na het spelen.","De rondjes uit de perforator zijn klein: veeg ze op als er een broertje of zusje onder de 3 rondkruipt. Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3."],"say":["Erin… en eruit!","Welk gaatje komt nu, denk je?","Ik zie dat je de veter helemaal doortrekt tot hij strak zit.","Wat werk je geconcentreerd: je bent al halverwege de vis!","Voel je hoe de veter door het gaatje glijdt?"],"words":["rijgen","gaatje","voor","achter","door","rondom","veter","strak"],"learn":["fijne-motoriek","concentratie","creativiteit"],"tips":["Plak een strook plakband over de rand voordat je ponst: dan scheuren de gaatjes minder snel uit.","Gebruik de voorkant van een oude verpakking of ansichtkaart: dan staat er meteen een vrolijk plaatje op."],"variations":["Papieren bordje: pons gaatjes rondom en rijg er een zon met stralen of een spinnenweb van.","Herfst: knip een groot blad, een appel of een paddenstoel uit en rijg met bruin of oranje touw.","Kerst: knip een kerstboom uit en rijg er een rood lint doorheen als slinger."],"themes":[]},
  {"id":"pijpenrager-figuurtjes","title":"Pijpenrager-figuurtjes en ringen","emoji":"🐛","category":"motoriek","summary":"Buig, draai en krul pijpenragers tot ringen, brilletjes en beestjes en rijg er grote kralen op: lekker frunniken voor handige handjes.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":3,"durationMinutes":20,"supervision":2,"materials":[{"id":"pijpenragers","note":"een bosje in verschillende kleuren"},{"id":"kralen","note":"grote houten kralen met een flink gat"}],"optional":[{"id":"pasta","note":"penne om te rijgen, als je geen kralen hebt"},{"id":"rietjes","note":"in stukjes geknipt om te rijgen"},{"id":"schaar","note":"een oude, om pijpenragers door te knippen"}],"steps":["Vouw de puntjes van elke pijpenrager een klein stukje om, zodat het ijzerdraadje niet prikt. Knip er een paar doormidden (dat doe jij).","Laat je kind eerst vrij buigen, draaien en krullen. Wat wordt het: een slang, een slak of een bloem?","Maak samen een ring: draai een halve pijpenrager om de vinger van je kind en draai de uiteinden in elkaar.","Rijg grote kralen op een pijpenrager. Buig het ene eind om, dan glijden ze er niet af.","Buig de pijpenrager met kralen tot een rups of armband, of draai vier halve pijpenragers in het midden samen tot een spin met acht poten.","Bewaar de figuurtjes in een doosje: morgen buig je ze gewoon om tot iets nieuws."],"ageTips":{"young":"Voor een driejarige zijn halve pijpenragers handiger dan hele. Kies kralen met grote gaten en laat het buigen vooral vrij: een kronkel is ook een kunstwerk.","old":"Laat je kleuter een brilletje maken: twee rondjes om een stift gedraaid, een bruggetje ertussen en pootjes voor achter de oren. Of buig samen letters en cijfers: welke letter lukt jou?"},"safety":["In pijpenragers zit ijzerdraad met scherpe puntjes: vouw alle uiteinden om, zeker bij een ring of brilletje (vingers en ogen).","Kralen passen door een wc-rolletje: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Berg ze hoog op als er jongere kinderen in huis zijn."],"say":["Draai, draai, draai… een krul!","Wat kun jij van deze kronkel maken?","Ik zie dat je de kraal precies over het puntje schuift.","Hoe voelt een pijpenrager: zacht of kriebelig?","Wat heb je lang geprobeerd, en nu staat je spin op acht poten!"],"words":["buigen","draaien","krul","rond","recht","kronkel","rijgen","kriebelig"],"learn":["fijne-motoriek","creativiteit","concentratie"],"tips":["Pijpenragers gaan lang mee: buig ze na het spelen recht en bewaar ze met de kralen in een potje.","Geen kralen? Rijg stukjes rietje of penne: licht en makkelijk, en het gat is lekker groot."],"variations":["Kerst: draai een rode en een witte pijpenrager in elkaar en buig er een zuurstok of ster van voor in de boom.","Bloemenperk: buig bloemen met rondjes als blaadjes en prik ze in een bal speeldeeg.","Pasen: buig een paashaas met lange oren of een kuikentje en zet het in een eierdoos."],"themes":[]},
  {"id":"was-ophangen","title":"De was ophangen","emoji":"🧦","category":"motoriek","summary":"Span een waslijn tussen twee stoelen en hang samen sokjes en poppenkleren op met wasknijpers: knijpen, paren zoeken en tellen in één.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":15,"supervision":2,"materials":[{"id":"touw","note":"±1,5 meter, als waslijn"},{"id":"stoelen","note":"twee, ruim een meter uit elkaar"},{"id":"wasknijpers","note":"10-20 stuks"},{"id":"sokken","note":"of poppenkleertjes, washandjes en kleine doekjes"}],"optional":[{"id":"wasmand","note":"voor de schone ‘was’"},{"id":"poppen","note":"om na het ophangen weer aan te kleden"}],"steps":["Zet twee stoelen ruim een meter uit elkaar en knoop een touw strak van stoelpoot naar stoelpoot, net onder de zitting: laag genoeg om bij te kunnen.","Doe de ‘was’ in een wasmand en zet de knijpers in een bakje ernaast.","Laat zien hoe het werkt: sok over het touw, knijper erop. Nu jij!","Zoek samen de paren: waar is de andere sok met streepjes? Hang ze naast elkaar.","Hang de was op kleur of van klein naar groot, en tel hoeveel knijpers je nodig hebt.","Haal alles eraf als de was ‘droog’ is, vouw samen op en ruim het touw meteen weg."],"ageTips":{"young":"Geef een tweejarige grote washandjes of doekjes en de slapste knijpers, en hang jij het eerste stuk op. Alleen over het touw hangen, zonder knijper, is ook al goed.","old":"Laat je kleuter in een patroon ophangen (sok, washandje, sok…), paren zoeken met de ogen dicht door alleen te voelen, of een poppenwasserette beginnen met een prijslijst."},"safety":["Een gespannen touw is een wurg- en struikelgevaar: hang het laag, niet in een looproute, en haal het direct weg na het spelen.","Knijpers knijpen ook in vingertjes en oorlelletjes: laat ze niet aan neus, oren of lippen hangen."],"say":["Sok… knijper… vast!","Waar is de andere sok met stippen?","Ik zie dat je de knijper helemaal openhoudt voor je hem loslaat.","Welke sok is het grootst: die van papa of die van jou?","Wat heb jij hard gewerkt, de hele was hangt!"],"words":["ophangen","knijpen","paar","hetzelfde","groot","klein","waslijn","eraf"],"learn":["fijne-motoriek","rekenen","taal"],"tips":["Echt helpen kan ook: laat je kind na de echte was sokken en washandjes aangeven of zelf aan het droogrek hangen.","Gebruik oude sokken van het hele gezin: grote en kleine door elkaar maken sorteren en vergelijken extra leuk."],"variations":["Poppenwas: was eerst poppenkleertjes in een sopje (dat wordt wel nat) en hang ze dan op.","Kunstlijn: hang de tekeningen van deze week aan de lijn, als een echte tentoonstelling.","Kleurenlijn: hang eerst alleen rode dingen op, dan alleen blauwe."],"themes":[]},
  {"id":"uitpakfeest","title":"Uitpakfeest: pakjes openscheuren","emoji":"🎁","category":"motoriek","summary":"Pak bekend speelgoed in met krant en plakband en laat je kind alles openscheuren: een feestje vol verrassingen en een goede oefening voor pakjesavond.","ageMin":1,"ageMax":3,"mess":2,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":15,"supervision":1,"materials":[{"id":"klein-speelgoed","note":"of knuffels en blokken die je kind al kent; groter dan een wc-rolletje"},{"id":"kranten","note":"of inpakpapier, keukenpapier of oude tekeningen"},{"id":"plakband","note":"hoe meer plakband, hoe spannender"}],"optional":[{"id":"dozen","note":"een doosje in een doos maakt het extra spannend"},{"id":"stoffen-tas","note":"als ‘zak van Sinterklaas’"},{"id":"wasmand","note":"om het papier in te mikken"},{"id":"muziek","note":"voor het pakjesspel"}],"steps":["Pak 5-8 bekende speeltjes in met krant of papier. Varieer: één los gevouwen, één met veel plakband, één in een doosje.","Leg de pakjes in een zak of wasmand en ga er samen bij zitten.","Laat je kind een pakje kiezen. Voel en schud eerst: wat zou erin zitten?","Scheur een klein randje los als je kind niet weet waar te beginnen, en laat de rest zelf doen.","Vier elke vondst: daar is beer! Speel er even mee voordat het volgende pakje aan de beurt is.","Prop het papier samen tot ballen en mik ze in de wasmand: opruimen is ook een spel."],"ageTips":{"young":"Pak voor een dreumes van 1 losjes in met één laag zacht papier zonder plakband, of stop het speeltje in een papieren zakje. Scheur alvast een beginnetje.","old":"Een driejarige kan raden wat erin zit door te voelen, de pakjes tellen en zelf een pakje inpakken voor een knuffel of voor jou. Of speel het pakjesspel: uitpakken zolang de muziek speelt."},"safety":["Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3: pak alleen grote speeltjes in.","Ruim snippers papier en propjes plakband meteen op: een dreumes stopt ze graag in de mond.","Pak niet in met plastic zakken of huishoudfolie: gevaarlijk als het over neus en mond komt."],"say":["Scheur! Wat is het?","Wat zou erin zitten? Schud maar eens.","Ik hoor iets rammelen… jij ook?","Hoe voelt het pakje: zacht, hard of rond?","Wat zoek je slim naar een randje om te beginnen!"],"words":["uitpakken","scheuren","pakje","verrassing","zacht","hard","rammelen","open"],"learn":["fijne-motoriek","zintuigen","taal","samen"],"tips":["Pak in terwijl je kind slaapt, of laat je kind juist meehelpen door stukjes plakband aan te geven.","Oude kranten, folders en tekeningen zijn prima inpakpapier, en dezelfde speeltjes kun je steeds opnieuw inpakken."],"variations":["Sinterklaas: stop de pakjes in een kussensloop als zak van Sinterklaas, zing een liedje en oefen voor pakjesavond.","Kerst: leg de pakjes onder de kerstboom en pak er samen één per dag uit.","Verjaardag: laat een knuffel jarig zijn: pakjes uitpakken, ‘dank je wel’ zeggen en samen zingen.","Lagenpakje: pak een speeltje in, en dat pakje weer, en weer: hoeveel lagen kom je tegen?"],"themes":["sinterklaas","kerst","verjaardag"]},
  {"id":"stickers-op-lijnen","title":"Stickers plakken op lijnen","emoji":"⭐","category":"motoriek","summary":"Jij tekent lijnen, je kind plakt er stickers op: sticker na sticker langs een golf, een zigzag of de eerste letter van de naam.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":3,"durationMinutes":15,"supervision":2,"materials":[{"id":"stickers","note":"ronde stippenstickers werken het best"},{"id":"papier","note":"A4 of groter"},{"id":"stiften","note":"een dikke, donkere stift voor de lijnen"}],"optional":[{"id":"groot-papier","note":"voor lange lijnen op tafel of de vloer"},{"id":"schilderstape","note":"om het vel vast te plakken"}],"steps":["Teken met een dikke stift een paar lijnen op een vel: een rechte, een golf, een zigzag en een grote cirkel.","Plak het vel met schilderstape vast op tafel, dan schuift het niet weg.","Trek bij het stickervel alvast het restpapier rond de stickers weg: dan steken ze uit en zijn ze makkelijker te pakken.","Laat zien hoe je een sticker met duim en wijsvinger lostrekt en precies op de lijn plakt.","Volg samen de lijn, sticker na sticker, als stapstenen. Waar gaat de golf naartoe?","Zet de datum op het vel en bewaar het: over een paar maanden zie je hoeveel preciezer je kind plakt."],"ageTips":{"young":"Begin bij een tweejarige met één korte, dikke rechte lijn en grote stickers. Plakt je peuter ernaast? Prima: het gaat om het lostrekken en plakken.","old":"Teken voor je kleuter de eerste letter van de naam, cijfers of een doolhof en plak in een patroon (rood, geel, rood…). Hoeveel stickers passen er op de cirkel?"},"safety":["Stickers en snippers restpapier zijn klein en blijven makkelijk plakken in een mond of keel: blijf bij je peuter en ruim losse stickers direct op."],"say":["Plak! Nog een!","Ik zie dat je precies op de golf plakt.","Waar gaat de lijn naartoe: omhoog of omlaag?","Hoeveel stickers passen er op de cirkel, denk je?","Wat kijk je goed waar je plakt, je neemt echt de tijd."],"words":["lijn","golf","zigzag","rondje","op","naast","omhoog","omlaag"],"learn":["fijne-motoriek","concentratie","rekenen","taal"],"tips":["Ronde stippenstickers vind je goedkoop in de kantoorboekhandel en ze zijn perfect voor kleine vingers.","Geen stickers? Teken stipjes op stukjes schilderstape en laat je kind die op de lijnen plakken."],"variations":["Kerst: teken een kerstboom en plak stickers als ballen langs de takken.","Herfst: teken een kale boom en plak gele en oranje stickers als blaadjes.","Stickerweg: teken een lange slingerweg op groot papier, plak hem vol en laat er daarna een autootje over rijden."],"themes":[]},
  {"id":"rammelaars","title":"Rammelaars maken van lege flesjes","emoji":"🎶","category":"muziek","summary":"Vul lege flesjes met rijst of pasta, plak de dop goed dicht en ontdek samen hoe elke vulling anders klinkt.","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":15,"supervision":1,"materials":[{"id":"plastic-flesjes","note":"kleine flesjes met dop, vanbinnen goed droog"},{"id":"rijst","note":"2-3 el per flesje"},{"id":"pasta","note":"een handje penne of macaroni"},{"id":"ducttape","note":"om de dop rondom dicht te plakken"}],"optional":[{"id":"trechter","note":"om te vullen zonder te morsen"},{"id":"stickers","note":"om te versieren"},{"id":"touw","note":"korte lintjes (max. 15 cm) om de flessenhals, voor een feestelijk tintje"}],"steps":["Spoel de flesjes om en laat ze helemaal drogen, anders plakt de vulling aan de binnenkant.","Zet kommetjes met rijst en pasta klaar en laat je kind met een lepel en een trechter de flesjes vullen. Een kwart vol is genoeg.","Draai de dop er stevig op en plak hem rondom dicht met een paar lagen ducttape. Dat doe jij.","Schud samen: hoe klinkt rijst en hoe klinkt pasta? Welke klinkt hard en welke zacht?","Versier de flesjes met stickers en zet een liedje op: schud mee op de maat!","Controleer de flesjes voor elk gebruik op scheurtjes en een losse dop, en bewaar ze bij het speelgoed."],"ageTips":{"young":"Een dreumes vult nog niet zelf: maak de rammelaars vooraf en laat je kind vooral schudden, rollen en luisteren. In een doorzichtig flesje zie je de rijst ook nog dansen.","old":"Laat je kleuter raden wat erin zit door alleen te luisteren: plak een paar flesjes helemaal af met tape. Of zet ze op een rij van zacht naar hard."},"safety":["Rijst, pasta en de dop zelf zijn te klein voor kinderen onder de 3 (alles wat door een wc-rolletje past): plak de dop rondom vast en vul de flesjes zelf als je dreumes alles in de mond stopt.","Controleer de rammelaar voor elk gebruik op scheurtjes en een losse dop, en gooi een kapot flesje meteen weg.","Gebruik alleen plastic flesjes, geen glazen potjes: die breken als ze vallen."],"say":["Schud, schud! Hoor je dat?","Hoe klinkt de rijst? En hoe klinkt de pasta?","Wat denk je: welke klinkt het hardst?","Ik hoor dat je heel zachtjes schudt… en nu heel hard!","Wat schud je goed op de maat mee!"],"words":["schudden","hard","zacht","snel","langzaam","rammelen","luisteren"],"learn":["zintuigen","fijne-motoriek","ontdekken"],"tips":["Kleine flesjes van drinkyoghurt of sap passen het best in kleine handjes.","Vul de flesjes boven een dienblad of grote bak: gemorste rijst schud je zo terug in het kommetje."],"variations":["Carnaval: maak een hele rammelband en loop schuddend in optocht door de kamer.","Koningsdag: versier de flesjes met oranje en rood-wit-blauwe tape en lintjes.","Geluidsmemory: maak steeds twee flesjes met dezelfde vulling en plak ze af. Welke twee klinken hetzelfde?"],"themes":["carnaval","koningsdag"]},
  {"id":"pannenorkest","title":"Pannenorkest en dozentrommel","emoji":"🥁","category":"muziek","summary":"Pannen, deksels en een doos worden een complete band: trommel samen hard en zacht, snel en langzaam, en ontdek hoe alles anders klinkt.","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":2,"durationMinutes":15,"supervision":2,"materials":[{"id":"pan","note":"een paar pannen en deksels, koud uit de kast"},{"id":"lepel","note":"houten lepels als trommelstokken"},{"id":"dozen","note":"een stevige doos als trommel"}],"optional":[{"id":"muziek","note":"om op mee te spelen"},{"id":"plastic-bekers","note":"omgekeerd klinken ze weer anders"}],"steps":["Zet een paar pannen, deksels en een stevige doos ondersteboven op de vloer en geef je kind twee houten lepels.","Ontdek samen: hoe klinkt de grote pan, en hoe klinkt het kleine deksel? En de doos?","Speel eerst hard en daarna heel zacht, als een muisje. Dan snel als regen en langzaam als een olifant.","Speel om de beurt: jij tikt een ritme (tik-tik-boem) en je kind speelt het na. Daarna mag je kind voorspelen.","Zet een liedje op en speel samen mee. Stopt de muziek? Dan stoppen jullie ook!","Ruim samen op door alles op te stapelen: past het kleine deksel op de grote pan?"],"ageTips":{"young":"Een dreumes slaat eerst vooral hard: geniet ervan en doe mee. Houten lepels zijn lichter en zachter dan metalen, en ondersteboven op de vloer staan de pannen stevig.","old":"Laat je kleuter dirigent zijn: armen omhoog is hard spelen, armen omlaag is zacht. Of trommel de lettergrepen van ieders naam: Sa-ra, Bram, Mo-ham-med."},"safety":["Gebruik alleen koude pannen uit de kast, nooit van het fornuis, en houd glazen deksels erbuiten: die kunnen breken.","Een metalen pan klinkt heel hard voor kleine oortjes: speel niet vlak bij het hoofd en wissel af met de zachtere doos."],"say":["Boem! Boem! Hoor je dat?","Welke klinkt het hardst: de pan of de doos?","Kun je ook heel zachtjes spelen, als een muisje?","Ik hoor dat je precies mijn ritme nadoet: tik-tik-boem!","Wat blijf je goed op de maat, ook als het liedje sneller gaat."],"words":["hard","zacht","snel","langzaam","boem","trommel","stil"],"learn":["zintuigen","samen","grove-motoriek","taal"],"tips":["Leg een oude handdoek of deken onder de pannen: dat dempt het geluid voor de buren en spaart je vloer.","Een kastje op kindhoogte met plastic bakjes, een pan en houten lepels is een gratis muziekhoek."],"variations":["Sinterklaas: tik met zachte lepeltjes het paard op het dak na op een doos en zing ‘Hoor de wind waait door de bomen’.","Onweer: begin met tikken met één vinger, dan twee, dan de hele hand, en eindig met een donderslag op de pan.","Fanfare: marcheer met een pan en een lepel door de kamer, en wissel om de beurt van instrument."],"themes":[]},
  {"id":"doosgitaar","title":"Gitaar van een doos","emoji":"🎸","category":"muziek","summary":"Span elastiekjes om een open doos, plak er een koker aan als hals en tokkel: ontdek samen welke snaar hoog en welke laag klinkt.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":15,"supervision":2,"materials":[{"id":"dozen","note":"een stevige doos zonder deksel, bijv. een schoenendoos"},{"id":"elastiekjes","note":"4-6 stuks, liefst dikke én dunne"},{"id":"wc-rollen","note":"een keukenrolkoker als hals"},{"id":"ducttape","note":"om de hals vast te plakken"}],"optional":[{"id":"potlood","note":"als ‘brug’ onder de elastiekjes: dan klinkt het luider"},{"id":"stiften","note":"om te versieren"},{"id":"stickers"}],"steps":["Plak een keukenrolkoker met ducttape tegen de korte kant van de doos: dat is de hals van je gitaar.","Span 4-6 elastiekjes in de lengte om de open doos, dik en dun door elkaar. Dat doe jij.","Schuif een potlood dwars onder de elastiekjes, vlak bij één rand: dan klinkt je gitaar luider.","Tokkel samen: klinkt een dik elastiek hoog of laag? En een dun?","Versier de gitaar met stiften of stickers en geef een concertje met je lievelingsliedje.","Bewaar de gitaar hoog op de kast: losse elastiekjes zijn gevaarlijk voor kleine broertjes of zusjes."],"ageTips":{"young":"Voor een driejarige is elastiekjes spannen te lastig en ze schieten snel weg. Span ze zelf en laat je kind tokkelen en plukken. Benoem: hoog, laag, hard, zacht.","old":"Laat je kleuter de elastiekjes ordenen van laag naar hoog, of ontdekken wat er gebeurt als je een elastiek strakker trekt. Lukt het om samen ‘Vader Jacob’ te tokkelen?"},"safety":["Elastiekjes kunnen terugschieten in de ogen: span ze zelf en laat je kind tokkelen zonder ze ver uit te rekken.","Elastiekjes zijn klein en passen door een wc-rolletje: bewaar de gitaar en losse elastiekjes buiten bereik van kinderen onder de 3.","Gooi een uitgedroogd of geknapt elastiekje meteen weg en vervang het."],"say":["Tok! Hoor je dat?","Welke klinkt hoger: het dikke of het dunne elastiek?","Wat gebeurt er als je het elastiek strakker trekt?","Ik zie het elastiek trillen. Voel je het ook met je vinger?","Wat tokkel je geduldig, alle elastiekjes om de beurt."],"words":["tokkelen","trillen","hoog","laag","strak","slap","dik","dun"],"learn":["zintuigen","ontdekken","fijne-motoriek","creativiteit"],"tips":["Een tissuedoos met een gat in het midden is al een kant-en-klare gitaar: span de elastiekjes over het gat.","Een stevige doos klinkt beter dan dun karton: een schoenendoos werkt prima, een cornflakesdoos zakt in."],"variations":["Klankproef: span hetzelfde elastiek om een plastic bakje, een doos en een pan. Welke klinkt het hardst?","Bandje: speel samen met de rammelaars en het pannenorkest en geef een concert voor de knuffels.","Mini-harp: span elastiekjes over een leeg boterkuipje en tokkel met één vinger een slaapliedje."],"themes":[]},
  {"id":"regenstok","title":"Regenstok maken","emoji":"☔","category":"muziek","summary":"Draai aluminiumfolie in een koker, doe er rijst in en plak hem dicht: als je de stok langzaam omdraait, hoor je het zachtjes regenen.","ageMin":3,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":20,"supervision":2,"materials":[{"id":"wc-rollen","note":"een keukenrolkoker, of twee kokers aan elkaar geplakt"},{"id":"aluminiumfolie","note":"2 vellen van ±50 cm"},{"id":"rijst","note":"±3 el"},{"id":"karton","note":"voor twee rondjes om de uiteinden dicht te maken"},{"id":"ducttape","note":"of andere stevige tape"}],"optional":[{"id":"trechter","note":"om de rijst erin te gieten"},{"id":"stiften","note":"om te versieren"},{"id":"stickers"}],"steps":["Trek op karton een rondje om de opening van de koker, knip het iets groter uit en plak er één kant mee dicht. Dat doe jij.","Scheur twee lange vellen aluminiumfolie af en laat je kind ze tot lange slierten draaien en kreukelen.","Draai de slierten tot een spiraal, als een veer, en duw ze in de koker: dat worden trapjes waar de rijst langs valt.","Laat je kind ±3 el rijst in de koker scheppen; met een trechter gaat het makkelijker.","Plak de andere kant dicht met een tweede rondje karton en een paar lagen tape, helemaal rondom.","Versier de regenstok met stiften of stickers en draai hem langzaam om: hoor je de regen?"],"ageTips":{"young":"Een driejarige kan prima folie kreukelen en rijst scheppen. Het dichtplakken doe jij; daarna mag je kind vooral luisteren: langzaam draaien is motregen, snel is een stortbui.","old":"Laat je kleuter testen: hoe klinkt de stok met rijst, met pasta of met linzen? En met meer of minder folie? Maak er twee en vergelijk."},"safety":["Plak de uiteinden met meerdere lagen tape dicht en controleer ze regelmatig: losse rijst is voor kinderen onder de 3 een verstikkingsgevaar.","Geef de regenstok niet aan jongere broertjes of zusjes die erop bijten: het karton wordt dan zacht en scheurt open."],"say":["Ssst… hoor je de regen?","Wat gebeurt er als je hem heel langzaam omdraait? En heel snel?","Ik hoor eerst zachte druppels en daarna een hele bui!","Wat heb je die folie goed gedraaid: het lijkt wel een slang.","Is het nu motregen of een onweersbui?"],"words":["regen","druppels","kreukelen","draaien","zachtjes","omdraaien","luisteren"],"learn":["fijne-motoriek","zintuigen","concentratie"],"tips":["Hoe langer de koker, hoe langer het regent: plak twee of drie kokers met tape aan elkaar.","Geen trechter? Rol een vel papier tot een puntzak en knip het puntje eraf."],"variations":["Herfst: versier de regenstok met gescheurde bladeren of paraplu’s en speel er een herfstbui mee.","Weerverhaal: vertel over de zon, een wolkje en een bui, en laat je kind op het juiste moment de regen maken.","Liedje: zing ‘Het regent, het zegent’ en laat de regenstok meespelen."],"themes":[]},
  {"id":"danslinten","title":"Danslinten maken","emoji":"💃","category":"muziek","summary":"Maak zwierige linten van crêpepapier aan een handvat en dans op muziek: zwaai rondjes, golven en slingers door de kamer.","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":15,"supervision":1,"materials":[{"id":"crepepapier","note":"of lint, stroken van ±3 cm breed en 50 cm lang"},{"id":"wc-rollen","note":"als handvat (of een ijsstokje)"},{"id":"plakband","note":"om de stroken vast te maken"},{"id":"muziek","note":"vrolijke muziek"}],"optional":[{"id":"papieren-bordjes","note":"de rand van een bordje als ring om vast te houden"},{"id":"stiften","note":"om het handvat te versieren"},{"id":"kinderschaar","note":"kleuters knippen de stroken zelf"}],"steps":["Knip crêpepapier in stroken van ongeveer 3 cm breed en 50 cm lang, in een paar kleuren.","Plak 3-5 stroken met flinke stukken plakband aan de binnenkant van een wc-rolletje: dat is het handvat.","Versier het handvat eventueel met stiften.","Zet vrolijke muziek op en dans samen: zwaai de linten hoog, laag, in rondjes en in golven.","Speel stopdans: als de muziek stopt, blijft iedereen stokstijf staan en hangen de linten slap naar beneden.","Bewaar de danslinten na afloop op een vaste plek, buiten bereik van het bedje."],"ageTips":{"young":"Een dreumes houdt een dik wc-rolletje of de rand van een papieren bordje makkelijker vast dan een ijsstokje. Dans samen, op de arm of aan de hand, en benoem: omhoog, omlaag, rondje!","old":"Laat je kleuter een eigen dans bedenken en die aan jou leren: eerst drie rondjes, dan een golf… Of teken met het lint een letter of cijfer in de lucht."},"safety":["Wurggevaar: houd de linten kort (±50 cm), nooit om de nek, en ruim ze op voor het slapen. Crêpepapier scheurt makkelijk en is daardoor veiliger dan stevig lint.","Zorg voor ruimte: schuif de salontafel opzij en dans niet op sokken op een gladde vloer.","Crêpepapier geeft kleur af als het nat wordt: laat je dreumes er niet op sabbelen."],"say":["Zwaai, zwaai! Omhoog!","Kun je het lint heel langzaam laten bewegen, als een slang?","Ik zie je lint rondjes draaien boven je hoofd.","Wat doe je goed je best om stil te staan als de muziek stopt!","Welke kleur lint wil jij vandaag?"],"words":["zwaaien","draaien","omhoog","omlaag","rondje","golf","stilstaan"],"learn":["grove-motoriek","creativiteit","concentratie"],"tips":["Knip de dichtgevouwen rol crêpepapier in plakken van 3 cm: zo heb je in één keer een hele bos lange stroken.","Stroken van een oud laken of T-shirt gaan langer mee dan crêpepapier en kunnen gewoon in de was."],"variations":["Koningsdag: maak oranje en rood-wit-blauwe linten en houd een optocht door de kamer.","Carnaval: verkleed je, pak je linten en loop met z’n allen een polonaise door het huis.","Weerdans: dans zachtjes als een briesje en wild als een storm. Wie bedenkt het volgende weer?","Kleurendans: maak een lint in elke kleur; roep een kleur en alleen dat lint mag dansen."],"themes":["koningsdag","carnaval"]},
  {"id":"ballontennis","title":"Ballontennis met bordjesrackets","emoji":"🎈","category":"muziek","summary":"Maak rackets van papieren bordjes en houd samen een ballon in de lucht: een rustig balspel dat binnen prima kan.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":15,"supervision":1,"materials":[{"id":"papieren-bordjes","note":"1 per racket, liefst stevige"},{"id":"ijsstokjes","note":"2 per racket, als handvat"},{"id":"ducttape","note":"om de stokjes stevig vast te plakken"},{"id":"ballonnen","note":"niet te hard opgeblazen (door jou)"}],"optional":[{"id":"stiften","note":"om een gezicht op het racket te tekenen"},{"id":"stickers"}],"steps":["Blaas een ballon op, niet te hard, en knoop hem goed dicht. Dat doe jij.","Plak twee ijsstokjes met ducttape tegen de onderkant van een papieren bordje: dat is het handvat.","Laat je kind het racket versieren met een gezichtje of stickers.","Tik de ballon met het racket omhoog. Lukt het om hem in de lucht te houden zonder dat hij de grond raakt?","Speel samen over en weer, of tel hoe vaak het lukt om hem achter elkaar te raken.","Laat na afloop de lucht uit de ballon of berg hem hoog op, en gooi een geknapte ballon meteen weg."],"ageTips":{"young":"Voor een tweejarige gaat een ballon fijn langzaam, maar een racket is nog lastig. Laat je kind eerst met de handen tikken, of houd het racket samen vast.","old":"Tel samen hoe vaak je de ballon hoog kunt houden en probeer je record te verbeteren. Of zet een stoel in het midden als net en speel een echte wedstrijd."},"safety":["Ballonnen alleen onder toezicht: gooi een kapotte ballon of een los stukje meteen weg, want dat is een groot verstikkingsgevaar. Laat een kind onder de 8 nooit zelf een ballon opblazen.","Ruim breekbare spullen en de salontafel opzij: wie naar de ballon kijkt, ziet niet waar hij loopt."],"say":["Tik! Omhoog!","Hoe lang kun je hem in de lucht houden?","Ik zie dat je goed naar de ballon blijft kijken.","Wat denk je: valt een ballon snel of langzaam?","Je bleef het proberen, en nu lukte het al vijf keer achter elkaar!"],"words":["omhoog","tikken","zweven","vallen","langzaam","hooghouden","racket"],"learn":["grove-motoriek","concentratie","samen","rekenen"],"tips":["Een ballon die niet te hard is opgeblazen, knapt minder snel en is fijner om mee te spelen.","Geen papieren bordjes? Een opgerolde krant of gewoon je hand werkt ook."],"variations":["Verjaardag: speel na het feest met de ballonnen van de versiering en houd ze allemaal tegelijk in de lucht.","Zonder racket: houd de ballon hoog met alleen je hoofd, je knie of je elleboog.","Muziekballon: houd de ballon hoog zolang de muziek speelt. Stopt de muziek, dan vang je hem."],"themes":[]},
  {"id":"hindernisbaan","title":"Hindernisbaan door de kamer","emoji":"🤸","category":"muziek","summary":"Bouw met kussens, stoelen en een deken een hindernisbaan door de kamer: kruipen, klimmen, balanceren en mikken in één avontuur.","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":20,"supervision":1,"materials":[{"id":"dekens","note":"kussens om overheen te klimmen en een deken als tunnel"},{"id":"stoelen","note":"2-3 stuks voor de tunnel"},{"id":"schilderstape","note":"voor een lijn om over te balanceren"},{"id":"wasmand","note":"om in te mikken"},{"id":"bal","note":"of een paar opgerolde sokken"}],"optional":[{"id":"knuffels","note":"om onderweg te redden"},{"id":"dozen","note":"een open doos als tunnel"},{"id":"muziek","note":"voor een swingende baan"}],"steps":["Schuif de salontafel opzij en bouw samen een route: een tunnel van een deken over twee stoelen, een berg van kussens en een tapelijn op de vloer.","Zet aan het eind een wasmand neer, met een bal of een paar opgerolde sokken ernaast.","Doe het eerst zelf voor: kruip door de tunnel, klim over de kussens, loop over de lijn en gooi de bal in de mand.","Laat je kind de baan afleggen. Moedig aan en benoem wat je ziet: door, over, onder, langs.","Verander de baan na een paar rondjes: de kussens verder uit elkaar, de lijn zigzag of de mand verder weg.","Ruim samen op: wie brengt de kussens terug naar de bank?"],"ageTips":{"young":"Voor een dreumes is kruipen door de tunnel en over één kussen al een avontuur. Houd de baan kort en laag, ga zelf aan de andere kant van de tunnel zitten en roep: kiekeboe!","old":"Laat je kleuter zelf de route bedenken en tekenen, en neem de tijd op met de stopwatch van je telefoon. Wie kan het snelst, of juist zo langzaam mogelijk?"},"safety":["Bouw op een zachte ondergrond en houd de baan laag: niet over tafels klimmen of van stoelen springen.","Speel op blote voeten of antislipsokken: op gewone sokken glijdt je kind snel uit.","Zet de stoelen voor de tunnel stevig neer, met de rugleuning tegen de bank of de muur, zodat ze niet kunnen omvallen."],"say":["Door de tunnel… kiekeboe!","Hoe kom je over de kussenberg? Klim je of kruip je?","Ik zie dat je je armen wijd houdt op de lijn. Zo blijf je in evenwicht!","Welke hindernis zullen we er nog bij bouwen?","Wat heb je goed doorgezet: de hele baan tot het eind!"],"words":["door","over","onder","langs","klimmen","kruipen","springen","evenwicht"],"learn":["grove-motoriek","taal","creativiteit"],"tips":["Een hindernisbaan is ideaal op een regendag of als je kind stuiterig is: na een paar rondjes is de ergste energie eruit.","Gebruik schilderstape voor de lijnen op de vloer: dat laat meestal geen lijmresten achter."],"variations":["Dierenbaan: kruip als een poes door de tunnel, spring als een kikker over de kussens en waggel als een pinguïn over de lijn.","Reddingsmissie: verstop knuffels langs de route en breng ze één voor één naar de veilige wasmand.","Sinterklaas: maak een dakenroute van kussens en laat je kind een cadeautje in de schoorsteen (de wasmand) gooien."],"themes":[]},
  {"id":"tapelijnen","title":"Balanceren op tapelijnen","emoji":"👣","category":"muziek","summary":"Plak rechte lijnen, zigzaglijnen en golven van schilderstape op de vloer en balanceer, spring en rijd er samen overheen.","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":20,"supervision":2,"materials":[{"id":"schilderstape","note":"een rol, liefst in een opvallende kleur"}],"optional":[{"id":"speelgoedautos","note":"om over de lijnen te laten rijden"},{"id":"knuffels","note":"om op je hoofd te balanceren"},{"id":"stiften","note":"om cijfers op de hinkelbaan te schrijven"},{"id":"muziek"}],"steps":["Plak met schilderstape een paar lijnen op de vloer: een rechte lijn, een zigzag, een golf en een grote cirkel.","Loop eerst zelf voor: voetje voor voetje over de rechte lijn, met je armen wijd als een koorddanser.","Laat je kind de lijnen volgen: gewoon lopen, op de tenen, zijwaarts, achteruit of als een dier.","Plak voor oudere kinderen een hinkelbaan met vakken en schrijf er met stift cijfers in.","Laat speelgoedautootjes over de lijnen rijden: de zigzag is een bergweg, de cirkel een rotonde.","Laat de tape een paar dagen liggen voor nieuwe spelletjes en trek hem daarna langzaam los."],"ageTips":{"young":"Een dreumes loopt nog niet netjes op een lijn: houd een handje vast en maak de lijn breder met twee stroken naast elkaar, of laat je kind ernaast kruipen met een autootje.","old":"Laat je kleuter van lijn naar lijn springen, hinkelen op één been of met een knuffel op het hoofd balanceren. Ook leuk: zelf een nieuw parcours bedenken en plakken."},"safety":["Balanceer op blote voeten of antislipsokken: op gewone sokken glijdt je kind op laminaat of tegels snel uit.","Trek losgeraakte stukjes tape meteen weg: een dreumes stopt ze zo in de mond.","Plak geen lijnen over een drempel of vlak bij de trap, en houd ze weg bij scherpe tafelhoeken."],"say":["Voetje, voetje, op de lijn!","Kun je ook achteruit over de lijn lopen?","Ik zie dat je je armen uitsteekt om niet te vallen.","Welke lijn vind je het moeilijkst: de rechte of de zigzag?","Wat blijf je goed proberen, ook als je er even afstapt!"],"words":["rechtdoor","zigzag","golf","rondje","evenwicht","tenen","springen","achteruit"],"learn":["grove-motoriek","concentratie","rekenen"],"tips":["Test de tape eerst op een onopvallend plekje: op de meeste vloeren laat schilderstape geen resten achter, op sommige vloerkleden wel.","Plak de lijnen in de gang: daar kom je toch langs, en de woonkamer blijft vrij."],"variations":["Letterpad: plak een grote letter, bijvoorbeeld de eerste letter van de naam van je kind, en loop hem samen na.","Muzieklijnen: zet muziek op en beweeg langs de lijnen, snel als de muziek snel is en langzaam als hij langzaam is.","Autostad: plak een hele stad met wegen, een rotonde en een parkeergarage onder de tafel."],"themes":[]},
  {"id":"fruitgezichtjes","title":"Fruitgezichtjes en fruitdieren","emoji":"🍓","category":"eetbaar","summary":"Leg samen grappige gezichten en dieren van stukjes fruit en groente op een bord, en eet je kunstwerk daarna lekker op.","ageMin":1,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":15,"supervision":1,"materials":[{"id":"fruit","note":"bijv. banaan, appel, mandarijn, kiwi en bessen"},{"id":"groente","note":"bijv. komkommer, paprika en cherrytomaatjes"},{"id":"bord","note":"een groot bord als ‘gezicht’"},{"id":"mes","note":"voor jou, om alles in stukjes te snijden"}],"optional":[{"id":"brood","note":"een cracker of rijstwafel als ondergrond"},{"id":"beleg","note":"roomkaas als lijm op de cracker"},{"id":"kaas","note":"geraspte kaas als haar"},{"id":"muffinvorm","note":"om de stukjes per soort in te doen"}],"steps":["Snijd fruit en groente in kleine stukjes en zet ze per soort in kommetjes klaar. Druiven en cherrytomaatjes snijd je in de lengte in vieren.","Leg een groot bord of een cracker voor je kind neer: dat wordt het gezicht.","Bedenk samen wat de ogen, de neus en de mond worden. Laat je kind zelf kiezen en leggen.","Maak er haar, oren of een hoed bij, bijvoorbeeld van reepjes paprika of een plakje appel.","Bewonder het gezicht, geef het een naam en… smakelijk eten!"],"ageTips":{"young":"Snijd voor een dreumes alles in kleine, zachte stukjes en leg zelf alvast een rond gezicht van plakjes komkommer neer. Laat je kind er ogen op leggen en benoem: oog, neus, mond… hap!","old":"Laat je kleuter een heel dier of een fruittuin leggen, met een verhaal erbij. Of maak een patroon: banaan, aardbei, banaan… wat komt er hierna?"},"safety":["Snijd druiven en cherrytomaatjes in de lengte in vieren, en geef dreumesen geen harde stukjes rauwe appel of wortel: rasp ze of snijd ze in dunne plakjes.","Laat je kind rechtop aan tafel zitten tijdens het eten en niet rondlopen met eten in de mond: zo verslikt het zich minder snel.","Allergie? Let op met kiwi en aardbei bij gevoelige kinderen, en met roomkaas (melk) of crackers (gluten)."],"say":["Wat wordt dit? Een oog of een neus?","Ik zie twee ogen van aardbei en een mond van banaan. Wat een vrolijk gezicht!","Ruik eens aan de mandarijn. Ruikt hij zoet of fris?","Hap! Daar gaat de neus!","Wat een goed idee om paprika als haar te gebruiken."],"words":["oog","neus","mond","rond","zoet","zuur","sappig","haar"],"learn":["creativiteit","fijne-motoriek","taal","zintuigen"],"tips":["Gebruik het fruit dat al in huis is: als ontbijt of tussendoortje eten kinderen zo vaak meer fruit en groente.","Zet de stukjes in een muffinvorm, elk vakje een soort: overzichtelijk en makkelijk pakken."],"variations":["Fruitrups: leg plakjes banaan en kiwi om en om op een rij, met een aardbei als kop.","Koningsdag: maak een oranje gezicht van mandarijn, wortel en meloen.","Halloween: maak bananenspookjes met oogjes van bessen, of een pompoengezicht van partjes mandarijn.","Regenboogbord: leg het fruit op kleur in een boog: rood, oranje, geel, groen en blauw."],"themes":[]},
  {"id":"koekjes-versieren","title":"Koekjes versieren","emoji":"🍪","category":"eetbaar","summary":"Smeer gekleurd glazuur op koekjes en strooi er spikkels over: smeren, strooien en snoepen in één.","ageMin":2,"ageMax":5,"mess":3,"wet":false,"dirty":true,"prepMinutes":10,"durationMinutes":20,"supervision":2,"materials":[{"id":"koekjes","note":"biscuitjes of zelfgebakken koekjes, ±15 stuks"},{"id":"poedersuiker","note":"±100 g"},{"id":"water","note":"±1 el, plus een paar druppels"},{"id":"kleurstof","note":"2-3 kleuren"},{"id":"hagelslag","note":"of spikkels"},{"id":"kom","note":"een kommetje per kleur glazuur"},{"id":"lepel","note":"theelepels om te roeren en te smeren"}],"optional":[{"id":"dienblad","note":"om op te werken: gevallen spikkels schud je zo terug"},{"id":"zip-zakjes","note":"als spuitzakje, met een piepklein puntje eraf"},{"id":"bakpapier","note":"om de koekjes op te laten drogen"},{"id":"oud-shirt"}],"steps":["Roer 100 g poedersuiker met 1 el water in een kom. Voeg druppel voor druppel meer water toe tot het glazuur dik is als tandpasta.","Verdeel het glazuur over een paar kommetjes en laat je kind in elk kommetje een druppel kleurstof roeren.","Zet de spikkels en hagelslag in schaaltjes klaar en leg de koekjes op een dienblad.","Laat je kind met de bolle kant van een theelepel glazuur op een koekje smeren en er meteen spikkels over strooien.","Leg de versierde koekjes op bakpapier en laat ze ongeveer een uur drogen. Eentje meteen opeten mag natuurlijk ook.","Bewaar de droge koekjes in een trommel; ze blijven een paar dagen lekker."],"ageTips":{"young":"Een tweejarige strooit vooral, en dat mag. Smeer zelf alvast wat glazuur op een paar koekjes en geef een klein bakje spikkels: een deel gaat in de mond, en dat is prima.","old":"Laat je kleuter vooraf een ontwerp bedenken: een gezichtje, een patroon of een letter. Met een diepvrieszakje met een piepklein puntje eraf spuit je echte lijntjes."},"safety":["Allergie: koekjes bevatten vaak gluten, melk en ei, en spikkels soms sporen van noten. Lees de verpakking als er een kind met een allergie meedoet.","Kleurstof vlekt op kleding en tafel: trek een oud shirt aan en werk op een dienblad of afwasbaar tafelkleed.","Gebruik voor kinderen onder de 3 gewone hagelslag en geen harde suikerparels: die zijn klein en hard."],"say":["Strooi, strooi! Kijk eens hoeveel spikkels!","Hoe voelt het glazuur: dik of dun? Plakkerig?","Ik zie dat je eerst roze hebt gesmeerd en daarna gele spikkels. Wat een vrolijk koekje.","Voor wie maak je dit koekje?","Wat werk je geduldig: helemaal tot aan de randjes."],"words":["smeren","strooien","zoet","plakkerig","spikkels","glazuur","dik","dun"],"learn":["fijne-motoriek","creativiteit","zintuigen"],"tips":["Maak het glazuur liever te dik dan te dun: dun glazuur loopt van het koekje af. Een extra tl poedersuiker maakt het weer dikker.","Werk op een dienblad met een rand: spikkels die ernaast vallen, schud je zo terug in het bakje."],"variations":["Sinterklaas: versier speculaasjes of letterkoekjes met de eerste letter van ieders naam.","Kerst: smeer groen glazuur op stervormige koekjes en strooi er gekleurde spikkels op als kerstballen.","Verjaardag: versier samen traktatiekoekjes met de leeftijd van de jarige erop.","Gezichtjes: maak elkaar na op een koekje. Wie is wie?"],"themes":["sinterklaas","kerst","verjaardag"]},
  {"id":"kruidnoten-bakken","title":"Kruidnoten bakken","emoji":"🥣","category":"eetbaar","summary":"Kneed samen een geurig deeg met speculaaskruiden, rol knikkergrote balletjes en bak je eigen kruidnoten voor Sinterklaas.","ageMin":2,"ageMax":5,"mess":3,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":30,"supervision":1,"materials":[{"id":"zelfrijzend-bakmeel","note":"125 g"},{"id":"basterdsuiker","note":"60 g"},{"id":"boter","note":"50 g, zacht (op kamertemperatuur)"},{"id":"melk","note":"2-3 el"},{"id":"kruiden","note":"1-2 tl speculaaskruiden"},{"id":"zout","note":"een snufje"},{"id":"kom","note":"een grote mengkom"},{"id":"bakpapier","note":"voor op de bakplaat"},{"id":"oven","note":"180 °C; de oven is voor jou"}],"optional":[{"id":"oud-shirt","note":"of een schort"},{"id":"zip-zakjes","note":"om kruidnoten in uit te delen"}],"steps":["Zet de oven aan op 180 °C en leg bakpapier op de bakplaat. Dat doe jij.","Weeg samen af: 125 g zelfrijzend bakmeel, 60 g basterdsuiker, 1-2 tl speculaaskruiden en een snufje zout. Laat je kind alles in de kom schudden.","Doe er 50 g zachte boter en 2 el melk bij en kneed met je handen tot een soepel deeg. Te droog? Nog een scheutje melk erbij.","Rol samen knikkergrote balletjes en leg ze met wat ruimte ertussen op de bakplaat. Tel maar mee!","Schuif de bakplaat in de oven (dat doe jij) en bak de kruidnoten ±15 minuten, tot ze goudbruin zijn.","Laat ze afkoelen op de bakplaat: dan worden ze knapperig. Bewaar ze in een trommel of pot."],"ageTips":{"young":"Weeg voor een tweejarige alles vooraf af in bakjes: dan hoeft je peuter alleen te gooien, kneden en rollen. Halveer het recept voor een kleine, overzichtelijke portie; scheve balletjes zijn net zo lekker.","old":"Laat je kleuter zelf afwegen en de cijfers op de weegschaal aflezen. Leg de balletjes in rijtjes van tien en tel samen hoeveel kruidnoten het worden."},"safety":["De oven en de hete bakplaat zijn voor jou: laat je kind op afstand blijven als de ovendeur opengaat.","Niet van het rauwe deeg snoepen: rauwe bloem kan bacteriën bevatten.","Kruidnoten zijn klein, rond en hard: breek ze voor jonge kinderen doormidden en laat ze aan tafel zittend eten.","Allergie: dit recept bevat gluten en melk. Gebruik bij een melkallergie plantaardige boter en plantaardige melk."],"say":["Rollen, rollen… een balletje!","Ruik eens aan de speculaaskruiden. Waar doet dat je aan denken?","Hoe voelt het deeg: plakkerig, droog of zacht?","Ik zie een hele rij balletjes. Zullen we tellen hoeveel het er zijn?","Wat heb je goed geholpen: jij hebt alles zelf in de kom gedaan."],"words":["afwegen","kneden","rollen","balletje","ruiken","knapperig","warm","afkoelen"],"learn":["fijne-motoriek","rekenen","zintuigen","samen"],"tips":["Weeg alles af voordat je je kind erbij roept: dan blijft het leukste werk over en hoeft er niet lang gewacht te worden.","Plakt het deeg aan de handjes? Een beetje bakmeel op de handen helpt.","In een goed gesloten trommel of pot blijven kruidnoten een paar weken lekker."],"variations":["Traktatie: doe een handje kruidnoten in een zakje met een strik en geef ze aan opa, oma of de buren.","Chocoladekruidnoten: doop de afgekoelde kruidnoten half in gesmolten chocolade. Het smelten doe jij.","Vormpjes: rol het deeg uit en steek er kleine sterretjes of letters uit. Bak ze iets korter, ±10 minuten."],"themes":["sinterklaas"]},
  {"id":"boterhamkunst","title":"Boterhamkunst met vormpjes","emoji":"🍞","category":"eetbaar","summary":"Steek vormpjes uit een boterham, gebruik beleg als lijm en versier je brood met gezichtjes van fruit, groente en hagelslag.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":15,"supervision":2,"materials":[{"id":"brood","note":"een paar boterhammen of wraps"},{"id":"uitsteekvormpjes","note":"liefst grote, simpele vormen (hart, ster, rondje)"},{"id":"beleg","note":"roomkaas, smeerkaas of jam als ‘lijm’"},{"id":"fruit","note":"in kleine stukjes, bijv. banaan en bessen"},{"id":"groente","note":"bijv. reepjes komkommer, paprika en wortel"},{"id":"hagelslag","note":"voor haar of spikkels"},{"id":"mes","note":"voor jou om te snijden; je kind smeert met een botermes"}],"optional":[{"id":"deegroller","note":"om het brood eerst plat te rollen"},{"id":"kaas","note":"geraspte kaas als haar"}],"steps":["Snijd groente en fruit in kleine stukjes en zet alles in kommetjes klaar: dat is je ‘verfdoos’.","Laat je kind een vormpje kiezen en uit een boterham steken: stevig drukken en een beetje heen en weer wiebelen.","Smeer samen een laagje roomkaas of jam op de vorm; dat is de lijm.","Versier de boterham met ogen van bessen, een mond van paprika en haar van hagelslag of kaas.","Bekijk het kunstwerk samen, bedenk een naam en… opeten!"],"ageTips":{"young":"Voor een tweejarige is uitsteken nog lastig: druk het vormpje samen in het brood, of steek zelf alvast een paar vormen uit. Smeren gaat makkelijker met de bolle kant van een lepel.","old":"Laat je kleuter een heel tafereel op een bord maken: een huis van brood, een zon van kaas en bloemen van komkommer. Of leg samen de eerste letter van de eigen naam met reepjes groente."},"safety":["Allergie: brood bevat gluten, roomkaas melk en sommige smeersels noten of pinda. Kies beleg dat past bij alle kinderen aan tafel.","Snijd druiven en cherrytomaatjes in de lengte in vieren, en harde groente zoals wortel voor jonge kinderen in dunne reepjes of geraspt.","Metalen uitsteekvormpjes hebben één scherpe kant: laat je kind op de omgerolde bovenrand drukken."],"say":["Druk, druk… en eruit! Een hartje!","Wat wordt dit, denk je? Een poes of een monster?","Ik zie dat je de bessen heel precies als oogjes hebt neergelegd.","Hoe smaakt de komkommer: fris of zoet?","Smeer, smeer, tot aan de randjes!"],"words":["uitsteken","smeren","hartje","ster","rondje","bovenop","plakkerig"],"learn":["fijne-motoriek","creativiteit","rekenen","taal"],"tips":["Rol de boterham eerst plat met een deegroller: dan gaat uitsteken veel makkelijker en blijft de vorm heel.","Gooi de randjes niet weg: maak er tosti’s, wentelteefjes of broodkruim van."],"variations":["Sinterklaas: snijd of steek een letter uit en strooi er hagelslag over: een chocoladeletter van brood.","Kerst: steek boompjes of sterren uit en versier ze met reepjes paprika als slingers.","Verjaardag: stapel drie rondjes brood met beleg ertussen tot een boterhamtaart en zet er een rietje als kaarsje in."],"themes":[]},
  {"id":"fruitijsjes","title":"Fruitijsjes maken","emoji":"🍦","category":"eetbaar","summary":"Prak fruit met yoghurt, schep het in vormpjes en vries het in: zelfgemaakte ijsjes waarbij je kind proeft, ruikt en kleuren ontdekt.","ageMin":1,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":10,"durationMinutes":15,"supervision":1,"materials":[{"id":"fruit","note":"±250 g zacht fruit, bijv. aardbeien, banaan, mango of bessen"},{"id":"yoghurt","note":"±250 g, bijv. Griekse yoghurt"},{"id":"ijsvormpjes","note":"of bekertjes met een ijsstokje erin"},{"id":"vork","note":"om te prakken"},{"id":"kom","note":"om in te prakken en te roeren"},{"id":"vriezer"}],"optional":[{"id":"blender","note":"voor een gladder ijsje"},{"id":"ijsblokjesvorm","note":"voor mini-ijsjes voor een dreumes"},{"id":"huishoudfolie","note":"over de bekertjes, zodat het stokje rechtop blijft"},{"id":"ijsstokjes","note":"als je met bekertjes werkt"}],"steps":["Was het fruit en snijd het in stukjes. Laat je kind de zachte stukjes, zoals banaan en aardbei, met een vork fijnprakken in een kom.","Roer er ongeveer evenveel yoghurt door. Wil je het heel glad, pureer het dan met de blender; dat doe jij.","Proef samen een likje: zoet genoeg? Een extra stukje rijpe banaan maakt het zoeter, zonder suiker.","Schep het mengsel in de ijsvormpjes en zet de stokjes erin. Morsen mag, aflikken ook!","Zet de vormpjes minstens 4 uur in de vriezer, of een nacht.","Houd een vormpje even onder de warme kraan: dan glijdt het ijsje er zo uit."],"ageTips":{"young":"Voor een dreumes is een ijsje op een stokje vaak te groot en te koud. Vries het mengsel in een ijsblokjesvorm in en geef één blokje in een kommetje. Prakken met de handen mag ook!","old":"Laat je kleuter een eigen recept bedenken en tekenen: welk fruit, hoeveel lepels yoghurt? Na het invriezen proef je samen of het recept geslaagd is."},"safety":["Allergie: yoghurt bevat melk. Gebruik bij een melkallergie alleen fruit of een plantaardige yoghurt.","Prak of pureer alles goed voor een dreumes: hele bessen of harde stukjes in het ijs kunnen in de keel schieten.","Een ijsje dat net uit de vriezer komt, kan aan lippen of tong vastvriezen: laat het eerst een minuutje liggen."],"say":["Prak, prak! Kijk, de banaan wordt zacht.","Welke kleur krijgt het als we de aardbeien erbij doen?","Ruik eens: ruikt het naar aardbei of naar banaan?","Wat denk je dat er in de vriezer gebeurt?","Brr, koud! Hoe voelt het op je tong?"],"words":["prakken","zacht","koud","bevroren","smelten","zoet","zuur","roze"],"learn":["zintuigen","fijne-motoriek","taal","ontdekken"],"tips":["Overrijp fruit of een zak diepvriesfruit is goedkoop en perfect voor ijsjes.","Geen ijsvormpjes? Gebruik plastic bekertjes, span er huishoudfolie over en prik het stokje erdoor: dan blijft het rechtop staan.","Laat je kind het ijsje aan tafel eten met een slabbetje of oud shirt aan: smeltend fruitijs druppelt en vlekt."],"variations":["Streepjesijs: vul de vormpjes laag voor laag met verschillende kleuren en vries elke laag een uurtje aan.","Sapijsjes: vries puur appelsap of geperst sinaasappelsap in, lekker verkoelend op een warme dag.","Koningsdag: maak oranje ijsjes van mango, sinaasappel en een beetje wortelsap.","Monsterijsjes: pureer banaan met een handje verse spinazie: knalgroen, en je proeft het bijna niet."],"themes":["zomer"]},
  {"id":"minipizzas","title":"Mini-pizza’s beleggen","emoji":"🍕","category":"eetbaar","summary":"Smeer saus op een wrap of pitabroodje, strooi kaas en leg een gezichtje van groente: zelfgemaakte pizza’s die je kind trots opeet.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":10,"durationMinutes":20,"supervision":2,"materials":[{"id":"brood","note":"kleine wraps, pitabroodjes of halve bolletjes"},{"id":"tomatensaus","note":"±1 el per pizza"},{"id":"kaas","note":"geraspt"},{"id":"groente","note":"bijv. paprika, champignons, maïs en cherrytomaatjes"},{"id":"bakpapier","note":"voor op de bakplaat"},{"id":"oven","note":"200 °C; de oven is voor jou"},{"id":"lepel","note":"om de saus te smeren"}],"optional":[{"id":"uitsteekvormpjes","note":"om sterretjes uit plakjes paprika of kaas te steken"},{"id":"oud-shirt","note":"tomatensaus vlekt"}],"steps":["Verwarm de oven voor op 200 °C en leg bakpapier op de bakplaat. Dat doe jij.","Snijd de groente in kleine stukjes en zet alles met de kaas in kommetjes klaar. Cherrytomaatjes snijd je in vieren.","Leg voor je kind een wrap of pitabroodje neer en laat het met de bolle kant van een lepel tomatensaus uitsmeren.","Laat je kind de pizza beleggen: kaas strooien en een gezichtje, bloem of patroon leggen met de groente.","Schuif de pizza’s in de oven en bak ze 8-10 minuten, tot de kaas gesmolten is. Kijk samen door het ovenraampje.","Laat de pizza’s een paar minuten afkoelen voordat je ze in stukken snijdt: gesmolten kaas is heet."],"ageTips":{"young":"Een tweejarige strooit vooral kaas, en heel veel. Geef kleine bakjes met grote, zachte stukjes groente en laat het patroon los: elke pizza is goed.","old":"Laat je kleuter een pizza bedenken voor iemand anders in huis: wat vindt die lekker? Of verdeel de pizza in vier vakken met elk een ander beleg en tel de stukjes."},"safety":["De oven, de hete bakplaat en gesmolten kaas zijn heet: haal de pizza’s er zelf uit en laat ze eerst afkoelen.","Allergie: wraps en pitabroodjes bevatten gluten, kaas bevat melk. Er zijn glutenvrije wraps en kaas zonder melk.","Snijd cherrytomaatjes in de lengte in vieren: heel zijn ze een verstikkingsgevaar."],"say":["Smeer, smeer! Helemaal tot de rand.","Wat leg jij op je pizza? Wat worden de ogen?","Ruik je dat? De kaas smelt in de oven.","Kijk door het raampje: wat gebeurt er met de kaas?","Je hebt je pizza helemaal zelf belegd. Hoe gaat hij heten?"],"words":["smeren","strooien","smelten","heet","rond","kaas","plakjes"],"learn":["fijne-motoriek","creativiteit","zintuigen"],"tips":["Gebruik restjes uit de koelkast, zoals een halve paprika of een stukje kaas: zo is het meteen een avondmaaltijd.","Trek je kind een oud shirt aan: tomatensaus vlekt, en kleine handen smeren graag met hun vingers."],"variations":["Halloween: maak een mummiepizza met reepjes kaas als verband en twee plakjes paprika als ogen.","Koningsdag: beleg de pizza met alles wat oranje is, zoals oranje paprika, geraspte wortel en cheddar.","Fruitpizza: smeer roomkaas op een cracker en beleg die met fruit; die hoeft niet eens de oven in."],"themes":[]},
  {"id":"kroon-maken","title":"Een kroon voor koning of koningin","emoji":"👑","category":"fantasie","summary":"Knip een kartonnen strook met punten, versier hem met stickers en glimmende foliejuwelen en zet hem op maat: klaar voor de kroning!","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":20,"supervision":1,"materials":[{"id":"karton","note":"een strook van ±10 cm hoog en ±60 cm lang, bijv. twee stroken van een cornflakesdoos"},{"id":"aluminiumfolie","note":"voor glimmende juwelen"},{"id":"stickers"},{"id":"nietmachine","note":"om de kroon op maat te maken (dat doe jij)"},{"id":"plakband"}],"optional":[{"id":"stiften","note":"of waskrijt, om te kleuren"},{"id":"gekleurd-papier","note":"geel, om de kroon mee te beplakken"},{"id":"lijmstift"},{"id":"kinderschaar","note":"voor kleuters die zelf de punten knippen"}],"steps":["Meet met een strook papier om het hoofd van je kind hoe lang de kroon moet worden en tel er 3 cm bij op.","Knip een strook karton van ±10 cm hoog op die lengte. Plak zo nodig twee stroken aan elkaar.","Teken een zigzaglijn over de bovenkant en knip de punten uit. Dat doe jij; een kleuter knipt zelf langs de lijn.","Laat je kind de kroon versieren met stickers en stift. Voor een gouden kroon plak je er eerst geel papier op.","Maak juwelen: scheur stukjes folie af, frommel ze tot propjes, druk ze plat en plak ze vast met een rolletje plakband.","Zet de kroon om het hoofd op maat met twee nietjes en plak de nietjes aan de binnenkant af.","Houd een echte kroning: laat je kind op een ‘troon’ zitten en zet de kroon plechtig op."],"ageTips":{"young":"Voor een tweejarige knip jij de kroon vooraf uit. Stickers plakken en folie frommelen is voor je peuter het hele feest: hoe meer, hoe beter.","old":"Laat je kleuter zelf punten tekenen en knippen, en een patroon maken: rood, blauw, rood, blauw. Hoeveel punten heeft jouw kroon?"},"safety":["Zet de nietjes met de gladde kant naar binnen en plak er een stukje plakband over, zodat er niets in het voorhoofd prikt.","Foliepropjes en stickers zijn klein: plak ze bij een tweejarige stevig vast en ruim losse stukjes meteen op. Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3."],"say":["Welke kleur juwelen moeten er op jouw kroon?","Kijk, de folie glimt als je hem beweegt!","Je drukt elke sticker heel stevig vast. Wat werk je precies.","Wat zou jij doen als je een dag koning of koningin was?","Kroon op! Hoera!"],"words":["kroon","punt","glimmen","juweel","koning","koningin","hoog"],"learn":["fijne-motoriek","creativiteit","taal"],"tips":["Plak de juwelen met plakband in plaats van lijm: dan kan de kroon meteen op en hoef je niets af te wassen.","Knip een paar kronen tegelijk uit en bewaar ze plat: handig voor een verjaardag of een regenachtige middag."],"variations":["Koningsdag: een oranje kroon met een rood-wit-blauw vlaggetje op de hoogste punt.","Verjaardag: zet het nieuwe leeftijdsgetal groot op de voorkant en plak op elke punt een papieren kaarsje.","Carnaval: maak er een prinsenkroon van met veertjes, of een bloemenkrans van gekleurde papieren bloemen.","Herfst: plak bladeren op een kartonnen strook voor een kroon van de koning van het bos."],"themes":["koningsdag","verjaardag","carnaval"]},
  {"id":"sokpoppen","title":"Sokpoppen maken","emoji":"🧦","category":"fantasie","summary":"Tover een oude sok om tot een praatpop met ogen, wollen haar en een vilten tong, en speel daarna samen een voorstelling.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":5,"durationMinutes":25,"supervision":1,"materials":[{"id":"sokken","note":"een effen sok per pop"},{"id":"knutsellijm","note":"witte hobbylijm, of textiellijm als je die hebt"},{"id":"vilt","note":"rood of roze voor de tong, wit voor de ogen"},{"id":"touw","note":"wol in een vrolijke kleur, voor het haar"},{"id":"stiften","note":"voor pupillen en wangetjes"}],"optional":[{"id":"karton","note":"om in de sok te schuiven tijdens het plakken"},{"id":"wiebeloogjes","note":"alleen vanaf 3 jaar"},{"id":"pompons","note":"als neus, alleen vanaf 3 jaar"},{"id":"kinderschaar","note":"voor kleuters die zelf vilt knippen"}],"steps":["Doe de sok om je hand: vingers in de teen, duim in de hiel. Laat zien hoe de mond open en dicht gaat.","Schuif een stuk karton in de sok, zodat de lijm niet doorlekt naar de andere kant.","Knip een tong van rood vilt (dat doe jij) en laat je kind die met knutsellijm in de mond plakken.","Plak ogen van wit vilt boven op de kop en teken er samen pupillen op.","Knip wol in stukjes van ±10 cm en laat je kind het haar bovenop plakken.","Laat de pop een paar uur drogen, liefst een nacht, voordat hij om een hand mag.","Speel een voorstelling: de rugleuning van de bank is het podium. Wat heeft de sok te vertellen?"],"ageTips":{"young":"Voor een tweejarige teken jij de ogen met stift en houd je het bij een tong en wat haar. Laat de pop meteen praten: een pratende sok is voor je peuter al magisch.","old":"Laat je kleuter zelf vilt knippen, een naam en een stemmetje bedenken, en met twee poppen een gesprekje spelen: wie is er boos, en hoe maken ze het weer goed?"},"safety":["Wiebeloogjes, pompons en knopen zijn klein: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Teken bij een tweejarige de ogen of gebruik grote rondjes vilt.","Trek na het drogen even aan ogen, neus en haar: zit iets los, plak het opnieuw voordat de pop in een peutermondje belandt."],"say":["Hallo! Ik ben Sok. Hoe heet jij?","Hap! Hap!","Wat zou jouw pop het liefst eten?","Je hebt het haar plukje voor plukje vastgeplakt. Wat werk je geduldig.","Is je pop vandaag blij of boos? Hoe klinkt dat?"],"words":["sok","mond","open","dicht","haar","tong","praten","fluisteren"],"learn":["creativiteit","taal","fijne-motoriek","samen"],"tips":["Haast? Teken ogen en wangetjes met stift en speel meteen; plakken kan morgen.","Maak ook een pop voor jezelf: twee poppen die met elkaar praten, maken het spel meteen echt.","Zet de sokpop in bij lastige momenten: een sok die meehelpt met tandenpoetsen of opruimen, werkt vaak wonderen."],"variations":["Dierensok: een slang met een lange tong, een draak met vilten stekels op de rug of een hond met flaporen.","Familie: maak een pop voor elk gezinslid, met dezelfde haarkleur als het echte gezinslid.","Papieren zakje: geen losse sok? Een boterhamzakje met een getekend gezicht is ook een handpop.","Monsterfeest: drie ogen, wild haar en een tong met stippen."],"themes":[]},
  {"id":"poppenkast","title":"Poppenkast van een grote doos","emoji":"🎭","category":"fantasie","summary":"Een grote doos met een raam en een theedoek als gordijn wordt een echt theater, waar knuffels en sokpoppen hun eigen voorstelling geven.","ageMin":3,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":15,"durationMinutes":30,"supervision":2,"materials":[{"id":"dozen","note":"een grote doos waar je kind achter kan zitten, bijv. een verhuisdoos"},{"id":"mes","note":"of een hobbymes, om het raam uit te snijden (dat doe jij)"},{"id":"handdoek","note":"twee theedoeken als gordijn"},{"id":"ducttape","note":"om het gordijn en losse flappen vast te zetten"},{"id":"stiften","note":"om de doos te versieren"}],"optional":[{"id":"gekleurd-papier","note":"voor sterren, een dak of de naam van het theater"},{"id":"lijmstift"},{"id":"knuffels","note":"als spelers"},{"id":"sokken","note":"voor sokpoppen"}],"steps":["Zet de doos rechtop en teken een groot raam van ±40 bij 30 cm, op ooghoogte van je zittende kind.","Snijd het raam uit en haal ook de achterkant weg, zodat je kind erachter kan zitten. Dat doe jij, terwijl je kind ergens anders speelt.","Plak twee theedoeken met ducttape aan de binnenkant boven het raam: een gordijn dat open en dicht kan.","Laat je kind de voorkant versieren met stiften en gekleurd papier: sterren, een dak, de naam van het theater.","Kies samen de spelers, zoals knuffels, sokpoppen of poppetjes, en bedenk wie er vandaag optreedt.","Geef om de beurt een voorstelling: de een speelt achter de kast, de ander is publiek en klapt na afloop."],"ageTips":{"young":"Een driejarige speelt vooral kiekeboe met het gordijn en laat een knuffel zwaaien. Speel zelf eerst iets kleins voor, zoals de beer die zijn bal kwijt is. Wie helpt zoeken?","old":"Laat je kleuter een verhaal bedenken met een begin, een probleem en een einde, toegangskaartjes tekenen en een bordje maken: ‘Vandaag voorstelling!’"},"safety":["Snijd het raam als je kind niet naast je staat, snijd van je af en berg het mes meteen op.","Een grote doos valt makkelijk om: zet hem tegen de muur of de bank, of leg een paar zware boeken onderin."],"say":["Gordijn open… daar komt de beer!","Wie komt er vandaag op bezoek in de poppenkast?","Wat gebeurt er als de krokodil de beer tegenkomt?","Je hebt het verhaal helemaal tot het einde gespeeld. Wat een doorzetter!","Klappen! Bravo!"],"words":["gordijn","open","dicht","voorstelling","publiek","klappen","achter","voor"],"learn":["creativiteit","taal","samen"],"tips":["Geen grote doos? Hang een laken over de rugleuning van de bank of over een omgedraaide tafel: je kind speelt erachter.","Laat de poppenkast een paar dagen staan: kinderen spelen hun voorstelling graag vaker, steeds een beetje anders."],"variations":["Sinterklaas: speel met knuffels de aankomst van de boot, of het paard dat over de daken loopt.","Dierengeluiden: alleen dieren uit de speelgoedkist, en het publiek raadt welk dier er piept, blaft of brult.","Sprookjes: speel Roodkapje of de drie biggetjes na met wat er in huis is.","Minitheater: plak gezichtjes van papier op wc-rolletjes en speel in een schoenendoos op tafel."],"themes":[]},
  {"id":"schaduwtheater","title":"Schaduwtheater met een zaklamp","emoji":"🔦","category":"fantasie","summary":"Knip figuren uit karton, zet ze op een stokje en laat ze in het licht van de zaklamp als grote schaduwen over de muur dansen.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":25,"supervision":1,"materials":[{"id":"karton","note":"dun karton, bijv. van een cornflakesdoos"},{"id":"ijsstokjes","note":"of rietjes, één per figuur"},{"id":"plakband"},{"id":"potlood"},{"id":"zaklamp","note":"of het lampje van je telefoon"}],"optional":[{"id":"dekens","note":"een wit laken, als je geen lichte muur hebt"},{"id":"wasknijpers","note":"om het laken op te hangen"},{"id":"kinderschaar","note":"voor kleuters die zelf grote vormen knippen"},{"id":"vloeipapier","note":"voor gekleurde raampjes in de figuren"}],"steps":["Teken samen een paar eenvoudige figuren van ±15 cm op karton: een kat, een huis, een maan, een spookje.","Knip de figuren uit (dat doe jij; een kleuter knipt grote vormen zelf) en plak elk figuur met plakband op een ijsstokje.","Maak de kamer donker en kies een lichte, lege muur, of hang met wasknijpers een wit laken over een wasrek.","Zet de zaklamp op een stapel boeken of op tafel, met het licht op de muur gericht.","Houd de figuren tussen de lamp en de muur. Dicht bij de lamp wordt de schaduw groot, dicht bij de muur klein en scherp.","Vertel samen een verhaal en laat je kind de figuren bewegen, praten en verstoppen."],"ageTips":{"young":"Een driejarige vindt het donker soms spannend: laat een klein lampje aan en begin met handschaduwen en een knuffel. Jij vertelt, je peuter beweegt de figuren.","old":"Laat je kleuter zelf figuren tekenen en knippen, en een verhaal met een begin, een probleem en een einde bedenken. Maak er kaartjes bij voor het publiek."},"safety":["Schijn niet met de zaklamp of het telefoonlampje recht in elkaars ogen: zet de lamp vast neer in plaats van ermee te zwaaien.","Ruim speelgoed en snoeren van de vloer voordat je de kamer donker maakt, zodat niemand struikelt."],"say":["Kijk, de kat wordt groter en groter!","Wat gebeurt er als je de maan dichter bij de lamp houdt?","Boe! Een spookje!","Je houdt het stokje heel stil, daardoor is de schaduw mooi scherp.","Waar is de schaduw gebleven als de lamp uit is?"],"words":["schaduw","licht","donker","groot","klein","dichtbij","ver weg","scherp"],"learn":["ontdekken","creativiteit","taal","fijne-motoriek"],"tips":["Speel aan het eind van de middag in de herfst of winter: dan is het vroeg donker en hoef je niets voor de ramen te hangen.","Bewaar de figuren in een envelop: zo heb je een kant-en-klaar theater voor de volgende keer."],"variations":["Halloween: spookjes, vleermuizen en een maan met een gezicht.","Winter: een sneeuwpop en een ster, en sneeuwvlokken die langzaam naar beneden dwarrelen.","Handschaduwen: maak met je handen een konijn, een hond of een vogel die wegvliegt.","Kleur: knip een raampje in een figuur en plak er vloeipapier over: een gekleurde schaduw!"],"themes":["halloween","winter"]},
  {"id":"dierenmaskers","title":"Dierenmaskers van papieren bordjes","emoji":"🦁","category":"fantasie","summary":"Verf een papieren bordje, plak er oren en een snuit op en houd het masker aan een stokje voor je gezicht: brul als een leeuw!","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":5,"durationMinutes":25,"supervision":2,"materials":[{"id":"papieren-bordjes","note":"één per masker"},{"id":"potlood"},{"id":"plakkaatverf","note":"of waskrijt en stiften als het minder vies mag"},{"id":"penselen"},{"id":"gekleurd-papier","note":"voor oren, snuit en manen"},{"id":"lijmstift"},{"id":"ijsstokjes","note":"als handvat"},{"id":"ducttape","note":"of stevig plakband, om het stokje vast te zetten"}],"optional":[{"id":"pijpenragers","note":"als snorharen"},{"id":"touw","note":"wol, voor manen of haar"},{"id":"veren","note":"voor een vogel- of uilenmasker"},{"id":"oud-shirt"},{"id":"oud-laken","note":"als knoeimat"}],"steps":["Houd het bordje voor het gezicht van je kind en zet met potlood twee stipjes waar de ogen komen.","Knip de ooggaten uit, ruim 3 cm groot. Dat doe jij: prik eerst een gaatje met de punt van de schaar.","Kies samen een dier en verf het bordje: geel voor een leeuw, roze voor een varken, grijs voor een muis.","Knip oren en een snuit uit gekleurd papier en laat je kind ze vastplakken. Voor een leeuw: stroken rondom als manen.","Laat de verf ±30 minuten drogen en plak dan een ijsstokje met ducttape aan de onderkant.","Speel ermee: raad welk dier er achter het masker zit, maak het geluid en houd een dierenoptocht door de kamer."],"ageTips":{"young":"Veel tweejarigen schrikken van iets vlak voor hun gezicht. Houd het masker eerst zelf op, speel kiekeboe en laat je peuter kiezen: voor het gezicht of gewoon in de hand.","old":"Laat je kleuter zelf een dier ontwerpen: welke oren, welke kleur, snorharen of veren? Laat de oren zelf knippen en bedenk samen een geluid en een loopje."},"safety":["Met een masker voor de ogen zie je minder: niet rennen, klimmen of traplopen met het masker op.","Pijpenragers hebben scherpe draadpuntjes: vouw de uiteinden een stukje om voordat ze als snorharen op het masker gaan.","Plakkaatverf kan vlekken op kleding en tafel: kies afwasbare kinderverf en trek een oud shirt aan."],"say":["Wie zit er achter dat masker? Is het een leeuw?","Kiekeboe!","Hoe klinkt jouw dier: brult het, piept het of knort het?","Je hebt het hele bordje geel gemaakt, tot in de randjes.","Welk dier wil jij vandaag zijn, en wat eet dat dier?"],"words":["masker","oren","snuit","snorharen","brullen","piepen","knorren","kiekeboe"],"learn":["creativiteit","fijne-motoriek","taal"],"tips":["Minder rommel: kleur het bordje met waskrijt in plaats van verf, dan kan het masker meteen gebruikt worden.","Maak een masker voor jezelf mee: samen een dierenfamilie spelen is veel leuker dan alleen."],"variations":["Carnaval: maak voor iedereen in huis een masker en houd een optocht op muziek.","Halloween: een zwarte kat, een vleermuis of een uil met veren.","Boerderij: een kip met veren, een varken met een snuit van een eierdoos-kuiltje of een koe met vlekken.","Herfst: een vos of een egel met echte bladeren als vacht."],"themes":["carnaval","halloween"]},
  {"id":"superheldencape","title":"Superheldencape zonder naaien","emoji":"🦸","category":"fantasie","summary":"Knip van een oud T-shirt een cape, plak er een eigen superheldenteken op en ga samen op reddingsmissie door de kamer.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":30,"supervision":2,"materials":[{"id":"oud-shirt","note":"een groot T-shirt van een volwassene, of een oude kussensloop"},{"id":"vilt","note":"of gekleurd papier, voor het superheldenteken"},{"id":"knutsellijm","note":"of textiellijm; voor papier werkt plakband ook"},{"id":"wasknijpers","note":"twee, om de cape los op de schouders vast te zetten"},{"id":"potlood"}],"optional":[{"id":"kinderschaar","note":"voor kleuters die zelf het teken knippen"},{"id":"aluminiumfolie","note":"voor een glimmende bliksem of ster"},{"id":"stiften"}],"steps":["Leg het T-shirt plat neer en knip de mouwen eraf (dat doe jij).","Knip langs de zijnaden en over de schoudernaden, zodat je het achterpand als één grote lap overhoudt.","Knip de cape op lengte: hij moet boven de knieholtes van je kind eindigen. Knip de onderkant recht, rond of met punten.","Laat je kind een teken kiezen, zoals een bliksem, een ster, een hart of de eerste letter van de naam, en teken het op vilt.","Knip het teken uit, plak het midden op de cape en laat het ±1 uur plat drogen.","Zet de cape met twee wasknijpers vast op de schouders van het shirt van je kind.","Bedenk samen een superheldennaam en een superkracht, en ga op missie: welke knuffels moeten er gered worden?"],"ageTips":{"young":"Een driejarige wil vooral snel een cape om. Knip jij de cape vooraf en laat je peuter het teken kleuren; opplakken kan straks.","old":"Laat je kleuter het teken zelf ontwerpen en knippen, en een missie met drie opdrachten bedenken: vlieg naar de keuken, red de beer, tel tot tien."},"safety":["Maak de cape nooit vast met een knoop of koord om de nek: blijft hij ergens achter haken, dan trekt hij de keel dicht. Wasknijpers schieten vanzelf los.","Doe de cape af bij klimmen (bank, trap, klimrek), in het autostoeltje en voor het slapen.","Superhelden vliegen over de vloer: rennen met gestrekte armen mag, springen van de bank of de trap niet."],"say":["Wat is jouw superkracht?","Zwiep! Daar vliegt de superheld!","Je hebt zelf een teken bedacht dat niemand anders heeft.","Wie moet er vandaag gered worden?","Hoe voelt het als je cape achter je aan wappert?"],"words":["cape","superheld","sterk","snel","vliegen","redden","zwiep"],"learn":["creativiteit","grove-motoriek","taal"],"tips":["Meteen spelen? Een kussensloop of oude handdoek met twee wasknijpers op de schouders is in één minuut een cape.","T-shirtstof rafelt niet: je hoeft de randen niet te zomen."],"variations":["Carnaval: maak er een tovenaarscape van met sterren en een maan van aluminiumfolie.","Verjaardag: maak capes voor alle feestgangers met de eerste letter van hun naam en speel een superheldenspeurtocht.","Reddingsmissie: verstop knuffels door het huis; elke geredde knuffel krijgt een pleister of een medaille van papier.","Superheldenmasker: knip een oogmasker van vilt of karton en houd het aan een ijsstokje voor je gezicht."],"themes":["carnaval","verjaardag"]},
  {"id":"winkeltje","title":"Winkeltje spelen met zelfgemaakt geld","emoji":"🛒","category":"fantasie","summary":"Zet lege verpakkingen op een rij, teken samen geld en prijskaartjes en speel om de beurt winkelier en klant.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":30,"supervision":1,"materials":[{"id":"verpakkingen","note":"8-10 lege doosjes, pakken en bakjes, omgespoeld"},{"id":"papier","note":"voor munten en briefjes"},{"id":"stiften"},{"id":"kinderschaar","note":"om het geld uit te knippen"},{"id":"schilderstape","note":"voor prijskaartjes"}],"optional":[{"id":"dozen","note":"als kassa, met een gleuf erin"},{"id":"wasmand","note":"als winkelmandje"},{"id":"stoffen-tas","note":"als boodschappentas"},{"id":"fruit","note":"echt fruit om te verkopen"}],"steps":["Zet 8-10 lege verpakkingen op een rij op de bank of een lage tafel: dat is het winkelschap.","Teken samen geld: rondjes als munten en rechthoeken als briefjes, met 1, 2 of 5 stippen erop. Knip ze uit.","Plak op elk product een stukje schilderstape als prijskaartje en teken er 1, 2 of 3 stippen op.","Maak een kassa van een doos met een gleuf (die snijd jij), of gebruik een bakje.","Speel om de beurt winkelier en klant: zeg goedemorgen, kies iets, betaal en tel samen de stippen af.","Ruil van rol en ruim samen op: alle munten in de kassa, alle producten terug op het schap."],"ageTips":{"young":"Geef een driejarige alleen munten met één stip en laat elk product één of twee munten kosten. Speel zelf eerst de klant: om de beurt praten is al de helft van het spel.","old":"Laat je kleuter zelf prijzen bedenken en cijfers op de kaartjes schrijven, en oefen met wisselgeld: je betaalt vijf, het kost drie. Wat krijg je terug?"},"safety":["Gebruik geen verpakkingen van schoonmaakmiddel, vaatwastabletten of medicijnen: zo blijft duidelijk dat die nooit speelgoed zijn.","Laat blikjes en glazen potjes weg: scherpe randen en scherven horen niet in een speelwinkel."],"say":["Goedemorgen! Wat mag het zijn?","Dit pak kost drie munten. Tel je mee?","Hoeveel munten heb je nog over?","Wat goed dat je wacht tot je aan de beurt bent.","Alsjeblieft! Dankjewel!"],"words":["kopen","betalen","munt","duur","goedkoop","meer","minder","alsjeblieft"],"learn":["rekenen","taal","samen"],"tips":["Bewaar een week lang lege verpakkingen in een doos: dan heb je een volle winkel zonder iets te kopen.","Echte appels en mandarijnen maken het extra echt; de ‘boodschappen’ gaan daarna gewoon de fruitschaal in."],"variations":["Groenteman: verkoop echte groente en fruit en weeg alles op de keukenweegschaal.","IJssalon: plastic bekers met propjes papier als bolletjes; elk bolletje kost één munt.","Bakkerij: bak broodjes en taartjes van speeldeeg en verkoop ze in de winkel.","Sinterklaas: maak een speelgoedwinkel en pak de gekochte cadeautjes samen in krantenpapier in."],"themes":[]},
  {"id":"knuffeldokter","title":"Dokter spelen voor knuffels","emoji":"🩹","category":"fantasie","summary":"Open de knuffelpraktijk: luister naar hartjes, plak pleisters, wikkel verband om en schrijf een recept voor de zieke beer.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":20,"supervision":2,"materials":[{"id":"knuffels","note":"een paar ‘zieke’ patiënten"},{"id":"pleisters","note":"of stukjes schilderstape met een getekend hartje"},{"id":"keukenpapier","note":"in stroken, als verband"},{"id":"schilderstape","note":"om het verband vast te plakken"},{"id":"dozen","note":"een schoenendoos als dokterstas"}],"optional":[{"id":"wc-rollen","note":"als stethoscoop of kijker"},{"id":"papier","note":"voor recepten en afsprakenkaartjes"},{"id":"stiften"},{"id":"lepel","note":"voor ‘medicijn’ van lucht"}],"steps":["Maak een dokterstas: teken een hartje op een schoenendoos en vul hem met pleisters, stroken keukenpapier en schilderstape.","Zet de zieke knuffels op een rij in de wachtkamer, bijvoorbeeld op de bank.","Roep de eerste patiënt binnen en vraag samen: waar doet het pijn?","Laat je kind onderzoeken: luisteren met een wc-rolletje, in de oren kijken, voelen aan de buik.","Wikkel verband van keukenpapier om een poot en plak het vast, of plak een pleister op de pijnlijke plek.","Teken een recept, zoals twee knuffels per dag en vroeg naar bed. Daarna mag de volgende patiënt komen."],"ageTips":{"young":"Voor je tweejarige is één knuffel met een paar pleisters genoeg: plakken en weer lostrekken is al spannend. Benoem de lichaamsdelen: poot, oor, buik.","old":"Laat je kleuter een wachtkamer met nummertjes maken, afsprakenkaartjes tekenen en zelf het recept schrijven. Speel ook eens dierenarts of tandarts."},"safety":["Gebruik nooit echte medicijnen, pillen, zalf of een injectiespuit met naald, en vertel erbij dat echte medicijnen alleen van jou of de dokter komen.","Speel je ook dokter op elkaar: wikkel nooit verband of touw om de nek, en stop niets in neus of oren, ook geen wattenstaafje.","Pleisterpapiertjes zijn klein en glad: ruim ze meteen op als er ook een dreumes rondloopt."],"say":["Ach, beer heeft pijn aan zijn poot. Wat moeten we doen?","Au! Pleister erop!","Luister… hoor je zijn hartje? Boem, boem.","Wat zorg jij voorzichtig voor je knuffel.","Wat deed de dokter toen jij er was?"],"words":["pijn","beter","pleister","verband","luisteren","voorzichtig","dokter","buik"],"learn":["taal","fijne-motoriek","creativiteit","samen"],"tips":["Gebruik het spel om een echt doktersbezoek of een prik voor te bereiden: speel samen na wat er gaat gebeuren.","Spaar je pleisters: stukjes schilderstape met een getekend hartje werken net zo goed en zijn veel goedkoper."],"variations":["Dierenarts: alle dieren uit de speelgoedkist krijgen een hok van een doos en een eigen etensbakje.","Tandarts: tel de tanden van een knuffel en poets ze met een oude tandenborstel.","Ziekenhuis: maak bedjes van schoenendozen met een theedoek als deken.","Consultatiebureau: weeg en meet de knuffels en zet het met streepjes op hun eigen kaart."],"themes":[]},
  {"id":"eigen-boekje","title":"Mijn eigen boekje maken","emoji":"📖","category":"fantasie","summary":"Vouw een boekje, laat je kind tekenen en plakken, en schrijf erbij wat het vertelt: een eigen verhaal om steeds weer voor te lezen.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":25,"supervision":1,"materials":[{"id":"papier","note":"3 vellen A4"},{"id":"nietmachine","note":"om de rug vast te zetten (dat doe jij)"},{"id":"kleurpotloden","note":"of stiften en waskrijt"},{"id":"potlood","note":"of pen, om op te schrijven wat je kind vertelt"}],"optional":[{"id":"tijdschriften","note":"om plaatjes uit te knippen"},{"id":"lijmstift"},{"id":"kinderschaar"},{"id":"gekleurd-papier","note":"voor een stevige kaft"},{"id":"stickers"}],"steps":["Leg 3 vellen A4 op elkaar en vouw ze samen dubbel: zo heb je een boekje van 12 bladzijden.","Zet twee nietjes in de vouw (dat doe jij). Voor een stevige kaft vouw je er eerst een vel gekleurd papier omheen.","Kies samen een onderwerp: ik, mijn dag, onze kat, wat ik leuk vind of een verzonnen avontuur.","Laat je kind per bladzijde tekenen, of plaatjes uit tijdschriften knippen en opplakken.","Vraag wat er op de bladzijde gebeurt en schrijf het onder de tekening op, precies zoals je kind het zegt.","Maak samen de kaft met een titel, een tekening en ‘geschreven door…’, en lees het boekje daarna samen voor."],"ageTips":{"young":"Een driejarige vertelt vaak één zin per plaatje, en dat is genoeg. Maak een boekje van één vel (4 bladzijden) en laat stickers en plaatjes het werk doen.","old":"Laat je kleuter eerst het verhaal plannen: wat gebeurt er eerst, dan en op het eind? Laat de titel naschrijven en bladzijdenummers erop zetten."},"safety":["De nietmachine is voor jou: houd de vingers van je kind uit de buurt bij het nieten en plak uitstekende nietpuntjes af.","Kies vooraf zelf een paar tijdschriften en folders, zodat er geen enge of ongeschikte plaatjes tussen zitten."],"say":["Wat gebeurt er op deze bladzijde?","En toen? Wat gebeurde er daarna?","Ik schrijf precies op wat jij zegt.","Je hebt aan elke bladzijde gewerkt. Wat een doorzetter!","Klaar! Lezen?"],"words":["boek","bladzijde","kaft","titel","verhaal","schrijver","eerst","daarna"],"learn":["taal","creativiteit","concentratie","fijne-motoriek"],"tips":["Werk in een paar keer: elke dag één bladzijde houdt het leuk, en het verhaal groeit vanzelf.","Zet het boekje tussen de echte boeken en lees het voor het slapengaan voor: kinderen zijn enorm trots op hun eigen boek."],"variations":["Cadeau: een boekje voor opa en oma, ‘Wat ik met oma doe’, met tekeningen of foto’s.","Telboek: op elke bladzijde één ding meer, van 1 zon tot 10 stippen.","Voelboek: plak op elke bladzijde iets anders om te voelen, zoals watten, aluminiumfolie, vilt of noppenfolie.","Herfst: een bladerenboek met op elke bladzijde een geplakt blad en wat je kind erover vertelt."],"themes":["cadeau"]},
  {"id":"post-voor-opa-en-oma","title":"Post maken voor opa en oma","emoji":"💌","category":"fantasie","summary":"Maak samen een kaart, versier de envelop met een zelfgemaakte postzegel en breng hem naar de brievenbus: opa en oma krijgen echte post!","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"durationMinutes":20,"supervision":1,"materials":[{"id":"karton","note":"of een stevig vel papier, dubbelgevouwen als kaart"},{"id":"waskrijt","note":"of stiften en kleurpotloden"},{"id":"enveloppen","note":"één die groot genoeg is voor de kaart"},{"id":"stickers","note":"een grote sticker als ‘postzegel’"},{"id":"potlood","note":"of pen, voor het adres en de tekst (dat doe jij)"}],"optional":[{"id":"tijdschriften","note":"om plaatjes uit te knippen"},{"id":"lijmstift"},{"id":"gekleurd-papier"}],"steps":["Vouw een stuk karton of stevig papier dubbel tot een kaart die in de envelop past.","Laat je kind de voorkant tekenen, kleuren of beplakken met plaatjes.","Vraag wat je kind tegen opa en oma wil zeggen en schrijf het binnenin op, precies zoals je kind het zegt. Je kind zet er een krabbel onder.","Versier samen de envelop met stickers en tekeningen; een sticker rechtsboven is de postzegel.","Schrijf het adres erop (dat doe jij) en plak er een echte postzegel op, of geef de post de volgende keer zelf aan opa en oma.","Loop samen naar de brievenbus en laat je kind de envelop erin doen. Over een paar dagen ligt hij bij opa en oma op de mat!"],"ageTips":{"young":"Voor een tweejarige is krassen en stickers plakken genoeg; schrijf jij op wat je peuter over de tekening vertelt. Laat je peuter de envelop zelf in de brievenbus duwen.","old":"Laat je kleuter de eigen naam schrijven of naschrijven, ‘opa’ en ‘oma’ op de envelop zetten en een vraag bedenken, zodat er ook post terugkomt."},"safety":["Geef je kind op weg naar de brievenbus een hand bij de stoep en bij het oversteken.","Het klepje van een brievenbus kan op kleine vingers dichtklappen: houd jij het open terwijl je kind de post erin laat vallen."],"say":["Wat wil je tegen opa en oma zeggen?","Plak! De postzegel zit erop.","Je hebt heel lang en geconcentreerd aan je tekening gewerkt.","Wat denk je dat oma zegt als ze de envelop openmaakt?","Hoe komt de brief eigenlijk bij opa en oma, denk je?"],"words":["kaart","envelop","postzegel","brievenbus","adres","versturen","opa","oma"],"learn":["taal","fijne-motoriek","creativiteit"],"tips":["Maak meteen een paar kaarten en bewaar ze voor verjaardagen of als bedankje.","Vraag opa en oma om terug te schrijven: zelf post krijgen is voor een kind net zo spannend als versturen."],"variations":["Kerst: een kerstkaart met een boom van gescheurde groene papiertjes en sterren van stickers.","Verjaardag: een kaart met een taart en papieren kaarsjes die je kind telt en opplakt.","Thuispostbode: maak een brievenbus van een schoenendoos en stuur elkaar in huis briefjes en tekeningen.","Ver weg: maak een foto van de kaart en stuur die alvast vooruit; de echte post komt een paar dagen later."],"themes":["cadeau","kerst","verjaardag"]},
  {"id":"sinterklaasmijter","title":"Mijter en staf voor Sinterklaas","emoji":"🎁","category":"fantasie","summary":"Knip een rode mijter met een geel kruis en maak een glimmende staf van kokers en folie: zo speel je zelf Sinterklaas.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":25,"supervision":1,"materials":[{"id":"gekleurd-papier","note":"rood voor de mijter (een A4’tje) en geel voor het kruis en de hoofdband"},{"id":"lijmstift"},{"id":"nietmachine","note":"om de band op maat te maken (dat doe jij)"},{"id":"wc-rollen","note":"2-3 keukenrolkokers voor de staf"},{"id":"aluminiumfolie"},{"id":"plakband"}],"optional":[{"id":"karton","note":"om achter de mijter te plakken als hij slap is"},{"id":"stickers","note":"als juwelen"},{"id":"kinderschaar"}],"steps":["Knip van geel papier een strook van ±5 cm breed die om het hoofd van je kind past, plus 3 cm extra.","Teken op rood papier een mijter van ±20 cm breed en ±28 cm hoog, met een punt bovenin. Knip hem uit (dat doe jij).","Laat je kind een kruis van twee gele stroken op de mijter plakken en versieren met stickers of platgedrukte propjes folie.","Zet de mijter met twee nietjes op de gele band, maak de band op maat en plak de nietjes aan de binnenkant af.","Plak 2-3 keukenrolkokers met plakband achter elkaar tot een lange staf en wikkel die samen met je kind in aluminiumfolie.","Draai een sliert folie tot een dikke slang, buig er een krul van en plak die bovenop de staf.","Zet de mijter op, pak de staf en zing samen een sinterklaasliedje."],"ageTips":{"young":"Voor een tweejarige knip jij alles vooraf. Het kruis opplakken en folie om de staf frommelen kan je peuter zelf; benoem samen rood, geel en glimmend.","old":"Laat je kleuter de mijter zelf natekenen en knippen, en speel daarna Sinterklaas met een groot boek: wat staat er over jou in het boek van de Sint?"},"safety":["Zet de nietjes met de gladde kant naar binnen en plak ze af, zodat er niets in het voorhoofd prikt.","Losse propjes folie en stickers zijn klein voor een tweejarige: plak ze stevig vast en ruim losse stukjes op. Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3."],"say":["Rood en geel! Plak!","Hoe hoog wordt jouw mijter? Hoger dan je hoofd?","Kijk, de staf glimt als het licht erop valt.","Je hebt de folie helemaal om de staf gewikkeld, zonder op te geven.","Wat zou Sinterklaas allemaal in zijn grote boek schrijven?"],"words":["mijter","staf","krul","kruis","rood","geel","glimmen","Sinterklaas"],"learn":["fijne-motoriek","creativiteit","taal"],"tips":["Geen rood papier? Kleur een wit vel helemaal rood met waskrijt; dat is meteen een mooie klus voor je kind.","Plak een stuk karton achter de mijter als hij slap wordt: dan blijft hij mooi rechtop staan."],"variations":["Pietenmuts: een platte muts van een papieren bordje met een veertje erop.","Sinterklaasavond: maak voor iedereen in huis een mijter en loop op sinterklaasliedjes een optocht door de kamer.","Het grote boek: maak een boek van gevouwen papier met een rode kaft en schrijf er samen in wat je kind goed kan."],"themes":["sinterklaas"]},
  {"id":"krantenhoed","title":"Krantenhoed vouwen","emoji":"📰","category":"fantasie","summary":"Vouw samen van één krantenpagina een klassieke hoed, versier hem met stickers en stift en houd een optocht door de kamer.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":2,"durationMinutes":15,"supervision":1,"materials":[{"id":"kranten","note":"één losse pagina per hoed"},{"id":"plakband"},{"id":"stickers"},{"id":"stiften"}],"optional":[{"id":"veren","note":"als pluim"},{"id":"crepepapier","note":"stroken als pluim of lint"},{"id":"gekleurd-papier"}],"steps":["Leg een krantenpagina neer en vouw hem doormidden, met de vouw bovenaan. Hij is nu ongeveer 30 cm breed.","Vouw de twee bovenhoeken schuin naar beneden, tot ze in het midden tegen elkaar komen. Onderaan blijft een rand over.","Vouw de onderrand aan de voorkant omhoog over de driehoeken. Draai de hoed om en doe hetzelfde aan de achterkant.","Vouw de uitstekende hoekjes van de rand om en plak ze vast met plakband.","Laat je kind de hoed versieren met stickers, stift en een pluim van een veer of crêpepapier.","Doe de hoed open, zet hem op en houd een optocht door de kamer op muziek."],"ageTips":{"young":"Bij een driejarige vouw jij en strijkt je peuter elke vouw plat met de hand, als een strijkijzer. Versieren is voor je peuter het echte werk.","old":"Laat je kleuter meevouwen op een eigen vel: jij doet elke stap voor, je kleuter doet hem na. Tel daarna samen de driehoeken in de hoed."},"safety":["Zakt de hoed over de ogen, dan ziet je kind de tafelrand of de trap niet: maak hem kleiner met een extra vouw of een stukje plakband aan de achterkant.","Drukinkt geeft wat af: laat je kind niet op de krant sabbelen en was na afloop de handen."],"say":["Eerst de hoekjes naar het midden. Strijk je mee?","Kijk, er komt een driehoek!","Je vouwt heel precies, de randjes liggen netjes op elkaar.","Wat voor hoed wordt het: van een soldaat, een piraat of een koning?","Hoed op! Optocht!"],"words":["vouwen","hoek","driehoek","rand","omdraaien","plat","hoed","optocht"],"learn":["fijne-motoriek","rekenen","concentratie"],"tips":["Is je krant groot? Knip de pagina eerst bij tot ongeveer 30 bij 40 cm, anders zakt de hoed over de schouders.","Pakpapier of een groot vel tekenpapier werkt ook en geeft geen inkt af."],"variations":["Koningsdag: oranje stickers en een pluim van oranje crêpepapier.","Carnaval: maak er een piratenhoed van met een doodshoofd van wit papier, of een soldatenhoed met een veer.","Bootje: met een paar extra vouwen wordt de hoed een bootje dat even in bad kan varen.","Verjaardag: vouw voor elk kind op het feestje een hoed en laat iedereen een eigen hoed versieren."],"themes":["carnaval","koningsdag"]},
  {"id":"verrekijker-safari","title":"Verrekijker maken en op safari in huis","emoji":"🦒","category":"fantasie","summary":"Plak twee wc-rolletjes aan elkaar tot een verrekijker en ga op safari: welke dieren zitten er verstopt achter de bank of onder de tafel?","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":10,"durationMinutes":25,"supervision":2,"materials":[{"id":"wc-rollen","note":"twee per verrekijker"},{"id":"plakband","note":"of schilderstape"},{"id":"stiften","note":"of stickers, om te versieren"},{"id":"knuffels","note":"of grote speelgoeddieren, 5-10 stuks om te verstoppen"}],"optional":[{"id":"gekleurd-papier","note":"om de rolletjes mee te beplakken"},{"id":"lijmstift"},{"id":"touw","note":"voor een kort koordje (alleen voor kleuters)"},{"id":"perforator","note":"voor de gaatjes van het koordje"},{"id":"wasmand","note":"als dierentuin voor de gevonden dieren"}],"steps":["Leg twee wc-rolletjes naast elkaar en plak ze stevig aan elkaar met een paar stroken plakband.","Laat je kind de verrekijker versieren met stift, stickers of gekleurd papier.","Verstop intussen 5-10 knuffels of speelgoeddieren in de kamer, half zichtbaar en op de hoogte van je kind.","Ga op safari: sluip door de kamer en kijk door de verrekijker. Wat zie je?","Zeg hardop wat je vindt en waar: een leeuw achter de bank, een beer onder de tafel!","Breng elk gevonden dier naar de dierentuin, zoals een mand of doos, en tel ze aan het eind samen."],"ageTips":{"young":"Verstop voor je tweejarige drie grote knuffels die half te zien zijn, en zoek samen. Laat het koordje weg en benoem de plek: achter, onder, op.","old":"Teken samen een schatkaart van de kamer met kruisjes, of geef aanwijzingen: de olifant zit onder iets zachts. Daarna verstopt je kleuter de dieren voor jou."},"safety":["Een koordje om de nek is een wurggevaar: laat het weg bij een tweejarige, houd het kort voor kleuters en doe de kijker af bij klimmen en slapen.","Verstop niets bij stopcontacten, medicijnen of schoonmaakmiddelen, en niet zo hoog dat je kind moet klimmen.","Speelgoeddiertjes die door een wc-rolletje passen, zijn te klein voor kinderen onder de 3: kies grote knuffels als je peuter meezoekt."],"say":["Ik zie, ik zie… iets met lange oren!","Waar zou de olifant zich verstopt hebben?","Sst… sluipen!","Je blijft zoeken tot je hem vindt. Wat ben jij een goede speurder.","Hoeveel dieren hebben we al gevonden?"],"words":["zoeken","sluipen","verstopt","achter","onder","bovenop","dichtbij","ver weg"],"learn":["taal","grove-motoriek","rekenen","fijne-motoriek"],"tips":["Speel het daarna andersom: je kind verstopt en jij zoekt. Peuters verstoppen vaak steeds op dezelfde plek, en dat is precies goed.","Bewaar de verrekijker bij het raam: zo kijk je samen naar vogels, wolken en de vuilniswagen."],"variations":["Vogelsafari: kijk door het raam naar vogels en tel hoeveel je er ziet.","Nachtsafari: maak de kamer donker en zoek de dieren met een zaklamp.","Kleurensafari: zoek alleen dingen in één kleur, bijvoorbeeld alles wat groen is.","Herfst: verstop dennenappels en bladeren voor een eekhoornsafari."],"themes":[]},
];
